-- Backyrd canonical Supabase baseline delta
-- Generated from the reconciled 2026-08-08 production contract.
-- Starts from the remotely registered state after migration 20260411100105.
-- This file is not intended to be applied to the current production database.
-- No production rows, personal data, provider keys, JWTs, or Vault values are included.

set check_function_bodies = false;

-- The registered foundation has incompatible bigint/text definitions for categories
-- and spots. A clean delta cannot safely cast arbitrary populated data to the UUID/enum
-- production contract. Fail closed unless all foundation tables are empty, then rebuild
-- only those six tables. This is exclusively for fresh environments after 00105.
do $$
begin
  if exists (
       select 1
       from supabase_migrations.schema_migrations
       where version not in (
         '20260411100101', '20260411100102', '20260411100103',
         '20260411100104', '20260411100105'
       )
     ) OR
      exists (select 1 from public.review_photos limit 1) OR
      exists (select 1 from public.spot_photos limit 1) OR
      exists (select 1 from public.reviews limit 1) OR
      exists (select 1 from public.spots limit 1) OR
      exists (select 1 from public.categories limit 1) OR
      exists (select 1 from public.profiles limit 1) then
    raise exception using
      errcode = '55000',
      message = 'canonical baseline requires an empty foundation state after 20260411100105';
  end if;
end;
$$;

drop trigger if exists on_auth_user_created_profile on auth.users;
drop table public.review_photos;
drop table public.spot_photos;
drop table public.reviews;
drop table public.spots;
drop table public.categories;
drop table public.profiles;

-- Canonical public application contract from the reviewed remote schema follows.


CREATE EXTENSION IF NOT EXISTS "pg_cron" WITH SCHEMA "pg_catalog";

CREATE EXTENSION IF NOT EXISTS "pg_net" WITH SCHEMA "public";

CREATE EXTENSION IF NOT EXISTS "citext" WITH SCHEMA "public";

CREATE EXTENSION IF NOT EXISTS "pg_trgm" WITH SCHEMA "public";

CREATE EXTENSION IF NOT EXISTS "pgcrypto" WITH SCHEMA "extensions";

CREATE EXTENSION IF NOT EXISTS "postgis" WITH SCHEMA "extensions";

CREATE EXTENSION IF NOT EXISTS "supabase_vault" WITH SCHEMA "vault";

CREATE EXTENSION IF NOT EXISTS "unaccent" WITH SCHEMA "public";

CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA "extensions";

CREATE EXTENSION IF NOT EXISTS "vector" WITH SCHEMA "public";

