CREATE OR REPLACE FUNCTION "public"."accept_legal_document_v1"("p_document_id" "uuid", "p_source" "text" DEFAULT 'mobile'::"text", "p_app_version" "text" DEFAULT NULL::"text", "p_locale" "text" DEFAULT 'de-CH'::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'not_authenticated'
      using errcode = '28000';
  end if;

  if p_source not in ('mobile', 'web') then
    raise exception 'invalid_source'
      using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.legal_documents d
    where d.id = p_document_id
      and d.status = 'published'
      and d.retired_at is null
      and d.effective_at <= now()
  ) then
    raise exception 'document_not_active'
      using errcode = '22023';
  end if;

  insert into public.user_legal_acceptances (
    user_id,
    document_id,
    source,
    app_version,
    locale
  )
  values (
    v_user_id,
    p_document_id,
    p_source,
    p_app_version,
    p_locale
  )
  on conflict (user_id, document_id)
  do nothing;

  insert into public.consent_events (
    user_id,
    document_id,
    event_type,
    source,
    app_version,
    locale
  )
  values (
    v_user_id,
    p_document_id,
    'document_accepted',
    p_source,
    p_app_version,
    p_locale
  );

  return true;
end;
$$;

ALTER FUNCTION "public"."accept_legal_document_v1"("p_document_id" "uuid", "p_source" "text", "p_app_version" "text", "p_locale" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_approve_spot_claim_v1"("p_claim_id" bigint, "p_reject_others" boolean DEFAULT true) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid;
  v_spot_id uuid;
  v_user_id uuid;
begin
  v_uid := auth.uid();
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  if not exists (
    select 1 from public.profiles me
    where me.id = v_uid and me.is_admin = true
  ) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select c.spot_id, c.user_id
    into v_spot_id, v_user_id
  from public.spot_claims c
  where c.id = p_claim_id;

  if v_spot_id is null then
    raise exception 'claim_not_found' using errcode = '22023';
  end if;

  update public.spots
  set owner_id = v_user_id
  where id = v_spot_id;

  update public.spot_claims
  set status = 'approved',
      updated_at = now()
  where id = p_claim_id;

  if p_reject_others then
    update public.spot_claims
    set status = 'rejected',
        updated_at = now()
    where spot_id = v_spot_id
      and id <> p_claim_id
      and status is distinct from 'approved';
  end if;
end;
$$;

ALTER FUNCTION "public"."admin_approve_spot_claim_v1"("p_claim_id" bigint, "p_reject_others" boolean) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_approve_spot_claim_v1"("p_claim_id" "uuid", "p_reject_others" boolean DEFAULT true) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid;
  v_spot_id uuid;
  v_user_id uuid;
begin
  v_uid := auth.uid();
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  -- Admin check
  if not exists (
    select 1 from public.profiles me
    where me.id = v_uid and me.is_admin = true
  ) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select c.spot_id, c.user_id
    into v_spot_id, v_user_id
  from public.spot_claims c
  where c.id = p_claim_id;

  if v_spot_id is null then
    raise exception 'claim_not_found' using errcode = '22023';
  end if;

  -- set owner
  update public.spots
  set owner_id = v_user_id
  where id = v_spot_id;

  -- approve this claim
  update public.spot_claims
  set status = 'approved',
      updated_at = now()
  where id = p_claim_id;

  -- reject other pending claims (optional)
  if p_reject_others then
    update public.spot_claims
    set status = 'rejected',
        updated_at = now()
    where spot_id = v_spot_id
      and id <> p_claim_id
      and status in ('pending','open','requested'); -- wir fangen mehrere mögliche values ab
  end if;
end;
$$;

ALTER FUNCTION "public"."admin_approve_spot_claim_v1"("p_claim_id" "uuid", "p_reject_others" boolean) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_clear_spot_owner_v1"("p_spot_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.admin_is_admin_v1() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  update public.spots
  set owner_id = null
  where id = p_spot_id;
end;
$$;

ALTER FUNCTION "public"."admin_clear_spot_owner_v1"("p_spot_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_complete_account_deletion_v1"("p_request_id" "uuid", "p_summary" "jsonb" DEFAULT '{}'::"jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if auth.uid() is null or not public.consent_is_admin_v1() then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  update public.data_rights_requests
  set
    status = 'completed',
    deletion_phase = 'completed',
    deletion_finished_at = now(),
    completed_at = now(),
    deletion_summary = deletion_summary || coalesce(p_summary, '{}'::jsonb),
    failure_code = null
  where id = p_request_id
    and request_type = 'account_deletion';

  return found;
end;
$$;

ALTER FUNCTION "public"."admin_complete_account_deletion_v1"("p_request_id" "uuid", "p_summary" "jsonb") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_decision_intelligence_v1"("p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  r jsonb;
begin
  if not coalesce(public.admin_is_admin_v1(), false) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  with ev as (
    select *
    from public.analytics_events
    where occurred_at >= p_from
      and occurred_at < p_to
      and event_name like 'decision_%'
  ), sessions as (
    select
      decision_id,
      min(occurred_at) as started_at,
      (array_agg(user_id order by occurred_at desc)
        filter (where user_id is not null))[1] as user_id,
      max(properties->>'query') as query,
      max(properties->>'input_mode') as input_mode,
      max(properties->>'model_version') as model_version,
      count(*) filter (where event_name = 'decision_spot_impression') as impressions,
      count(*) filter (where event_name = 'decision_like') as likes,
      count(*) filter (where event_name = 'decision_dislike') as dislikes,
      count(*) filter (where event_name in ('decision_spot_opened', 'decision_open')) as opens,
      count(*) filter (where event_name = 'decision_remixed') as remixes,
      count(*) filter (where event_name in ('decision_empty', 'decision_no_results')) as empty_results
    from ev
    group by decision_id
  ), daily as (
    select
      date_trunc('day', occurred_at)::date as metric_day,
      count(*) filter (where event_name = 'decision_started') as sessions,
      count(*) filter (where event_name = 'decision_spot_impression') as impressions,
      count(*) filter (where event_name = 'decision_like') as likes,
      count(*) filter (where event_name = 'decision_dislike') as dislikes,
      count(*) filter (where event_name in ('decision_spot_opened', 'decision_open')) as opens
    from ev
    group by 1
    order by 1
  ), queries as (
    select
      coalesce(nullif(properties->>'query', ''), 'Ohne Query') as query,
      count(distinct coalesce(decision_id::text, session_id::text)) as sessions,
      count(*) filter (where event_name = 'decision_spot_impression') as impressions,
      count(*) filter (where event_name = 'decision_like') as likes,
      count(*) filter (where event_name = 'decision_dislike') as dislikes,
      count(*) filter (where event_name in ('decision_spot_opened', 'decision_open')) as opens,
      count(*) filter (where event_name in ('decision_empty', 'decision_no_results')) as empty_results
    from ev
    group by 1
    order by sessions desc
    limit greatest(1, least(p_limit, 500))
  ), spots as (
    select
      e.spot_id,
      s.name,
      count(*) filter (where e.event_name = 'decision_spot_impression') as impressions,
      count(*) filter (where e.event_name = 'decision_like') as likes,
      count(*) filter (where e.event_name = 'decision_dislike') as dislikes,
      count(*) filter (where e.event_name in ('decision_spot_opened', 'decision_open')) as opens
    from ev e
    left join public.spots s on s.id = e.spot_id
    where e.spot_id is not null
    group by e.spot_id, s.name
    order by impressions desc
    limit 50
  ), models as (
    select
      coalesce(nullif(properties->>'model_version', ''), 'unknown') as model_version,
      count(distinct coalesce(decision_id::text, session_id::text)) as sessions,
      count(*) filter (where event_name = 'decision_spot_impression') as impressions,
      count(*) filter (where event_name = 'decision_like') as likes,
      count(*) filter (where event_name = 'decision_dislike') as dislikes,
      count(*) filter (where event_name in ('decision_spot_opened', 'decision_open')) as opens
    from ev
    group by 1
    order by sessions desc
  )
  select jsonb_build_object(
    'summary', jsonb_build_object(
      'sessions', (select count(*) from ev where event_name = 'decision_started'),
      'unique_users', (select count(distinct user_id) from ev where user_id is not null),
      'impressions', (select count(*) from ev where event_name = 'decision_spot_impression'),
      'likes', (select count(*) from ev where event_name = 'decision_like'),
      'dislikes', (select count(*) from ev where event_name = 'decision_dislike'),
      'opens', (select count(*) from ev where event_name in ('decision_spot_opened', 'decision_open')),
      'remixes', (select count(*) from ev where event_name = 'decision_remixed'),
      'empty_results', (select count(*) from ev where event_name in ('decision_empty', 'decision_no_results'))
    ),
    'daily', coalesce((select jsonb_agg(to_jsonb(daily) order by metric_day) from daily), '[]'::jsonb),
    'queries', coalesce((select jsonb_agg(to_jsonb(queries)) from queries), '[]'::jsonb),
    'spots', coalesce((select jsonb_agg(to_jsonb(spots)) from spots), '[]'::jsonb),
    'models', coalesce((select jsonb_agg(to_jsonb(models)) from models), '[]'::jsonb),
    'sessions', coalesce((
      select jsonb_agg(to_jsonb(s) order by started_at desc)
      from (
        select *
        from sessions
        order by started_at desc
        limit 100
      ) s
    ), '[]'::jsonb)
  ) into r;

  return r;
end;
$$;

ALTER FUNCTION "public"."admin_decision_intelligence_v1"("p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_decision_session_v1"("p_decision_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare r jsonb;
begin
 if not coalesce(public.admin_is_admin_v1(),false) then raise exception 'not_authorized' using errcode='42501'; end if;
 select jsonb_build_object(
  'session',(select to_jsonb(x) from (select ds.id,ds.user_id,ds.city,ds.mood_a_text,ds.mood_b_text,ds.created_at,p.display_name,p.username from public.decision_sessions ds left join public.profiles p on p.id=ds.user_id where ds.id=p_decision_id)x),
  'events',coalesce((select jsonb_agg(to_jsonb(x) order by occurred_at) from (select e.id,e.event_name,e.occurred_at,e.screen_name,e.spot_id,s.name spot_name,e.properties from public.analytics_events e left join public.spots s on s.id=e.spot_id where e.decision_id=p_decision_id)x),'[]'::jsonb)
 ) into r; return r;
end$$;

ALTER FUNCTION "public"."admin_decision_session_v1"("p_decision_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_delete_taxonomy_node_v1"("p_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare sys boolean; usage_count bigint; child_count bigint;
begin
  if coalesce(public.admin_is_admin_v1(), false) is not true then
    raise exception 'admin access required' using errcode='42501';
  end if;
  select is_system into sys from public.taxonomy_nodes where id=p_id;
  if sys is null then raise exception 'taxonomy node not found'; end if;
  if sys then raise exception 'system node cannot be deleted'; end if;
  select count(*) into usage_count from public.spot_taxonomies where taxonomy_node_id=p_id;
  if usage_count>0 then raise exception 'node is used by % spot assignments; deactivate instead',usage_count; end if;
  select count(*) into child_count from public.taxonomy_nodes where parent_id=p_id;
  if child_count>0 then raise exception 'node has % child nodes',child_count; end if;
  delete from public.taxonomy_nodes where id=p_id;
  return true;
end $$;

ALTER FUNCTION "public"."admin_delete_taxonomy_node_v1"("p_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_erase_account_data_v1"("p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_request public.data_rights_requests%rowtype;
  v_profile public.profiles%rowtype;
  v_pseudonym uuid := gen_random_uuid();
  v_owned_spots bigint;
  v_summary jsonb := '{}'::jsonb;
  v_count bigint;
begin
  if auth.uid() is null or not public.consent_is_admin_v1() then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  select * into v_request
  from public.data_rights_requests r
  where r.id = p_request_id
    and r.request_type = 'account_deletion'
  for update;

  if not found then
    raise exception 'deletion_request_not_found' using errcode = '22023';
  end if;

  if v_request.scheduled_for is null
     or v_request.scheduled_for > now() then
    raise exception 'deletion_cooling_off_not_complete'
      using errcode = '42501';
  end if;

  select * into v_profile
  from public.profiles p
  where p.id = v_request.user_id
  for update;

  if not found then
    raise exception 'profile_not_found' using errcode = '22023';
  end if;

  if coalesce(v_profile.is_admin, false) then
    raise exception 'admin_account_requires_manual_transfer'
      using errcode = '42501';
  end if;

  select count(*) into v_owned_spots
  from public.spots s
  where s.owner_id = v_request.user_id;

  if v_owned_spots > 0 then
    raise exception 'owned_spots_require_transfer:%', v_owned_spots
      using errcode = '23514';
  end if;

  update public.data_rights_requests
  set
    status = 'processing',
    deletion_phase = 'retention_snapshot',
    deletion_started_at = coalesce(deletion_started_at, now()),
    failure_code = null
  where id = p_request_id;

  insert into public.data_rights_retention_records (
    request_id,
    pseudonym_id,
    record_type,
    retained_payload,
    retain_until,
    legal_basis,
    metadata
  )
  select
    p_request_id,
    v_pseudonym,
    'consent_audit',
    jsonb_build_object(
      'consents', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'purpose_key', uc.purpose_key,
            'status', uc.status,
            'granted_at', uc.granted_at,
            'withdrawn_at', uc.withdrawn_at,
            'document_id', uc.document_id,
            'source', uc.source,
            'app_version', uc.app_version,
            'locale', uc.locale
          )
        )
        from public.user_consents uc
        where uc.user_id = v_request.user_id
      ), '[]'::jsonb),
      'legal_acceptances', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'document_id', ula.document_id,
            'accepted_at', ula.accepted_at,
            'source', ula.source,
            'app_version', ula.app_version,
            'locale', ula.locale
          )
        )
        from public.user_legal_acceptances ula
        where ula.user_id = v_request.user_id
      ), '[]'::jsonb),
      'events', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'purpose_key', ce.purpose_key,
            'document_id', ce.document_id,
            'event_type', ce.event_type,
            'source', ce.source,
            'app_version', ce.app_version,
            'locale', ce.locale,
            'occurred_at', ce.occurred_at
          )
        )
        from public.consent_events ce
        where ce.user_id = v_request.user_id
      ), '[]'::jsonb)
    ),
    now() + interval '10 years',
    'Nachweis rechtlicher Einwilligungen und Erklärungen',
    jsonb_build_object(
      'identity_removed', true,
      'retention_version', 'v1'
    );

  insert into public.data_rights_retention_records (
    request_id,
    pseudonym_id,
    record_type,
    retained_payload,
    retain_until,
    legal_basis,
    metadata
  )
  values (
    p_request_id,
    v_pseudonym,
    'safety_integrity',
    jsonb_build_object(
      'reports', coalesce((
        select jsonb_agg(
          to_jsonb(r)
          - 'reporter_user_id'
          - 'reviewed_by'
          - 'internal_notes'
          - 'reviewer_notes'
          - 'ip_address'
          - 'user_agent'
        )
        from public.safety_user_reports r
        where r.reporter_user_id = v_request.user_id
      ), '[]'::jsonb),
      'appeals', coalesce((
        select jsonb_agg(
          to_jsonb(a)
          - 'appellant_user_id'
          - 'reviewer_id'
          - 'internal_notes'
          - 'reviewer_notes'
          - 'ip_address'
          - 'user_agent'
        )
        from public.safety_appeals a
        where a.appellant_user_id = v_request.user_id
      ), '[]'::jsonb),
      'measures', coalesce((
        select jsonb_agg(
          to_jsonb(m)
          - 'user_id'
          - 'created_by'
          - 'revoked_by'
          - 'internal_notes'
          - 'reviewer_notes'
          - 'ip_address'
          - 'user_agent'
        )
        from public.safety_account_measures m
        where m.user_id = v_request.user_id
      ), '[]'::jsonb),
      'enforcement_events', coalesce((
        select jsonb_agg(
          to_jsonb(e)
          - 'user_id'
          - 'actor_user_id'
          - 'created_by'
          - 'internal_notes'
          - 'reviewer_notes'
          - 'ip_address'
          - 'user_agent'
        )
        from public.safety_user_enforcement_events e
        where e.user_id = v_request.user_id
      ), '[]'::jsonb)
    ),
    now() + interval '5 years',
    'Plattformintegrität, Missbrauchsprävention und Rechtsverteidigung',
    jsonb_build_object(
      'identity_removed', true,
      'internal_notes_omitted', true,
      'retention_version', 'v1'
    )
  );

  update public.data_rights_requests
  set deletion_phase = 'content_erasure'
  where id = p_request_id;

  v_count := public.data_rights_delete_by_user_v1(
    'social_post_reactions', 'user_id', v_request.user_id
  );
  v_summary := v_summary || jsonb_build_object('social_post_reactions', v_count);

  v_count := public.data_rights_delete_by_user_v1(
    'social_comments', 'user_id', v_request.user_id
  );
  v_summary := v_summary || jsonb_build_object('social_comments', v_count);

  v_count := public.data_rights_delete_by_user_v1(
    'social_posts', 'user_id', v_request.user_id
  );
  v_summary := v_summary || jsonb_build_object('social_posts', v_count);

  v_count := public.data_rights_delete_by_user_v1(
    'review_likes', 'user_id', v_request.user_id
  );
  v_summary := v_summary || jsonb_build_object('review_likes', v_count);

  v_count := public.data_rights_delete_by_user_v1(
    'review_comments', 'user_id', v_request.user_id
  );
  v_summary := v_summary || jsonb_build_object('review_comments', v_count);

  v_count := public.data_rights_delete_by_user_v1(
    'reviews', 'user_id', v_request.user_id
  );
  v_summary := v_summary || jsonb_build_object('reviews', v_count);

  v_count := public.data_rights_delete_by_user_v1(
    'messages', 'sender_id', v_request.user_id
  );
  v_summary := v_summary || jsonb_build_object('messages', v_count);

  perform public.data_rights_delete_by_user_v1('favorites','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('spot_follows','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('follows','follower',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('follows','following',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('decision_sessions','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('user_searches','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('user_events','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('user_achievements','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('user_badges','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('challenge_participants','user_id',v_request.user_id);

  perform public.data_rights_delete_by_user_v1('analytics_events','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('analytics_sessions','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('analytics_installations','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('analytics_referral_events','user_id',v_request.user_id);
  perform public.data_rights_set_null_by_user_v1('analytics_errors','user_id',v_request.user_id);

  perform public.data_rights_delete_by_user_v1('backyrd_ml_events_v1','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('backyrd_recommendation_runs_v1','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('backyrd_user_context_feature_preferences_v1','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('backyrd_user_feature_weights_v1','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('user_taste_events_v2','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('user_taste_concepts_v2','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('user_taste_moods_v1','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('user_taste_time_v1','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('user_taste_profile_v1','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('user_place_type_preferences_v1','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('user_preferences_model','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('user_favorite_spot_seeds','user_id',v_request.user_id);

  perform public.data_rights_delete_by_user_v1('user_push_devices','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('spot_claim_email_verifications_v1','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('spot_claims','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('chat_participants','user_id',v_request.user_id);

  perform public.data_rights_delete_by_user_v1('user_consents','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('user_legal_acceptances','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('consent_events','user_id',v_request.user_id);

  perform public.data_rights_delete_by_user_v1('safety_user_reports','reporter_user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('safety_appeals','appellant_user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('safety_account_measures','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('safety_user_enforcement_events','user_id',v_request.user_id);
  perform public.data_rights_delete_by_user_v1('safety_reporter_reputation','user_id',v_request.user_id);

  update public.spots
  set owner_id = null, created_by = null
  where owner_id = v_request.user_id
     or created_by = v_request.user_id;

  perform public.data_rights_set_null_by_user_v1('spot_photos','uploaded_by',v_request.user_id);
  perform public.data_rights_set_null_by_user_v1('review_photos','uploaded_by',v_request.user_id);
  perform public.data_rights_set_null_by_user_v1('spot_taxonomies','created_by',v_request.user_id);
  perform public.data_rights_set_null_by_user_v1('spot_taxonomies','verified_by',v_request.user_id);
  perform public.data_rights_set_null_by_user_v1('taxonomy_nodes','created_by',v_request.user_id);
  perform public.data_rights_set_null_by_user_v1('spot_descriptions','owner_user_id',v_request.user_id);
  perform public.data_rights_set_null_by_user_v1('spot_descriptions','admin_user_id',v_request.user_id);
  perform public.data_rights_set_null_by_user_v1('spot_intelligence_v1','updated_by',v_request.user_id);

  perform public.data_rights_set_null_by_user_v1('spot_claims','reviewed_by',v_request.user_id);
  perform public.data_rights_set_null_by_user_v1('safety_cases','assigned_to',v_request.user_id);
  perform public.data_rights_set_null_by_user_v1('safety_cases','decided_by',v_request.user_id);
  perform public.data_rights_set_null_by_user_v1('safety_user_reports','reviewed_by',v_request.user_id);
  perform public.data_rights_set_null_by_user_v1('safety_appeals','reviewer_id',v_request.user_id);
  -- User-owned Safety content must be removed before deleting the profile.
  -- The FK uses ON DELETE SET NULL, but trg_safety_sync_content_actor_v2
  -- repopulates actor_user_id during that UPDATE and would recreate the
  -- soon-to-be-deleted profile UUID.
  delete from public.safety_content_items sci
  where sci.actor_user_id = v_request.user_id;

  get diagnostics v_count = row_count;
  v_summary := v_summary || jsonb_build_object(
    'safety_content_items',
    v_count
  );

  perform public.data_rights_set_null_by_user_v1(
    'safety_decision_events',
    'actor_user_id',
    v_request.user_id
  );
  perform public.data_rights_set_null_by_user_v1(
    'safety_policy_versions',
    'created_by',
    v_request.user_id
  );

  update public.data_rights_requests
  set
    deletion_phase = 'profile_erasure',
    deletion_summary = v_summary || jsonb_build_object(
      'pseudonym_id', v_pseudonym,
      'retention_records', 2
    )
  where id = p_request_id;

  delete from public.profiles
  where id = v_request.user_id;

  update public.data_rights_requests
  set deletion_phase = 'auth_deletion'
  where id = p_request_id;

  return jsonb_build_object(
    'ok', true,
    'request_id', p_request_id,
    'user_id', v_request.user_id,
    'pseudonym_id', v_pseudonym,
    'summary', v_summary,
    'next_phase', 'auth_deletion'
  );
end;
$$;

ALTER FUNCTION "public"."admin_erase_account_data_v1"("p_request_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_error_detail_v1"("p_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare r jsonb;
begin
 if not coalesce(public.admin_is_admin_v1(),false) then raise exception 'not_authorized' using errcode='42501'; end if;
 select jsonb_build_object(
  'group',jsonb_build_object('fingerprint',p_fingerprint,'status',coalesce((select status from public.analytics_error_groups where fingerprint=p_fingerprint),'open'),'internal_note',(select internal_note from public.analytics_error_groups where fingerprint=p_fingerprint)),
  'occurrences',coalesce((select jsonb_agg(to_jsonb(x) order by occurred_at desc) from (select e.id,e.message,e.error_type,e.severity,e.stack,e.screen_name,e.platform,e.app_version,e.user_id,e.session_id,e.handled,e.context,e.occurred_at from public.analytics_errors e where coalesce(nullif(e.fingerprint,''),md5(coalesce(e.message,'')||coalesce(e.stack,'')))=p_fingerprint order by e.occurred_at desc limit 250)x),'[]'::jsonb)
 ) into r; return r;
end$$;

ALTER FUNCTION "public"."admin_error_detail_v1"("p_fingerprint" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_errors_intelligence_v1"("p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_limit" integer DEFAULT 200) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare r jsonb;
begin
 if not coalesce(public.admin_is_admin_v1(),false) then raise exception 'not_authorized' using errcode='42501'; end if;
 with g as (
  select coalesce(nullif(e.fingerprint,''),md5(coalesce(e.message,'')||coalesce(e.stack,''))) fingerprint,
   min(e.message) message,min(e.error_type) error_type,max(e.severity) severity,
   count(*) occurrences,count(distinct e.user_id) users,count(distinct e.session_id) sessions,
   min(e.occurred_at) first_seen_at,max(e.occurred_at) last_seen_at,
   (array_agg(e.screen_name order by e.occurred_at desc) filter(where e.screen_name is not null))[1] screen_name,
   (array_agg(e.platform order by e.occurred_at desc) filter(where e.platform is not null))[1] platform,
   (array_agg(e.app_version order by e.occurred_at desc) filter(where e.app_version is not null))[1] app_version,
   coalesce(eg.status,'open') status,eg.internal_note
  from public.analytics_errors e left join public.analytics_error_groups eg on eg.fingerprint=coalesce(nullif(e.fingerprint,''),md5(coalesce(e.message,'')||coalesce(e.stack,'')))
  where e.occurred_at>=p_from and e.occurred_at<p_to
  group by 1,eg.status,eg.internal_note order by last_seen_at desc limit greatest(1,least(p_limit,1000))
 )
 select jsonb_build_object('summary',jsonb_build_object(
  'occurrences',(select count(*) from public.analytics_errors where occurred_at>=p_from and occurred_at<p_to),
  'groups',(select count(*) from g),
  'affected_users',(select count(distinct user_id) from public.analytics_errors where occurred_at>=p_from and occurred_at<p_to and user_id is not null),
  'fatal',(select count(*) from public.analytics_errors where occurred_at>=p_from and occurred_at<p_to and severity='fatal')
 ),'groups',coalesce((select jsonb_agg(to_jsonb(g)) from g),'[]'::jsonb)) into r; return r;
end$$;

ALTER FUNCTION "public"."admin_errors_intelligence_v1"("p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_fail_account_deletion_v1"("p_request_id" "uuid", "p_phase" "text", "p_failure_code" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if auth.uid() is null or not public.consent_is_admin_v1() then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  update public.data_rights_requests
  set
    status = 'failed',
    deletion_phase = nullif(btrim(p_phase), ''),
    failure_code = left(coalesce(p_failure_code, 'unknown_failure'), 500)
  where id = p_request_id
    and request_type = 'account_deletion';

  return found;
end;
$$;

ALTER FUNCTION "public"."admin_fail_account_deletion_v1"("p_request_id" "uuid", "p_phase" "text", "p_failure_code" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_founder_overview_v1"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_from timestamptz := p_from;
  v_to timestamptz := p_to;
  v_duration interval;
  v_prev_from timestamptz;
  v_prev_to timestamptz;
  v_result jsonb;
begin
  if not coalesce(public.admin_is_admin_v1(), false) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if v_from is null or v_to is null or v_from >= v_to then
    raise exception 'invalid_period';
  end if;

  v_duration := v_to - v_from;
  v_prev_to := v_from;
  v_prev_from := v_from - v_duration;

  with
  activity as (
    select user_id, created_at as occurred_at, 'review_created'::text as event_name from public.reviews
    union all
    select user_id, created_at, 'decision_started' from public.decision_sessions
    union all
    select user_id, created_at, event_type from public.user_events
    union all
    select user_id, created_at, event_type from public.backyrd_ml_events_v1
    union all
    select user_id, created_at, event_type from public.social_feed_events
    union all
    select user_id, occurred_at, event_name from public.analytics_events
  ),
  current_active as (
    select count(distinct user_id)::int as value
    from activity
    where user_id is not null and occurred_at >= v_from and occurred_at < v_to
  ),
  previous_active as (
    select count(distinct user_id)::int as value
    from activity
    where user_id is not null and occurred_at >= v_prev_from and occurred_at < v_prev_to
  ),
  mau as (
    select count(distinct user_id)::int as value
    from activity
    where user_id is not null and occurred_at >= v_to - interval '30 days' and occurred_at < v_to
  ),
  dau as (
    select count(distinct user_id)::int as value
    from activity
    where user_id is not null and occurred_at >= v_to - interval '1 day' and occurred_at < v_to
  ),
  daily as (
    select d.day,
      count(distinct a.user_id)::int as active_users,
      count(*) filter (where a.event_name = 'review_created')::int as reviews,
      count(*) filter (where a.event_name = 'decision_started')::int as decisions,
      count(*) filter (where a.event_name = 'screen_view')::int as screen_views
    from generate_series(date_trunc('day', v_from), date_trunc('day', v_to - interval '1 second'), interval '1 day') d(day)
    left join activity a on a.occurred_at >= d.day and a.occurred_at < d.day + interval '1 day'
    group by d.day
    order by d.day
  ),
  decision_stats as (
    select
      (select count(*) from public.decision_sessions where created_at >= v_from and created_at < v_to)::int as sessions,
      (select count(*) from public.decision_impressions where created_at >= v_from and created_at < v_to)::int as impressions,
      (select count(*) from public.backyrd_ml_events_v1 where event_type = 'decision_open' and created_at >= v_from and created_at < v_to)::int as opens,
      (select count(*) from public.backyrd_ml_events_v1 where event_type = 'decision_like' and created_at >= v_from and created_at < v_to)::int as likes,
      (select count(*) from public.backyrd_ml_events_v1 where event_type = 'decision_dislike' and created_at >= v_from and created_at < v_to)::int as dislikes
  )
  select jsonb_build_object(
    'period', jsonb_build_object('from', v_from, 'to', v_to, 'previous_from', v_prev_from, 'previous_to', v_prev_to),
    'kpis', jsonb_build_object(
      'signups', (select count(*) from auth.users where created_at >= v_from and created_at < v_to and deleted_at is null),
      'signups_previous', (select count(*) from auth.users where created_at >= v_prev_from and created_at < v_prev_to and deleted_at is null),
      'activated_users', (select count(*) from public.profiles where profile_onboarding_completed_at >= v_from and profile_onboarding_completed_at < v_to),
      'activated_users_previous', (select count(*) from public.profiles where profile_onboarding_completed_at >= v_prev_from and profile_onboarding_completed_at < v_prev_to),
      'active_users', (select value from current_active),
      'active_users_previous', (select value from previous_active),
      'dau', (select value from dau),
      'mau', (select value from mau),
      'stickiness', case when (select value from mau) > 0 then round((select value from dau)::numeric / (select value from mau)::numeric * 100, 1) else 0 end,
      'reviews', (select count(*) from public.reviews where created_at >= v_from and created_at < v_to),
      'reviews_previous', (select count(*) from public.reviews where created_at >= v_prev_from and created_at < v_prev_to),
      'reviews_per_active_user', case when (select value from current_active) > 0 then round((select count(*) from public.reviews where created_at >= v_from and created_at < v_to)::numeric / (select value from current_active)::numeric, 2) else 0 end,
      'partner_spots', (select count(*) from public.spots where owner_id is not null),
      'pending_claims', (select count(*) from public.spot_claims where status = 'pending'),
      'errors', (select count(*) from public.analytics_errors where occurred_at >= v_from and occurred_at < v_to),
      'screen_views', (select count(*) from public.analytics_events where event_name = 'screen_view' and occurred_at >= v_from and occurred_at < v_to),
      'spot_opens', (select count(*) from public.analytics_events where event_name in ('spot_opened','spot_detail_opened') and occurred_at >= v_from and occurred_at < v_to)
    ),
    'decision', (select to_jsonb(decision_stats) from decision_stats),
    'daily', coalesce((select jsonb_agg(jsonb_build_object('day', day, 'active_users', active_users, 'reviews', reviews, 'decisions', decisions, 'screen_views', screen_views) order by day) from daily), '[]'::jsonb),
    'top_screens', coalesce((
      select jsonb_agg(x order by (x->>'views')::int desc)
      from (
        select jsonb_build_object('screen_name', screen_name, 'views', count(*), 'users', count(distinct user_id)) x
        from public.analytics_events
        where event_name = 'screen_view' and occurred_at >= v_from and occurred_at < v_to and screen_name is not null
        group by screen_name
        order by count(*) desc
        limit 10
      ) q
    ), '[]'::jsonb),
    'top_spots', coalesce((
      select jsonb_agg(x order by (x->>'views')::int desc)
      from (
        select jsonb_build_object('spot_id', e.spot_id, 'name', max(s.name), 'views', count(*), 'users', count(distinct e.user_id)) x
        from public.analytics_events e
        left join public.spots s on s.id = e.spot_id
        where e.event_name in ('spot_opened','spot_detail_opened') and e.occurred_at >= v_from and e.occurred_at < v_to and e.spot_id is not null
        group by e.spot_id
        order by count(*) desc
        limit 10
      ) q
    ), '[]'::jsonb),
    'latest_errors', coalesce((
      select jsonb_agg(to_jsonb(q) order by q.occurred_at desc)
      from (
        select id, message, severity, screen_name, app_version, occurred_at
        from public.analytics_errors
        where occurred_at >= v_from and occurred_at < v_to
        order by occurred_at desc
        limit 8
      ) q
    ), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$$;

ALTER FUNCTION "public"."admin_founder_overview_v1"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_get_legal_document_v1"("p_document_id" "uuid") RETURNS TABLE("document_id" "uuid", "document_type" "text", "version" "text", "locale" "text", "title" "text", "summary" "text", "content_markdown" "text", "content_hash" "text", "status" "text", "requires_acceptance" boolean, "requires_reacceptance" boolean, "change_summary" "text", "published_at" timestamp with time zone, "effective_at" timestamp with time zone, "retired_at" timestamp with time zone, "supersedes_document_id" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if auth.uid() is null or not public.consent_is_admin_v1() then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  return query
  select
    d.id,
    d.document_type,
    d.version,
    d.locale,
    d.title,
    d.summary,
    d.content_markdown,
    d.content_hash,
    d.status,
    d.requires_acceptance,
    d.requires_reacceptance,
    d.change_summary,
    d.published_at,
    d.effective_at,
    d.retired_at,
    d.supersedes_document_id,
    d.created_at,
    d.updated_at
  from public.legal_documents d
  where d.id = p_document_id;
end;
$$;

ALTER FUNCTION "public"."admin_get_legal_document_v1"("p_document_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_get_spot_owner_moderation_queue_v1"("p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 200) RETURNS TABLE("event_id" "uuid", "spot_id" "uuid", "spot_name" "text", "changed_by" "uuid", "changed_by_name" "text", "change_area" "text", "change_source" "text", "old_data" "jsonb", "new_data" "jsonb", "moderation_status" "text", "risk_flags" "text"[], "validation_warnings" "text"[], "moderation_note" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if public.is_admin_v1(auth.uid()) is not true then raise exception 'admin_required'; end if;

  return query
  select
    e.id, e.spot_id, s.name, e.changed_by,
    coalesce(nullif(trim(concat_ws(' ', p.first_name, p.last_name)), ''), p.display_name, p.username, e.changed_by::text),
    e.change_area, e.change_source, e.old_data, e.new_data,
    e.moderation_status, e.risk_flags, e.validation_warnings,
    e.moderation_note, e.created_at
  from public.spot_owner_change_events e
  join public.spots s on s.id = e.spot_id
  left join public.profiles p on p.id = e.changed_by
  where p_status is null or e.moderation_status = lower(trim(p_status))
  order by
    case when e.moderation_status = 'flagged' then 0 else 1 end,
    e.created_at desc
  limit greatest(1, least(coalesce(p_limit, 200), 1000));
end;
$$;

ALTER FUNCTION "public"."admin_get_spot_owner_moderation_queue_v1"("p_status" "text", "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_get_taxonomy_node_v1"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v jsonb;
begin
  if coalesce(public.admin_is_admin_v1(), false) is not true then
    raise exception 'admin access required' using errcode='42501';
  end if;

  select jsonb_build_object(
    'id',n.id,'slug',n.slug,'node_type',n.node_type,'parent_id',n.parent_id,
    'icon',n.icon,'color',n.color,'sort_order',n.sort_order,'is_active',n.is_active,
    'is_owner_selectable',n.is_owner_selectable,'is_system',n.is_system,
    'ml_weight',n.ml_weight,'label_de',de.label,'short_label_de',de.short_label,
    'description_de',de.description,'label_en',en.label,'short_label_en',en.short_label,
    'description_en',en.description,
    'category_ids',coalesce((select jsonb_agg(category_id) from public.taxonomy_node_categories where taxonomy_node_id=n.id),'[]'::jsonb),
    'synonyms',coalesce((select jsonb_agg(jsonb_build_object('id',id,'locale',locale,'synonym',synonym,'weight',weight) order by locale,synonym)
                         from public.taxonomy_synonyms where taxonomy_node_id=n.id),'[]'::jsonb)
  ) into v
  from public.taxonomy_nodes n
  left join public.taxonomy_node_translations de on de.taxonomy_node_id=n.id and de.locale='de'
  left join public.taxonomy_node_translations en on en.taxonomy_node_id=n.id and en.locale='en'
  where n.id=p_id;

  if v is null then raise exception 'taxonomy node not found'; end if;
  return v;
end $$;

ALTER FUNCTION "public"."admin_get_taxonomy_node_v1"("p_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_get_taxonomy_overview_v1"() RETURNS TABLE("id" "uuid", "slug" "text", "node_type" "text", "parent_id" "uuid", "parent_label" "text", "label_de" "text", "label_en" "text", "icon" "text", "color" "text", "sort_order" integer, "is_active" boolean, "is_owner_selectable" boolean, "is_system" boolean, "ml_weight" numeric, "category_ids" "uuid"[], "category_names" "text"[], "synonyms_count" bigint, "spots_count" bigint, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if coalesce(public.admin_is_admin_v1(), false) is not true then
    raise exception 'admin access required' using errcode='42501';
  end if;

  return query
  select n.id,n.slug,n.node_type,n.parent_id,coalesce(pt.label,pn.slug),
         coalesce(de.label,n.slug),coalesce(en.label,de.label,n.slug),
         n.icon,n.color,n.sort_order,n.is_active,n.is_owner_selectable,
         n.is_system,n.ml_weight,
         coalesce(cat.ids,'{}'::uuid[]),coalesce(cat.names,'{}'::text[]),
         coalesce(syn.cnt,0),coalesce(st.cnt,0),n.updated_at
  from public.taxonomy_nodes n
  left join public.taxonomy_node_translations de on de.taxonomy_node_id=n.id and de.locale='de'
  left join public.taxonomy_node_translations en on en.taxonomy_node_id=n.id and en.locale='en'
  left join public.taxonomy_nodes pn on pn.id=n.parent_id
  left join public.taxonomy_node_translations pt on pt.taxonomy_node_id=pn.id and pt.locale='de'
  left join lateral (
    select array_agg(c.id order by c.name) ids,array_agg(c.name order by c.name) names
    from public.taxonomy_node_categories nc join public.categories c on c.id=nc.category_id
    where nc.taxonomy_node_id=n.id
  ) cat on true
  left join lateral (
    select count(*)::bigint cnt from public.taxonomy_synonyms s where s.taxonomy_node_id=n.id
  ) syn on true
  left join lateral (
    select count(distinct x.spot_id)::bigint cnt from public.spot_taxonomies x where x.taxonomy_node_id=n.id
  ) st on true
  order by n.node_type,n.sort_order,coalesce(de.label,n.slug);
end $$;

ALTER FUNCTION "public"."admin_get_taxonomy_overview_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_growth_intelligence_v1"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_result jsonb;
begin
  if not coalesce(public.admin_is_admin_v1(), false) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if p_from is null or p_to is null or p_from >= p_to then
    raise exception 'invalid_date_range';
  end if;

  with
  core_events as (
    select
      e.user_id,
      e.event_name,
      e.occurred_at,
      e.session_id
    from public.analytics_events e
    where e.user_id is not null
      and e.occurred_at < p_to
      and e.event_name in (
        'app_opened','app_foregrounded','screen_view',
        'spot_opened','spot_detail_opened','decision_spot_opened',
        'map_spot_opened','feed_spot_opened','profile_spot_opened',
        'profile_favorite_spot_opened','nearby_spot_opened',
        'decision_started','decision_completed','decision_like','decision_dislike',
        'review_started','review_submitted','profile_updated',
        'feed_like_added','feed_comments_opened','spot_favorited'
      )
  ),
  first_value as (
    select
      u.id as user_id,
      u.created_at as registered_at,
      min(e.occurred_at) filter (
        where e.event_name in (
          'spot_opened','spot_detail_opened','decision_spot_opened',
          'map_spot_opened','feed_spot_opened','profile_spot_opened',
          'profile_favorite_spot_opened','nearby_spot_opened',
          'decision_started','decision_completed','review_submitted'
        )
      ) as first_value_at,
      min(e.occurred_at) filter (where e.event_name = 'decision_started') as first_decision_at,
      min(e.occurred_at) filter (where e.event_name = 'review_submitted') as first_review_at
    from auth.users u
    left join core_events e on e.user_id = u.id and e.occurred_at >= u.created_at
    group by u.id, u.created_at
  ),
  cohort_users as (
    select *
    from first_value
    where registered_at >= p_from and registered_at < p_to
  ),
  active_in_range as (
    select distinct e.user_id
    from core_events e
    where e.occurred_at >= p_from and e.occurred_at < p_to
  ),
  daily_series as (
    select generate_series(
      date_trunc('day', p_from),
      date_trunc('day', p_to - interval '1 millisecond'),
      interval '1 day'
    )::date as metric_date
  ),
  daily_growth as (
    select
      d.metric_date,
      (select count(*) from auth.users u
       where u.created_at >= d.metric_date::timestamptz
         and u.created_at < (d.metric_date + 1)::timestamptz) as registrations,
      (select count(*) from first_value f
       where f.first_value_at >= d.metric_date::timestamptz
         and f.first_value_at < (d.metric_date + 1)::timestamptz) as activations,
      (select count(distinct e.user_id) from core_events e
       where e.occurred_at >= d.metric_date::timestamptz
         and e.occurred_at < (d.metric_date + 1)::timestamptz) as active_users,
      (select count(*) from public.reviews r
       where r.created_at >= d.metric_date::timestamptz
         and r.created_at < (d.metric_date + 1)::timestamptz) as reviews,
      (select count(*) from public.analytics_events e
       where e.event_name = 'decision_started'
         and e.occurred_at >= d.metric_date::timestamptz
         and e.occurred_at < (d.metric_date + 1)::timestamptz) as decisions
    from daily_series d
  ),
  weekly_cohorts as (
    select
      date_trunc('week', f.registered_at)::date as cohort_week,
      count(*) as cohort_size,
      count(*) filter (where f.first_value_at is not null and f.first_value_at < f.registered_at + interval '7 days') as activated,
      count(*) filter (where exists (
        select 1 from core_events e
        where e.user_id = f.user_id
          and e.occurred_at >= f.registered_at + interval '1 day'
          and e.occurred_at < f.registered_at + interval '2 days'
      )) as d1_retained,
      count(*) filter (where exists (
        select 1 from core_events e
        where e.user_id = f.user_id
          and e.occurred_at >= f.registered_at + interval '7 days'
          and e.occurred_at < f.registered_at + interval '8 days'
      )) as d7_retained,
      count(*) filter (where exists (
        select 1 from core_events e
        where e.user_id = f.user_id
          and e.occurred_at >= f.registered_at + interval '30 days'
          and e.occurred_at < f.registered_at + interval '31 days'
      )) as d30_retained
    from first_value f
    where f.registered_at >= p_from and f.registered_at < p_to
    group by 1
    order by 1
  ),
  funnel as (
    select 1 as step_order, 'Registriert'::text as step_name,
           count(*)::bigint as users from cohort_users
    union all
    select 2, 'Aktiviert', count(*)::bigint from cohort_users
      where first_value_at is not null and first_value_at < registered_at + interval '7 days'
    union all
    select 3, 'Erste Decision', count(*)::bigint from cohort_users
      where first_decision_at is not null
    union all
    select 4, 'Erster Review', count(*)::bigint from cohort_users
      where first_review_at is not null
    union all
    select 5, 'Zurückgekehrt D7', count(*)::bigint from cohort_users f
      where exists (
        select 1 from core_events e
        where e.user_id=f.user_id
          and e.occurred_at >= f.registered_at + interval '7 days'
          and e.occurred_at < f.registered_at + interval '8 days'
      )
  ),
  acquisition as (
    select
      coalesce(nullif(e.properties->>'source',''), nullif(e.properties->>'channel',''), 'Direkt / unbekannt') as source,
      count(distinct e.user_id) as users
    from public.analytics_events e
    where e.user_id is not null
      and e.occurred_at >= p_from and e.occurred_at < p_to
      and e.event_name in ('app_opened','screen_view')
    group by 1
    order by users desc
    limit 12
  )
  select jsonb_build_object(
    'summary', jsonb_build_object(
      'registrations', (select count(*) from auth.users u where u.created_at >= p_from and u.created_at < p_to),
      'activated', (select count(*) from cohort_users where first_value_at is not null and first_value_at < registered_at + interval '7 days'),
      'active_users', (select count(*) from active_in_range),
      'returning_users', (
        select count(*) from active_in_range a
        where exists (select 1 from core_events e where e.user_id=a.user_id and e.occurred_at < p_from)
      ),
      'new_active_users', (
        select count(*) from active_in_range a
        where not exists (select 1 from core_events e where e.user_id=a.user_id and e.occurred_at < p_from)
      ),
      'activation_rate', coalesce(round(
        (select count(*) from cohort_users where first_value_at is not null and first_value_at < registered_at + interval '7 days') * 100.0 /
        nullif((select count(*) from cohort_users), 0), 1
      ), 0),
      'median_time_to_value_minutes', coalesce((
        select round(percentile_cont(0.5) within group (
          order by extract(epoch from (first_value_at - registered_at)) / 60.0
        )::numeric, 1)
        from cohort_users
        where first_value_at is not null and first_value_at >= registered_at
      ), 0),
      'd1_retention', coalesce(round(
        (select count(*) from cohort_users f where exists (
          select 1 from core_events e where e.user_id=f.user_id
            and e.occurred_at >= f.registered_at + interval '1 day'
            and e.occurred_at < f.registered_at + interval '2 days'
        )) * 100.0 / nullif((select count(*) from cohort_users where registered_at < p_to - interval '2 days'),0), 1
      ),0),
      'd7_retention', coalesce(round(
        (select count(*) from cohort_users f where exists (
          select 1 from core_events e where e.user_id=f.user_id
            and e.occurred_at >= f.registered_at + interval '7 days'
            and e.occurred_at < f.registered_at + interval '8 days'
        )) * 100.0 / nullif((select count(*) from cohort_users where registered_at < p_to - interval '8 days'),0), 1
      ),0),
      'd30_retention', coalesce(round(
        (select count(*) from cohort_users f where exists (
          select 1 from core_events e where e.user_id=f.user_id
            and e.occurred_at >= f.registered_at + interval '30 days'
            and e.occurred_at < f.registered_at + interval '31 days'
        )) * 100.0 / nullif((select count(*) from cohort_users where registered_at < p_to - interval '31 days'),0), 1
      ),0)
    ),
    'daily', coalesce((select jsonb_agg(to_jsonb(d) order by d.metric_date) from daily_growth d), '[]'::jsonb),
    'cohorts', coalesce((select jsonb_agg(to_jsonb(c) order by c.cohort_week) from weekly_cohorts c), '[]'::jsonb),
    'funnel', coalesce((select jsonb_agg(to_jsonb(f) order by f.step_order) from funnel f), '[]'::jsonb),
    'acquisition', coalesce((select jsonb_agg(to_jsonb(a)) from acquisition a), '[]'::jsonb)
  ) into v_result;

  return v_result;
end;
$$;

ALTER FUNCTION "public"."admin_growth_intelligence_v1"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_is_admin_v1"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.profiles p
    where p.id = auth.uid()
      and p.is_admin = true
  );
$$;

ALTER FUNCTION "public"."admin_is_admin_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_list_data_rights_requests_v1"("p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 200) RETURNS TABLE("request_id" "uuid", "user_id" "uuid", "display_name" "text", "username" "text", "contact_email" "text", "request_type" "text", "status" "text", "requested_at" timestamp with time zone, "scheduled_for" timestamp with time zone, "completed_at" timestamp with time zone, "export_expires_at" timestamp with time zone, "failure_code" "text", "user_note" "text", "admin_note" "text", "metadata" "jsonb", "deletion_phase" "text", "deletion_started_at" timestamp with time zone, "deletion_finished_at" timestamp with time zone, "deletion_summary" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if auth.uid() is null or not public.consent_is_admin_v1() then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  return query
  select
    r.id,
    r.user_id,
    p.display_name,
    p.username,
    p.contact_email,
    r.request_type,
    r.status,
    r.requested_at,
    r.scheduled_for,
    r.completed_at,
    r.export_expires_at,
    r.failure_code,
    r.user_note,
    r.admin_note,
    r.metadata,
    r.deletion_phase,
    r.deletion_started_at,
    r.deletion_finished_at,
    r.deletion_summary
  from public.data_rights_requests r
  left join public.profiles p on p.id = r.user_id
  where p_status is null or r.status = p_status
  order by
    case
      when r.status in (
        'requested',
        'scheduled',
        'processing',
        'failed'
      ) then 0
      else 1
    end,
    r.requested_at desc
  limit greatest(1, least(coalesce(p_limit, 200), 1000));
end;
$$;

ALTER FUNCTION "public"."admin_list_data_rights_requests_v1"("p_status" "text", "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_list_legal_documents_v1"() RETURNS TABLE("document_id" "uuid", "document_type" "text", "version" "text", "locale" "text", "title" "text", "status" "text", "requires_acceptance" boolean, "requires_reacceptance" boolean, "change_summary" "text", "content_hash" "text", "published_at" timestamp with time zone, "effective_at" timestamp with time zone, "retired_at" timestamp with time zone, "supersedes_document_id" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if auth.uid() is null or not public.consent_is_admin_v1() then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  return query
  select d.id,d.document_type,d.version,d.locale,d.title,d.status,
         d.requires_acceptance,d.requires_reacceptance,d.change_summary,
         d.content_hash,d.published_at,d.effective_at,d.retired_at,
         d.supersedes_document_id,d.created_at,d.updated_at
  from public.legal_documents d
  order by d.document_type,d.locale,d.created_at desc;
end;
$$;

ALTER FUNCTION "public"."admin_list_legal_documents_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_list_profiles_v1"("p_query" "text" DEFAULT ''::"text", "p_limit" integer DEFAULT 500) RETURNS TABLE("id" "uuid", "display_name" "text", "username" "text", "first_name" "text", "last_name" "text", "avatar_url" "text", "city" "text", "country" "text", "is_admin" boolean, "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    p.id,
    p.display_name,
    p.username,
    p.first_name,
    p.last_name,
    p.avatar_url,
    p.city,
    p.country,
    p.is_admin,
    p.created_at
  from public.profiles p
  where
    exists (
      select 1
      from public.profiles me
      where me.id = auth.uid() and me.is_admin = true
    )
    and (
      coalesce(p_query,'') = ''
      or (
        p.display_name ilike '%'||p_query||'%'
        or p.username ilike '%'||p_query||'%'
        or p.first_name ilike '%'||p_query||'%'
        or p.last_name ilike '%'||p_query||'%'
        or ((p.first_name || ' ' || p.last_name) ilike '%'||p_query||'%')
        or p.city ilike '%'||p_query||'%'
        or p.country ilike '%'||p_query||'%'
        or (p.id::text ilike '%'||p_query||'%')
      )
    )
  order by p.created_at desc nulls last
  limit greatest(1, least(coalesce(p_limit, 500), 2000));
$$;

ALTER FUNCTION "public"."admin_list_profiles_v1"("p_query" "text", "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_moments_intelligence_v1"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  r jsonb;
begin
  if not coalesce(public.admin_is_admin_v1(), false) then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  if p_from is null or p_to is null or p_from >= p_to then
    raise exception 'invalid_period';
  end if;

  with
  posts_in_period as (
    select p.*
    from public.social_posts p
    where p.created_at >= p_from and p.created_at < p_to
  ),
  reactions_in_period as (
    select r.*
    from public.social_post_reactions r
    where r.created_at >= p_from and r.created_at < p_to
  ),
  comments_in_period as (
    select c.*
    from public.social_comments c
    where c.created_at >= p_from and c.created_at < p_to
  ),
  feed_events as (
    select e.*
    from public.social_feed_events e
    where e.created_at >= p_from and e.created_at < p_to
  ),
  analytics_feed as (
    select e.*
    from public.analytics_events e
    where e.occurred_at >= p_from and e.occurred_at < p_to
      and e.event_name like 'feed_%'
  ),
  daily as (
    select
      d.metric_day,
      coalesce((select count(*) from posts_in_period p where p.created_at >= d.metric_day and p.created_at < d.metric_day + interval '1 day'), 0)::int as posts,
      coalesce((select count(*) from reactions_in_period x where x.reaction_type = 'like' and x.created_at >= d.metric_day and x.created_at < d.metric_day + interval '1 day'), 0)::int as likes,
      coalesce((select count(*) from comments_in_period x where x.created_at >= d.metric_day and x.created_at < d.metric_day + interval '1 day'), 0)::int as comments,
      coalesce((select count(*) from reactions_in_period x where x.reaction_type = 'save' and x.created_at >= d.metric_day and x.created_at < d.metric_day + interval '1 day'), 0)::int as saves,
      coalesce((select count(*) from analytics_feed x where x.event_name = 'feed_post_shared' and x.occurred_at >= d.metric_day and x.occurred_at < d.metric_day + interval '1 day'), 0)::int as shares,
      coalesce((select count(distinct user_id) from feed_events x where x.user_id is not null and x.created_at >= d.metric_day and x.created_at < d.metric_day + interval '1 day'), 0)::int as active_users
    from (
      select generate_series(
        date_trunc('day', p_from),
        date_trunc('day', p_to - interval '1 second'),
        interval '1 day'
      ) as metric_day
    ) d
  ),
  top_posts as (
    select
      p.id as post_id,
      p.user_id,
      coalesce(nullif(trim(concat_ws(' ', pr.first_name, pr.last_name)), ''), pr.display_name, pr.username, 'Backyrd User') as creator_name,
      p.caption,
      p.created_at,
      p.like_count,
      p.comment_count,
      p.save_count,
      p.status,
      p.visibility,
      p.source_type,
      s.name as spot_name,
      coalesce((select count(*) from analytics_feed a where a.entity_id::text = p.id::text and a.event_name = 'feed_post_shared'), 0)::int as shares,
      (coalesce(p.like_count,0) + coalesce(p.comment_count,0) * 2 + coalesce(p.save_count,0) * 2)::int as engagement_score
    from posts_in_period p
    left join public.profiles pr on pr.id::text = p.user_id::text
    left join public.spots s on s.id::text = p.spot_id::text
    order by engagement_score desc, p.created_at desc
    limit 25
  ),
  creators as (
    select
      p.user_id,
      coalesce(nullif(trim(concat_ws(' ', pr.first_name, pr.last_name)), ''), pr.display_name, pr.username, 'Backyrd User') as creator_name,
      count(*)::int as posts,
      sum(coalesce(p.like_count,0))::int as likes,
      sum(coalesce(p.comment_count,0))::int as comments,
      sum(coalesce(p.save_count,0))::int as saves,
      (sum(coalesce(p.like_count,0)) + sum(coalesce(p.comment_count,0))*2 + sum(coalesce(p.save_count,0))*2)::int as engagement_score
    from posts_in_period p
    left join public.profiles pr on pr.id::text = p.user_id::text
    group by p.user_id, creator_name
    order by engagement_score desc, posts desc
    limit 20
  ),
  modes as (
    select
      coalesce(nullif(e.context->>'feed_mode',''), 'unknown') as feed_mode,
      count(*)::int as events,
      count(distinct e.user_id)::int as users
    from feed_events e
    group by 1
    order by 2 desc
  ),
  events as (
    select event_type, count(*)::int as events, count(distinct user_id)::int as users
    from feed_events
    group by event_type
    order by events desc
  )
  select jsonb_build_object(
    'summary', jsonb_build_object(
      'posts', (select count(*)::int from posts_in_period),
      'creators', (select count(distinct user_id)::int from posts_in_period),
      'likes', (select count(*)::int from reactions_in_period where reaction_type = 'like'),
      'comments', (select count(*)::int from comments_in_period),
      'saves', (select count(*)::int from reactions_in_period where reaction_type = 'save'),
      'shares', (select count(*)::int from analytics_feed where event_name = 'feed_post_shared'),
      'feed_users', (select count(distinct user_id)::int from feed_events where user_id is not null),
      'feed_events', (select count(*)::int from feed_events),
      'engagement_rate', (
        select case when count(*) > 0 then round((sum(coalesce(like_count,0)+coalesce(comment_count,0)+coalesce(save_count,0))::numeric / count(*)), 2) else 0 end
        from posts_in_period
      )
    ),
    'daily', coalesce((select jsonb_agg(to_jsonb(d) order by d.metric_day) from daily d), '[]'::jsonb),
    'top_posts', coalesce((select jsonb_agg(to_jsonb(x)) from top_posts x), '[]'::jsonb),
    'creators', coalesce((select jsonb_agg(to_jsonb(x)) from creators x), '[]'::jsonb),
    'feed_modes', coalesce((select jsonb_agg(to_jsonb(x)) from modes x), '[]'::jsonb),
    'event_types', coalesce((select jsonb_agg(to_jsonb(x)) from events x), '[]'::jsonb)
  ) into r;

  return r;
end;
$$;

ALTER FUNCTION "public"."admin_moments_intelligence_v1"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_partners_intelligence_v1"("p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_limit" integer DEFAULT 100, "p_search" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  result jsonb;
begin
  if not public.admin_is_admin_v1() then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  with partner_spots as (
    select
      s.id,
      s.name,
      s.city,
      s.status,
      s.owner_id,
      s.header_photo_path,
      coalesce(
        nullif(trim(concat_ws(' ', p.first_name, p.last_name)), ''),
        nullif(p.display_name, ''),
        case when p.username is not null then '@' || p.username else null end,
        s.owner_id::text
      ) as owner_name,
      p.username as owner_username,
      p.avatar_url as owner_avatar
    from public.spots s
    left join public.profiles p on p.id::text = s.owner_id::text
    where s.owner_id is not null
      and (
        p_search is null or trim(p_search) = '' or
        concat_ws(' ', s.name, s.city, p.first_name, p.last_name, p.display_name, p.username, s.owner_id::text)
          ilike '%' || trim(p_search) || '%'
      )
  ),
  event_rollup as (
    select
      e.spot_id::text as spot_id_text,
      count(*) filter (where e.event_name in (
        'spot_opened','spot_detail_opened','decision_spot_opened','map_spot_opened',
        'feed_spot_opened','profile_spot_opened','profile_favorite_spot_opened','nearby_spot_opened'
      )) as views,
      count(distinct e.user_id) filter (where e.event_name in (
        'spot_opened','spot_detail_opened','decision_spot_opened','map_spot_opened',
        'feed_spot_opened','profile_spot_opened','profile_favorite_spot_opened','nearby_spot_opened'
      )) as unique_users,
      count(*) filter (where e.event_name = 'decision_spot_impression') as decision_impressions,
      count(*) filter (where e.event_name = 'decision_spot_opened') as decision_opens,
      count(*) filter (where e.event_name = 'spot_route_clicked') as route_clicks,
      count(*) filter (where e.event_name = 'spot_website_clicked') as website_clicks,
      count(*) filter (where e.event_name = 'spot_phone_clicked') as phone_clicks,
      max(e.occurred_at) as last_activity
    from public.analytics_events e
    where e.occurred_at >= p_from and e.occurred_at < p_to
      and e.spot_id is not null
    group by e.spot_id::text
  ),
  review_rollup as (
    select r.spot_id::text as spot_id_text, count(*) as reviews
    from public.reviews r
    where r.created_at >= p_from and r.created_at < p_to
    group by r.spot_id::text
  ),
  rows_data as (
    select
      ps.id as spot_id,
      ps.name,
      ps.city,
      ps.status,
      ps.owner_id,
      ps.owner_name,
      ps.owner_username,
      ps.owner_avatar,
      ps.header_photo_path,
      coalesce(er.views,0) as views,
      coalesce(er.unique_users,0) as unique_users,
      coalesce(er.decision_impressions,0) as decision_impressions,
      coalesce(er.decision_opens,0) as decision_opens,
      case when coalesce(er.decision_impressions,0) > 0
        then round(coalesce(er.decision_opens,0) * 100.0 / er.decision_impressions, 1)
        else 0 end as decision_ctr,
      coalesce(rr.reviews,0) as reviews,
      coalesce(er.route_clicks,0) as route_clicks,
      coalesce(er.website_clicks,0) as website_clicks,
      coalesce(er.phone_clicks,0) as phone_clicks,
      coalesce(er.route_clicks,0)+coalesce(er.website_clicks,0)+coalesce(er.phone_clicks,0) as intent_actions,
      er.last_activity
    from partner_spots ps
    left join event_rollup er on er.spot_id_text = ps.id::text
    left join review_rollup rr on rr.spot_id_text = ps.id::text
  ),
  limited_rows as (
    select * from rows_data
    order by intent_actions desc, views desc, name asc
    limit greatest(1, least(coalesce(p_limit,100),500))
  ),
  owner_rollup as (
    select
      owner_id,
      max(owner_name) as owner_name,
      count(*) as spots,
      sum(views) as views,
      sum(unique_users) as unique_users,
      sum(intent_actions) as intent_actions,
      sum(reviews) as reviews
    from rows_data
    group by owner_id
    order by intent_actions desc, views desc
    limit 50
  ),
  claim_counts as (
    select
      status,
      count(*) as claims
    from public.spot_claims
    where created_at >= p_from and created_at < p_to
    group by status
  )
  select jsonb_build_object(
    'summary', jsonb_build_object(
      'partner_spots', (select count(*) from partner_spots),
      'active_owners', (select count(distinct owner_id) from partner_spots),
      'views', coalesce((select sum(views) from rows_data),0),
      'unique_users', coalesce((select sum(unique_users) from rows_data),0),
      'reviews', coalesce((select sum(reviews) from rows_data),0),
      'intent_actions', coalesce((select sum(intent_actions) from rows_data),0),
      'route_clicks', coalesce((select sum(route_clicks) from rows_data),0),
      'website_clicks', coalesce((select sum(website_clicks) from rows_data),0),
      'phone_clicks', coalesce((select sum(phone_clicks) from rows_data),0),
      'pending_claims', (select count(*) from public.spot_claims where status='pending'),
      'approved_claims_period', (select count(*) from public.spot_claims where status='approved' and updated_at >= p_from and updated_at < p_to)
    ),
    'partners', coalesce((select jsonb_agg(to_jsonb(x)) from limited_rows x), '[]'::jsonb),
    'owners', coalesce((select jsonb_agg(to_jsonb(x)) from owner_rollup x), '[]'::jsonb),
    'claims', coalesce((select jsonb_agg(to_jsonb(x)) from claim_counts x), '[]'::jsonb)
  ) into result;

  return result;
end;
$$;

ALTER FUNCTION "public"."admin_partners_intelligence_v1"("p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_limit" integer, "p_search" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_preview_account_deletion_v1"("p_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_request public.data_rights_requests%rowtype;
  v_profile public.profiles%rowtype;
  v_owned_spots bigint := 0;
  v_created_spots bigint := 0;
  v_active_admins bigint := 0;
  v_cooling_off_complete boolean := false;
  v_result jsonb;
begin
  if auth.uid() is null or not public.consent_is_admin_v1() then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  select * into v_request
  from public.data_rights_requests r
  where r.id = p_request_id
    and r.request_type = 'account_deletion';

  if not found then
    raise exception 'deletion_request_not_found' using errcode = '22023';
  end if;

  select * into v_profile
  from public.profiles p
  where p.id = v_request.user_id;

  select count(*) into v_owned_spots
  from public.spots s
  where s.owner_id = v_request.user_id;

  select count(*) into v_created_spots
  from public.spots s
  where s.created_by = v_request.user_id;

  select count(*) into v_active_admins
  from public.profiles p
  where coalesce(p.is_admin, false) = true
    and p.id <> v_request.user_id;

  v_cooling_off_complete :=
    v_request.scheduled_for is not null
    and v_request.scheduled_for <= now();

  select jsonb_build_object(
    'request_id', v_request.id,
    'user_id', v_request.user_id,
    'status', v_request.status,
    'scheduled_for', v_request.scheduled_for,
    'cooling_off_complete', v_cooling_off_complete,
    'profile_exists', v_profile.id is not null,
    'is_admin', coalesce(v_profile.is_admin, false),
    'remaining_admins', v_active_admins,
    'owned_spots', v_owned_spots,
    'created_spots', v_created_spots,
    'blockers', jsonb_strip_nulls(jsonb_build_object(
      'cooling_off',
        case when not v_cooling_off_complete
          then format(
            'Die 14-tägige Sicherheitsfrist läuft bis %s.',
            coalesce(v_request.scheduled_for::text, 'unbekannt')
          )
        end,
      'admin_account',
        case when coalesce(v_profile.is_admin, false)
          then 'Admin-Rechte müssen zuerst entfernt oder übertragen werden.'
        end,
      'owned_spots',
        case when v_owned_spots > 0
          then format(
            '%s Spot-Verantwortlichkeiten müssen zuerst übertragen oder entfernt werden.',
            v_owned_spots
          )
        end,
      'invalid_status',
        case when v_request.status not in ('scheduled', 'processing', 'failed')
          then format('Status %s ist nicht löschbar.', v_request.status)
        end
    )),
    'counts', jsonb_build_object(
      'reviews', (
        select count(*) from public.reviews r
        where r.user_id = v_request.user_id
      ),
      'social_posts', (
        select count(*) from public.social_posts p
        where p.user_id = v_request.user_id
      ),
      'messages', (
        select count(*) from public.messages m
        where m.sender_id = v_request.user_id
      ),
      'decision_sessions', (
        select count(*) from public.decision_sessions d
        where d.user_id = v_request.user_id
      ),
      'consent_events', (
        select count(*) from public.consent_events e
        where e.user_id = v_request.user_id
      ),
      'safety_reports', (
        select count(*) from public.safety_user_reports r
        where r.reporter_user_id = v_request.user_id
      ),
      'safety_appeals', (
        select count(*) from public.safety_appeals a
        where a.appellant_user_id = v_request.user_id
      ),
      'safety_measures', (
        select count(*) from public.safety_account_measures m
        where m.user_id = v_request.user_id
      ),
      'safety_enforcement_events', (
        select count(*) from public.safety_user_enforcement_events e
        where e.user_id = v_request.user_id
      )
    ),
    'can_execute',
      v_profile.id is not null
      and not coalesce(v_profile.is_admin, false)
      and v_owned_spots = 0
      and v_cooling_off_complete
      and v_request.status in ('scheduled', 'processing', 'failed')
  )
  into v_result;

  return v_result;
end;
$$;

ALTER FUNCTION "public"."admin_preview_account_deletion_v1"("p_request_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_preview_legal_publication_v1"("p_document_id" "uuid") RETURNS TABLE("document_id" "uuid", "document_type" "text", "version" "text", "locale" "text", "currently_published_document_id" "uuid", "current_version" "text", "requires_acceptance" boolean, "requires_reacceptance" boolean, "existing_acceptance_count" bigint, "affected_user_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if auth.uid() is null or not public.consent_is_admin_v1() then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  return query
  with candidate as (
    select * from public.legal_documents
    where id=p_document_id and status='draft'
  ),
  current_doc as (
    select d.*
    from public.legal_documents d
    join candidate c on c.document_type=d.document_type and c.locale=d.locale
    where d.status='published' and d.retired_at is null
    order by d.published_at desc
    limit 1
  )
  select
    c.id,c.document_type,c.version,c.locale,cd.id,cd.version,
    c.requires_acceptance,c.requires_reacceptance,
    (select count(*) from public.user_legal_acceptances ula where ula.document_id=cd.id),
    case
      when c.requires_acceptance=false then 0::bigint
      when cd.id is null then (select count(*) from auth.users)
      when c.requires_reacceptance=true then (select count(*) from auth.users)
      else 0::bigint
    end
  from candidate c
  left join current_doc cd on true;
end;
$$;

ALTER FUNCTION "public"."admin_preview_legal_publication_v1"("p_document_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_privacy_overview_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_result jsonb;
begin
  if auth.uid() is null or not public.consent_is_admin_v1() then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'profiles_total', (select count(*) from public.profiles),
    'documents_total', (select count(*) from public.legal_documents),
    'documents_draft', (
      select count(*) from public.legal_documents where status = 'draft'
    ),
    'documents_published', (
      select count(*) from public.legal_documents where status = 'published'
    ),
    'documents_retired', (
      select count(*) from public.legal_documents where status = 'retired'
    ),
    'acceptances_total', (
      select count(*) from public.user_legal_acceptances
    ),
    'consent_events_total', (
      select count(*) from public.consent_events
    ),
    'pending_required_acceptances', (
      select count(*)
      from public.profiles p
      cross join public.legal_documents d
      where d.status = 'published'
        and d.retired_at is null
        and d.effective_at <= now()
        and d.requires_acceptance = true
        and not exists (
          select 1
          from public.user_legal_acceptances ula
          where ula.user_id = p.id
            and ula.document_id = d.id
        )
    ),
    'purposes', (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'purpose_key', cp.key,
            'title', cp.title_de,
            'requires_consent', cp.requires_consent,
            'is_required', cp.is_required,
            'default_enabled', cp.default_enabled,
            'granted_users', (
              select count(*)
              from public.user_consents uc
              where uc.purpose_key = cp.key
                and uc.status = 'granted'
            ),
            'withdrawn_users', (
              select count(*)
              from public.user_consents uc
              where uc.purpose_key = cp.key
                and uc.status = 'withdrawn'
            ),
            'not_set_profiles', (
              select count(*)
              from public.profiles p
              where not exists (
                select 1
                from public.user_consents uc
                where uc.user_id = p.id
                  and uc.purpose_key = cp.key
              )
            )
          )
          order by cp.sort_order, cp.key
        ),
        '[]'::jsonb
      )
      from public.consent_purposes cp
      where cp.is_active = true
    )
  )
  into v_result;

  return v_result;
end;
$$;

ALTER FUNCTION "public"."admin_privacy_overview_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_publish_legal_document_v1"("p_document_id" "uuid", "p_effective_at" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("document_id" "uuid", "document_type" "text", "version" "text", "locale" "text", "status" "text", "published_at" timestamp with time zone, "effective_at" timestamp with time zone, "supersedes_document_id" "uuid", "requires_reacceptance" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_admin_id uuid := auth.uid();
  v_document public.legal_documents%rowtype;
  v_previous_id uuid;
  v_now timestamptz := now();
begin
  if v_admin_id is null or not public.consent_is_admin_v1() then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  select * into v_document
  from public.legal_documents
  where id=p_document_id and status='draft'
  for update;

  if not found then
    raise exception 'draft_not_found' using errcode = '22023';
  end if;

  select id into v_previous_id
  from public.legal_documents
  where document_type=v_document.document_type
    and locale=v_document.locale
    and status='published'
    and retired_at is null
  order by published_at desc
  limit 1
  for update;

  if v_previous_id is not null then
    update public.legal_documents
    set status='retired', retired_at=v_now, retired_by=v_admin_id
    where id=v_previous_id;
  end if;

  update public.legal_documents
  set status='published',
      published_at=v_now,
      effective_at=greatest(coalesce(p_effective_at,v_now),v_now),
      published_by=v_admin_id,
      supersedes_document_id=v_previous_id,
      retired_at=null,
      retired_by=null
  where id=p_document_id;

  return query
  select d.id,d.document_type,d.version,d.locale,d.status,d.published_at,
         d.effective_at,d.supersedes_document_id,d.requires_reacceptance
  from public.legal_documents d
  where d.id=p_document_id;
end;
$$;

ALTER FUNCTION "public"."admin_publish_legal_document_v1"("p_document_id" "uuid", "p_effective_at" timestamp with time zone) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_reject_spot_claim_v1"("p_claim_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid;
begin
  v_uid := auth.uid();
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  if not exists (
    select 1 from public.profiles me
    where me.id = v_uid and me.is_admin = true
  ) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  update public.spot_claims
  set status = 'rejected',
      updated_at = now()
  where id = p_claim_id;

  if not found then
    raise exception 'claim_not_found' using errcode = '22023';
  end if;
end;
$$;

