CREATE OR REPLACE FUNCTION "public"."admin_review_spot_owner_change_v1"("p_event_id" "uuid", "p_decision" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_event public.spot_owner_change_events%rowtype;
  v_decision text := lower(trim(coalesce(p_decision, '')));
  v_ids uuid[];
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if public.is_admin_v1(auth.uid()) is not true then raise exception 'admin_required'; end if;
  if v_decision not in ('approved','flagged','reverted') then
    raise exception 'invalid_decision';
  end if;

  select * into v_event
  from public.spot_owner_change_events
  where id = p_event_id
  for update;

  if v_event.id is null then raise exception 'change_event_not_found'; end if;

  if v_decision = 'reverted' then
    if v_event.change_area in ('profile','mobile_profile') then
      update public.spots set
        name = coalesce(v_event.old_data ->> 'name', name),
        address = case when v_event.old_data ? 'address' then nullif(v_event.old_data ->> 'address','') else address end,
        city = case when v_event.old_data ? 'city' then nullif(v_event.old_data ->> 'city','') else city end,
        country = case when v_event.old_data ? 'country' then nullif(v_event.old_data ->> 'country','') else country end,
        category_id = case when v_event.old_data ? 'category_id' and nullif(v_event.old_data ->> 'category_id','') is not null then (v_event.old_data ->> 'category_id')::uuid else category_id end,
        phone = case when v_event.old_data ? 'phone' then nullif(v_event.old_data ->> 'phone','') else phone end,
        website = case when v_event.old_data ? 'website' then nullif(v_event.old_data ->> 'website','') else website end,
        email = case when v_event.old_data ? 'email' then nullif(v_event.old_data ->> 'email','') else email end,
        price_level = case when v_event.old_data ? 'price_level' and (v_event.old_data ->> 'price_level') is not null then (v_event.old_data ->> 'price_level')::integer else price_level end
      where id = v_event.spot_id;

      if v_event.old_data ? 'owner_description' then
        update public.spot_descriptions set
          owner_description = nullif(v_event.old_data ->> 'owner_description',''),
          owner_keywords = coalesce(
            array(select jsonb_array_elements_text(v_event.old_data -> 'owner_keywords')),
            '{}'::text[]
          ),
          updated_at = now()
        where spot_id = v_event.spot_id;
      end if;
    elsif v_event.change_area = 'intelligence' then
      update public.spot_intelligence_v1 set
        best_for = coalesce(array(select jsonb_array_elements_text(v_event.old_data -> 'best_for')), '{}'::text[]),
        occasion_tags = coalesce(array(select jsonb_array_elements_text(v_event.old_data -> 'occasion_tags')), '{}'::text[]),
        atmosphere_tags = coalesce(array(select jsonb_array_elements_text(v_event.old_data -> 'atmosphere_tags')), '{}'::text[]),
        avoid_if_tags = coalesce(array(select jsonb_array_elements_text(v_event.old_data -> 'avoid_if_tags')), '{}'::text[]),
        good_for_time = coalesce(array(select jsonb_array_elements_text(v_event.old_data -> 'good_for_time')), '{}'::text[]),
        noise_level = nullif(v_event.old_data ->> 'noise_level',''),
        crowd_type = coalesce(array(select jsonb_array_elements_text(v_event.old_data -> 'crowd_type')), '{}'::text[]),
        dress_code = nullif(v_event.old_data ->> 'dress_code',''),
        reservation_recommended = case when v_event.old_data ? 'reservation_recommended' then (v_event.old_data ->> 'reservation_recommended')::boolean else null end,
        average_duration_minutes = case when nullif(v_event.old_data ->> 'average_duration_minutes','') is not null then (v_event.old_data ->> 'average_duration_minutes')::integer else null end,
        signature_items = coalesce(array(select jsonb_array_elements_text(v_event.old_data -> 'signature_items')), '{}'::text[]),
        special_notes = nullif(v_event.old_data ->> 'special_notes',''),
        updated_by = auth.uid(),
        updated_at = now()
      where spot_id = v_event.spot_id;
    elsif v_event.change_area = 'taxonomy' then
      select coalesce(array_agg(x::uuid), '{}'::uuid[])
      into v_ids
      from jsonb_array_elements_text(v_event.old_data -> 'taxonomy_node_ids') x;

      delete from public.spot_taxonomies
      where spot_id = v_event.spot_id and source = 'owner';

      insert into public.spot_taxonomies(
        spot_id, taxonomy_node_id, source, confidence,
        is_verified, created_by, verified_by, verified_at
      )
      select v_event.spot_id, unnest(v_ids), 'owner', 1.000, true,
             auth.uid(), auth.uid(), now();
    end if;
  end if;

  update public.spot_owner_change_events set
    moderation_status = v_decision,
    moderation_note = nullif(trim(coalesce(p_note, '')), ''),
    reviewed_by = auth.uid(),
    reviewed_at = now(),
    reverted_at = case when v_decision = 'reverted' then now() else reverted_at end
  where id = p_event_id;

  return jsonb_build_object(
    'ok', true,
    'event_id', p_event_id,
    'decision', v_decision
  );
end;
$$;

ALTER FUNCTION "public"."admin_review_spot_owner_change_v1"("p_event_id" "uuid", "p_decision" "text", "p_note" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_set_spot_owner_v1"("p_spot_id" "uuid", "p_owner_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.admin_is_admin_v1() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  update public.spots
  set owner_id = p_owner_id
  where id = p_spot_id;
end;
$$;

ALTER FUNCTION "public"."admin_set_spot_owner_v1"("p_spot_id" "uuid", "p_owner_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_set_taxonomy_synonyms_v1"("p_taxonomy_node_id" "uuid", "p_synonyms" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare n integer;
begin
  if coalesce(public.admin_is_admin_v1(), false) is not true then
    raise exception 'admin access required' using errcode='42501';
  end if;
  delete from public.taxonomy_synonyms where taxonomy_node_id=p_taxonomy_node_id;
  insert into public.taxonomy_synonyms(taxonomy_node_id,locale,synonym,normalized_synonym,weight)
  select p_taxonomy_node_id,
         case when lower(coalesce(x->>'locale','de'))='en' then 'en' else 'de' end,
         trim(x->>'synonym'),lower(trim(x->>'synonym')),
         greatest(0.1,least(5,coalesce((x->>'weight')::numeric,1)))
  from jsonb_array_elements(coalesce(p_synonyms,'[]'::jsonb)) x
  where nullif(trim(x->>'synonym'),'') is not null;
  get diagnostics n=row_count;
  return n;
end $$;

ALTER FUNCTION "public"."admin_set_taxonomy_synonyms_v1"("p_taxonomy_node_id" "uuid", "p_synonyms" "jsonb") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_spot_detail_intelligence_v1"("p_spot_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare r jsonb;
begin
 if not coalesce(public.admin_is_admin_v1(),false) then raise exception 'not_authorized' using errcode='42501'; end if;
 select jsonb_build_object('spot',(select to_jsonb(x) from(select id,name,city,status,owner_id,header_photo_path from public.spots where id=p_spot_id)x),'metrics',jsonb_build_object('views',(select count(*) from public.analytics_events where spot_id=p_spot_id and occurred_at>=p_from and occurred_at<p_to and event_name in('spot_opened','spot_detail_opened','decision_spot_opened','map_spot_opened','feed_spot_opened','profile_spot_opened','profile_favorite_spot_opened','nearby_spot_opened')),'users',(select count(distinct user_id) from public.analytics_events where spot_id=p_spot_id and occurred_at>=p_from and occurred_at<p_to),'decision_impressions',(select count(*) from public.analytics_events where spot_id=p_spot_id and event_name='decision_spot_impression' and occurred_at>=p_from and occurred_at<p_to),'decision_opens',(select count(*) from public.analytics_events where spot_id=p_spot_id and event_name='decision_spot_opened' and occurred_at>=p_from and occurred_at<p_to),'ctr',(select case when count(*) filter(where event_name='decision_spot_impression')>0 then round(count(*) filter(where event_name='decision_spot_opened')*100.0/count(*) filter(where event_name='decision_spot_impression'),1) else 0 end from public.analytics_events where spot_id=p_spot_id and occurred_at>=p_from and occurred_at<p_to),'reviews',(select count(*) from public.reviews where spot_id=p_spot_id and created_at>=p_from and created_at<p_to),'favorites',(select count(*) from public.favorites where spot_id=p_spot_id),'route_clicks',(select count(*) from public.analytics_events where spot_id=p_spot_id and event_name='spot_route_clicked' and occurred_at>=p_from and occurred_at<p_to),'website_clicks',(select count(*) from public.analytics_events where spot_id=p_spot_id and event_name='spot_website_clicked' and occurred_at>=p_from and occurred_at<p_to),'phone_clicks',(select count(*) from public.analytics_events where spot_id=p_spot_id and event_name='spot_phone_clicked' and occurred_at>=p_from and occurred_at<p_to)),'sources',coalesce((select jsonb_agg(to_jsonb(x)) from(select coalesce(properties->>'source',screen_name,'direct')source,count(*)views from public.analytics_events where spot_id=p_spot_id and occurred_at>=p_from and occurred_at<p_to group by 1 order by 2 desc)x),'[]'::jsonb),'daily',coalesce((select jsonb_agg(to_jsonb(x) order by x.metric_day) from(select date_trunc('day',occurred_at)::date as metric_day,count(*) as views,count(distinct user_id) as users from public.analytics_events where spot_id=p_spot_id and occurred_at>=p_from and occurred_at<p_to group by 1)x),'[]'::jsonb)) into r;return r;
end$$;

ALTER FUNCTION "public"."admin_spot_detail_intelligence_v1"("p_spot_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_spot_quality_v1"("p_limit" integer DEFAULT 250, "p_offset" integer DEFAULT 0, "p_search" "text" DEFAULT NULL::"text", "p_issue" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = auth.uid()
      and coalesce(p.is_admin, false) = true
  ) then
    raise exception 'Admin access required';
  end if;

  with
  photo_stats as (
    select
      sp.spot_id,
      count(*) filter (
        where sp.url is not null
          and btrim(sp.url) <> ''
      )::integer as photo_count
    from public.spot_photos sp
    group by sp.spot_id
  ),
  hour_stats as (
    select
      sh.spot_id,
      count(*) filter (
        where sh.open_time is not null
          and sh.close_time is not null
      )::integer as opening_slot_count
    from public.spot_hours sh
    group by sh.spot_id
  ),
  description_stats as (
    select
      sd.spot_id,
      (
        coalesce(nullif(btrim(sd.owner_description), ''), '') <> ''
        or coalesce(nullif(btrim(sd.enriched_description), ''), '') <> ''
      ) as has_description,
      (
        coalesce(array_length(sd.owner_keywords, 1), 0) > 0
        or coalesce(array_length(sd.enriched_keywords, 1), 0) > 0
      ) as has_keywords
    from public.spot_descriptions sd
  ),
  taxonomy_stats as (
    select
      st.spot_id,
      count(*)::integer as taxonomy_count,
      count(*) filter (
        where coalesce(st.is_verified, false) = true
      )::integer as verified_taxonomy_count
    from public.spot_taxonomies st
    group by st.spot_id
  ),
  normalized as (
    select
      s.*,
      lower(
        regexp_replace(
          unaccent(coalesce(s.name, '')),
          '[^a-zA-Z0-9]+',
          '',
          'g'
        )
      ) as normalized_name,
      lower(
        regexp_replace(
          unaccent(coalesce(s.address, '')),
          '[^a-zA-Z0-9]+',
          '',
          'g'
        )
      ) as normalized_address
    from public.spots s
  ),
  duplicate_stats as (
    select
      n.id as spot_id,
      (
        n.google_place_id is not null
        and exists (
          select 1
          from normalized other
          where other.id <> n.id
            and other.google_place_id = n.google_place_id
        )
      ) as duplicate_google_place_id,
      (
        n.normalized_name <> ''
        and n.normalized_address <> ''
        and exists (
          select 1
          from normalized other
          where other.id <> n.id
            and other.normalized_name = n.normalized_name
            and other.normalized_address = n.normalized_address
        )
      ) as duplicate_name_address
    from normalized n
  ),
  scored as (
    select
      s.id,
      s.name,
      s.address,
      s.city,
      s.country,
      s.status,
      s.lat,
      s.lng,
      s.category_id,
      s.website,
      s.phone,
      s.price_level,
      s.header_photo_path,
      s.google_place_id,
      coalesce(s.google_photo_enabled, true) as google_photo_enabled,
      s.created_at,

      coalesce(ps.photo_count, 0) as photo_count,
      coalesce(hs.opening_slot_count, 0) as opening_slot_count,
      coalesce(ds.has_description, false) as has_description,
      coalesce(ds.has_keywords, false) as has_keywords,
      coalesce(ts.taxonomy_count, 0) as taxonomy_count,
      coalesce(ts.verified_taxonomy_count, 0) as verified_taxonomy_count,
      coalesce(dup.duplicate_google_place_id, false) as duplicate_google_place_id,
      coalesce(dup.duplicate_name_address, false) as duplicate_name_address,

      (
        case when coalesce(nullif(btrim(s.name), ''), '') <> '' then 5 else 0 end
        + case when coalesce(nullif(btrim(s.address), ''), '') <> '' then 10 else 0 end
        + case when s.lat is not null and s.lng is not null then 10 else 0 end
        + case when s.category_id is not null then 5 else 0 end
        + case when coalesce(nullif(btrim(s.google_place_id), ''), '') <> '' then 10 else 0 end
        + case
            when coalesce(nullif(btrim(s.header_photo_path), ''), '') <> ''
              or coalesce(ps.photo_count, 0) > 0
              then 15
            when coalesce(nullif(btrim(s.google_place_id), ''), '') <> ''
              and coalesce(s.google_photo_enabled, true) = true
              then 8
            else 0
          end
        + case when coalesce(ds.has_description, false) then 10 else 0 end
        + case when coalesce(hs.opening_slot_count, 0) > 0 then 10 else 0 end
        + case when coalesce(nullif(btrim(s.website), ''), '') <> '' then 5 else 0 end
        + case when coalesce(nullif(btrim(s.phone), ''), '') <> '' then 3 else 0 end
        + case
            when coalesce(ts.taxonomy_count, 0) >= 8 then 12
            when coalesce(ts.taxonomy_count, 0) >= 4 then 8
            when coalesce(ts.taxonomy_count, 0) >= 1 then 4
            else 0
          end
        + case when s.status = 'approved' then 5 else 0 end
      )::integer as quality_score
    from public.spots s
    left join photo_stats ps on ps.spot_id = s.id
    left join hour_stats hs on hs.spot_id = s.id
    left join description_stats ds on ds.spot_id = s.id
    left join taxonomy_stats ts on ts.spot_id = s.id
    left join duplicate_stats dup on dup.spot_id = s.id
  ),
  enriched as (
    select
      scored.*,
      jsonb_strip_nulls(
        jsonb_build_object(
          'missing_google_place_id',
            case
              when google_place_id is null or btrim(google_place_id) = ''
              then jsonb_build_object(
                'key', 'missing_google_place_id',
                'label', 'Google Place ID fehlt',
                'severity', 'high',
                'points', 10
              )
            end,
          'missing_photo',
            case
              when (
                coalesce(nullif(btrim(header_photo_path), ''), '') = ''
                and photo_count = 0
                and (
                  google_place_id is null
                  or btrim(google_place_id) = ''
                  or google_photo_enabled = false
                )
              )
              then jsonb_build_object(
                'key', 'missing_photo',
                'label', 'Kein Bild verfügbar',
                'severity', 'high',
                'points', 15
              )
            end,
          'missing_description',
            case
              when has_description = false
              then jsonb_build_object(
                'key', 'missing_description',
                'label', 'Beschreibung fehlt',
                'severity', 'high',
                'points', 10
              )
            end,
          'missing_opening_hours',
            case
              when opening_slot_count = 0
              then jsonb_build_object(
                'key', 'missing_opening_hours',
                'label', 'Öffnungszeiten fehlen',
                'severity', 'high',
                'points', 10
              )
            end,
          'missing_taxonomies',
            case
              when taxonomy_count < 4
              then jsonb_build_object(
                'key', 'missing_taxonomies',
                'label',
                  case
                    when taxonomy_count = 0
                    then 'Taxonomien fehlen'
                    else 'Zu wenige Taxonomien'
                  end,
                'severity', 'medium',
                'points',
                  case
                    when taxonomy_count = 0 then 12
                    else 8
                  end
              )
            end,
          'missing_coordinates',
            case
              when lat is null or lng is null
              then jsonb_build_object(
                'key', 'missing_coordinates',
                'label', 'Koordinaten fehlen',
                'severity', 'high',
                'points', 10
              )
            end,
          'missing_category',
            case
              when category_id is null
              then jsonb_build_object(
                'key', 'missing_category',
                'label', 'Kategorie fehlt',
                'severity', 'medium',
                'points', 5
              )
            end,
          'missing_website',
            case
              when website is null or btrim(website) = ''
              then jsonb_build_object(
                'key', 'missing_website',
                'label', 'Website fehlt',
                'severity', 'low',
                'points', 5
              )
            end,
          'missing_phone',
            case
              when phone is null or btrim(phone) = ''
              then jsonb_build_object(
                'key', 'missing_phone',
                'label', 'Telefonnummer fehlt',
                'severity', 'low',
                'points', 3
              )
            end,
          'not_approved',
            case
              when status is distinct from 'approved'
              then jsonb_build_object(
                'key', 'not_approved',
                'label', 'Spot ist nicht approved',
                'severity', 'medium',
                'points', 5
              )
            end,
          'possible_duplicate',
            case
              when duplicate_google_place_id or duplicate_name_address
              then jsonb_build_object(
                'key', 'possible_duplicate',
                'label', 'Mögliches Duplikat',
                'severity', 'critical',
                'points', 0
              )
            end
        )
      ) as issue_map
    from scored
  ),
  filtered as (
    select *
    from enriched e
    where (
      p_search is null
      or btrim(p_search) = ''
      or e.name ilike '%' || p_search || '%'
      or coalesce(e.address, '') ilike '%' || p_search || '%'
      or coalesce(e.city, '') ilike '%' || p_search || '%'
    )
    and (
      p_issue is null
      or btrim(p_issue) = ''
      or p_issue = 'all'
      or e.issue_map ? p_issue
      or (
        p_issue = 'low_quality'
        and e.quality_score < 70
      )
    )
  ),
  summary as (
    select jsonb_build_object(
      'total', count(*),
      'excellent', count(*) filter (where quality_score >= 90),
      'good', count(*) filter (where quality_score between 75 and 89),
      'needs_work', count(*) filter (where quality_score between 50 and 74),
      'critical', count(*) filter (where quality_score < 50),
      'missing_google_place_id',
        count(*) filter (where issue_map ? 'missing_google_place_id'),
      'missing_photo',
        count(*) filter (where issue_map ? 'missing_photo'),
      'missing_description',
        count(*) filter (where issue_map ? 'missing_description'),
      'missing_opening_hours',
        count(*) filter (where issue_map ? 'missing_opening_hours'),
      'missing_taxonomies',
        count(*) filter (where issue_map ? 'missing_taxonomies'),
      'possible_duplicates',
        count(*) filter (where issue_map ? 'possible_duplicate'),
      'average_score',
        coalesce(round(avg(quality_score)::numeric, 1), 0)
    ) as payload
    from enriched
  ),
  page_rows as (
    select *
    from filtered
    order by
      (issue_map ? 'possible_duplicate') desc,
      quality_score asc,
      created_at desc
    limit greatest(1, least(coalesce(p_limit, 250), 1000))
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'summary', (select payload from summary),
    'rows', coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'spot_id', p.id,
            'name', p.name,
            'address', p.address,
            'city', p.city,
            'country', p.country,
            'status', p.status,
            'quality_score', p.quality_score,
            'photo_count', p.photo_count,
            'opening_slot_count', p.opening_slot_count,
            'has_description', p.has_description,
            'has_keywords', p.has_keywords,
            'taxonomy_count', p.taxonomy_count,
            'verified_taxonomy_count', p.verified_taxonomy_count,
            'google_place_id', p.google_place_id,
            'google_photo_enabled', p.google_photo_enabled,
            'duplicate_google_place_id', p.duplicate_google_place_id,
            'duplicate_name_address', p.duplicate_name_address,
            'issues', (
              select coalesce(jsonb_agg(value), '[]'::jsonb)
              from jsonb_each(p.issue_map)
            ),
            'created_at', p.created_at
          )
          order by
            (p.issue_map ? 'possible_duplicate') desc,
            p.quality_score asc,
            p.created_at desc
        )
        from page_rows p
      ),
      '[]'::jsonb
    )
  )
  into v_result;

  return v_result;
end;
$$;

ALTER FUNCTION "public"."admin_spot_quality_v1"("p_limit" integer, "p_offset" integer, "p_search" "text", "p_issue" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_spots_intelligence_v1"("p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_limit" integer DEFAULT 500, "p_offset" integer DEFAULT 0, "p_search" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare r jsonb;
begin
 if not coalesce(public.admin_is_admin_v1(),false) then raise exception 'not_authorized' using errcode='42501'; end if;
 with b as(select s.id spot_id,s.name,s.city,s.status,(s.owner_id is not null)partner,
 count(e.id) filter(where e.occurred_at>=p_from and e.occurred_at<p_to and e.event_name in('spot_opened','spot_detail_opened','decision_spot_opened','map_spot_opened','feed_spot_opened','profile_spot_opened','profile_favorite_spot_opened','nearby_spot_opened'))views,
 count(distinct e.user_id) filter(where e.occurred_at>=p_from and e.occurred_at<p_to)users,
 count(e.id) filter(where e.occurred_at>=p_from and e.occurred_at<p_to and e.event_name='decision_spot_impression')decision_impressions,
 count(e.id) filter(where e.occurred_at>=p_from and e.occurred_at<p_to and e.event_name='decision_spot_opened')decision_opens,
 count(distinct rv.id) filter(where rv.created_at>=p_from and rv.created_at<p_to)reviews,
 count(distinct f.user_id)favorites,
 count(e.id) filter(where e.occurred_at>=p_from and e.occurred_at<p_to and e.event_name='spot_route_clicked')route_clicks,
 count(e.id) filter(where e.occurred_at>=p_from and e.occurred_at<p_to and e.event_name='spot_website_clicked')website_clicks,
 count(e.id) filter(where e.occurred_at>=p_from and e.occurred_at<p_to and e.event_name='spot_phone_clicked')phone_clicks
 from public.spots s left join public.analytics_events e on e.spot_id=s.id left join public.reviews rv on rv.spot_id=s.id left join public.favorites f on f.spot_id=s.id where p_search is null or concat_ws(' ',s.name,s.city) ilike '%'||p_search||'%' group by s.id,s.name,s.city,s.status,s.owner_id), page as(select *,case when decision_impressions>0 then round(decision_opens*100.0/decision_impressions,1) else 0 end ctr from b order by views desc,name limit greatest(1,least(p_limit,2000)) offset greatest(p_offset,0))
 select jsonb_build_object('summary',jsonb_build_object('spots',(select count(*) from b),'viewed',(select count(*) from b where views>0),'partner_spots',(select count(*) from b where partner),'views',(select coalesce(sum(views),0) from b)),'spots',coalesce((select jsonb_agg(to_jsonb(page)) from page),'[]'::jsonb)) into r;return r;
end$$;

ALTER FUNCTION "public"."admin_spots_intelligence_v1"("p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_limit" integer, "p_offset" integer, "p_search" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_system_intelligence_v1"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  result jsonb;
  v_events bigint := 0;
  v_sessions bigint := 0;
  v_errors bigint := 0;
  v_users bigint := 0;
  v_installations bigint := 0;
  v_last_event timestamptz;
  v_last_session timestamptz;
  v_last_error timestamptz;
  v_error_rate numeric := 0;
begin
  if not public.admin_is_admin_v1() then
    raise exception 'not_authorized' using errcode = '42501';
  end if;

  select count(*), max(occurred_at)
    into v_events, v_last_event
  from public.analytics_events
  where occurred_at >= p_from and occurred_at < p_to;

  select count(*), max(last_seen_at)
    into v_sessions, v_last_session
  from public.analytics_sessions
  where started_at >= p_from and started_at < p_to;

  select count(*), max(occurred_at)
    into v_errors, v_last_error
  from public.analytics_errors
  where occurred_at >= p_from and occurred_at < p_to;

  select count(distinct user_id)
    into v_users
  from public.analytics_events
  where occurred_at >= p_from and occurred_at < p_to
    and user_id is not null;

  select count(*)
    into v_installations
  from public.analytics_installations
  where first_seen_at < p_to;

  v_error_rate := case when v_sessions > 0
    then round(v_errors * 100.0 / v_sessions, 2)
    else 0 end;

  with daily as (
    select
      d::date as metric_day,
      coalesce(e.events, 0) as events,
      coalesce(e.users, 0) as users,
      coalesce(s.sessions, 0) as sessions,
      coalesce(er.errors, 0) as errors
    from generate_series(
      date_trunc('day', p_from),
      date_trunc('day', p_to - interval '1 millisecond'),
      interval '1 day'
    ) d
    left join (
      select date_trunc('day', occurred_at)::date as metric_day,
             count(*) as events,
             count(distinct user_id) filter (where user_id is not null) as users
      from public.analytics_events
      where occurred_at >= p_from and occurred_at < p_to
      group by 1
    ) e on e.metric_day = d::date
    left join (
      select date_trunc('day', started_at)::date as metric_day,
             count(*) as sessions
      from public.analytics_sessions
      where started_at >= p_from and started_at < p_to
      group by 1
    ) s on s.metric_day = d::date
    left join (
      select date_trunc('day', occurred_at)::date as metric_day,
             count(*) as errors
      from public.analytics_errors
      where occurred_at >= p_from and occurred_at < p_to
      group by 1
    ) er on er.metric_day = d::date
    order by d
  ),
  versions as (
    select
      coalesce(nullif(app_version,''), 'unknown') as app_version,
      count(*) as events,
      count(distinct user_id) filter (where user_id is not null) as users,
      max(occurred_at) as last_seen
    from public.analytics_events
    where occurred_at >= p_from and occurred_at < p_to
    group by 1
    order by events desc
    limit 20
  ),
  platforms as (
    select
      coalesce(nullif(platform,''), 'unknown') as platform,
      count(*) as events,
      count(distinct user_id) filter (where user_id is not null) as users,
      count(distinct installation_id) filter (where installation_id is not null) as installations
    from public.analytics_events
    where occurred_at >= p_from and occurred_at < p_to
    group by 1
    order by events desc
  ),
  top_events as (
    select event_name, count(*) as occurrences,
           count(distinct user_id) filter (where user_id is not null) as users
    from public.analytics_events
    where occurred_at >= p_from and occurred_at < p_to
    group by event_name
    order by occurrences desc
    limit 20
  ),
  recent_errors as (
    select id, fingerprint, error_type, message, severity, screen_name,
           platform, app_version, handled, occurred_at
    from public.analytics_errors
    where occurred_at >= p_from and occurred_at < p_to
    order by occurred_at desc
    limit 15
  ),
  table_health as (
    select * from (values
      ('analytics_events', (select count(*)::bigint from public.analytics_events), pg_total_relation_size('public.analytics_events'::regclass)),
      ('analytics_sessions', (select count(*)::bigint from public.analytics_sessions), pg_total_relation_size('public.analytics_sessions'::regclass)),
      ('analytics_errors', (select count(*)::bigint from public.analytics_errors), pg_total_relation_size('public.analytics_errors'::regclass)),
      ('analytics_installations', (select count(*)::bigint from public.analytics_installations), pg_total_relation_size('public.analytics_installations'::regclass)),
      ('reviews', (select count(*)::bigint from public.reviews), pg_total_relation_size('public.reviews'::regclass)),
      ('spots', (select count(*)::bigint from public.spots), pg_total_relation_size('public.spots'::regclass)),
      ('profiles', (select count(*)::bigint from public.profiles), pg_total_relation_size('public.profiles'::regclass))
    ) as t(table_name, row_count, size_bytes)
  ),
  insights as (
    select * from (
      select 1 as sort_order,
        case when v_last_event is null then 'critical'
             when v_last_event < now() - interval '24 hours' then 'warning'
             else 'good' end as tone,
        'Event-Ingestion'::text as title,
        case when v_last_event is null then 'Im gewählten Zeitraum wurden keine Analytics-Events erfasst.'
             when v_last_event < now() - interval '24 hours' then 'Das letzte Event ist älter als 24 Stunden. Mobile Tracking und App-Nutzung prüfen.'
             else 'Analytics-Events laufen aktuell und die Datenpipeline ist frisch.' end as body
      union all
      select 2,
        case when v_error_rate >= 10 then 'critical' when v_error_rate >= 3 then 'warning' else 'good' end,
        'Fehlerquote',
        case when v_sessions = 0 then 'Noch keine Sessions im gewählten Zeitraum.'
             else format('%s Fehler je 100 Sessions. %s Fehler bei %s Sessions.', v_error_rate, v_errors, v_sessions) end
      union all
      select 3,
        case when v_users = 0 then 'warning' else 'info' end,
        'Aktive Nutzer',
        case when v_users = 0 then 'Keine identifizierten aktiven Nutzer im gewählten Zeitraum.'
             else format('%s identifizierte Nutzer haben %s Events erzeugt.', v_users, v_events) end
      union all
      select 4,
        case when v_installations = 0 then 'warning' else 'info' end,
        'Installationsbasis',
        format('%s Geräteinstallationen sind aktuell registriert.', v_installations)
    ) i
    order by sort_order
  )
  select jsonb_build_object(
    'generated_at', now(),
    'summary', jsonb_build_object(
      'events', v_events,
      'sessions', v_sessions,
      'active_users', v_users,
      'errors', v_errors,
      'error_rate', v_error_rate,
      'installations', v_installations,
      'last_event_at', v_last_event,
      'last_session_at', v_last_session,
      'last_error_at', v_last_error
    ),
    'daily', coalesce((select jsonb_agg(to_jsonb(x) order by x.metric_day) from daily x), '[]'::jsonb),
    'versions', coalesce((select jsonb_agg(to_jsonb(x)) from versions x), '[]'::jsonb),
    'platforms', coalesce((select jsonb_agg(to_jsonb(x)) from platforms x), '[]'::jsonb),
    'top_events', coalesce((select jsonb_agg(to_jsonb(x)) from top_events x), '[]'::jsonb),
    'recent_errors', coalesce((select jsonb_agg(to_jsonb(x)) from recent_errors x), '[]'::jsonb),
    'tables', coalesce((select jsonb_agg(to_jsonb(x)) from table_health x), '[]'::jsonb),
    'insights', coalesce((select jsonb_agg(to_jsonb(x)) from insights x), '[]'::jsonb)
  ) into result;

  return result;
end;
$$;

ALTER FUNCTION "public"."admin_system_intelligence_v1"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_update_data_rights_request_v1"("p_request_id" "uuid", "p_status" "text", "p_admin_note" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if auth.uid() is null or not public.consent_is_admin_v1() then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  if p_status not in ('requested', 'processing', 'ready', 'scheduled',
                      'completed', 'cancelled', 'rejected', 'failed') then
    raise exception 'invalid_status' using errcode = '22023';
  end if;

  update public.data_rights_requests r
  set
    status = p_status,
    admin_note = nullif(btrim(p_admin_note), ''),
    processing_started_at = case
      when p_status = 'processing' and r.processing_started_at is null
        then now()
      else r.processing_started_at
    end,
    completed_at = case
      when p_status = 'completed' then now()
      else r.completed_at
    end
  where r.id = p_request_id;

  return found;
end;
$$;

ALTER FUNCTION "public"."admin_update_data_rights_request_v1"("p_request_id" "uuid", "p_status" "text", "p_admin_note" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_update_error_group_v1"("p_fingerprint" "text", "p_status" "text", "p_internal_note" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
begin
 if not coalesce(public.admin_is_admin_v1(),false) then raise exception 'not_authorized' using errcode='42501'; end if;
 if p_status not in ('open','watching','resolved') then raise exception 'invalid_status'; end if;
 insert into public.analytics_error_groups(fingerprint,status,internal_note,resolved_at,resolved_by,updated_at)
 values(p_fingerprint,p_status,p_internal_note,case when p_status='resolved' then now() else null end,case when p_status='resolved' then auth.uid() else null end,now())
 on conflict(fingerprint) do update set status=excluded.status,internal_note=excluded.internal_note,resolved_at=excluded.resolved_at,resolved_by=excluded.resolved_by,updated_at=now();
end$$;

ALTER FUNCTION "public"."admin_update_error_group_v1"("p_fingerprint" "text", "p_status" "text", "p_internal_note" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_upsert_legal_document_draft_v1"("p_document_id" "uuid", "p_document_type" "text", "p_version" "text", "p_locale" "text", "p_title" "text", "p_summary" "text", "p_content_markdown" "text", "p_requires_acceptance" boolean, "p_requires_reacceptance" boolean, "p_change_summary" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_admin_id uuid := auth.uid();
  v_document_id uuid;
  v_hash text;
begin
  if v_admin_id is null or not public.consent_is_admin_v1() then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  if nullif(btrim(p_document_type), '') is null
    or nullif(btrim(p_version), '') is null
    or nullif(btrim(p_locale), '') is null
    or nullif(btrim(p_title), '') is null
    or nullif(btrim(p_content_markdown), '') is null
  then
    raise exception 'missing_required_document_fields' using errcode = '22023';
  end if;

  if p_document_type not in (
    'privacy_notice','terms_of_service','community_guidelines',
    'consent_information','marketing_information','location_information',
    'analytics_information','media_ai_information'
  ) then
    raise exception 'invalid_document_type' using errcode = '22023';
  end if;

  v_hash := public.legal_document_content_hash_v1(
    p_document_type,p_version,p_locale,p_title,p_summary,p_content_markdown,
    p_requires_acceptance,p_requires_reacceptance
  );

  if p_document_id is null then
    insert into public.legal_documents (
      document_type,version,locale,title,summary,content_markdown,content_hash,
      status,requires_acceptance,requires_reacceptance,change_summary,created_by
    )
    values (
      p_document_type,p_version,p_locale,p_title,p_summary,p_content_markdown,
      v_hash,'draft',p_requires_acceptance,p_requires_reacceptance,
      p_change_summary,v_admin_id
    )
    returning id into v_document_id;
  else
    update public.legal_documents
    set document_type=p_document_type,
        version=p_version,
        locale=p_locale,
        title=p_title,
        summary=p_summary,
        content_markdown=p_content_markdown,
        content_hash=v_hash,
        requires_acceptance=p_requires_acceptance,
        requires_reacceptance=p_requires_reacceptance,
        change_summary=p_change_summary
    where id=p_document_id and status='draft'
    returning id into v_document_id;

    if v_document_id is null then
      raise exception 'draft_not_found_or_not_editable' using errcode = '22023';
    end if;
  end if;

  return v_document_id;
end;
$$;

ALTER FUNCTION "public"."admin_upsert_legal_document_draft_v1"("p_document_id" "uuid", "p_document_type" "text", "p_version" "text", "p_locale" "text", "p_title" "text", "p_summary" "text", "p_content_markdown" "text", "p_requires_acceptance" boolean, "p_requires_reacceptance" boolean, "p_change_summary" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_upsert_taxonomy_node_v1"("p_id" "uuid", "p_slug" "text", "p_node_type" "text", "p_label_de" "text", "p_label_en" "text", "p_parent_id" "uuid" DEFAULT NULL::"uuid", "p_icon" "text" DEFAULT NULL::"text", "p_color" "text" DEFAULT NULL::"text", "p_sort_order" integer DEFAULT 0, "p_is_active" boolean DEFAULT true, "p_is_owner_selectable" boolean DEFAULT true, "p_category_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
begin
  if auth.uid() is null or not exists (
    select 1
    from public.profiles p
    where p.id = auth.uid()
      and coalesce(p.is_admin, false) = true
  ) then
    raise exception 'Admin access required.';
  end if;

  insert into public.taxonomy_nodes (
    id, slug, node_type, parent_id, icon, color, sort_order,
    is_active, is_owner_selectable, created_by
  )
  values (
    coalesce(p_id, gen_random_uuid()),
    lower(btrim(p_slug)),
    p_node_type,
    p_parent_id,
    p_icon,
    p_color,
    coalesce(p_sort_order, 0),
    coalesce(p_is_active, true),
    coalesce(p_is_owner_selectable, true),
    auth.uid()
  )
  on conflict (slug) do update
  set
    node_type = excluded.node_type,
    parent_id = excluded.parent_id,
    icon = excluded.icon,
    color = excluded.color,
    sort_order = excluded.sort_order,
    is_active = excluded.is_active,
    is_owner_selectable = excluded.is_owner_selectable,
    updated_at = now()
  returning id into v_id;

  insert into public.taxonomy_node_translations (
    taxonomy_node_id, locale, label
  )
  values
    (v_id, 'de', p_label_de),
    (v_id, 'en', coalesce(nullif(btrim(p_label_en), ''), p_label_de))
  on conflict (taxonomy_node_id, locale) do update
  set label = excluded.label, updated_at = now();

  delete from public.taxonomy_node_categories
  where taxonomy_node_id = v_id;

  if p_category_ids is not null then
    insert into public.taxonomy_node_categories (
      taxonomy_node_id, category_id
    )
    select v_id, x
    from (
      select distinct unnest(p_category_ids) as x
    ) q;
  end if;

  return v_id;
end;
$$;

ALTER FUNCTION "public"."admin_upsert_taxonomy_node_v1"("p_id" "uuid", "p_slug" "text", "p_node_type" "text", "p_label_de" "text", "p_label_en" "text", "p_parent_id" "uuid", "p_icon" "text", "p_color" "text", "p_sort_order" integer, "p_is_active" boolean, "p_is_owner_selectable" boolean, "p_category_ids" "uuid"[]) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_upsert_taxonomy_node_v2"("p_id" "uuid", "p_slug" "text", "p_node_type" "text", "p_parent_id" "uuid", "p_icon" "text", "p_color" "text", "p_sort_order" integer, "p_is_active" boolean, "p_is_owner_selectable" boolean, "p_ml_weight" numeric, "p_label_de" "text", "p_short_label_de" "text", "p_description_de" "text", "p_label_en" "text", "p_short_label_en" "text", "p_description_en" "text", "p_category_ids" "uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare v_id uuid; v_slug text:=lower(trim(p_slug)); v_type text:=lower(trim(p_node_type));
begin
  if coalesce(public.admin_is_admin_v1(), false) is not true then
    raise exception 'admin access required' using errcode='42501';
  end if;
  if v_slug is null or v_slug='' or v_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' then raise exception 'invalid slug'; end if;
  if v_type not in ('subcategory','feature','offering','service') then raise exception 'invalid node_type'; end if;
  if nullif(trim(p_label_de),'') is null then raise exception 'German label required'; end if;
  if coalesce(p_ml_weight,1)<0.1 or coalesce(p_ml_weight,1)>5 then raise exception 'ml_weight must be 0.1..5'; end if;
  if p_parent_id is not null and p_parent_id=p_id then raise exception 'node cannot be own parent'; end if;

  if p_id is null then
    insert into public.taxonomy_nodes(slug,node_type,parent_id,icon,color,sort_order,is_active,is_owner_selectable,ml_weight,created_by)
    values(v_slug,v_type,p_parent_id,nullif(trim(p_icon),''),nullif(trim(p_color),''),coalesce(p_sort_order,0),
           coalesce(p_is_active,true),coalesce(p_is_owner_selectable,true),coalesce(p_ml_weight,1),auth.uid())
    returning id into v_id;
  else
    update public.taxonomy_nodes set slug=v_slug,node_type=v_type,parent_id=p_parent_id,
      icon=nullif(trim(p_icon),''),color=nullif(trim(p_color),''),sort_order=coalesce(p_sort_order,0),
      is_active=coalesce(p_is_active,true),is_owner_selectable=coalesce(p_is_owner_selectable,true),
      ml_weight=coalesce(p_ml_weight,1),updated_at=now()
    where id=p_id returning id into v_id;
    if v_id is null then raise exception 'taxonomy node not found'; end if;
  end if;

  insert into public.taxonomy_node_translations(taxonomy_node_id,locale,label,short_label,description)
  values(v_id,'de',trim(p_label_de),nullif(trim(p_short_label_de),''),nullif(trim(p_description_de),''))
  on conflict(taxonomy_node_id,locale) do update set label=excluded.label,short_label=excluded.short_label,
    description=excluded.description,updated_at=now();

  if nullif(trim(p_label_en),'') is null then
    delete from public.taxonomy_node_translations where taxonomy_node_id=v_id and locale='en';
  else
    insert into public.taxonomy_node_translations(taxonomy_node_id,locale,label,short_label,description)
    values(v_id,'en',trim(p_label_en),nullif(trim(p_short_label_en),''),nullif(trim(p_description_en),''))
    on conflict(taxonomy_node_id,locale) do update set label=excluded.label,short_label=excluded.short_label,
      description=excluded.description,updated_at=now();
  end if;

  delete from public.taxonomy_node_categories where taxonomy_node_id=v_id;
  insert into public.taxonomy_node_categories(taxonomy_node_id,category_id)
  select v_id,x from unnest(coalesce(p_category_ids,'{}'::uuid[])) x on conflict do nothing;
  return v_id;
end $_$;

ALTER FUNCTION "public"."admin_upsert_taxonomy_node_v2"("p_id" "uuid", "p_slug" "text", "p_node_type" "text", "p_parent_id" "uuid", "p_icon" "text", "p_color" "text", "p_sort_order" integer, "p_is_active" boolean, "p_is_owner_selectable" boolean, "p_ml_weight" numeric, "p_label_de" "text", "p_short_label_de" "text", "p_description_de" "text", "p_label_en" "text", "p_short_label_en" "text", "p_description_en" "text", "p_category_ids" "uuid"[]) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_user_detail_intelligence_v1"("p_user_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare r jsonb;
begin
 if not coalesce(public.admin_is_admin_v1(),false) then raise exception 'not_authorized' using errcode='42501'; end if;
 select jsonb_build_object(
 'user',(select to_jsonb(x) from(select u.id user_id,u.email,p.display_name,p.username,p.avatar_url,p.city,p.country,u.created_at registered_at,(select max(z.t) from(values((select max(e.occurred_at) from public.analytics_events e where e.user_id=u.id)),((select max(s.last_seen_at) from public.analytics_sessions s where s.user_id=u.id)),((select max(rv.created_at) from public.reviews rv where rv.user_id=u.id)))z(t))last_active_at,(select platform from public.analytics_sessions where user_id=u.id order by last_seen_at desc limit 1)platform,(select app_version from public.analytics_sessions where user_id=u.id order by last_seen_at desc limit 1)app_version from auth.users u left join public.profiles p on p.id=u.id where u.id=p_user_id)x),
 'metrics',jsonb_build_object('sessions',(select count(*) from public.analytics_sessions where user_id=p_user_id and started_at>=p_from and started_at<p_to),'screen_views',(select count(*) from public.analytics_events where user_id=p_user_id and event_name='screen_view' and occurred_at>=p_from and occurred_at<p_to),'spot_opens',(select count(*) from public.analytics_events where user_id=p_user_id and spot_id is not null and occurred_at>=p_from and occurred_at<p_to),'decisions',(select count(*) from public.decision_sessions where user_id=p_user_id and created_at>=p_from and created_at<p_to),'reviews',(select count(*) from public.reviews where user_id=p_user_id and created_at>=p_from and created_at<p_to),'favorites',(select count(*) from public.favorites where user_id=p_user_id)),
 'timeline',coalesce((select jsonb_agg(to_jsonb(t) order by occurred_at desc) from(select 'event'::text kind,e.event_name name,e.screen_name,e.spot_id,s.name spot_name,e.occurred_at,e.properties from public.analytics_events e left join public.spots s on s.id=e.spot_id where e.user_id=p_user_id and e.occurred_at>=p_from and e.occurred_at<p_to union all select 'review','review_created',null,r.spot_id,s.name,r.created_at,jsonb_build_object('review_id',r.id) from public.reviews r left join public.spots s on s.id=r.spot_id where r.user_id=p_user_id and r.created_at>=p_from and r.created_at<p_to)t limit 300),'[]'::jsonb)
 ) into r; return r;
end$$;

ALTER FUNCTION "public"."admin_user_detail_intelligence_v1"("p_user_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."admin_users_intelligence_v1"("p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_limit" integer DEFAULT 250, "p_offset" integer DEFAULT 0, "p_search" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare r jsonb;
begin
 if not coalesce(public.admin_is_admin_v1(),false) then raise exception 'not_authorized' using errcode='42501'; end if;
 with base as (
  select u.id user_id,u.email,p.display_name,p.username,p.avatar_url,p.city,u.created_at registered_at,
   greatest(max(e.occurred_at),max(s.last_seen_at),max(rv.created_at),max(ds.created_at)) last_active_at,
   count(distinct s.id) filter(where s.started_at>=p_from and s.started_at<p_to) sessions,
   count(distinct e.id) filter(where e.event_name='screen_view' and e.occurred_at>=p_from and e.occurred_at<p_to) screen_views,
   count(distinct e.id) filter(where e.event_name in('spot_opened','spot_detail_opened','decision_spot_opened','map_spot_opened','feed_spot_opened','profile_spot_opened','profile_favorite_spot_opened','nearby_spot_opened') and e.occurred_at>=p_from and e.occurred_at<p_to) spot_opens,
   count(distinct ds.id) filter(where ds.created_at>=p_from and ds.created_at<p_to) decisions,
   count(distinct rv.id) filter(where rv.created_at>=p_from and rv.created_at<p_to) reviews,
   (exists(select 1 from public.analytics_events ax where ax.user_id=u.id and ax.occurred_at<u.created_at+interval '7 days' and ax.event_name in('spot_opened','spot_detail_opened','decision_started','review_submitted')) or exists(select 1 from public.reviews rx where rx.user_id=u.id and rx.created_at<u.created_at+interval '7 days')) activated,
   (array_agg(s.platform order by s.last_seen_at desc) filter(where s.platform is not null))[1] platform,
   (array_agg(s.app_version order by s.last_seen_at desc) filter(where s.app_version is not null))[1] app_version
  from auth.users u left join public.profiles p on p.id=u.id left join public.analytics_sessions s on s.user_id=u.id left join public.analytics_events e on e.user_id=u.id left join public.reviews rv on rv.user_id=u.id left join public.decision_sessions ds on ds.user_id=u.id
  where u.deleted_at is null and (p_search is null or concat_ws(' ',u.email,p.display_name,p.username,p.city,u.id::text) ilike '%'||p_search||'%')
  group by u.id,u.email,p.display_name,p.username,p.avatar_url,p.city,u.created_at
 ), page as (select * from base order by coalesce(last_active_at,registered_at) desc limit greatest(1,least(p_limit,1000)) offset greatest(p_offset,0))
 select jsonb_build_object('summary',jsonb_build_object('registered',(select count(*) from base),'active',(select count(*) from base where last_active_at>=p_from and last_active_at<p_to),'activated',(select count(*) from base where activated),'sessions',(select coalesce(sum(sessions),0) from base)),'total',(select count(*) from base),'users',coalesce((select jsonb_agg(to_jsonb(page)) from page),'[]'::jsonb)) into r;
 return r;
end$$;

ALTER FUNCTION "public"."admin_users_intelligence_v1"("p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_limit" integer, "p_offset" integer, "p_search" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."analytics_register_installation_v1"("p_installation_id" "uuid", "p_platform" "text" DEFAULT NULL::"text", "p_app_version" "text" DEFAULT NULL::"text", "p_build_number" "text" DEFAULT NULL::"text", "p_device_model" "text" DEFAULT NULL::"text", "p_os_version" "text" DEFAULT NULL::"text", "p_locale" "text" DEFAULT NULL::"text", "p_country" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_properties" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
begin
  insert into public.analytics_installations(
    installation_id, user_id, platform, app_version, build_number,
    device_model, os_version, locale, country, city, properties
  ) values (
    p_installation_id, auth.uid(), p_platform, p_app_version, p_build_number,
    p_device_model, p_os_version, p_locale, p_country, p_city,
    coalesce(p_properties, '{}'::jsonb)
  )
  on conflict (installation_id) do update
  set user_id = coalesce(auth.uid(), analytics_installations.user_id),
      platform = coalesce(excluded.platform, analytics_installations.platform),
      app_version = coalesce(excluded.app_version, analytics_installations.app_version),
      build_number = coalesce(excluded.build_number, analytics_installations.build_number),
      device_model = coalesce(excluded.device_model, analytics_installations.device_model),
      os_version = coalesce(excluded.os_version, analytics_installations.os_version),
      locale = coalesce(excluded.locale, analytics_installations.locale),
      country = coalesce(excluded.country, analytics_installations.country),
      city = coalesce(excluded.city, analytics_installations.city),
      properties = analytics_installations.properties || excluded.properties,
      last_seen_at = now();
end;
$$;

