CREATE OR REPLACE FUNCTION "public"."analytics_report_error_v1"("p_message" "text", "p_session_id" "uuid" DEFAULT NULL::"uuid", "p_installation_id" "uuid" DEFAULT NULL::"uuid", "p_fingerprint" "text" DEFAULT NULL::"text", "p_error_type" "text" DEFAULT 'app_error'::"text", "p_stack" "text" DEFAULT NULL::"text", "p_screen_name" "text" DEFAULT NULL::"text", "p_severity" "text" DEFAULT 'error'::"text", "p_platform" "text" DEFAULT NULL::"text", "p_app_version" "text" DEFAULT NULL::"text", "p_handled" boolean DEFAULT true, "p_context" "jsonb" DEFAULT '{}'::"jsonb", "p_occurred_at" timestamp with time zone DEFAULT "now"()) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_id bigint;
begin
  if nullif(trim(p_message), '') is null then
    raise exception 'message is required';
  end if;

  insert into public.analytics_errors(
    user_id, session_id, installation_id, fingerprint, error_type,
    message, stack, screen_name, severity, platform, app_version,
    handled, context, occurred_at
  ) values (
    auth.uid(), p_session_id, p_installation_id, nullif(trim(p_fingerprint), ''),
    coalesce(nullif(trim(p_error_type), ''), 'app_error'), trim(p_message),
    p_stack, nullif(trim(p_screen_name), ''),
    case when p_severity in ('info','warning','error','fatal') then p_severity else 'error' end,
    nullif(trim(p_platform), ''), nullif(trim(p_app_version), ''),
    coalesce(p_handled, true), coalesce(p_context, '{}'::jsonb),
    coalesce(p_occurred_at, now())
  ) returning id into v_id;

  return v_id;
end;
$$;

