CREATE OR REPLACE FUNCTION "public"."analytics_track_event_v1"("p_event_name" "text", "p_session_id" "uuid" DEFAULT NULL::"uuid", "p_installation_id" "uuid" DEFAULT NULL::"uuid", "p_screen_name" "text" DEFAULT NULL::"text", "p_entity_type" "text" DEFAULT NULL::"text", "p_entity_id" "uuid" DEFAULT NULL::"uuid", "p_spot_id" "uuid" DEFAULT NULL::"uuid", "p_decision_id" "uuid" DEFAULT NULL::"uuid", "p_platform" "text" DEFAULT NULL::"text", "p_app_version" "text" DEFAULT NULL::"text", "p_properties" "jsonb" DEFAULT '{}'::"jsonb", "p_occurred_at" timestamp with time zone DEFAULT "now"()) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_id bigint;
  v_user_id uuid := auth.uid();
begin
  if nullif(trim(p_event_name), '') is null then
    raise exception 'event_name is required';
  end if;

  insert into public.analytics_events(
    user_id, session_id, installation_id, event_name, screen_name,
    entity_type, entity_id, spot_id, decision_id, platform,
    app_version, properties, occurred_at
  ) values (
    v_user_id, p_session_id, p_installation_id, trim(p_event_name),
    nullif(trim(p_screen_name), ''), nullif(trim(p_entity_type), ''),
    p_entity_id, p_spot_id, p_decision_id, nullif(trim(p_platform), ''),
    nullif(trim(p_app_version), ''), coalesce(p_properties, '{}'::jsonb),
    coalesce(p_occurred_at, now())
  ) returning id into v_id;

  if p_session_id is not null then
    update public.analytics_sessions
    set last_seen_at = now(),
        exit_screen = coalesce(nullif(trim(p_screen_name), ''), exit_screen)
    where id = p_session_id
      and (user_id = v_user_id or user_id is null);
  end if;

  return v_id;
end;
$$;

