CREATE OR REPLACE FUNCTION "public"."apply_favorite_spot_seeds_v1"("p_city" "text", "p_days" integer DEFAULT 365) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid;
  v_decision_id uuid;
  v_spot_ids uuid[];
  v_why text[];
begin
  v_uid := auth.uid();
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  if p_city is null or trim(p_city) = '' then
    raise exception 'city_required';
  end if;

  -- collect last seeds (only real spot_ids)
  select coalesce(array_agg(s.spot_id), '{}'::uuid[])
  into v_spot_ids
  from public.user_favorite_spot_seeds s
  where s.user_id = v_uid
    and lower(s.city) = lower(trim(p_city))
    and s.spot_id is not null
    and s.created_at >= now() - make_interval(days => greatest(p_days, 1));

  -- create synthetic decision session
  v_decision_id := public.create_decision_session_v1(
    p_city := trim(p_city),
    p_mood_a_text := 'favorite',
    p_mood_b_text := 'onboarding'
  );

  -- if there are spot ids, log impressions + exact_mood
  if array_length(v_spot_ids, 1) is not null then

    -- ✅ build why array without polymorphic traps
    select array_agg('Lieblingsspot (Onboarding).'::text)
    into v_why
    from unnest(v_spot_ids);

    perform public.log_decision_impressions_v1(
      p_decision_id := v_decision_id,
      p_spot_ids := v_spot_ids,
      p_why_this := coalesce(v_why, '{}'::text[])
    );

    -- log exact_mood once per spot for this session
    insert into public.decision_actions(decision_id, spot_id, action, created_at)
    select v_decision_id, sid, 'exact_mood', now()
    from unnest(v_spot_ids) sid
    on conflict do nothing;

  end if;

  -- rebuild taste profile (adjust params if your signature differs)
  perform public.rebuild_user_taste_profile_v1(v_uid, 0.65, 5);

  return v_decision_id;
end;
$$;

ALTER FUNCTION "public"."apply_favorite_spot_seeds_v1"("p_city" "text", "p_days" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."apply_shadow_event_to_user_v1"("p_user_id" "uuid", "p_event_type" "text", "p_spot_id" "uuid", "p_mood_text" "text" DEFAULT NULL::"text", "p_time_bucket" "text" DEFAULT NULL::"text", "p_occurred_at" timestamp with time zone DEFAULT "now"(), "p_city" "text" DEFAULT 'Basel'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_decision_id uuid;
  v_action text;
begin
  if p_user_id is null then
    raise exception 'user_required';
  end if;

  /*
    Shadow events we expect:
      - seed_favorite_spot  (onboarding seed)
      - tapped
      - was_here
      - exact_mood
      - not_there

    Strategy:
      - seed_favorite_spot -> treat as a weak positive signal ("was_here")
        (fast path into taste profile; same pipeline as real actions)
  */

  if p_event_type = 'seed_favorite_spot' then
    v_action := 'was_here';
  elsif p_event_type in ('tapped','was_here','exact_mood','not_there') then
    v_action := p_event_type;
  else
    raise exception 'unsupported_event_type: %', p_event_type;
  end if;

  -- Create a decision session to attach actions (same tables/pipeline)
  insert into public.decision_sessions(user_id, city, mood_a_text, mood_b_text, created_at)
  values (
    p_user_id,
    p_city,
    nullif(p_mood_text,''),
    null,
    coalesce(p_occurred_at, now())
  )
  returning id into v_decision_id;

  -- Insert action
  if v_action = 'tapped' then
    insert into public.decision_actions(decision_id, spot_id, action, created_at)
    values (v_decision_id, p_spot_id, 'tapped', coalesce(p_occurred_at, now()))
    on conflict do nothing;
  else
    insert into public.decision_actions(decision_id, spot_id, action, created_at)
    values (v_decision_id, p_spot_id, v_action, coalesce(p_occurred_at, now()));
  end if;

  -- Rebuild taste (same as production)
  perform public.rebuild_user_taste_profile_v2(p_user_id);

end;
$$;

ALTER FUNCTION "public"."apply_shadow_event_to_user_v1"("p_user_id" "uuid", "p_event_type" "text", "p_spot_id" "uuid", "p_mood_text" "text", "p_time_bucket" "text", "p_occurred_at" timestamp with time zone, "p_city" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."approve_spot_claim_v1"("p_claim_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_spot_id uuid;
  v_user_id uuid;
begin
  select spot_id, user_id into v_spot_id, v_user_id
  from public.spot_claims
  where id = p_claim_id;

  if v_spot_id is null then
    raise exception 'claim_not_found';
  end if;

  update public.spot_claims
  set status = 'approved', updated_at = now()
  where id = p_claim_id;

  insert into public.spot_descriptions (spot_id, owner_user_id, is_verified)
  values (v_spot_id, v_user_id, true)
  on conflict (spot_id) do update
    set owner_user_id = excluded.owner_user_id,
        is_verified = true,
        updated_at = now();
end $$;

ALTER FUNCTION "public"."approve_spot_claim_v1"("p_claim_id" bigint) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."auto_link_recent_decision_review_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform *
  from public.link_decision_review_v1(
    new.id,
    null,
    jsonb_build_object(
      'auto_detected', true,
      'auto_detected_reason', 'review_created_after_recent_same_spot_decision',
      'review_created_at', new.created_at
    )
  );

  return new;
exception when others then
  -- Never block review creation if the intelligence layer fails.
  raise notice 'auto_link_recent_decision_review_v1 failed for review %: %', new.id, sqlerrm;
  return new;
end;
$$;

