CREATE OR REPLACE FUNCTION "public"."auto_upgrade_decision_review_social_post_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_link record;
begin
  if new.review_id is null then
    return new;
  end if;

  select *
  into v_link
  from public.backyrd_decision_review_links_v1
  where review_id = new.review_id
  limit 1;

  if found then
    update public.social_posts
    set
      source_type = 'decision_review',
      source_context = coalesce(source_context, '{}'::jsonb)
        || coalesce(v_link.context, '{}'::jsonb)
        || jsonb_build_object(
          'decision_id', v_link.decision_id,
          'decision_match_type', v_link.match_type,
          'decision_signal_strength', v_link.signal_strength,
          'hours_between_decision_and_review', v_link.hours_between
        )
    where id = new.id;
  end if;

  return new;
end;
$$;

ALTER FUNCTION "public"."auto_upgrade_decision_review_social_post_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backfill_social_moments_from_my_reviews_v1"("p_limit" integer DEFAULT 50) RETURNS TABLE("processed" integer, "created_or_updated" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  r record;
  v_post_id uuid;
  v_processed integer := 0;
  v_changed integer := 0;
begin
  if auth.uid() is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  for r in
    select rev.id
    from public.reviews rev
    where coalesce(
      nullif(to_jsonb(rev) ->> 'user_id', '')::uuid,
      nullif(to_jsonb(rev) ->> 'profile_id', '')::uuid,
      nullif(to_jsonb(rev) ->> 'created_by', '')::uuid
    ) = auth.uid()
    order by coalesce(nullif(to_jsonb(rev) ->> 'created_at', '')::timestamptz, now()) desc
    limit greatest(1, least(coalesce(p_limit, 50), 300))
  loop
    v_processed := v_processed + 1;
    v_post_id := public.create_social_moment_from_review_v1(r.id, 'public');
    if v_post_id is not null then
      v_changed := v_changed + 1;
    end if;
  end loop;

  return query select v_processed, v_changed;
end;
$$;

ALTER FUNCTION "public"."backfill_social_moments_from_my_reviews_v1"("p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_apply_contextual_taste_from_event_v1"("p_event_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_event public.backyrd_ml_events_v1%rowtype;
  v_strength numeric;
  v_delta numeric;
  v_cap numeric;
  v_scope_multiplier numeric;
  v_feature_multiplier numeric;
  v_safety_multiplier numeric;
  v_is_positive boolean;
  ctx record;
  f record;
begin
  select *
  into v_event
  from public.backyrd_ml_events_v1 e
  where e.id = p_event_id;

  if v_event.id is null then
    return;
  end if;

  if v_event.spot_id is null then
    return;
  end if;

  if v_event.event_type not in (
    'decision_like',
    'decision_dislike',
    'decision_open',
    'favorite_add',
    'favorite_remove',
    'review_create',
    'review_update',
    'spot_detail_view',
    'search_result_click',
    'map_spot_tap'
  ) then
    return;
  end if;

  v_strength := coalesce(
    v_event.signal_strength,
    public.backyrd_ml_event_strength_v1(v_event.event_type)
  );

  if abs(v_strength) < 0.05 then
    return;
  end if;

  for ctx in
    select *
    from public.backyrd_context_keys_from_ml_event_v1(
      v_event.city,
      v_event.mood_a_text,
      v_event.mood_b_text,
      v_event.context
    )
  loop
    v_scope_multiplier := case ctx.context_scope
      when 'global' then
        case when v_strength < 0 then 0.025 else 0.13 end

      when 'category' then
        case when v_strength < 0 then 0.16 else 0.48 end

      when 'situation' then
        case when v_strength < 0 then 0.28 else 0.68 end

      when 'category_situation' then
        case when v_strength < 0 then 0.42 else 0.88 end

      else 0.20
    end;

    for f in
      select *
      from public.backyrd_ml_extract_spot_features_v1(v_event.spot_id)
    loop
      v_feature_multiplier := 1.0;

      -- City ist Kontext, nicht Geschmack.
      if f.feature_type = 'city' then
        if v_strength < 0 then
          v_feature_multiplier := 0.0;
        else
          v_feature_multiplier := 0.10;
        end if;
      end if;

      -- Negative Signale: breite Konzepte weniger hart bestrafen.
      if v_strength < 0 then
        if f.feature_type in ('mood', 'mood_concept', 'atmosphere') then
          v_feature_multiplier := v_feature_multiplier * 0.48;
        elsif f.feature_type in ('category', 'keyword', 'best_for', 'occasion') then
          v_feature_multiplier := v_feature_multiplier * 0.60;
        elsif f.feature_type in ('price', 'good_for_time', 'noise_level') then
          v_feature_multiplier := v_feature_multiplier * 0.36;
        end if;
      end if;

      v_safety_multiplier := public.backyrd_context_feature_learning_multiplier_v1(
        v_event.event_type,
        v_strength,
        ctx.context_scope,
        ctx.context_key,
        f.feature_type,
        f.feature_key,
        v_event.context
      );

      v_delta := v_strength
        * coalesce(f.feature_strength, 0)
        * v_scope_multiplier
        * v_feature_multiplier
        * v_safety_multiplier;

      if abs(v_delta) <= 0.00001 then
        continue;
      end if;

      v_cap := case ctx.context_scope
        when 'global' then least(0.50, public.backyrd_ml_feature_cap_v1(f.feature_type) * 0.25)
        when 'category' then least(1.00, public.backyrd_ml_feature_cap_v1(f.feature_type) * 0.62)
        when 'situation' then least(1.15, public.backyrd_ml_feature_cap_v1(f.feature_type) * 0.74)
        when 'category_situation' then least(1.35, public.backyrd_ml_feature_cap_v1(f.feature_type) * 0.84)
        else 1.0
      end;

      v_is_positive := v_delta > 0;

      insert into public.backyrd_user_context_feature_preferences_v1 (
        user_id,
        context_scope,
        context_key,
        feature_type,
        feature_key,
        weight,
        confidence,
        positive_count,
        negative_count,
        last_event_at,
        updated_at
      )
      values (
        v_event.user_id,
        ctx.context_scope,
        ctx.context_key,
        f.feature_type,
        f.feature_key,
        greatest(-v_cap, least(v_cap, v_delta)),
        greatest(0, least(1, abs(v_delta) * 0.12)),
        case when v_is_positive then 1 else 0 end,
        case when v_is_positive then 0 else 1 end,
        v_event.created_at,
        now()
      )
      on conflict (
        user_id,
        context_scope,
        context_key,
        feature_type,
        feature_key
      )
      do update set
        weight =
          case
            when excluded.weight >= 0 then
              least(
                case public.backyrd_user_context_feature_preferences_v1.context_scope
                  when 'global' then least(0.50, public.backyrd_ml_feature_cap_v1(public.backyrd_user_context_feature_preferences_v1.feature_type) * 0.25)
                  when 'category' then least(1.00, public.backyrd_ml_feature_cap_v1(public.backyrd_user_context_feature_preferences_v1.feature_type) * 0.62)
                  when 'situation' then least(1.15, public.backyrd_ml_feature_cap_v1(public.backyrd_user_context_feature_preferences_v1.feature_type) * 0.74)
                  when 'category_situation' then least(1.35, public.backyrd_ml_feature_cap_v1(public.backyrd_user_context_feature_preferences_v1.feature_type) * 0.84)
                  else 1.0
                end,
                public.backyrd_user_context_feature_preferences_v1.weight
                + excluded.weight
                * (
                  1 - least(
                    0.92,
                    greatest(0, public.backyrd_user_context_feature_preferences_v1.weight)
                    / greatest(
                      0.01,
                      case public.backyrd_user_context_feature_preferences_v1.context_scope
                        when 'global' then least(0.50, public.backyrd_ml_feature_cap_v1(public.backyrd_user_context_feature_preferences_v1.feature_type) * 0.25)
                        when 'category' then least(1.00, public.backyrd_ml_feature_cap_v1(public.backyrd_user_context_feature_preferences_v1.feature_type) * 0.62)
                        when 'situation' then least(1.15, public.backyrd_ml_feature_cap_v1(public.backyrd_user_context_feature_preferences_v1.feature_type) * 0.74)
                        when 'category_situation' then least(1.35, public.backyrd_ml_feature_cap_v1(public.backyrd_user_context_feature_preferences_v1.feature_type) * 0.84)
                        else 1.0
                      end
                    )
                  )
                )
              )
            else
              greatest(
                -case public.backyrd_user_context_feature_preferences_v1.context_scope
                  when 'global' then least(0.50, public.backyrd_ml_feature_cap_v1(public.backyrd_user_context_feature_preferences_v1.feature_type) * 0.25)
                  when 'category' then least(1.00, public.backyrd_ml_feature_cap_v1(public.backyrd_user_context_feature_preferences_v1.feature_type) * 0.62)
                  when 'situation' then least(1.15, public.backyrd_ml_feature_cap_v1(public.backyrd_user_context_feature_preferences_v1.feature_type) * 0.74)
                  when 'category_situation' then least(1.35, public.backyrd_ml_feature_cap_v1(public.backyrd_user_context_feature_preferences_v1.feature_type) * 0.84)
                  else 1.0
                end,
                public.backyrd_user_context_feature_preferences_v1.weight
                + excluded.weight
                * (
                  1 - least(
                    0.92,
                    greatest(0, -public.backyrd_user_context_feature_preferences_v1.weight)
                    / greatest(
                      0.01,
                      case public.backyrd_user_context_feature_preferences_v1.context_scope
                        when 'global' then least(0.50, public.backyrd_ml_feature_cap_v1(public.backyrd_user_context_feature_preferences_v1.feature_type) * 0.25)
                        when 'category' then least(1.00, public.backyrd_ml_feature_cap_v1(public.backyrd_user_context_feature_preferences_v1.feature_type) * 0.62)
                        when 'situation' then least(1.15, public.backyrd_ml_feature_cap_v1(public.backyrd_user_context_feature_preferences_v1.feature_type) * 0.74)
                        when 'category_situation' then least(1.35, public.backyrd_ml_feature_cap_v1(public.backyrd_user_context_feature_preferences_v1.feature_type) * 0.84)
                        else 1.0
                      end
                    )
                  )
                )
              )
          end,
        confidence = greatest(
          0,
          least(
            1,
            public.backyrd_user_context_feature_preferences_v1.confidence
            + abs(excluded.weight) * 0.05
          )
        ),
        positive_count = public.backyrd_user_context_feature_preferences_v1.positive_count + excluded.positive_count,
        negative_count = public.backyrd_user_context_feature_preferences_v1.negative_count + excluded.negative_count,
        last_event_at = excluded.last_event_at,
        updated_at = now();
    end loop;
  end loop;
end;
$$;

ALTER FUNCTION "public"."backyrd_apply_contextual_taste_from_event_v1"("p_event_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_backfill_contextual_taste_v1"("p_limit" integer DEFAULT 5000) RETURNS TABLE("processed" integer, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_count integer := 0;
  e record;
begin
  for e in
    select id
    from public.backyrd_ml_events_v1
    where spot_id is not null
      and event_type in (
        'decision_like',
        'decision_dislike',
        'decision_open',
        'favorite_add',
        'favorite_remove',
        'review_create',
        'review_update',
        'spot_detail_view',
        'search_result_click',
        'map_spot_tap'
      )
    order by created_at asc
    limit greatest(1, least(coalesce(p_limit, 5000), 50000))
  loop
    perform public.backyrd_apply_contextual_taste_from_event_v1(e.id);
    v_count := v_count + 1;
  end loop;

  return query
  select v_count, 'contextual_taste_backfilled'::text;
end;
$$;

ALTER FUNCTION "public"."backyrd_backfill_contextual_taste_v1"("p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_backfill_place_type_preferences_v1"("p_limit" integer DEFAULT 5000) RETURNS TABLE("processed_count" integer, "profile_rows" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  r record;
  v_processed integer := 0;
begin
  if not exists (
    select 1
    from information_schema.tables
    where table_schema = 'public'
      and table_name = 'backyrd_ml_events_v1'
  ) then
    processed_count := 0;
    profile_rows := 0;
    return next;
    return;
  end if;

  for r in
    select
      e.user_id,
      e.spot_id,
      e.event_type,
      e.signal_strength,
      e.city,
      e.mood_a_text,
      e.mood_b_text,
      e.context,
      e.created_at
    from public.backyrd_ml_events_v1 e
    where e.user_id is not null
      and e.spot_id is not null
      and e.event_type in (
        'decision_like',
        'decision_dislike',
        'decision_open',
        'decision_save',
        'decision_skip',
        'tapped',
        'exact_mood',
        'was_here',
        'not_there'
      )
    order by e.created_at asc
    limit greatest(1, least(coalesce(p_limit, 5000), 50000))
  loop
    perform public.backyrd_update_place_type_preference_v1(
      p_user_id := r.user_id,
      p_spot_id := r.spot_id,
      p_event_type := r.event_type,
      p_signal_strength := r.signal_strength,
      p_city := r.city,
      p_mood_a_text := r.mood_a_text,
      p_mood_b_text := r.mood_b_text,
      p_context := coalesce(r.context, '{}'::jsonb)
    );

    v_processed := v_processed + 1;
  end loop;

  processed_count := v_processed;

  select count(*)::integer
    into profile_rows
  from public.user_place_type_preferences_v1;

  return next;
end;
$$;

ALTER FUNCTION "public"."backyrd_backfill_place_type_preferences_v1"("p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_backfill_taxonomy_embeddings_v1"("p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0, "p_approved_only" boolean DEFAULT true) RETURNS TABLE("processed" integer, "queued" integer, "failed" integer, "next_offset" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_spot record;
  v_processed integer := 0;
  v_queued integer := 0;
  v_failed integer := 0;
begin
  if coalesce(p_limit, 0) < 1 or p_limit > 500 then
    raise exception 'p_limit must be between 1 and 500';
  end if;

  for v_spot in
    select s.id
    from public.spots s
    where (not p_approved_only or s.status = 'approved'::public.spot_status)
    order by s.created_at, s.id
    limit p_limit
    offset greatest(coalesce(p_offset, 0), 0)
  loop
    v_processed := v_processed + 1;
    begin
      perform public.backyrd_enqueue_spot_embedding_v13(
        v_spot.id,
        'taxonomy_v2_backfill'
      );
      v_queued := v_queued + 1;
    exception when others then
      v_failed := v_failed + 1;
      raise warning 'taxonomy backfill failed for spot %: %', v_spot.id, sqlerrm;
    end;
  end loop;

  return query
  select v_processed, v_queued, v_failed,
         greatest(coalesce(p_offset, 0), 0) + v_processed;
end;
$$;

ALTER FUNCTION "public"."backyrd_backfill_taxonomy_embeddings_v1"("p_limit" integer, "p_offset" integer, "p_approved_only" boolean) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_build_spot_ml_document_v13"("p_spot_id" "uuid") RETURNS TABLE("spot_id" "uuid", "document_text" "text", "document_json" "jsonb", "source_hash" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
with spot_base as (
  select
    s.id as spot_id,
    s.name,
    s.address,
    s.city,
    s.country,
    s.price_level,
    s.website,
    s.phone,
    s.email,
    s.status::text as status,
    c.name as category_name,
    ec.description_source,
    ec.effective_description,
    ec.effective_keywords
  from public.spots s
  left join public.categories c on c.id = s.category_id
  left join public.spot_effective_content_v1 ec on ec.spot_id = s.id
  where s.id = p_spot_id
),
moods as (
  select
    sm.spot_id,
    array_agg(distinct mt.token order by mt.token)
      filter (where mt.token is not null) as mood_tokens,
    jsonb_agg(distinct jsonb_build_object(
      'token', mt.token,
      'token_norm', mt.token_norm,
      'count', sm.mood_count,
      'rank', sm.rank
    )) filter (where mt.token is not null) as mood_json
  from public.spot_moods sm
  join public.mood_tokens mt on mt.id = sm.mood_id
  where sm.spot_id = p_spot_id
    and mt.valid = true
  group by sm.spot_id
),
concepts as (
  select
    smc.spot_id,
    array_agg(distinct mc.label order by mc.label)
      filter (where mc.label is not null) as concept_labels,
    jsonb_agg(distinct jsonb_build_object(
      'label', mc.label,
      'label_norm', mc.label_norm,
      'cluster_id', mc.primary_cluster_id,
      'strength', smc.strength,
      'source', smc.source
    )) filter (where mc.label is not null) as concept_json
  from public.spot_mood_concepts smc
  join public.mood_concepts mc on mc.id = smc.concept_id
  where smc.spot_id = p_spot_id
  group by smc.spot_id
),
intelligence as (
  select
    si.spot_id,
    si.best_for,
    si.occasion_tags,
    si.atmosphere_tags,
    si.avoid_if_tags,
    si.good_for_time,
    si.noise_level,
    si.crowd_type,
    si.dress_code,
    si.reservation_recommended,
    si.average_duration_minutes,
    si.signature_items,
    si.special_notes,
    si.source,
    si.is_verified
  from public.spot_intelligence_v1 si
  where si.spot_id = p_spot_id
),
review_summary as (
  select
    r.spot_id,
    count(*)::integer as review_count,
    array_agg(distinct public.backyrd_ml_clean_text_v13(r.mood_a))
      filter (where public.backyrd_ml_clean_text_v13(r.mood_a) is not null) as review_mood_a,
    array_agg(distinct public.backyrd_ml_clean_text_v13(r.mood_b))
      filter (where public.backyrd_ml_clean_text_v13(r.mood_b) is not null) as review_mood_b,
    array_agg(
      public.backyrd_ml_clean_text_v13(left(r.text, 280))
      order by r.created_at desc
    ) filter (where public.backyrd_ml_clean_text_v13(r.text) is not null) as review_texts
  from public.reviews r
  where r.spot_id = p_spot_id
  group by r.spot_id
),
hours_summary as (
  select
    sh.spot_id,
    jsonb_agg(
      jsonb_build_object(
        'day', sh.day_of_week,
        'open', sh.open_time::text,
        'close', sh.close_time::text,
        'idx', sh.idx
      )
      order by sh.idx nulls last, sh.day_of_week, sh.open_time
    ) as hours_json,
    string_agg(
      sh.day_of_week || ' ' || sh.open_time::text || '-' || sh.close_time::text,
      '; '
      order by sh.idx nulls last, sh.day_of_week, sh.open_time
    ) as hours_text
  from public.spot_hours sh
  where sh.spot_id = p_spot_id
  group by sh.spot_id
),
taxonomy as (
  select * from public.backyrd_get_spot_taxonomy_ml_v1(p_spot_id, 'de')
),
assembled as (
  select
    sb.spot_id,
    jsonb_build_object(
      'name', sb.name,
      'category', sb.category_name,
      'address', sb.address,
      'city', sb.city,
      'country', sb.country,
      'price_level', sb.price_level,
      'status', sb.status,
      'description_source', sb.description_source,
      'description', public.backyrd_ml_clean_text_v13(sb.effective_description),
      'keywords', coalesce(sb.effective_keywords, '{}'::text[]),

      'taxonomy', coalesce(t.taxonomy_json, '[]'::jsonb),
      'subcategories', coalesce(t.subcategories, '{}'::text[]),
      'features', coalesce(t.features, '{}'::text[]),
      'services', coalesce(t.services, '{}'::text[]),
      'offerings', coalesce(t.offerings, '{}'::text[]),
      'taxonomy_synonyms', coalesce(t.synonyms, '{}'::text[]),

      'moods', coalesce(m.mood_tokens, '{}'::text[]),
      'mood_details', coalesce(m.mood_json, '[]'::jsonb),
      'concepts', coalesce(c.concept_labels, '{}'::text[]),
      'concept_details', coalesce(c.concept_json, '[]'::jsonb),

      'intelligence', jsonb_build_object(
        'best_for', coalesce(i.best_for, '{}'::text[]),
        'occasion_tags', coalesce(i.occasion_tags, '{}'::text[]),
        'atmosphere_tags', coalesce(i.atmosphere_tags, '{}'::text[]),
        'avoid_if_tags', coalesce(i.avoid_if_tags, '{}'::text[]),
        'good_for_time', coalesce(i.good_for_time, '{}'::text[]),
        'noise_level', i.noise_level,
        'crowd_type', coalesce(i.crowd_type, '{}'::text[]),
        'dress_code', i.dress_code,
        'reservation_recommended', i.reservation_recommended,
        'average_duration_minutes', i.average_duration_minutes,
        'signature_items', coalesce(i.signature_items, '{}'::text[]),
        'special_notes', public.backyrd_ml_clean_text_v13(i.special_notes),
        'source', i.source,
        'is_verified', coalesce(i.is_verified, false)
      ),

      'review_count', coalesce(rs.review_count, 0),
      'review_moods_a', coalesce(rs.review_mood_a, '{}'::text[]),
      'review_moods_b', coalesce(rs.review_mood_b, '{}'::text[]),
      'review_texts', coalesce(rs.review_texts[1:5], '{}'::text[]),
      'hours', coalesce(h.hours_json, '[]'::jsonb)
    ) as document_json,

    concat_ws(
      E'\n',
      'Spot: ' || coalesce(sb.name, ''),
      'Kategorie: ' || coalesce(sb.category_name, ''),
      'Stadt: ' || coalesce(sb.city, ''),
      'Land: ' || coalesce(sb.country, ''),
      case when sb.address is not null then 'Adresse: ' || sb.address end,
      case when sb.price_level is not null then 'Preislevel: ' || sb.price_level::text end,

      case when cardinality(t.subcategories) > 0
        then 'Unterkategorien: ' || array_to_string(t.subcategories, ', ') end,
      case when cardinality(t.features) > 0
        then 'Ausstattung und Merkmale: ' || array_to_string(t.features, ', ') end,
      case when cardinality(t.offerings) > 0
        then 'Angebot: ' || array_to_string(t.offerings, ', ') end,
      case when cardinality(t.services) > 0
        then 'Services: ' || array_to_string(t.services, ', ') end,
      case when cardinality(t.synonyms) > 0
        then 'Verwandte Suchbegriffe: ' || array_to_string(t.synonyms, ', ') end,
      case when nullif(btrim(t.weighted_text), '') is not null
        then 'Gewichtete Taxonomie-Signale: ' || t.weighted_text end,

      case when public.backyrd_ml_clean_text_v13(sb.effective_description) is not null
        then 'Beschreibung: ' || public.backyrd_ml_clean_text_v13(sb.effective_description) end,
      case when cardinality(coalesce(sb.effective_keywords, '{}'::text[])) > 0
        then 'Keywords: ' || array_to_string(sb.effective_keywords, ', ') end,
      case when cardinality(coalesce(m.mood_tokens, '{}'::text[])) > 0
        then 'Moods: ' || array_to_string(m.mood_tokens, ', ') end,
      case when cardinality(coalesce(c.concept_labels, '{}'::text[])) > 0
        then 'Mood Concepts: ' || array_to_string(c.concept_labels, ', ') end,
      case when cardinality(coalesce(i.best_for, '{}'::text[])) > 0
        then 'Gut für: ' || array_to_string(i.best_for, ', ') end,
      case when cardinality(coalesce(i.occasion_tags, '{}'::text[])) > 0
        then 'Anlässe: ' || array_to_string(i.occasion_tags, ', ') end,
      case when cardinality(coalesce(i.atmosphere_tags, '{}'::text[])) > 0
        then 'Atmosphäre: ' || array_to_string(i.atmosphere_tags, ', ') end,
      case when cardinality(coalesce(i.good_for_time, '{}'::text[])) > 0
        then 'Gute Tageszeiten: ' || array_to_string(i.good_for_time, ', ') end,
      case when cardinality(coalesce(i.avoid_if_tags, '{}'::text[])) > 0
        then 'Eher nicht geeignet für: ' || array_to_string(i.avoid_if_tags, ', ') end,
      case when i.noise_level is not null then 'Geräuschlevel: ' || i.noise_level end,
      case when cardinality(coalesce(i.crowd_type, '{}'::text[])) > 0
        then 'Crowd: ' || array_to_string(i.crowd_type, ', ') end,
      case when i.dress_code is not null then 'Dresscode: ' || i.dress_code end,
      case when i.reservation_recommended is not null
        then 'Reservation empfohlen: ' || case when i.reservation_recommended then 'ja' else 'nein' end end,
      case when i.average_duration_minutes is not null
        then 'Typische Aufenthaltsdauer Minuten: ' || i.average_duration_minutes::text end,
      case when cardinality(coalesce(i.signature_items, '{}'::text[])) > 0
        then 'Signature Items: ' || array_to_string(i.signature_items, ', ') end,
      case when public.backyrd_ml_clean_text_v13(i.special_notes) is not null
        then 'Besondere Hinweise: ' || public.backyrd_ml_clean_text_v13(i.special_notes) end,
      case when cardinality(coalesce(rs.review_mood_a, '{}'::text[])) > 0
        then 'Review Mood A: ' || array_to_string(rs.review_mood_a, ', ') end,
      case when cardinality(coalesce(rs.review_mood_b, '{}'::text[])) > 0
        then 'Review Mood B: ' || array_to_string(rs.review_mood_b, ', ') end,
      case when cardinality(coalesce(rs.review_texts, '{}'::text[])) > 0
        then 'Review Auszüge: ' || array_to_string(rs.review_texts[1:5], ' | ') end,
      case when public.backyrd_ml_clean_text_v13(h.hours_text) is not null
        then 'Öffnungszeiten: ' || public.backyrd_ml_clean_text_v13(h.hours_text) end
    ) as document_text
  from spot_base sb
  left join moods m on m.spot_id = sb.spot_id
  left join concepts c on c.spot_id = sb.spot_id
  left join intelligence i on i.spot_id = sb.spot_id
  left join review_summary rs on rs.spot_id = sb.spot_id
  left join hours_summary h on h.spot_id = sb.spot_id
  cross join taxonomy t
)
select
  a.spot_id,
  a.document_text,
  a.document_json,
  md5(coalesce(a.document_text, '') || '|' || coalesce(a.document_json::text, '')) as source_hash
from assembled a;
$$;

ALTER FUNCTION "public"."backyrd_build_spot_ml_document_v13"("p_spot_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_claim_domain_match_v1"("p_spot_id" "uuid", "p_email" "text") RETURNS TABLE("allowed" boolean, "score" numeric, "reason" "text", "spot_tokens" "text"[], "domain_tokens" "text"[], "email_domain" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_spot_name text;
  v_domain text;
  v_domain_root text;
  v_spot_tokens text[];
  v_domain_tokens text[];
  v_public_domains text[] := array[
    'gmail.com',
    'googlemail.com',
    'yahoo.com',
    'ymail.com',
    'hotmail.com',
    'outlook.com',
    'live.com',
    'icloud.com',
    'me.com',
    'mac.com',
    'bluewin.ch',
    'gmx.ch',
    'gmx.net',
    'gmx.de',
    'web.de',
    'proton.me',
    'protonmail.com',
    'mail.com',
    'aol.com'
  ];
  v_match_count integer := 0;
  v_score numeric := 0;
begin
  if p_spot_id is null then
    raise exception 'spot_id_required';
  end if;

  if p_email is null
     or p_email !~* '^[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}$' then
    return query
    select
      false,
      0::numeric,
      'invalid_email'::text,
      '{}'::text[],
      '{}'::text[],
      null::text;
    return;
  end if;

  select s.name
  into v_spot_name
  from public.spots s
  where s.id = p_spot_id;

  if v_spot_name is null then
    raise exception 'spot_not_found';
  end if;

  v_domain := public.backyrd_claim_email_domain_v1(p_email);
  v_domain_root := public.backyrd_claim_domain_root_v1(v_domain);

  v_spot_tokens := public.backyrd_claim_tokens_v1(v_spot_name);
  v_domain_tokens := public.backyrd_claim_tokens_v1(v_domain_root);

  if v_domain = any(v_public_domains) then
    return query
    select
      false,
      0::numeric,
      'public_email_domain_not_allowed'::text,
      v_spot_tokens,
      v_domain_tokens,
      v_domain;
    return;
  end if;

  select count(*)::integer
  into v_match_count
  from unnest(v_spot_tokens) as st(token)
  join unnest(v_domain_tokens) as dt(token)
    on (
      st.token = dt.token
      or position(st.token in dt.token) > 0
      or position(dt.token in st.token) > 0
    )
  where length(st.token) >= 2
    and length(dt.token) >= 2;

  v_score := case
    when cardinality(v_spot_tokens) = 0 then 0
    else least(1, v_match_count::numeric / greatest(1, cardinality(v_spot_tokens))::numeric)
  end;

  if v_match_count > 0 then
    return query
    select
      true,
      greatest(0.55, v_score),
      'business_domain_matches_spot_name'::text,
      v_spot_tokens,
      v_domain_tokens,
      v_domain;
    return;
  end if;

  return query
  select
    false,
    0::numeric,
    'business_domain_does_not_match_spot_name'::text,
    v_spot_tokens,
    v_domain_tokens,
    v_domain;
end;
$_$;

ALTER FUNCTION "public"."backyrd_claim_domain_match_v1"("p_spot_id" "uuid", "p_email" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_claim_domain_root_v1"("p_domain" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  select public.backyrd_claim_norm_v1(
    regexp_replace(
      regexp_replace(lower(coalesce(p_domain, '')), '^www\.', ''),
      '\.[a-z]{2,}$',
      ''
    )
  );
$_$;

ALTER FUNCTION "public"."backyrd_claim_domain_root_v1"("p_domain" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_claim_email_domain_v1"("p_email" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select nullif(
    regexp_replace(
      lower(trim(split_part(coalesce(p_email, ''), '@', 2))),
      '^www\.',
      ''
    ),
    ''
  );
$$;

ALTER FUNCTION "public"."backyrd_claim_email_domain_v1"("p_email" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_claim_norm_v1"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select nullif(
    trim(
      regexp_replace(
        replace(
          replace(
            replace(
              replace(
                replace(
                  replace(
                    lower(coalesce(p_text, '')),
                    'ä', 'ae'
                  ),
                  'ö', 'oe'
                ),
                'ü', 'ue'
              ),
              'é', 'e'
            ),
            'è', 'e'
          ),
          'à', 'a'
        ),
        '[^a-z0-9]+',
        ' ',
        'g'
      )
    ),
    ''
  );
$$;

ALTER FUNCTION "public"."backyrd_claim_norm_v1"("p_text" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_claim_spot_embedding_jobs_v13"("p_limit" integer DEFAULT 10) RETURNS TABLE("spot_id" "uuid", "document_text" "text", "document_version" "text", "source_hash" "text", "attempts" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 10), 100));
begin
  return query
  with claimable as (
    select j.spot_id
    from public.backyrd_embedding_jobs_v1 j
    where
      (
        j.status = 'pending'
        or (
          j.status = 'processing'
          and j.locked_at < now() - interval '5 minutes'
        )
        or (
          j.status = 'failed'
          and j.attempts < j.max_attempts
        )
      )
    order by j.queued_at asc
    limit v_limit
    for update skip locked
  ),
  claimed as (
    update public.backyrd_embedding_jobs_v1 j
    set
      status = 'processing',
      attempts = j.attempts + 1,
      locked_at = now(),
      updated_at = now()
    from claimable c
    where j.spot_id = c.spot_id
    returning
      j.spot_id,
      j.attempts
  )
  select
    d.spot_id,
    d.document_text,
    d.document_version,
    d.source_hash,
    c.attempts
  from claimed c
  join public.backyrd_spot_ml_documents_v1 d
    on d.spot_id = c.spot_id;
end;
$$;

ALTER FUNCTION "public"."backyrd_claim_spot_embedding_jobs_v13"("p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_claim_tokens_v1"("p_text" "text") RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE
    AS $$
  with raw_tokens as (
    select token
    from regexp_split_to_table(coalesce(public.backyrd_claim_norm_v1(p_text), ''), '\s+') as token
  )
  select coalesce(
    array_agg(distinct token order by token),
    '{}'::text[]
  )
  from raw_tokens
  where length(token) >= 2
    and token not in (
      'ag',
      'gmbh',
      'ltd',
      'sa',
      'sarl',
      'und',
      'the',
      'der',
      'die',
      'das',
      'von',
      'zum',
      'zur',
      'bei',
      'im',
      'am',
      'an',
      'in',
      'basel',
      'zuerich',
      'zurich',
      'schweiz',
      'switzerland',
      'restaurant',
      'restoran',
      'ristorante',
      'cafe',
      'café',
      'bar',
      'hotel',
      'club'
    );
$$;

ALTER FUNCTION "public"."backyrd_claim_tokens_v1"("p_text" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_context_feature_learning_multiplier_v1"("p_event_type" "text", "p_strength" numeric, "p_context_scope" "text", "p_context_key" "text", "p_feature_type" "text", "p_feature_key" "text", "p_event_context" "jsonb" DEFAULT '{}'::"jsonb") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare
  v_event_type text := lower(trim(coalesce(p_event_type, '')));
  v_scope text := lower(trim(coalesce(p_context_scope, '')));
  v_context_key text := lower(trim(coalesce(p_context_key, '')));
  v_feature_type text := lower(trim(coalesce(p_feature_type, '')));
  v_feature_key text := lower(trim(coalesce(p_feature_key, '')));
  v_is_negative boolean := coalesce(p_strength, 0) < 0;
  v_is_positive boolean := coalesce(p_strength, 0) > 0;
begin
  -- Safety: Kids-Kontext soll nie Romantic/Date lernen.
  -- Das war bei Basler Münster ein Artefakt aus Spot-/matched_tokens, nicht aus der eigentlichen Nutzerabsicht.
  if v_context_key like '%kids%'
     and (
       v_feature_key in (
         'concept:romantic',
         'mood:romantisch',
         'mood:romantic',
         'occasion:date',
         'best_for:date'
       )
       or v_feature_key like '%romantic%'
       or v_feature_key like '%romantisch%'
     )
  then
    return 0;
  end if;

  -- Ein Dislike eines einzelnen Spots soll nicht die ganze Kategorie zerstören.
  if v_is_negative
     and v_feature_type = 'category'
     and (
       (v_context_key like 'category:activity%' and v_feature_key in ('category:aktivität', 'category:aktivitaet', 'category:activity'))
       or
       (v_context_key like 'category:culture%' and v_feature_key in ('category:museum', 'category:kultur', 'category:culture'))
       or
       (v_context_key like 'category:cafe%' and v_feature_key in ('category:café', 'category:cafe'))
       or
       (v_context_key like 'category:bar%' and v_feature_key in ('category:bar'))
       or
       (v_context_key like 'category:restaurant%' and v_feature_key in ('category:restaurant'))
       or
       (v_context_key like 'category:outing%' and v_feature_key in ('category:ausflug', 'category:aussichtspunkt', 'category:park'))
       or
       (v_context_key like 'category:experience%' and v_feature_key in ('category:besonderes erlebnis', 'category:erlebnis'))
     )
  then
    return 0.06;
  end if;

  -- Broad Kids-Qualitäten nicht hart negativ lernen.
  if v_is_negative
     and v_context_key like '%kids%'
     and v_feature_type in ('mood_concept', 'atmosphere', 'keyword')
     and (
       v_feature_key in (
         'concept:family_friendly',
         'concept:family-friendly',
         'concept:outdoor',
         'concept:nature',
         'keyword:kinder',
         'keyword:familie',
         'keyword:family',
         'keyword:outdoor',
         'keyword:natur'
       )
       or v_feature_key like '%family%'
       or v_feature_key like '%familie%'
       or v_feature_key like '%kinder%'
       or v_feature_key like '%outdoor%'
       or v_feature_key like '%nature%'
       or v_feature_key like '%natur%'
     )
  then
    return 0.12;
  end if;

  -- Global Taste soft halten.
  if v_is_positive
     and v_scope = 'global'
     and v_feature_type in ('category', 'mood', 'mood_concept', 'keyword')
  then
    return 0.72;
  end if;

  return 1;
end;
$$;

ALTER FUNCTION "public"."backyrd_context_feature_learning_multiplier_v1"("p_event_type" "text", "p_strength" numeric, "p_context_scope" "text", "p_context_key" "text", "p_feature_type" "text", "p_feature_key" "text", "p_event_context" "jsonb") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_context_keys_from_ml_event_v1"("p_city" "text" DEFAULT NULL::"text", "p_mood_a_text" "text" DEFAULT NULL::"text", "p_mood_b_text" "text" DEFAULT NULL::"text", "p_context" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("context_scope" "text", "context_key" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  v_context jsonb := coalesce(p_context, '{}'::jsonb);
  v_text_blob text;
  v_category_name text;
  v_inferred_place_type text;
  v_place_type text;
  v_place_types text[] := '{}'::text[];
  v_situations text[] := '{}'::text[];
  v_value text;
begin
  v_category_name := nullif(trim(coalesce(v_context->>'category_name', '')), '');
  v_inferred_place_type := public.backyrd_infer_place_type_from_category_v1(v_category_name);

  v_text_blob := lower(
    coalesce(p_city, '') || ' ' ||
    coalesce(p_mood_a_text, '') || ' ' ||
    coalesce(p_mood_b_text, '') || ' ' ||
    coalesce(v_context::text, '')
  );

  -- global immer.
  return query
  select 'global'::text, 'global'::text;

  -- explicit place types from context, falls Mobile sie liefert.
  if jsonb_typeof(v_context->'preferredPlaceTypes') = 'array' then
    for v_value in
      select jsonb_array_elements_text(v_context->'preferredPlaceTypes')
    loop
      if nullif(trim(v_value), '') is not null then
        v_place_types := array_append(v_place_types, lower(trim(v_value)));
      end if;
    end loop;
  end if;

  if jsonb_typeof(v_context->'primaryPlaceTypes') = 'array' then
    for v_value in
      select jsonb_array_elements_text(v_context->'primaryPlaceTypes')
    loop
      if nullif(trim(v_value), '') is not null then
        v_place_types := array_append(v_place_types, lower(trim(v_value)));
      end if;
    end loop;
  end if;

  if nullif(trim(coalesce(v_context->>'place_type', '')), '') is not null then
    v_place_types := array_append(v_place_types, lower(trim(v_context->>'place_type')));
  end if;

  if v_inferred_place_type is not null then
    v_place_types := array_append(v_place_types, v_inferred_place_type);
  end if;

  -- Textbasierte Kategorie-Erkennung als Fallback.
  if v_text_blob ~ '(museum|kultur|kunst|ausstellung)' then
    v_place_types := array_append(v_place_types, 'culture');
  end if;

  if v_text_blob ~ '(aktivität|aktivitaet|unternehmen|sport|bewegung|spielen|klettern|bouldern)' then
    v_place_types := array_append(v_place_types, 'activity');
  end if;

  if v_text_blob ~ '(ausflug|spaziergang|park|draussen|draußen|outdoor|natur)' then
    v_place_types := array_append(v_place_types, 'outing');
  end if;

  if v_text_blob ~ '(café|cafe|kaffee)' then
    v_place_types := array_append(v_place_types, 'cafe');
  end if;

  if v_text_blob ~ '(bar|drinks|cocktail|wein)' then
    v_place_types := array_append(v_place_types, 'bar');
  end if;

  if v_text_blob ~ '(restaurant|essen|dinner|lunch|brunch)' then
    v_place_types := array_append(v_place_types, 'restaurant');
  end if;

  -- Situation/Audience erkennen.
  if jsonb_typeof(v_context->'audience') = 'array' then
    for v_value in
      select jsonb_array_elements_text(v_context->'audience')
    loop
      if lower(trim(v_value)) in ('kids', 'kid', 'children', 'child', 'family', 'familie', 'kind', 'kinder') then
        v_situations := array_append(v_situations, 'kids');
      elsif nullif(trim(v_value), '') is not null then
        v_situations := array_append(v_situations, lower(trim(v_value)));
      end if;
    end loop;
  end if;

  if v_text_blob ~ '(kind|kinder|tochter|sohn|4 jähr|4-jähr|familie|family|kleinkind)' then
    v_situations := array_append(v_situations, 'kids');
  end if;

  if v_text_blob ~ '(sonntag|sunday)' then
    v_situations := array_append(v_situations, 'sunday');
  end if;

  if v_text_blob ~ '(wochenende|weekend|samstag)' then
    v_situations := array_append(v_situations, 'weekend');
  end if;

  if v_text_blob ~ '(regen|regnet|rain|indoor|drinnen)' then
    v_situations := array_append(v_situations, 'rainy_day');
  end if;

  if v_text_blob ~ '(date|romantisch|romantic)' then
    v_situations := array_append(v_situations, 'date');
  end if;

  if v_text_blob ~ '(freunde|friends|gruppe|gruppen)' then
    v_situations := array_append(v_situations, 'friends');
  end if;

  if v_text_blob ~ '(allein|solo|me time|metime)' then
    v_situations := array_append(v_situations, 'solo');
  end if;

  -- Kategorie-Kontexte ausgeben.
  for v_place_type in
    select distinct unnest(v_place_types)
  loop
    if v_place_type in (
      'cafe',
      'bar',
      'restaurant',
      'nightlife',
      'culture',
      'outing',
      'activity',
      'experience',
      'hotel',
      'other'
    ) then
      return query
      select 'category'::text, ('category:' || v_place_type)::text;
    end if;
  end loop;

  -- Situations-Kontexte ausgeben.
  for v_value in
    select distinct unnest(v_situations)
  loop
    if nullif(trim(v_value), '') is not null then
      return query
      select 'situation'::text, ('situation:' || lower(trim(v_value)))::text;
    end if;
  end loop;

  -- Kategorie + Situation Kombis.
  for v_place_type in
    select distinct unnest(v_place_types)
  loop
    for v_value in
      select distinct unnest(v_situations)
    loop
      if v_place_type in (
        'cafe',
        'bar',
        'restaurant',
        'nightlife',
        'culture',
        'outing',
        'activity',
        'experience',
        'hotel',
        'other'
      )
      and nullif(trim(v_value), '') is not null then
        return query
        select
          'category_situation'::text,
          ('category_situation:' || v_place_type || '+' || lower(trim(v_value)))::text;
      end if;
    end loop;
  end loop;
end;
$$;

ALTER FUNCTION "public"."backyrd_context_keys_from_ml_event_v1"("p_city" "text", "p_mood_a_text" "text", "p_mood_b_text" "text", "p_context" "jsonb") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_create_decision_session_v1"("p_city" "text", "p_selected_cluster_ids" integer[], "p_query" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  mood_names text;
  mood_a text;
  mood_b text;
  new_id uuid;
begin
  -- map cluster ids -> names (fallback: empty)
  select coalesce(string_agg(mc.name_norm, ', ' order by mc.id), '')
    into mood_names
  from public.mood_clusters mc
  where mc.id = any(p_selected_cluster_ids);

  -- legacy expects 2 mood texts, we fill deterministically
  mood_a := split_part(mood_names, ', ', 1);
  mood_b := split_part(mood_names, ', ', 2);

  -- if query exists but moods are empty, we still store some signal
  if coalesce(mood_a, '') = '' and coalesce(mood_b, '') = '' then
    mood_a := nullif(p_query, '');
  end if;

  select public.create_decision_session_v1(
    p_city := p_city,
    p_mood_a_text := mood_a,
    p_mood_b_text := mood_b
  )
  into new_id;

  return new_id;
end;
$$;

ALTER FUNCTION "public"."backyrd_create_decision_session_v1"("p_city" "text", "p_selected_cluster_ids" integer[], "p_query" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_debug_get_user_taste_affinity_for_user_v1"("p_user_id" "uuid", "p_spot_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_aff numeric;
begin
  -- Supabase SQL Editor runs as postgres. We restrict this debug function to postgres only.
  if current_user <> 'postgres' then
    raise exception 'Forbidden';
  end if;

  -- Assumes your affinity function uses auth.uid(). We temporarily emulate by computing directly here.
  -- Affinity = sum(spot_strength * user_weight) over concepts.
  select coalesce(sum(smc.strength * utc.weight), 0)::numeric
  into v_aff
  from public.spot_mood_concepts smc
  join public.user_taste_concepts_v2 utc
    on utc.user_id = p_user_id
   and utc.concept_id = smc.concept_id
  where smc.spot_id = p_spot_id;

  return v_aff;
end;
$$;

ALTER FUNCTION "public"."backyrd_debug_get_user_taste_affinity_for_user_v1"("p_user_id" "uuid", "p_spot_id" "uuid") OWNER TO "postgres";

