ALTER FUNCTION "public"."backyrd_debug_spot_taxonomy_ml_v1"("p_spot_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_decision_context_key_v1"("p_mood_a_text" "text" DEFAULT NULL::"text", "p_mood_b_text" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when nullif(trim(coalesce(p_mood_a_text, '')), '') is null
     and nullif(trim(coalesce(p_mood_b_text, '')), '') is null
      then 'global'
    else
      lower(
        regexp_replace(
          trim(
            concat_ws(
              '+',
              nullif(trim(coalesce(p_mood_a_text, '')), ''),
              nullif(trim(coalesce(p_mood_b_text, '')), '')
            )
          ),
          '\s+',
          ' ',
          'g'
        )
      )
  end;
$$;

ALTER FUNCTION "public"."backyrd_decision_context_key_v1"("p_mood_a_text" "text", "p_mood_b_text" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_embedding_queue_status_v13"() RETURNS TABLE("pending" integer, "processing" integer, "done" integer, "failed" integer, "total" integer)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    count(*) filter (where status = 'pending')::integer as pending,
    count(*) filter (where status = 'processing')::integer as processing,
    count(*) filter (where status = 'done')::integer as done,
    count(*) filter (where status = 'failed')::integer as failed,
    count(*)::integer as total
  from public.backyrd_embedding_jobs_v1;
$$;

ALTER FUNCTION "public"."backyrd_embedding_queue_status_v13"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_embedding_status_v13"() RETURNS TABLE("total_documents" integer, "total_embeddings" integer, "missing_embeddings" integer, "stale_embeddings" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    count(d.spot_id)::integer as total_documents,
    count(e.spot_id)::integer as total_embeddings,
    count(d.spot_id) filter (where e.spot_id is null)::integer as missing_embeddings,
    count(d.spot_id) filter (
      where e.spot_id is not null
        and e.source_hash <> d.source_hash
    )::integer as stale_embeddings
  from public.backyrd_spot_ml_documents_v1 d
  left join public.backyrd_spot_embeddings_v1 e
    on e.spot_id = d.spot_id;
$$;

ALTER FUNCTION "public"."backyrd_embedding_status_v13"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_enqueue_spot_embedding_v13"("p_spot_id" "uuid", "p_reason" "text" DEFAULT 'spot_changed'::"text") RETURNS TABLE("ok" boolean, "spot_id" "uuid", "status" "text", "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_doc record;
  v_status text;
begin
  if p_spot_id is null then
    raise exception 'spot_id_required';
  end if;

  perform public.backyrd_refresh_spot_ml_document_v13(p_spot_id);

  select
    d.spot_id,
    d.document_version,
    d.source_hash
  into v_doc
  from public.backyrd_spot_ml_documents_v1 d
  where d.spot_id = p_spot_id
  limit 1;

  if v_doc.spot_id is null then
    raise exception 'spot_ml_document_not_found';
  end if;

  insert into public.backyrd_embedding_jobs_v1 (
    spot_id,
    status,
    reason,
    document_version,
    source_hash,
    attempts,
    last_error,
    queued_at,
    locked_at,
    processed_at,
    created_at,
    updated_at
  )
  values (
    p_spot_id,
    'pending',
    coalesce(nullif(trim(p_reason), ''), 'spot_changed'),
    v_doc.document_version,
    v_doc.source_hash,
    0,
    null,
    now(),
    null,
    null,
    now(),
    now()
  )
  on conflict on constraint backyrd_embedding_jobs_v1_pkey
  do update set
    status = case
      when public.backyrd_embedding_jobs_v1.status = 'processing'
        and public.backyrd_embedding_jobs_v1.locked_at > now() - interval '5 minutes'
      then public.backyrd_embedding_jobs_v1.status
      else 'pending'
    end,
    reason = excluded.reason,
    document_version = excluded.document_version,
    source_hash = excluded.source_hash,
    attempts = case
      when public.backyrd_embedding_jobs_v1.source_hash is distinct from excluded.source_hash
      then 0
      else public.backyrd_embedding_jobs_v1.attempts
    end,
    last_error = null,
    queued_at = now(),
    processed_at = null,
    updated_at = now()
  returning public.backyrd_embedding_jobs_v1.status
  into v_status;

  return query
  select
    true as ok,
    p_spot_id as spot_id,
    coalesce(v_status, 'pending') as status,
    'embedding_job_queued'::text as message;
end;
$$;

ALTER FUNCTION "public"."backyrd_enqueue_spot_embedding_v13"("p_spot_id" "uuid", "p_reason" "text") OWNER TO "postgres";

