ALTER FUNCTION "public"."backyrd_get_context_keys_for_decision_v1"("p_city" "text", "p_mood_a_text" "text", "p_mood_b_text" "text", "p_context" "jsonb") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_get_decision_context_v2"("p_city" "text" DEFAULT NULL::"text", "p_selected_cluster_ids" integer[] DEFAULT NULL::integer[], "p_query" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 10) RETURNS TABLE("mode" "text", "strong_personalized" boolean, "weak_personalized" boolean, "used_semantic_fallback" boolean, "top_score" numeric, "top_raw_mood_strength" integer, "explanation" "text")
    LANGUAGE "sql" STABLE
    AS $$
with topn as (
  select *
  from public.backyrd_get_decision_debug_v2(
    p_city := p_city,
    p_selected_cluster_ids := p_selected_cluster_ids,
    p_query := p_query,
    p_limit := p_limit
  )
),
agg as (
  select
    max(final_score) as top_score,
    max(raw_mood_strength) as top_raw_mood_strength,
    bool_or(has_mood_signal) as any_mood_signal,
    bool_or(has_text_signal) as any_text_signal
  from topn
)
select
  case
    when a.top_raw_mood_strength >= 4 then 'strong_personalized'
    when a.any_mood_signal then 'weak_personalized'
    when a.any_text_signal then 'text_match'
    else 'fallback'
  end as mode,
  (a.top_raw_mood_strength >= 4) as strong_personalized,
  (a.any_mood_signal and a.top_raw_mood_strength < 4) as weak_personalized,
  (not a.any_mood_signal) as used_semantic_fallback,
  a.top_score,
  a.top_raw_mood_strength,
  case
    when a.top_raw_mood_strength >= 4 then 'Starkes Mood-Signal in den Top-Ergebnissen.'
    when a.any_mood_signal then 'Mood-Signal vorhanden, aber noch dünn (wenige Votes).'
    when a.any_text_signal then 'Kein Mood-Signal; Text-Match steuert das Ranking.'
    else 'Kein Mood/Text-Signal; Fallback (Trend/Popularität).'
  end as explanation
from agg a;
$$;

ALTER FUNCTION "public"."backyrd_get_decision_context_v2"("p_city" "text", "p_selected_cluster_ids" integer[], "p_query" "text", "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_get_decision_debug_v11"("p_city" "text" DEFAULT NULL::"text", "p_selected_cluster_ids" integer[] DEFAULT NULL::integer[], "p_query" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 10, "p_k" numeric DEFAULT 1.0, "p_open_bonus" numeric DEFAULT 0.0, "p_taste_weight" numeric DEFAULT 0.28, "p_explore_weight" numeric DEFAULT 0.05) RETURNS TABLE("spot_id" "uuid", "name" "text", "city" "text", "is_open_now" boolean, "final_score" numeric, "matched_tokens" "text"[], "matched_counts" integer[], "matched_terms" "text"[], "why_this" "text")
    LANGUAGE "sql" STABLE
    AS $$
with
  params as (
    select
      greatest(0, least(0.35, coalesce(p_taste_weight, 0.28)))::numeric as taste_w,
      greatest(0, least(0.20, coalesce(p_explore_weight, 0.05)))::numeric as explore_w
  ),
  base as (
    select
      d.spot_id,
      d.name,
      d.city,
      d.is_open_now,
      d.final_score as base_score,
      d.matched_tokens,
      d.matched_counts,
      d.matched_terms,
      d.why_this
    from public.backyrd_get_decision_debug_v3(
      p_city := p_city,
      p_selected_cluster_ids := p_selected_cluster_ids,
      p_query := p_query,
      p_limit := greatest(p_limit, 10),         -- wir holen mind. 10 als candidate set
      p_k := p_k,
      p_open_bonus := p_open_bonus
    ) d
  ),
  scored as (
    select
      b.*,

      -- Taste affinity can be negative/positive; 0 if no profile
      public.backyrd_get_user_taste_affinity_v2(b.spot_id) as taste_affinity,

      -- map affinity -> [0..1] smoothly (sigmoid)
      -- sigmoid(x) = 1/(1+e^-x). we scale x a bit to make it "feel" responsive.
      (1::numeric / (1::numeric + exp(-(coalesce(public.backyrd_get_user_taste_affinity_v2(b.spot_id),0) * 2))))::numeric
        as taste_component,

      -- deterministic explore component in [0..1] based on spot_id hash
      ((abs(hashtext(b.spot_id::text)) % 1000) / 1000.0)::numeric
        as explore_component
    from base b
  )
select
  s.spot_id,
  s.name,
  s.city,
  s.is_open_now,

  (
    -- weights
    ( (1 - p.taste_w - p.explore_w) * s.base_score )
    + ( p.taste_w * s.taste_component )
    + ( p.explore_w * s.explore_component )
  )::numeric as final_score,

  s.matched_tokens,
  s.matched_counts,
  s.matched_terms,

  -- keep old explanation for now (Explanation Engine v2 comes next)
  s.why_this

from scored s
cross join params p
order by final_score desc
limit p_limit;
$$;

ALTER FUNCTION "public"."backyrd_get_decision_debug_v11"("p_city" "text", "p_selected_cluster_ids" integer[], "p_query" "text", "p_limit" integer, "p_k" numeric, "p_open_bonus" numeric, "p_taste_weight" numeric, "p_explore_weight" numeric) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_get_decision_debug_v2"("p_city" "text" DEFAULT NULL::"text", "p_selected_cluster_ids" integer[] DEFAULT NULL::integer[], "p_query" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 30, "p_k" numeric DEFAULT 3.0, "p_open_bonus" numeric DEFAULT 0.02) RETURNS TABLE("spot_id" "uuid", "name" "text", "city" "text", "is_open_now" boolean, "raw_mood_strength" integer, "mood_strength_norm" numeric, "mood_match_count" integer, "text_match_score" numeric, "open_now_bonus" numeric, "final_score" numeric, "has_mood_signal" boolean, "has_text_signal" boolean, "used_semantic_fallback" boolean, "matched_tokens" "text"[], "matched_counts" integer[], "matched_terms" "text"[], "why_this" "text")
    LANGUAGE "sql" STABLE
    AS $$
with base_spots as (
  select s.id as spot_id, s.name, s.city
  from public.spots s
  where (p_city is null or s.city = p_city)
),
text_sig as (
  select
    b.spot_id,
    case
      when p_query is null or length(trim(p_query)) = 0 then 0::numeric
      when lower(b.name) like '%' || lower(p_query) || '%' then 1::numeric
      when lower(b.city) like '%' || lower(p_query) || '%' then 0.5::numeric
      else 0::numeric
    end as text_match_score,
    case
      when p_query is null or length(trim(p_query)) = 0 then array[]::text[]
      else array[p_query]::text[]
    end as matched_terms
  from base_spots b
),
token_counts as (
  select
    a.spot_id,
    a.mood_id as token_id,
    a.mood_count
  from public.spot_moods_agg_reviews_v1 a
  join base_spots b on b.spot_id = a.spot_id
),
token_to_cluster as (
  select
    tc.spot_id,
    mtc.cluster_id,
    tc.token_id,
    tc.mood_count
  from token_counts tc
  join public.mood_token_clusters mtc
    on mtc.token_id = tc.token_id
),
selected_cluster_token as (
  select *
  from token_to_cluster
  where (p_selected_cluster_ids is null or cluster_id = any(p_selected_cluster_ids))
),
mood_sig as (
  select
    sct.spot_id,
    coalesce(sum(sct.mood_count),0)::int as raw_mood_strength,
    count(distinct sct.cluster_id)::int as mood_match_count,
    -- explain: top contributing tokens
    array_agg(mt.token_norm order by sct.mood_count desc, mt.token_norm) filter (where sct.mood_count > 0) as matched_tokens_all,
    array_agg(sct.mood_count order by sct.mood_count desc, mt.token_norm) filter (where sct.mood_count > 0) as matched_counts_all
  from selected_cluster_token sct
  join public.mood_tokens mt on mt.id = sct.token_id
  group by sct.spot_id
),
open_sig as (
  select
    b.spot_id,
    public.spot_is_open_now_safe_v1(b.spot_id) as is_open_now
  from base_spots b
),
final as (
  select
    b.spot_id,
    b.name,
    b.city,
    o.is_open_now,
    coalesce(m.raw_mood_strength,0) as raw_mood_strength,
    -- smooth normalization (no cliffs):
    -- mood_strength_norm = 1 - exp(-raw/k)
    (1 - exp( - (coalesce(m.raw_mood_strength,0)::numeric) / nullif(p_k,0) ))::numeric as mood_strength_norm,
    coalesce(m.mood_match_count,0) as mood_match_count,
    coalesce(t.text_match_score,0) as text_match_score,
    case when o.is_open_now is true then p_open_bonus else 0::numeric end as open_now_bonus,
    -- Final score: mood dominates, text assists, open is tiny
    (
      (1 - exp( - (coalesce(m.raw_mood_strength,0)::numeric) / nullif(p_k,0) ))::numeric
      + (coalesce(t.text_match_score,0) * 0.15)
      + (case when o.is_open_now is true then p_open_bonus else 0::numeric end)
    ) as final_score,
    (coalesce(m.raw_mood_strength,0) > 0) as has_mood_signal,
    (coalesce(t.text_match_score,0) > 0) as has_text_signal,
    -- semantic fallback = no mood match (we’ll let context decide)
    (coalesce(m.raw_mood_strength,0) = 0) as used_semantic_fallback,
    -- cap explain arrays to keep UI clean
    coalesce(m.matched_tokens_all[1:5], array[]::text[]) as matched_tokens,
    coalesce(m.matched_counts_all[1:5], array[]::int[]) as matched_counts,
    coalesce(t.matched_terms, array[]::text[]) as matched_terms,
    -- WHY string: deterministic + honest
    case
      when coalesce(m.raw_mood_strength,0) > 0 then
        'Mood-Match: ' || coalesce(m.raw_mood_strength,0)::text || ' Signals, ' ||
        coalesce(m.mood_match_count,0)::text || ' Cluster. Top Token: ' ||
        coalesce((m.matched_tokens_all[1])::text, '—') || '.'
      when coalesce(t.text_match_score,0) > 0 then
        'Text-Match zu "' || p_query || '".'
      else
        'Fallback: wenig Mood/Text-Signal (Trend/Popularität o.ä.).'
    end as why_this
  from base_spots b
  left join mood_sig m on m.spot_id = b.spot_id
  left join text_sig t on t.spot_id = b.spot_id
  left join open_sig o on o.spot_id = b.spot_id
)
select *
from final
order by final_score desc, raw_mood_strength desc, name asc
limit p_limit;
$$;

ALTER FUNCTION "public"."backyrd_get_decision_debug_v2"("p_city" "text", "p_selected_cluster_ids" integer[], "p_query" "text", "p_limit" integer, "p_k" numeric, "p_open_bonus" numeric) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_get_decision_debug_v3"("p_city" "text" DEFAULT NULL::"text", "p_selected_cluster_ids" integer[] DEFAULT NULL::integer[], "p_query" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 30, "p_k" numeric DEFAULT 3.0, "p_open_bonus" numeric DEFAULT 0.02) RETURNS TABLE("spot_id" "uuid", "name" "text", "city" "text", "is_open_now" boolean, "raw_mood_strength" integer, "mood_strength_norm" numeric, "mood_match_count" integer, "text_match_score" numeric, "open_now_bonus" numeric, "final_score" numeric, "has_mood_signal" boolean, "has_text_signal" boolean, "used_semantic_fallback" boolean, "matched_tokens" "text"[], "matched_counts" integer[], "matched_terms" "text"[], "why_this" "text")
    LANGUAGE "sql" STABLE
    AS $$
with base_spots as (
  select s.id as spot_id, s.name, s.city
  from public.spots s
  where (p_city is null or s.city = p_city)
),
text_sig as (
  select
    b.spot_id,
    case
      when p_query is null or length(trim(p_query)) = 0 then 0::numeric
      when lower(b.name) like '%' || lower(p_query) || '%' then 1::numeric
      when lower(b.city) like '%' || lower(p_query) || '%' then 0.5::numeric
      else 0::numeric
    end as text_match_score,
    case
      when p_query is null or length(trim(p_query)) = 0 then array[]::text[]
      else array[p_query]::text[]
    end as matched_terms
  from base_spots b
),
cluster_tokens_mapped as (
  select distinct mtc.cluster_id, mtc.token_id
  from public.mood_token_clusters mtc
  where (p_selected_cluster_ids is null or mtc.cluster_id = any(p_selected_cluster_ids))
),
cluster_tokens_seed as (
  select distinct c.id as cluster_id, t.id as token_id
  from public.mood_clusters c
  join public.mood_tokens t
    on t.token_norm = c.name_norm
  where (p_selected_cluster_ids is null or c.id = any(p_selected_cluster_ids))
),
selected_cluster_tokens as (
  select * from cluster_tokens_mapped
  union
  select * from cluster_tokens_seed
),
token_counts as (
  select
    a.spot_id,
    a.mood_id as token_id,
    a.mood_count
  from public.spot_moods_agg_reviews_v1 a
  join base_spots b on b.spot_id = a.spot_id
),
selected_token_counts as (
  select
    tc.spot_id,
    sct.cluster_id,
    tc.token_id,
    tc.mood_count
  from token_counts tc
  join selected_cluster_tokens sct
    on sct.token_id = tc.token_id
),
mood_sig as (
  select
    stc.spot_id,
    coalesce(sum(stc.mood_count),0)::int as raw_mood_strength,
    count(distinct stc.cluster_id)::int as mood_match_count,
    array_agg(mt.token_norm order by stc.mood_count desc, mt.token_norm) filter (where stc.mood_count > 0) as matched_tokens_all,
    array_agg(stc.mood_count order by stc.mood_count desc, mt.token_norm) filter (where stc.mood_count > 0) as matched_counts_all
  from selected_token_counts stc
  join public.mood_tokens mt on mt.id = stc.token_id
  group by stc.spot_id
),
open_sig as (
  select
    b.spot_id,
    public.spot_is_open_now_safe_v1(b.spot_id) as is_open_now
  from base_spots b
),
final as (
  select
    b.spot_id,
    b.name,
    b.city,
    o.is_open_now,
    coalesce(m.raw_mood_strength,0) as raw_mood_strength,
    (1 - exp( - (coalesce(m.raw_mood_strength,0)::numeric) / nullif(p_k,0) ))::numeric as mood_strength_norm,
    coalesce(m.mood_match_count,0) as mood_match_count,
    coalesce(t.text_match_score,0) as text_match_score,
    case when o.is_open_now is true then p_open_bonus else 0::numeric end as open_now_bonus,
    (
      (1 - exp( - (coalesce(m.raw_mood_strength,0)::numeric) / nullif(p_k,0) ))::numeric
      + (coalesce(t.text_match_score,0) * 0.15)
      + (case when o.is_open_now is true then p_open_bonus else 0::numeric end)
    ) as final_score,
    (coalesce(m.raw_mood_strength,0) > 0) as has_mood_signal,
    (coalesce(t.text_match_score,0) > 0) as has_text_signal,
    (coalesce(m.raw_mood_strength,0) = 0) as used_semantic_fallback,
    coalesce(m.matched_tokens_all[1:5], array[]::text[]) as matched_tokens,
    coalesce(m.matched_counts_all[1:5], array[]::int[]) as matched_counts,
    coalesce(t.matched_terms, array[]::text[]) as matched_terms,
    case
      when coalesce(m.raw_mood_strength,0) > 0 then
        'Mood-Match: ' || coalesce(m.raw_mood_strength,0)::text || ' Signals, ' ||
        coalesce(m.mood_match_count,0)::text || ' Cluster. Top Token: ' ||
        coalesce((m.matched_tokens_all[1])::text, '—') || '.'
      when coalesce(t.text_match_score,0) > 0 then
        'Text-Match zu "' || p_query || '".'
      else
        'Fallback: wenig Mood/Text-Signal (Trend/Popularität o.ä.).'
    end as why_this
  from base_spots b
  left join mood_sig m on m.spot_id = b.spot_id
  left join text_sig t on t.spot_id = b.spot_id
  left join open_sig o on o.spot_id = b.spot_id
)
select *
from final
order by final_score desc, raw_mood_strength desc, name asc
limit p_limit;
$$;

ALTER FUNCTION "public"."backyrd_get_decision_debug_v3"("p_city" "text", "p_selected_cluster_ids" integer[], "p_query" "text", "p_limit" integer, "p_k" numeric, "p_open_bonus" numeric) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_get_decision_debug_v4"("p_city" "text" DEFAULT NULL::"text", "p_selected_cluster_ids" integer[] DEFAULT NULL::integer[], "p_query" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 10, "p_k" numeric DEFAULT 1.0, "p_open_bonus" numeric DEFAULT 0.0) RETURNS TABLE("spot_id" "uuid", "name" "text", "city" "text", "is_open_now" boolean, "raw_mood_strength" integer, "mood_strength_norm" numeric, "mood_match_count" integer, "text_match_score" numeric, "open_now_bonus" numeric, "final_score" numeric, "has_mood_signal" boolean, "has_text_signal" boolean, "used_semantic_fallback" boolean, "matched_tokens" "text"[], "matched_counts" integer[], "matched_terms" "text"[], "why_this" "text")
    LANGUAGE "sql" STABLE
    AS $$
with
inp as (
  select
    nullif(trim(p_city), '') as city,
    coalesce(p_selected_cluster_ids, array[]::integer[]) as cluster_ids,
    nullif(lower(trim(coalesce(p_query,''))), '') as q,
    greatest(coalesce(p_limit,10),1) as lim,
    greatest(coalesce(p_k,1.0), 0.01) as k,
    coalesce(p_open_bonus, 0.0) as open_bonus
),
q_terms as (
  select distinct t.term
  from inp
  cross join lateral (
    select regexp_replace(x, '\s+', ' ', 'g') as term
    from regexp_split_to_table(coalesce(inp.q,''), '[^a-z0-9_]+') x
  ) t
  where t.term is not null and length(t.term) >= 2
),
q_concepts_direct as (
  select mc.id as concept_id, mc.label_norm
  from q_terms qt
  join public.mood_concepts mc
    on mc.label_norm = qt.term
),
q_concepts_via_tokens as (
  select mtc.concept_id, mc.label_norm
  from q_terms qt
  join public.mood_tokens mt
    on mt.token_norm = qt.term and mt.valid = true
  join public.mood_token_concepts mtc
    on mtc.token_id = mt.id
  join public.mood_concepts mc
    on mc.id = mtc.concept_id
),
q_concepts as (
  select distinct concept_id, label_norm
  from (
    select * from q_concepts_direct
    union all
    select * from q_concepts_via_tokens
  ) u
),

concept_scores as (
  select
    smc.spot_id,
    sum(smc.strength) as concept_strength,
    count(*) as concept_match_count,
    array_agg(qc.label_norm order by smc.strength desc, qc.label_norm asc) as matched_concepts,
    array_agg(greatest(1, least(9, round(smc.strength*10)::int)) order by smc.strength desc, qc.label_norm asc) as matched_concept_counts
  from q_concepts qc
  join public.spot_mood_concepts smc
    on smc.concept_id = qc.concept_id
  group by smc.spot_id
),

cluster_scores as (
  select
    sma.spot_id,
    sum(sma.mood_count)::int as cluster_strength,
    count(*)::int as cluster_match_count
  from inp
  join public.spot_moods_agg sma
    on sma.mood_id = any(inp.cluster_ids)
  group by sma.spot_id
),
candidates as (
  select s.id as spot_id, s.name, s.city
  from inp
  join public.spots s
    on (inp.city is null or s.city = inp.city)
),
scored as (
  select
    c.spot_id,
    c.name,
    c.city,
    null::boolean as is_open_now,
    coalesce(cs.cluster_strength, 0) as cluster_strength,
    coalesce(cs.cluster_match_count, 0) as cluster_match_count,
    coalesce(co.concept_strength, 0) as concept_strength,
    coalesce(co.concept_match_count, 0) as concept_match_count,
    coalesce(co.matched_concepts, array[]::text[]) as matched_concepts,
    coalesce(co.matched_concept_counts, array[]::int[]) as matched_concept_counts
  from candidates c
  left join cluster_scores cs on cs.spot_id = c.spot_id
  left join concept_scores co on co.spot_id = c.spot_id
),
norm as (
  select
    s.*,
    (concept_strength / (concept_strength + (select k from inp)))::numeric as concept_norm,
    (cluster_strength / (cluster_strength + (select k from inp)))::numeric as cluster_norm
  from scored s
),
final as (
  select
    n.*,
    case
      when (select count(*) from q_concepts) > 0 then
        (0.75 * n.concept_norm + 0.25 * n.cluster_norm)
      else
        (1.00 * n.cluster_norm)
    end as score
  from norm n
),
topn as (
  select *
  from final
  order by score desc, name asc
  limit (select lim from inp)
)
select
  t.spot_id,
  t.name,
  t.city,
  t.is_open_now,
  case when (select count(*) from q_concepts) > 0 then round(t.concept_strength)::int else t.cluster_strength end as raw_mood_strength,
  case when (select count(*) from q_concepts) > 0 then t.concept_norm else t.cluster_norm end as mood_strength_norm,
  case when (select count(*) from q_concepts) > 0 then t.concept_match_count else t.cluster_match_count end as mood_match_count,
  case when (select count(*) from q_concepts) > 0 then t.concept_norm else 0 end as text_match_score,
  0::numeric as open_now_bonus,
  t.score as final_score,
  (case when (select count(*) from q_concepts) > 0 then t.concept_strength > 0 else t.cluster_strength > 0 end) as has_mood_signal,
  ((select count(*) from q_concepts) > 0) as has_text_signal,
  (case when ((select count(*) from q_concepts) > 0) then (t.concept_strength = 0 and t.cluster_strength = 0) else (t.cluster_strength = 0) end) as used_semantic_fallback,
  case when (select count(*) from q_concepts) > 0 then t.matched_concepts else array[]::text[] end as matched_tokens,
  case when (select count(*) from q_concepts) > 0 then t.matched_concept_counts else array[]::int[] end as matched_counts,
  case when (select count(*) from q_concepts) > 0 then (select array_agg(label_norm order by label_norm asc) from q_concepts) else array[]::text[] end as matched_terms,
  case
    when (select count(*) from q_concepts) = 0 and t.cluster_strength = 0 then
      'Fallback'
    when (select count(*) from q_concepts) = 0 then
      'Cluster'
    else
      'Concept'
  end as why_this
from topn t;
$$;

ALTER FUNCTION "public"."backyrd_get_decision_debug_v4"("p_city" "text", "p_selected_cluster_ids" integer[], "p_query" "text", "p_limit" integer, "p_k" numeric, "p_open_bonus" numeric) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_get_decision_spots_v10"("p_city" "text" DEFAULT NULL::"text", "p_selected_cluster_ids" integer[] DEFAULT NULL::integer[], "p_query" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 10) RETURNS TABLE("spot_id" "uuid", "name" "text", "city" "text", "is_open_now" boolean, "final_score" numeric, "matched_tokens" "text"[], "matched_counts" integer[], "matched_terms" "text"[], "why_this" "text")
    LANGUAGE "sql" STABLE
    AS $$
select
  d.spot_id,
  d.name,
  d.city,
  d.is_open_now,
  d.final_score,
  d.matched_tokens,
  d.matched_counts,
  d.matched_terms,
  d.why_this
from public.backyrd_get_decision_debug_v4(
  p_city := p_city,
  p_selected_cluster_ids := p_selected_cluster_ids,
  p_query := p_query,
  p_limit := p_limit,
  p_k := 1.0,
  p_open_bonus := 0.0
) d
order by d.final_score desc;
$$;

ALTER FUNCTION "public"."backyrd_get_decision_spots_v10"("p_city" "text", "p_selected_cluster_ids" integer[], "p_query" "text", "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_get_decision_spots_v11"("p_city" "text" DEFAULT NULL::"text", "p_selected_cluster_ids" integer[] DEFAULT NULL::integer[], "p_query" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 10, "p_k" numeric DEFAULT 1.0, "p_open_bonus" numeric DEFAULT 0.0, "p_taste_weight" numeric DEFAULT 0.28, "p_explore_weight" numeric DEFAULT 0.05) RETURNS TABLE("spot_id" "uuid", "name" "text", "city" "text", "is_open_now" boolean, "final_score" numeric, "matched_tokens" "text"[], "matched_counts" integer[], "matched_terms" "text"[], "why_this" "text")
    LANGUAGE "sql" STABLE
    AS $$
  select *
  from public.backyrd_get_decision_debug_v11(
    p_city := p_city,
    p_selected_cluster_ids := p_selected_cluster_ids,
    p_query := p_query,
    p_limit := p_limit,
    p_k := p_k,
    p_open_bonus := p_open_bonus,
    p_taste_weight := p_taste_weight,
    p_explore_weight := p_explore_weight
  )
  order by final_score desc;
$$;

ALTER FUNCTION "public"."backyrd_get_decision_spots_v11"("p_city" "text", "p_selected_cluster_ids" integer[], "p_query" "text", "p_limit" integer, "p_k" numeric, "p_open_bonus" numeric, "p_taste_weight" numeric, "p_explore_weight" numeric) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_get_decision_spots_v12"("p_city" "text" DEFAULT NULL::"text", "p_selected_cluster_ids" integer[] DEFAULT NULL::integer[], "p_query" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 10, "p_k" numeric DEFAULT 1.0, "p_open_bonus" numeric DEFAULT 0.0, "p_taste_weight" numeric DEFAULT 0.52, "p_explore_weight" numeric DEFAULT 0.055, "p_mood_a_text" "text" DEFAULT NULL::"text", "p_mood_b_text" "text" DEFAULT NULL::"text") RETURNS TABLE("spot_id" "uuid", "name" "text", "city" "text", "is_open_now" boolean, "final_score" numeric, "matched_tokens" "text"[], "matched_counts" integer[], "matched_terms" "text"[], "why_this" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_limit integer := greatest(1, least(coalesce(p_limit, 10), 20));
  v_candidate_limit integer := greatest(12, least(coalesce(p_limit, 10) * 5, 40));
  v_run_id uuid;

  v_mood_a text := public.backyrd_ml_norm_text_v1(p_mood_a_text);
  v_mood_b text := public.backyrd_ml_norm_text_v1(p_mood_b_text);

  rec record;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  insert into public.backyrd_recommendation_runs_v1 (
    user_id,
    source,
    city,
    mood_a_text,
    mood_b_text,
    model_name,
    model_version,
    candidate_count,
    shown_count,
    params,
    created_at
  )
  values (
    v_uid,
    'decision',
    nullif(trim(p_city), ''),
    nullif(trim(p_mood_a_text), ''),
    nullif(trim(p_mood_b_text), ''),
    'backyrd_decision_v12_relevance_clean',
    '1.0.6',
    v_candidate_limit,
    v_limit,
    jsonb_build_object(
      'p_query', p_query,
      'p_selected_cluster_ids', p_selected_cluster_ids,
      'p_k', p_k,
      'p_open_bonus', p_open_bonus,
      'p_taste_weight', p_taste_weight,
      'p_explore_weight', p_explore_weight,
      'note', 'deduped and capped mood relevance'
    ),
    now()
  )
  returning id into v_run_id;

  for rec in
    with raw_query_terms as (
      select unnest(
        array_remove(array[
          v_mood_a,
          v_mood_b,

          case when v_mood_a in ('cozy', 'gemütlich', 'gemuetlich') or v_mood_b in ('cozy', 'gemütlich', 'gemuetlich') then 'cozy' end,
          case when v_mood_a in ('cozy', 'gemütlich', 'gemuetlich') or v_mood_b in ('cozy', 'gemütlich', 'gemuetlich') then 'gemütlich' end,
          case when v_mood_a in ('cozy', 'gemütlich', 'gemuetlich') or v_mood_b in ('cozy', 'gemütlich', 'gemuetlich') then 'warm' end,
          case when v_mood_a in ('cozy', 'gemütlich', 'gemuetlich') or v_mood_b in ('cozy', 'gemütlich', 'gemuetlich') then 'intimate' end,

          case when v_mood_a in ('romantisch', 'romantic', 'date night', 'datenight') or v_mood_b in ('romantisch', 'romantic', 'date night', 'datenight') then 'romantisch' end,
          case when v_mood_a in ('romantisch', 'romantic', 'date night', 'datenight') or v_mood_b in ('romantisch', 'romantic', 'date night', 'datenight') then 'romantic' end,
          case when v_mood_a in ('romantisch', 'romantic', 'date night', 'datenight') or v_mood_b in ('romantisch', 'romantic', 'date night', 'datenight') then 'date' end,
          case when v_mood_a in ('romantisch', 'romantic', 'date night', 'datenight') or v_mood_b in ('romantisch', 'romantic', 'date night', 'datenight') then 'intimate' end
        ], null)
      )::text as term
    ),

    query_terms as (
      select distinct public.backyrd_ml_norm_text_v1(term) as term
      from raw_query_terms
      where public.backyrd_ml_norm_text_v1(term) is not null
    ),

    base_candidates as (
      select
        base.spot_id as candidate_spot_id,
        base.name as candidate_name,
        base.city as candidate_city,
        base.is_open_now as candidate_is_open_now,
        coalesce(base.final_score, 0)::numeric as base_score,
        coalesce(base.matched_tokens, '{}'::text[]) as candidate_matched_tokens,
        coalesce(base.matched_counts, '{}'::integer[]) as candidate_matched_counts,
        coalesce(base.matched_terms, '{}'::text[]) as candidate_matched_terms,
        base.why_this as candidate_why_this
      from public.backyrd_get_decision_spots_v11(
        p_city := p_city,
        p_selected_cluster_ids := p_selected_cluster_ids,
        p_query := p_query,
        p_limit := v_candidate_limit,
        p_k := p_k,
        p_open_bonus := p_open_bonus,
        p_taste_weight := 0.10,
        p_explore_weight := least(coalesce(p_explore_weight, 0.055), 0.08)
      ) as base
    ),

    enriched_candidates as (
      select
        bc.*,
        coalesce(cat.name, 'unknown') as category_name
      from base_candidates bc
      left join public.spots sp
        on sp.id = bc.candidate_spot_id
      left join public.categories cat
        on cat.id = sp.category_id
    ),

    scored as (
      select
        ec.candidate_spot_id,
        ec.candidate_name,
        ec.candidate_city,
        ec.candidate_is_open_now,
        ec.base_score,
        ec.candidate_matched_tokens,
        ec.candidate_matched_counts,
        ec.candidate_matched_terms,
        ec.candidate_why_this,
        ec.category_name,

        coalesce(taste.taste_score, 0)::numeric as taste_score,
        coalesce(taste.top_features, '[]'::jsonb) as top_features,

        least(2.0, coalesce(mood_rel.mood_relevance_score, 0))::numeric as mood_relevance_score,
        coalesce(mood_rel.mood_relevance_features, '[]'::jsonb) as mood_relevance_features,

        (
          case
            when least(2.0, coalesce(mood_rel.mood_relevance_score, 0)) >= 1.15 then 0.30
            when least(2.0, coalesce(mood_rel.mood_relevance_score, 0)) >= 0.70 then 0.22
            when least(2.0, coalesce(mood_rel.mood_relevance_score, 0)) >= 0.35 then 0.10
            else 0
          end
        )::numeric as direct_mood_bonus,

        (
          case
            when least(2.0, coalesce(mood_rel.mood_relevance_score, 0)) <= 0.05
              and ec.base_score < 0.42
            then -0.18
            else 0
          end
          +
          case
            when lower(ec.category_name) in ('nachtleben', 'club')
              and (
                v_mood_a in ('cozy', 'gemütlich', 'gemuetlich', 'romantisch', 'romantic')
                or v_mood_b in ('cozy', 'gemütlich', 'gemuetlich', 'romantisch', 'romantic')
              )
              and least(2.0, coalesce(mood_rel.mood_relevance_score, 0)) < 0.9
            then -0.22
            else 0
          end
          +
          case
            when lower(ec.category_name) = 'bar'
              and (
                v_mood_a in ('cozy', 'gemütlich', 'gemuetlich', 'romantisch', 'romantic')
                or v_mood_b in ('cozy', 'gemütlich', 'gemuetlich', 'romantisch', 'romantic')
              )
              and least(2.0, coalesce(mood_rel.mood_relevance_score, 0)) < 0.7
            then -0.10
            else 0
          end
        )::numeric as mood_relevance_penalty,

        (
          case
            when exists (
              select 1
              from public.backyrd_ml_events_v1 ev_seen
              where ev_seen.user_id = v_uid
                and ev_seen.spot_id = ec.candidate_spot_id
                and ev_seen.event_type = 'decision_impression'
                and ev_seen.created_at > now() - interval '3 days'
            )
            then -0.07
            else 0
          end
          +
          case
            when exists (
              select 1
              from public.backyrd_ml_events_v1 ev_disliked
              where ev_disliked.user_id = v_uid
                and ev_disliked.spot_id = ec.candidate_spot_id
                and ev_disliked.event_type = 'decision_dislike'
                and ev_disliked.created_at > now() - interval '21 days'
            )
            then -0.30
            else 0
          end
          +
          case
            when exists (
              select 1
              from public.backyrd_ml_events_v1 ev_liked
              where ev_liked.user_id = v_uid
                and ev_liked.spot_id = ec.candidate_spot_id
                and ev_liked.event_type in ('decision_like', 'decision_open', 'favorite_add')
                and ev_liked.created_at > now() - interval '45 days'
            )
            then 0.16
            else 0
          end
        )::numeric as behavior_adjustment,

        random()::numeric as explore_score

      from enriched_candidates ec

      left join lateral (
        select
          coalesce(
            sum(
              sf.feature_strength
              * ufw.weight
              * greatest(0.25, ufw.confidence)
            ),
            0
          )::numeric as taste_score,

          coalesce(
            jsonb_agg(
              jsonb_build_object(
                'feature_type', sf.feature_type,
                'feature_key', sf.feature_key,
                'spot_strength', sf.feature_strength,
                'user_weight', ufw.weight,
                'confidence', ufw.confidence,
                'contribution', sf.feature_strength * ufw.weight * greatest(0.25, ufw.confidence)
              )
              order by abs(sf.feature_strength * ufw.weight * greatest(0.25, ufw.confidence)) desc
            ) filter (where ufw.feature_key is not null),
            '[]'::jsonb
          ) as top_features

        from public.backyrd_ml_extract_spot_features_v1(ec.candidate_spot_id) sf
        join public.backyrd_user_feature_weights_v1 ufw
          on ufw.user_id = v_uid
         and ufw.feature_type = sf.feature_type
         and ufw.feature_key = sf.feature_key
      ) taste on true

      left join lateral (
        with matched_features as (
          select distinct
            sf.feature_type,
            sf.feature_key,
            sf.feature_strength
          from public.backyrd_ml_extract_spot_features_v1(ec.candidate_spot_id) sf
          join query_terms qt
            on sf.feature_key like '%' || qt.term || '%'
          where sf.feature_type in ('mood', 'mood_concept', 'keyword')
        )
        select
          coalesce(
            sum(least(1.0, mf.feature_strength)),
            0
          )::numeric as mood_relevance_score,

          coalesce(
            jsonb_agg(
              jsonb_build_object(
                'feature_type', mf.feature_type,
                'feature_key', mf.feature_key,
                'spot_strength', mf.feature_strength
              )
              order by mf.feature_strength desc
            ),
            '[]'::jsonb
          ) as mood_relevance_features
        from matched_features mf
      ) mood_rel on true
    ),

    diversity as (
      select
        sc.*,
        row_number() over (
          partition by sc.category_name
          order by sc.base_score desc, sc.taste_score desc, sc.candidate_name asc
        )::integer as category_position
      from scored sc
    ),

    final_ranked as (
      select
        dv.*,

        case
          when dv.category_position <= 1 then 0::numeric
          else (-0.07 * (dv.category_position - 1))::numeric
        end as diversity_penalty,

        (
          dv.base_score * 0.55
          + dv.taste_score * coalesce(p_taste_weight, 0.52)
          + dv.direct_mood_bonus
          + dv.mood_relevance_penalty
          + dv.explore_score * least(coalesce(p_explore_weight, 0.055), 0.08)
          + dv.behavior_adjustment
          + case
              when dv.category_position <= 1 then 0
              else -0.07 * (dv.category_position - 1)
            end
        )::numeric as combined_score
      from diversity dv
    ),

    numbered as (
      select
        fr.*,
        row_number() over (
          order by fr.combined_score desc, fr.candidate_name asc
        )::integer as final_position
      from final_ranked fr
    )

    select
      num.candidate_spot_id,
      num.candidate_name,
      num.candidate_city,
      num.candidate_is_open_now,
      num.combined_score,
      num.candidate_matched_tokens,
      num.candidate_matched_counts,
      num.candidate_matched_terms,
      num.candidate_why_this,
      num.category_name,
      num.base_score,
      num.taste_score,
      num.direct_mood_bonus,
      num.mood_relevance_score,
      num.mood_relevance_penalty,
      num.explore_score,
      num.behavior_adjustment,
      num.diversity_penalty,
      num.top_features,
      num.mood_relevance_features,
      num.final_position
    from numbered num
    where num.final_position <= v_limit
    order by num.final_position asc
  loop
    insert into public.backyrd_recommendation_run_items_v1 (
      run_id,
      spot_id,
      rank,
      score,
      taste_score,
      mood_score,
      explore_score,
      penalty_score,
      reasons,
      created_at
    )
    values (
      v_run_id,
      rec.candidate_spot_id,
      rec.final_position,
      rec.combined_score,
      rec.taste_score,
      rec.direct_mood_bonus,
      rec.explore_score,
      rec.behavior_adjustment + rec.diversity_penalty + rec.mood_relevance_penalty,
      jsonb_build_object(
        'model', 'backyrd_decision_v12_relevance_clean',
        'model_version', '1.0.6',
        'category_name', rec.category_name,
        'base_score', rec.base_score,
        'taste_score', rec.taste_score,
        'direct_mood_bonus', rec.direct_mood_bonus,
        'mood_relevance_score', rec.mood_relevance_score,
        'mood_relevance_penalty', rec.mood_relevance_penalty,
        'explore_score', rec.explore_score,
        'behavior_adjustment', rec.behavior_adjustment,
        'diversity_penalty', rec.diversity_penalty,
        'top_taste_features', rec.top_features,
        'mood_relevance_features', rec.mood_relevance_features,
        'matched_tokens', rec.candidate_matched_tokens,
        'matched_terms', rec.candidate_matched_terms
      ),
      now()
    );

    spot_id := rec.candidate_spot_id;
    name := rec.candidate_name;
    city := rec.candidate_city;
    is_open_now := rec.candidate_is_open_now;
    final_score := rec.combined_score;
    matched_tokens := rec.candidate_matched_tokens;
    matched_counts := rec.candidate_matched_counts;
    matched_terms := rec.candidate_matched_terms;

    why_this :=
      case
        when rec.taste_score > 0.16 and rec.mood_relevance_score > 0.35 then
          trim(coalesce(rec.candidate_why_this, '') || ' Passt außerdem gut zu dem, was dir bisher gefallen hat.')
        when rec.mood_relevance_score > 0.70 then
          trim(coalesce(rec.candidate_why_this, '') || ' Trifft die Richtung deiner aktuellen Stimmung ziemlich klar.')
        when rec.behavior_adjustment < -0.25 then
          trim(coalesce(rec.candidate_why_this, '') || ' Ich bin hier etwas vorsichtig, weil du Ähnliches zuletzt eher übersprungen hast.')
        else
          rec.candidate_why_this
      end;

    return next;
  end loop;

  return;
end;
$$;

ALTER FUNCTION "public"."backyrd_get_decision_spots_v12"("p_city" "text", "p_selected_cluster_ids" integer[], "p_query" "text", "p_limit" integer, "p_k" numeric, "p_open_bonus" numeric, "p_taste_weight" numeric, "p_explore_weight" numeric, "p_mood_a_text" "text", "p_mood_b_text" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_get_decision_spots_v9"("p_city" "text" DEFAULT NULL::"text", "p_selected_cluster_ids" integer[] DEFAULT NULL::integer[], "p_query" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 10) RETURNS TABLE("spot_id" "uuid", "name" "text", "city" "text", "is_open_now" boolean, "final_score" numeric, "matched_tokens" "text"[], "matched_counts" integer[], "matched_terms" "text"[], "why_this" "text")
    LANGUAGE "sql" STABLE
    AS $$
select
  d.spot_id,
  d.name,
  d.city,
  d.is_open_now,
  d.final_score,
  d.matched_tokens,
  d.matched_counts,
  d.matched_terms,
  d.why_this
from public.backyrd_get_decision_debug_v3(
  p_city := p_city,
  p_selected_cluster_ids := p_selected_cluster_ids,
  p_query := p_query,
  p_limit := p_limit
) d
order by d.final_score desc;
$$;

