    p.confidence,
    p.positive_count,
    p.negative_count,
    p.last_event_at
  from public.backyrd_user_context_feature_preferences_v1 p
  where p.user_id = auth.uid()
    and p.context_key = any(coalesce(p_context_keys, array['global']::text[]))
  order by
    case p.context_scope
      when 'category_situation' then 0
      when 'situation' then 1
      when 'category' then 2
      when 'global' then 3
