CREATE OR REPLACE FUNCTION "public"."backyrd_get_place_type_reason_v1"("p_user_id" "uuid", "p_place_type" "text", "p_mood_a_text" "text" DEFAULT NULL::"text", "p_mood_b_text" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_context_key text;
  v_label text;
  v_context_weight numeric := 0;
  v_global_weight numeric := 0;
begin
  v_context_key := public.backyrd_decision_context_key_v1(p_mood_a_text, p_mood_b_text);
  v_label := public.backyrd_place_type_label_v1(p_place_type);

  select coalesce(p.weight, 0)
    into v_context_weight
  from public.user_place_type_preferences_v1 p
  where p.user_id = p_user_id
    and p.context_key = v_context_key
    and p.place_type = p_place_type
  limit 1;

  select coalesce(p.weight, 0)
    into v_global_weight
  from public.user_place_type_preferences_v1 p
  where p.user_id = p_user_id
    and p.context_key = 'global'
    and p.place_type = p_place_type
  limit 1;

  if coalesce(v_context_weight, 0) > 0.25 then
    return 'Du reagierst bei dieser Stimmung öfter positiv auf ' || v_label || '-Orte.';
  elsif coalesce(v_global_weight, 0) > 0.25 then
    return 'Du magst generell häufiger ' || v_label || '-Orte.';
  elsif coalesce(v_context_weight, 0) < -0.2 then
    return 'Bei dieser Stimmung war ' || v_label || ' bisher eher selten dein Treffer.';
  else
    return null;
  end if;
end;
$$;

ALTER FUNCTION "public"."backyrd_get_place_type_reason_v1"("p_user_id" "uuid", "p_place_type" "text", "p_mood_a_text" "text", "p_mood_b_text" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_get_recent_decision_memory_v1"("p_hours" integer DEFAULT 48, "p_limit" integer DEFAULT 200) RETURNS TABLE("spot_id" "uuid", "spot_name" "text", "memory_kind" "text", "last_event_type" "text", "last_rank" integer, "penalty" numeric, "bonus" numeric, "last_event_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with recent as (
    select distinct on (e.spot_id)
      e.spot_id,
      s.name as spot_name,
      e.event_type,
      e.rank,
      e.signal_strength,
      e.created_at
    from public.backyrd_ml_events_v1 e
    left join public.spots s
      on s.id = e.spot_id
    where e.user_id = auth.uid()
      and e.spot_id is not null
      and e.created_at >= now() - make_interval(hours => greatest(1, least(coalesce(p_hours, 48), 720)))
      and e.event_type in (
        'decision_impression',
        'decision_like',
        'decision_dislike',
        'decision_open',
        'favorite_add',
        'spot_detail_view'
      )
    order by e.spot_id, e.created_at desc
  )
  select
    r.spot_id,
    r.spot_name,
    case
      when r.event_type = 'decision_dislike' then 'recent_dislike'
      when r.event_type in ('decision_like', 'favorite_add') then 'recent_positive'
      when r.event_type in ('decision_open', 'spot_detail_view') then 'recent_open'
      when r.event_type = 'decision_impression' then 'recent_seen'
      else 'recent'
    end as memory_kind,
    r.event_type as last_event_type,
    r.rank as last_rank,
    case
      when r.event_type = 'decision_dislike' then -0.34
      when r.event_type in ('decision_like', 'favorite_add') then -0.07
      when r.event_type in ('decision_open', 'spot_detail_view') then -0.06
      when r.event_type = 'decision_impression' then -0.045
      else 0
    end::numeric as penalty,
    case
      when r.event_type in ('decision_like', 'favorite_add') then 0.10
      when r.event_type in ('decision_open', 'spot_detail_view') then 0.04
      else 0
    end::numeric as bonus,
    r.created_at as last_event_at
  from recent r
  order by r.created_at desc
  limit greatest(1, least(coalesce(p_limit, 200), 500));
$$;

ALTER FUNCTION "public"."backyrd_get_recent_decision_memory_v1"("p_hours" integer, "p_limit" integer) OWNER TO "postgres";

