CREATE OR REPLACE FUNCTION "public"."backyrd_get_spot_taxonomy_ml_v1"("p_spot_id" "uuid", "p_locale" "text" DEFAULT 'de'::"text") RETURNS TABLE("taxonomy_json" "jsonb", "subcategories" "text"[], "features" "text"[], "services" "text"[], "offerings" "text"[], "synonyms" "text"[], "weighted_text" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
with effective as (
  select distinct on (st.taxonomy_node_id)
    st.taxonomy_node_id,
    tn.slug,
    tn.node_type,
    tn.ml_weight,
    st.source,
    st.confidence,
    st.is_verified,
    coalesce(req.label, de.label, en.label, tn.slug) as label
  from public.spot_taxonomies st
  join public.taxonomy_nodes tn
    on tn.id = st.taxonomy_node_id
   and tn.is_active = true
  left join public.taxonomy_node_translations req
    on req.taxonomy_node_id = tn.id
   and req.locale = case when p_locale in ('de','en','fr','it') then p_locale else 'de' end
  left join public.taxonomy_node_translations de
    on de.taxonomy_node_id = tn.id and de.locale = 'de'
  left join public.taxonomy_node_translations en
    on en.taxonomy_node_id = tn.id and en.locale = 'en'
  where st.spot_id = p_spot_id
  order by
    st.taxonomy_node_id,
    case st.source
      when 'admin' then 1
      when 'owner' then 2
      when 'community' then 3
      when 'ai' then 4
      when 'import' then 5
      else 9
    end,
    st.is_verified desc,
    st.confidence desc,
    st.updated_at desc
),
synonym_rows as (
  select
    e.taxonomy_node_id,
    array_agg(distinct ts.synonym order by ts.synonym)
      filter (where ts.synonym is not null) as node_synonyms
  from effective e
  left join public.taxonomy_synonyms ts
    on ts.taxonomy_node_id = e.taxonomy_node_id
   and ts.locale = case when p_locale in ('de','en','fr','it') then p_locale else 'de' end
   and ts.weight >= 0.700
  group by e.taxonomy_node_id
),
node_json as (
  select jsonb_agg(
    jsonb_build_object(
      'id', e.taxonomy_node_id,
      'slug', e.slug,
      'type', e.node_type,
      'label', e.label,
      'ml_weight', e.ml_weight,
      'source', e.source,
      'confidence', e.confidence,
      'is_verified', e.is_verified,
      'synonyms', coalesce(sr.node_synonyms, '{}'::text[])
    )
    order by e.node_type, e.ml_weight desc, e.label
  ) as taxonomy_json
  from effective e
  left join synonym_rows sr on sr.taxonomy_node_id = e.taxonomy_node_id
),
arrays as (
  select
    array_agg(e.label order by e.ml_weight desc, e.label)
      filter (where e.node_type = 'subcategory') as subcategories,
    array_agg(e.label order by e.ml_weight desc, e.label)
      filter (where e.node_type = 'feature') as features,
    array_agg(e.label order by e.ml_weight desc, e.label)
      filter (where e.node_type = 'service') as services,
    array_agg(e.label order by e.ml_weight desc, e.label)
      filter (where e.node_type = 'offering') as offerings
  from effective e
),
all_synonyms as (
  select array_agg(distinct x.synonym order by x.synonym) as synonyms
  from synonym_rows sr
  cross join lateral unnest(coalesce(sr.node_synonyms, '{}'::text[])) as x(synonym)
),
weighted as (
  select string_agg(
    trim(both ' ' from concat_ws(
      ' ',
      e.label,
      case when e.ml_weight >= 0.75 then e.label end,
      case when e.ml_weight >= 1.25 then e.label end,
      case when e.ml_weight >= 1.75 then e.label end
    )),
    ' | '
    order by e.node_type, e.ml_weight desc, e.label
  ) as weighted_text
  from effective e
  where e.ml_weight > 0
)
select
  coalesce(n.taxonomy_json, '[]'::jsonb),
  coalesce(a.subcategories, '{}'::text[]),
  coalesce(a.features, '{}'::text[]),
  coalesce(a.services, '{}'::text[]),
  coalesce(a.offerings, '{}'::text[]),
  coalesce(s.synonyms, '{}'::text[]),
  coalesce(w.weighted_text, '')
from node_json n
cross join arrays a
cross join all_synonyms s
cross join weighted w;
$$;

ALTER FUNCTION "public"."backyrd_get_spot_taxonomy_ml_v1"("p_spot_id" "uuid", "p_locale" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_get_user_taste_affinity_v2"("p_spot_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  with u as (
    select user_id, concept_id, weight
    from public.user_taste_concepts_v2
    where user_id = auth.uid()
  )
  select coalesce(sum(u.weight * smc.strength), 0)::numeric
  from public.spot_mood_concepts smc
  join u on u.concept_id = smc.concept_id
  where smc.spot_id = p_spot_id;
$$;

