CREATE OR REPLACE FUNCTION "public"."backyrd_infer_place_type_from_category_v1"("p_category_name" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when p_category_name is null then null

    when lower(p_category_name) like '%café%'
      or lower(p_category_name) like '%cafe%'
      or lower(p_category_name) like '%kaffee%'
      then 'cafe'

    when lower(p_category_name) like '%bar%'
      or lower(p_category_name) like '%wein%'
      or lower(p_category_name) like '%cocktail%'
      then 'bar'

    when lower(p_category_name) like '%restaurant%'
      or lower(p_category_name) like '%essen%'
      or lower(p_category_name) like '%food%'
      then 'restaurant'

    when lower(p_category_name) like '%nacht%'
      or lower(p_category_name) like '%club%'
      then 'nightlife'

    when lower(p_category_name) like '%museum%'
      or lower(p_category_name) like '%kultur%'
      or lower(p_category_name) like '%kunst%'
      then 'culture'

    when lower(p_category_name) like '%ausflug%'
      or lower(p_category_name) like '%aussicht%'
      or lower(p_category_name) like '%park%'
      then 'outing'

    when lower(p_category_name) like '%aktivität%'
      or lower(p_category_name) like '%aktivitaet%'
      or lower(p_category_name) like '%sport%'
      or lower(p_category_name) like '%bewegung%'
      then 'activity'

    when lower(p_category_name) like '%erlebnis%'
      or lower(p_category_name) like '%besonderes%'
      then 'experience'

    when lower(p_category_name) like '%hotel%'
      or lower(p_category_name) like '%unterkunft%'
      then 'hotel'

    else null
  end;
$$;

ALTER FUNCTION "public"."backyrd_infer_place_type_from_category_v1"("p_category_name" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_jsonb_collect_texts_v1"("p_json" "jsonb", "p_keys" "text"[]) RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare
  v_key text;
  v_result text[] := '{}'::text[];
  v_value jsonb;
  v_text text;
begin
  if p_json is null then
    return '{}'::text[];
  end if;

  foreach v_key in array coalesce(p_keys, '{}'::text[]) loop
    v_value := p_json -> v_key;

    if v_value is null or v_value = 'null'::jsonb then
      continue;
    end if;

    if jsonb_typeof(v_value) = 'array' then
      for v_text in
        select nullif(trim(value), '')
        from jsonb_array_elements_text(v_value) as value
      loop
        if v_text is not null and not (v_text = any(v_result)) then
          v_result := array_append(v_result, v_text);
        end if;
      end loop;
    else
      v_text := nullif(trim(p_json ->> v_key), '');
      if v_text is not null and not (v_text = any(v_result)) then
        v_result := array_append(v_result, v_text);
      end if;
    end if;
  end loop;

  return coalesce(v_result, '{}'::text[]);
end;
$$;

ALTER FUNCTION "public"."backyrd_jsonb_collect_texts_v1"("p_json" "jsonb", "p_keys" "text"[]) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_log_decision_action_v1"("p_decision_id" "uuid", "p_spot_id" "uuid", "p_action" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_action text := lower(trim(coalesce(p_action, '')));
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  if p_decision_id is null or p_spot_id is null or v_action = '' then
    raise exception 'bad_request' using errcode = '22023';
  end if;

  if v_action not in ('tapped', 'was_here', 'exact_mood', 'not_there') then
    raise exception 'bad_request' using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.decision_sessions ds
    where ds.id = p_decision_id
      and ds.user_id = v_uid
  ) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if v_action = 'tapped' then
    insert into public.decision_actions (
      decision_id,
      spot_id,
      action,
      created_at
    )
    values (
      p_decision_id,
      p_spot_id,
      'tapped',
      now()
    )
    on conflict do nothing;

    return;
  end if;

  if exists (
    select 1
    from public.decision_actions da
    where da.decision_id = p_decision_id
      and da.spot_id = p_spot_id
      and da.action in ('was_here', 'exact_mood', 'not_there')
  ) then
    update public.decision_actions da
    set
      action = v_action,
      created_at = now()
    where da.decision_id = p_decision_id
      and da.spot_id = p_spot_id
      and da.action in ('was_here', 'exact_mood', 'not_there');
  else
    insert into public.decision_actions (
      decision_id,
      spot_id,
      action,
      created_at
    )
    values (
      p_decision_id,
      p_spot_id,
      v_action,
      now()
    );
  end if;

  -- Important:
  -- No rebuild_user_taste_profile here anymore.
  -- ML learning is handled by backyrd_ml_log_event_v1.
  return;
end;
$$;

