CREATE OR REPLACE FUNCTION "public"."backyrd_log_taste_event_v2"("p_spot_id" "uuid", "p_event_type" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_factor numeric;
begin
  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  -- event factors (high-end default)
  v_factor := case lower(coalesce(p_event_type,''))
    when 'tapped' then 0.04
    when 'was_here' then 0.10
    when 'exact_mood' then 0.18
    when 'not_there' then -0.12
    when 'saved' then 0.14
    else 0.02
  end;

  insert into public.user_taste_events_v2(user_id, spot_id, event_type, factor)
  values (v_user_id, p_spot_id, lower(coalesce(p_event_type,'')), v_factor);

  -- update weights per concept
  insert into public.user_taste_concepts_v2(user_id, concept_id, weight, confidence, updated_at)
  select
    v_user_id,
    smc.concept_id,
    -- weight update: weight += strength * factor, then clamp to [-1, +1]
    greatest(-1, least(1, (coalesce(utc.weight,0) + (smc.strength * v_factor)))),
    -- confidence update: small positive step with any interaction
    greatest(0, least(1, coalesce(utc.confidence,0) + 0.03)),
    now()
  from public.spot_mood_concepts smc
  left join public.user_taste_concepts_v2 utc
    on utc.user_id = v_user_id and utc.concept_id = smc.concept_id
  where smc.spot_id = p_spot_id
  on conflict (user_id, concept_id) do update set
    weight = excluded.weight,
    confidence = excluded.confidence,
    updated_at = excluded.updated_at;

end;
$$;

ALTER FUNCTION "public"."backyrd_log_taste_event_v2"("p_spot_id" "uuid", "p_event_type" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_log_taste_event_v2"("p_spot_id" "uuid", "p_event_type" "text", "p_cap" numeric DEFAULT 0.4, "p_conf_inc" numeric DEFAULT 0.03) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.backyrd_log_taste_event_v3(
    p_spot_id := p_spot_id,
    p_event_type := p_event_type,
    p_cap := p_cap,
    p_conf_inc := p_conf_inc
  );
end;
$$;

ALTER FUNCTION "public"."backyrd_log_taste_event_v2"("p_spot_id" "uuid", "p_event_type" "text", "p_cap" numeric, "p_conf_inc" numeric) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_log_taste_event_v3"("p_spot_id" "uuid", "p_event_type" "text", "p_cap" numeric DEFAULT 0.4, "p_conf_inc" numeric DEFAULT 0.03) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_event_type text := lower(trim(coalesce(p_event_type, '')));
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  -- Keep a tiny compatibility event if the table exists.
  -- Do NOT rebuild taste profiles here anymore.
  -- Do NOT update old taste concept tables here anymore.
  -- New ML learning happens through backyrd_ml_log_event_v1 from the app.
  if exists (
    select 1
    from information_schema.tables
    where table_schema = 'public'
      and table_name = 'user_taste_events_v2'
  ) then
    insert into public.user_taste_events_v2 (
      user_id,
      spot_id,
      event_type,
      factor,
      created_at
    )
    values (
      v_uid,
      p_spot_id,
      v_event_type,
      case
        when v_event_type in ('exact_mood', 'was_here') then 0.01
        when v_event_type = 'tapped' then 0.005
        when v_event_type = 'not_there' then -0.005
        else 0
      end,
      now()
    );
  end if;

  return;
exception
  when others then
    -- Legacy logging must never break Decision UX.
    return;
end;
$$;

ALTER FUNCTION "public"."backyrd_log_taste_event_v3"("p_spot_id" "uuid", "p_event_type" "text", "p_cap" numeric, "p_conf_inc" numeric) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_mark_spot_embedding_job_done_v13"("p_spot_id" "uuid", "p_source_hash" "text" DEFAULT NULL::"text") RETURNS TABLE("ok" boolean, "spot_id" "uuid", "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  update public.backyrd_embedding_jobs_v1 j
  set
    status = 'done',
    source_hash = coalesce(p_source_hash, j.source_hash),
    last_error = null,
    locked_at = null,
    processed_at = now(),
    updated_at = now()
  where j.spot_id = p_spot_id;

  ok := true;
  spot_id := p_spot_id;
  message := 'embedding_job_done';
  return next;
end;
$$;

ALTER FUNCTION "public"."backyrd_mark_spot_embedding_job_done_v13"("p_spot_id" "uuid", "p_source_hash" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_mark_spot_embedding_job_failed_v13"("p_spot_id" "uuid", "p_error" "text" DEFAULT NULL::"text") RETURNS TABLE("ok" boolean, "spot_id" "uuid", "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_attempts integer;
  v_max_attempts integer;
begin
  select attempts, max_attempts
  into v_attempts, v_max_attempts
  from public.backyrd_embedding_jobs_v1
  where spot_id = p_spot_id;

  update public.backyrd_embedding_jobs_v1 j
  set
    status = case
      when coalesce(v_attempts, 0) >= coalesce(v_max_attempts, 5)
      then 'failed'
      else 'pending'
    end,
    last_error = left(coalesce(p_error, 'unknown_error'), 2000),
    locked_at = null,
    updated_at = now()
  where j.spot_id = p_spot_id;

  ok := true;
  spot_id := p_spot_id;
  message := 'embedding_job_failed_recorded';
  return next;
end;
$$;

ALTER FUNCTION "public"."backyrd_mark_spot_embedding_job_failed_v13"("p_spot_id" "uuid", "p_error" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_match_spot_embeddings_v13"("p_query_embedding" "public"."vector", "p_city" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20, "p_exclude_spot_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS TABLE("spot_id" "uuid", "name" "text", "city" "text", "category_name" "text", "similarity" numeric, "document_text" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    s.id as spot_id,
    s.name,
    s.city,
    c.name as category_name,
    (1 - (e.embedding <=> p_query_embedding))::numeric as similarity,
    d.document_text
  from public.backyrd_spot_embeddings_v1 e
  join public.spots s
    on s.id = e.spot_id
  left join public.categories c
    on c.id = s.category_id
  join public.backyrd_spot_ml_documents_v1 d
    on d.spot_id = e.spot_id
  where s.status::text = 'approved'
    and (
      p_city is null
      or trim(p_city) = ''
      or lower(coalesce(s.city, '')) = lower(trim(p_city))
      or lower(coalesce(d.document_json->>'city', '')) = lower(trim(p_city))
    )
    and not (s.id = any(coalesce(p_exclude_spot_ids, '{}'::uuid[])))
  order by e.embedding <=> p_query_embedding
  limit greatest(1, least(coalesce(p_limit, 20), 100));
$$;

ALTER FUNCTION "public"."backyrd_match_spot_embeddings_v13"("p_query_embedding" "public"."vector", "p_city" "text", "p_limit" integer, "p_exclude_spot_ids" "uuid"[]) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_ml_clean_text_v13"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select nullif(
    trim(
      regexp_replace(
        regexp_replace(
          coalesce(p_text, ''),
          '[\r\n\t]+',
          ' ',
          'g'
        ),
        '\s+',
        ' ',
        'g'
      )
    ),
    ''
  );
$$;

ALTER FUNCTION "public"."backyrd_ml_clean_text_v13"("p_text" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_ml_event_strength_v1"("p_event_type" "text") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case lower(coalesce(p_event_type, ''))
    when 'decision_impression' then 0.01
    when 'decision_like' then 0.22
    when 'decision_dislike' then -0.10
    when 'decision_open' then 0.14
    when 'decision_remix' then -0.025
    when 'favorite_add' then 0.38
    when 'favorite_remove' then -0.18
    when 'review_create' then 0.48
    when 'review_update' then 0.20
    when 'spot_detail_view' then 0.08
    when 'search_result_click' then 0.10
    when 'map_spot_tap' then 0.08
    else 0
  end;
$$;

ALTER FUNCTION "public"."backyrd_ml_event_strength_v1"("p_event_type" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_ml_events_contextual_taste_trigger_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  begin
    perform public.backyrd_apply_contextual_taste_from_event_v1(new.id);
  exception
    when others then
      raise warning 'contextual taste update failed for event %: %', new.id, sqlerrm;
  end;

  return new;
end;
$$;

ALTER FUNCTION "public"."backyrd_ml_events_contextual_taste_trigger_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_ml_extract_spot_features_v1"("p_spot_id" "uuid") RETURNS TABLE("feature_type" "text", "feature_key" "text", "feature_strength" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with base_spot as (
    select
      s.id,
      s.city,
      s.price_level,
      s.category_id,
      c.name as category_name
    from public.spots s
    left join public.categories c on c.id = s.category_id
    where s.id = p_spot_id
  ),

  city_features as (
    select
      'city'::text as feature_type,
      'city:' || public.backyrd_ml_norm_text_v1(city) as feature_key,
      0.45::numeric as feature_strength
    from base_spot
    where public.backyrd_ml_norm_text_v1(city) is not null
  ),

  category_features as (
    select
      'category'::text as feature_type,
      'category:' || public.backyrd_ml_norm_text_v1(category_name) as feature_key,
      0.85::numeric as feature_strength
    from base_spot
    where public.backyrd_ml_norm_text_v1(category_name) is not null
  ),

  price_features as (
    select
      'price'::text as feature_type,
      'price:' || price_level::text as feature_key,
      0.35::numeric as feature_strength
    from base_spot
    where price_level is not null
  ),

  mood_features as (
    select
      'mood'::text as feature_type,
      'mood:' || public.backyrd_ml_norm_text_v1(coalesce(mt.token_norm, mt.token::text)) as feature_key,
      greatest(
        0.15,
        least(
          1.15,
          0.25 + coalesce(sm.rank, 1)::numeric * 0.2 + least(0.5, coalesce(sm.mood_count, 0)::numeric * 0.08)
        )
      )::numeric as feature_strength
    from public.spot_moods sm
    join public.mood_tokens mt on mt.id = sm.mood_id
    where sm.spot_id = p_spot_id
      and mt.valid = true
      and public.backyrd_ml_norm_text_v1(coalesce(mt.token_norm, mt.token::text)) is not null
  ),

  concept_features as (
    select
      'mood_concept'::text as feature_type,
      'concept:' || public.backyrd_ml_norm_text_v1(coalesce(mc.label_norm, mc.label)) as feature_key,
      greatest(0.1, least(1.5, coalesce(smc.strength, 0.4)))::numeric as feature_strength
    from public.spot_mood_concepts smc
    join public.mood_concepts mc on mc.id = smc.concept_id
    where smc.spot_id = p_spot_id
      and public.backyrd_ml_norm_text_v1(coalesce(mc.label_norm, mc.label)) is not null
  ),

  keyword_features as (
    select
      'keyword'::text as feature_type,
      'keyword:' || public.backyrd_ml_norm_text_v1(keyword_value) as feature_key,
      0.42::numeric as feature_strength
    from public.spot_effective_content_v1 ec
    cross join lateral unnest(coalesce(ec.effective_keywords, '{}'::text[])) as keyword_value
    where ec.spot_id = p_spot_id
      and public.backyrd_ml_norm_text_v1(keyword_value) is not null
  ),

  intelligence_best_for_features as (
    select
      'best_for'::text as feature_type,
      'best_for:' || public.backyrd_ml_norm_text_v1(value) as feature_key,
      0.72::numeric as feature_strength
    from public.spot_intelligence_v1 si
    cross join lateral unnest(coalesce(si.best_for, '{}'::text[])) as value
    where si.spot_id = p_spot_id
      and public.backyrd_ml_norm_text_v1(value) is not null
  ),

  intelligence_occasion_features as (
    select
      'occasion'::text as feature_type,
      'occasion:' || public.backyrd_ml_norm_text_v1(value) as feature_key,
      0.62::numeric as feature_strength
    from public.spot_intelligence_v1 si
    cross join lateral unnest(coalesce(si.occasion_tags, '{}'::text[])) as value
    where si.spot_id = p_spot_id
      and public.backyrd_ml_norm_text_v1(value) is not null
  ),

  intelligence_atmosphere_features as (
    select
      'atmosphere'::text as feature_type,
      'atmosphere:' || public.backyrd_ml_norm_text_v1(value) as feature_key,
      0.68::numeric as feature_strength
    from public.spot_intelligence_v1 si
    cross join lateral unnest(coalesce(si.atmosphere_tags, '{}'::text[])) as value
    where si.spot_id = p_spot_id
      and public.backyrd_ml_norm_text_v1(value) is not null
  ),

  intelligence_time_features as (
    select
      'good_for_time'::text as feature_type,
      'good_for_time:' || public.backyrd_ml_norm_text_v1(value) as feature_key,
      0.46::numeric as feature_strength
    from public.spot_intelligence_v1 si
    cross join lateral unnest(coalesce(si.good_for_time, '{}'::text[])) as value
    where si.spot_id = p_spot_id
      and public.backyrd_ml_norm_text_v1(value) is not null
  ),

  intelligence_noise_features as (
    select
      'noise_level'::text as feature_type,
      'noise_level:' || public.backyrd_ml_norm_text_v1(si.noise_level) as feature_key,
      0.36::numeric as feature_strength
    from public.spot_intelligence_v1 si
    where si.spot_id = p_spot_id
      and public.backyrd_ml_norm_text_v1(si.noise_level) is not null
  )

  select * from city_features
  union all
  select * from category_features
  union all
  select * from price_features
  union all
  select * from mood_features
  union all
  select * from concept_features
  union all
  select * from keyword_features
  union all
  select * from intelligence_best_for_features
  union all
  select * from intelligence_occasion_features
  union all
  select * from intelligence_atmosphere_features
  union all
  select * from intelligence_time_features
  union all
  select * from intelligence_noise_features;
$$;

ALTER FUNCTION "public"."backyrd_ml_extract_spot_features_v1"("p_spot_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_ml_feature_cap_v1"("p_feature_type" "text") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case lower(coalesce(p_feature_type, ''))
    when 'mood' then 2.0
    when 'mood_concept' then 2.0
    when 'category' then 1.6
    when 'keyword' then 1.25
    when 'best_for' then 1.45
    when 'occasion' then 1.35
    when 'atmosphere' then 1.45
    when 'good_for_time' then 1.05
    when 'noise_level' then 0.95
    when 'price' then 0.9
    when 'city' then 0.8
    else 1.0
  end;
$$;

ALTER FUNCTION "public"."backyrd_ml_feature_cap_v1"("p_feature_type" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_ml_get_my_taste_vector_v1"("p_limit" integer DEFAULT 80) RETURNS TABLE("feature_type" "text", "feature_key" "text", "weight" numeric, "confidence" numeric, "positive_count" integer, "negative_count" integer, "last_event_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    w.feature_type,
    w.feature_key,
    w.weight,
    w.confidence,
    w.positive_count,
    w.negative_count,
    w.last_event_at
  from public.backyrd_user_feature_weights_v1 w
  where w.user_id = auth.uid()
  order by abs(w.weight) desc, w.confidence desc, w.updated_at desc
  limit greatest(1, least(coalesce(p_limit, 80), 250));
$$;

ALTER FUNCTION "public"."backyrd_ml_get_my_taste_vector_v1"("p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_ml_log_event_v1"("p_event_type" "text", "p_spot_id" "uuid" DEFAULT NULL::"uuid", "p_decision_id" "uuid" DEFAULT NULL::"uuid", "p_rank" integer DEFAULT NULL::integer, "p_city" "text" DEFAULT NULL::"text", "p_mood_a_text" "text" DEFAULT NULL::"text", "p_mood_b_text" "text" DEFAULT NULL::"text", "p_context" "jsonb" DEFAULT '{}'::"jsonb", "p_signal_strength" numeric DEFAULT NULL::numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_event_id uuid;
  v_event_type text := lower(trim(coalesce(p_event_type, '')));
  v_strength numeric;
  v_delta numeric;
  v_cap numeric;
  v_is_positive boolean;
  v_should_update_taste boolean;

  v_mood_a text := public.backyrd_ml_norm_text_v1(p_mood_a_text);
  v_mood_b text := public.backyrd_ml_norm_text_v1(p_mood_b_text);

  v_feature_multiplier numeric;
  f record;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  v_strength := coalesce(p_signal_strength, public.backyrd_ml_event_strength_v1(v_event_type));

  if v_strength = 0 then
    raise exception 'unsupported_event_type: %', p_event_type using errcode = '22023';
  end if;

  insert into public.backyrd_ml_events_v1 (
    user_id,
    event_type,
    spot_id,
    decision_id,
    rank,
    city,
    mood_a_text,
    mood_b_text,
    signal_strength,
    context,
    created_at
  )
  values (
    v_uid,
    v_event_type,
    p_spot_id,
    p_decision_id,
    p_rank,
    nullif(trim(p_city), ''),
    nullif(trim(p_mood_a_text), ''),
    nullif(trim(p_mood_b_text), ''),
    v_strength,
    coalesce(p_context, '{}'::jsonb),
    now()
  )
  returning id into v_event_id;

  v_should_update_taste :=
    p_spot_id is not null
    and v_event_type in (
      'decision_like',
      'decision_dislike',
      'decision_open',
      'favorite_add',
      'favorite_remove',
      'review_create',
      'review_update',
      'spot_detail_view',
      'search_result_click',
      'map_spot_tap'
    )
    and abs(v_strength) >= 0.05;

  if v_should_update_taste then
    for f in
      select *
      from public.backyrd_ml_extract_spot_features_v1(p_spot_id)
    loop
      v_feature_multiplier := 1.0;

      -- City is context, not taste. Positive city signal is tiny; negative city signal is ignored.
      if f.feature_type = 'city' then
        if v_strength < 0 then
          v_feature_multiplier := 0.0;
        else
          v_feature_multiplier := 0.18;
        end if;
      end if;

      -- Dislike should not over-punish broad mood/category/keyword concepts.
      if v_strength < 0 then
        if f.feature_type in ('mood', 'mood_concept') then
          v_feature_multiplier := v_feature_multiplier * 0.62;
        elsif f.feature_type in ('category', 'keyword') then
          v_feature_multiplier := v_feature_multiplier * 0.78;
        elsif f.feature_type = 'price' then
          v_feature_multiplier := v_feature_multiplier * 0.45;
        end if;
      end if;

      -- If the user explicitly searched this mood, a rejected spot should not mean the mood is bad.
      if v_strength < 0
        and f.feature_type in ('mood', 'mood_concept', 'keyword')
        and (
          (v_mood_a is not null and f.feature_key like '%' || v_mood_a || '%')
          or
          (v_mood_b is not null and f.feature_key like '%' || v_mood_b || '%')
        )
      then
        v_feature_multiplier := v_feature_multiplier * 0.22;
      end if;

      v_delta := v_strength * coalesce(f.feature_strength, 0) * v_feature_multiplier;
      v_cap := public.backyrd_ml_feature_cap_v1(f.feature_type);
      v_is_positive := v_delta > 0;

      if abs(v_delta) > 0.00001 then
        insert into public.backyrd_user_feature_weights_v1 (
          user_id,
          feature_type,
          feature_key,
          weight,
          confidence,
          positive_count,
          negative_count,
          last_event_at,
          updated_at
        )
        values (
          v_uid,
          f.feature_type,
          f.feature_key,
          greatest(-v_cap, least(v_cap, v_delta)),
          greatest(0, least(1, abs(v_delta) * 0.11)),
          case when v_is_positive then 1 else 0 end,
          case when v_is_positive then 0 else 1 end,
          now(),
          now()
        )
        on conflict (user_id, feature_type, feature_key)
        do update set
          weight =
            case
              when excluded.weight >= 0 then
                least(
                  public.backyrd_ml_feature_cap_v1(public.backyrd_user_feature_weights_v1.feature_type),
                  public.backyrd_user_feature_weights_v1.weight
                    + excluded.weight
                    * (
                      1 - least(
                        0.92,
                        greatest(0, public.backyrd_user_feature_weights_v1.weight)
                        / public.backyrd_ml_feature_cap_v1(public.backyrd_user_feature_weights_v1.feature_type)
                      )
                    )
                )
              else
                greatest(
                  -public.backyrd_ml_feature_cap_v1(public.backyrd_user_feature_weights_v1.feature_type),
                  public.backyrd_user_feature_weights_v1.weight
                    + excluded.weight
                    * (
                      1 - least(
                        0.92,
                        greatest(0, -public.backyrd_user_feature_weights_v1.weight)
                        / public.backyrd_ml_feature_cap_v1(public.backyrd_user_feature_weights_v1.feature_type)
                      )
                    )
                )
            end,
          confidence = greatest(
            0,
            least(
              1,
              public.backyrd_user_feature_weights_v1.confidence + abs(excluded.weight) * 0.045
            )
          ),
          positive_count = public.backyrd_user_feature_weights_v1.positive_count + excluded.positive_count,
          negative_count = public.backyrd_user_feature_weights_v1.negative_count + excluded.negative_count,
          last_event_at = now(),
          updated_at = now();
      end if;
    end loop;

    begin
      insert into public.user_taste_profile_v1 (
        user_id,
        qualified_actions,
        last_rebuild_at,
        confidence,
        notes
      )
      values (
        v_uid,
        1,
        now(),
        least(1, abs(v_strength) * 0.12),
        'ml_core_v1_2'
      )
      on conflict (user_id)
      do update set
        qualified_actions = public.user_taste_profile_v1.qualified_actions + 1,
        confidence = least(
          1,
          public.user_taste_profile_v1.confidence + abs(v_strength) * 0.025
        ),
        last_rebuild_at = now(),
        notes = 'ml_core_v1_2';
    exception when others then
      null;
    end;
  end if;

  return v_event_id;
end;
$$;

ALTER FUNCTION "public"."backyrd_ml_log_event_v1"("p_event_type" "text", "p_spot_id" "uuid", "p_decision_id" "uuid", "p_rank" integer, "p_city" "text", "p_mood_a_text" "text", "p_mood_b_text" "text", "p_context" "jsonb", "p_signal_strength" numeric) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_ml_norm_text_v1"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select nullif(
    trim(
      regexp_replace(
        lower(coalesce(p_text, '')),
        '\s+',
        ' ',
        'g'
      )
    ),
    ''
  );
$$;

ALTER FUNCTION "public"."backyrd_ml_norm_text_v1"("p_text" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_ml_rank_decision_spots_v1"("p_city" "text" DEFAULT NULL::"text", "p_mood_a_text" "text" DEFAULT NULL::"text", "p_mood_b_text" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20, "p_explore_weight" numeric DEFAULT 0.08) RETURNS TABLE("spot_id" "uuid", "name" "text", "city" "text", "category_name" "text", "price_level" integer, "score" numeric, "taste_score" numeric, "mood_score" numeric, "explore_score" numeric, "penalty_score" numeric, "reasons" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_city text := public.backyrd_ml_norm_text_v1(p_city);
  v_mood_a text := public.backyrd_ml_norm_text_v1(p_mood_a_text);
  v_mood_b text := public.backyrd_ml_norm_text_v1(p_mood_b_text);
  v_limit integer := greatest(1, least(coalesce(p_limit, 20), 100));
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  return query
  with candidate_spots as (
    select
      s.id,
      s.name,
      s.city,
      s.price_level,
      c.name as category_name
    from public.spots s
    left join public.categories c on c.id = s.category_id
    where (s.status::text = 'approved' or s.status is not null)
      and (
        v_city is null
        or public.backyrd_ml_norm_text_v1(s.city) = v_city
      )
  ),

  scored as (
    select
      s.id as spot_id,
      s.name,
      s.city,
      s.category_name,
      s.price_level,

      coalesce(t.taste_score, 0)::numeric as taste_score,
      coalesce(m.mood_score, 0)::numeric as mood_score,
      coalesce(e.explore_score, 0)::numeric as explore_score,
      coalesce(p.penalty_score, 0)::numeric as penalty_score,

      (
        coalesce(t.taste_score, 0) * 0.42
        + coalesce(m.mood_score, 0) * 0.34
        + coalesce(e.explore_score, 0) * coalesce(p_explore_weight, 0.08)
        + coalesce(p.penalty_score, 0)
      )::numeric as final_score,

      jsonb_build_object(
        'taste_score', coalesce(t.taste_score, 0),
        'mood_score', coalesce(m.mood_score, 0),
        'explore_score', coalesce(e.explore_score, 0),
        'penalty_score', coalesce(p.penalty_score, 0),
        'top_taste_features', coalesce(t.top_features, '[]'::jsonb),
        'mood_matches', coalesce(m.mood_matches, '[]'::jsonb)
      ) as reasons

    from candidate_spots s

    left join lateral (
      select
        coalesce(
          sum(
            f.feature_strength
            * w.weight
            * greatest(0.18, w.confidence)
          ),
          0
        )::numeric as taste_score,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'feature_type', f.feature_type,
              'feature_key', f.feature_key,
              'spot_strength', f.feature_strength,
              'user_weight', w.weight,
              'confidence', w.confidence
            )
            order by abs(f.feature_strength * w.weight * greatest(0.18, w.confidence)) desc
          ) filter (where w.feature_key is not null),
          '[]'::jsonb
        ) as top_features
      from public.backyrd_ml_extract_spot_features_v1(s.id) f
      join public.backyrd_user_feature_weights_v1 w
        on w.user_id = v_uid
       and w.feature_type = f.feature_type
       and w.feature_key = f.feature_key
    ) t on true

    left join lateral (
      select
        coalesce(
          sum(
            case
              when v_mood_a is not null and f.feature_key like '%' || v_mood_a || '%' then f.feature_strength
              when v_mood_b is not null and f.feature_key like '%' || v_mood_b || '%' then f.feature_strength
              else 0
            end
          ),
          0
        )::numeric as mood_score,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'feature_type', f.feature_type,
              'feature_key', f.feature_key,
              'strength', f.feature_strength
            )
          ) filter (
            where
              (v_mood_a is not null and f.feature_key like '%' || v_mood_a || '%')
              or
              (v_mood_b is not null and f.feature_key like '%' || v_mood_b || '%')
          ),
          '[]'::jsonb
        ) as mood_matches
      from public.backyrd_ml_extract_spot_features_v1(s.id) f
      where f.feature_type in ('mood', 'mood_concept', 'keyword', 'category')
    ) m on true

    left join lateral (
      select random()::numeric as explore_score
    ) e on true

    left join lateral (
      select
        (
          case
            when exists (
              select 1
              from public.backyrd_ml_events_v1 ev
              where ev.user_id = v_uid
                and ev.spot_id = s.id
                and ev.event_type = 'decision_impression'
                and ev.created_at > now() - interval '7 days'
            )
            then -0.20
            else 0
          end
          +
          case
            when exists (
              select 1
              from public.backyrd_ml_events_v1 ev
              where ev.user_id = v_uid
                and ev.spot_id = s.id
                and ev.event_type = 'decision_dislike'
                and ev.created_at > now() - interval '30 days'
            )
            then -0.55
            else 0
          end
          +
          case
            when exists (
              select 1
              from public.backyrd_ml_events_v1 ev
              where ev.user_id = v_uid
                and ev.spot_id = s.id
                and ev.event_type in ('decision_like', 'decision_open', 'favorite_add')
                and ev.created_at > now() - interval '45 days'
            )
            then 0.12
            else 0
          end
        )::numeric as penalty_score
    ) p on true
  )

  select
    scored.spot_id,
    scored.name,
    scored.city,
    scored.category_name,
    scored.price_level,
    scored.final_score as score,
    scored.taste_score,
    scored.mood_score,
    scored.explore_score,
    scored.penalty_score,
    scored.reasons
  from scored
  order by scored.final_score desc, scored.name asc
  limit v_limit;
end;
$$;

ALTER FUNCTION "public"."backyrd_ml_rank_decision_spots_v1"("p_city" "text", "p_mood_a_text" "text", "p_mood_b_text" "text", "p_limit" integer, "p_explore_weight" numeric) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_normalize_owner_email_v1"("p_value" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select nullif(lower(trim(coalesce(p_value, ''))), '');
$$;

ALTER FUNCTION "public"."backyrd_normalize_owner_email_v1"("p_value" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_normalize_owner_phone_v1"("p_value" "text", "p_country" "text" DEFAULT 'Schweiz'::"text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare
  v text := nullif(trim(coalesce(p_value, '')), '');
  digits text;
begin
  if v is null then return null; end if;

  v := regexp_replace(v, '[^0-9+]', '', 'g');
  if left(v, 2) = '00' then v := '+' || substr(v, 3); end if;

  if lower(coalesce(p_country, '')) in ('schweiz','switzerland','ch','suisse','svizzera') then
    if left(v, 1) = '0' and left(v, 2) <> '00' then
      v := '+41' || substr(v, 2);
    end if;
  end if;

  return v;
end;
$$;

ALTER FUNCTION "public"."backyrd_normalize_owner_phone_v1"("p_value" "text", "p_country" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_normalize_owner_website_v1"("p_value" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare
  v text := nullif(trim(coalesce(p_value, '')), '');
begin
  if v is null then return null; end if;
  if v !~* '^https?://' then v := 'https://' || v; end if;
  return v;
end;
$$;

ALTER FUNCTION "public"."backyrd_normalize_owner_website_v1"("p_value" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_owner_assert_spot_v1"("p_spot_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_owner_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select s.owner_id
  into v_owner_id
  from public.spots s
  where s.id = p_spot_id
  limit 1;

  if v_owner_id is null or v_owner_id <> auth.uid() then
    raise exception 'You are not allowed to manage this spot';
  end if;

  return v_owner_id;
end;
$$;

ALTER FUNCTION "public"."backyrd_owner_assert_spot_v1"("p_spot_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_owner_text_risk_flags_v1"("p_values" "text"[]) RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare
  v_text text := lower(array_to_string(coalesce(p_values, '{}'::text[]), ' '));
  v_flags text[] := '{}'::text[];
begin
  if length(v_text) > 6000 then
    v_flags := array_append(v_flags, 'very_long_content');
  end if;

  if v_text ~ '(https?://|www\.)' then
    v_flags := array_append(v_flags, 'external_link_in_content');
  end if;

  if v_text ~ (
    '(^|[^[:alnum:]_])(' ||
    'fuck|' ||
    'fucking|' ||
    'arschloch|' ||
    'hurensohn|' ||
    'verpiss|' ||
    'scheiss|' ||
    'scheiß|' ||
    'bastard' ||
    ')'
  ) then
    v_flags := array_append(v_flags, 'possible_abusive_language');
  end if;

  return v_flags;
end;
$$;

ALTER FUNCTION "public"."backyrd_owner_text_risk_flags_v1"("p_values" "text"[]) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_place_type_event_strength_v1"("p_event_type" "text", "p_signal_strength" numeric DEFAULT NULL::numeric) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare
  v_event text := lower(coalesce(p_event_type, ''));
  v_strength numeric := coalesce(p_signal_strength, 0);
begin
  -- Prefer explicit signal_strength if it exists and is meaningful.
  if abs(v_strength) > 0 then
    return greatest(-0.5, least(0.5, v_strength));
  end if;

  return case v_event
    when 'onboarding_favorite' then 0.35
    when 'decision_like' then 0.22
    when 'decision_open' then 0.12
    when 'decision_save' then 0.28
    when 'decision_dislike' then -0.12
    when 'decision_skip' then -0.04
    when 'decision_remix' then -0.025
    when 'decision_impression' then 0.008
    when 'tapped' then 0.08
    when 'exact_mood' then 0.18
    when 'was_here' then 0.16
    when 'not_there' then -0.12
    else 0
  end;
end;
$$;

ALTER FUNCTION "public"."backyrd_place_type_event_strength_v1"("p_event_type" "text", "p_signal_strength" numeric) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_place_type_from_category_v1"("p_category_name" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when lower(coalesce(p_category_name, '')) in ('café', 'cafe', 'coffee', 'kaffee') then 'cafe'
    when lower(coalesce(p_category_name, '')) in ('bar') then 'bar'
    when lower(coalesce(p_category_name, '')) in ('restaurant', 'essen', 'food') then 'restaurant'
    when lower(coalesce(p_category_name, '')) in ('nachtleben', 'club', 'nightlife') then 'nightlife'
    when lower(coalesce(p_category_name, '')) in ('museum', 'kultur', 'galerie', 'gallery') then 'culture'
    when lower(coalesce(p_category_name, '')) in ('aussichtspunkt', 'viewpoint', 'ausflug') then 'outing'
    when lower(coalesce(p_category_name, '')) in ('aktivität', 'aktivitat', 'activity') then 'activity'
    when lower(coalesce(p_category_name, '')) in ('besonderes erlebnis', 'erlebnis', 'experience') then 'experience'
    when lower(coalesce(p_category_name, '')) in ('unterkunft / hotel', 'hotel', 'unterkunft') then 'hotel'
    else 'other'
  end;
$$;

ALTER FUNCTION "public"."backyrd_place_type_from_category_v1"("p_category_name" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_place_type_from_ml_event_trigger_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid;
  v_spot_id uuid;
  v_event_type text;
  v_signal_strength numeric;
  v_city text;
  v_mood_a text;
  v_mood_b text;
  v_context jsonb;
begin
  -- This trigger expects columns that exist in backyrd_ml_events_v1.
  -- If a column is absent in your exact schema, the trigger creation will fail,
  -- which is why we create it only after checking the table exists.
  v_user_id := new.user_id;
  v_spot_id := new.spot_id;
  v_event_type := new.event_type;
  v_signal_strength := new.signal_strength;
  v_city := new.city;
  v_mood_a := new.mood_a_text;
  v_mood_b := new.mood_b_text;
  v_context := coalesce(new.context, '{}'::jsonb);

  perform public.backyrd_update_place_type_preference_v1(
    p_user_id := v_user_id,
    p_spot_id := v_spot_id,
    p_event_type := v_event_type,
    p_signal_strength := v_signal_strength,
    p_city := v_city,
    p_mood_a_text := v_mood_a,
    p_mood_b_text := v_mood_b,
    p_context := v_context
  );

  return new;
exception
  when others then
    raise log 'backyrd_place_type_from_ml_event_trigger_v1 failed: %', sqlerrm;
    return new;
end;
$$;

ALTER FUNCTION "public"."backyrd_place_type_from_ml_event_trigger_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_place_type_label_v1"("p_place_type" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case lower(coalesce(p_place_type, ''))
    when 'cafe' then 'Café'
    when 'bar' then 'Bar'
    when 'restaurant' then 'Restaurant'
    when 'nightlife' then 'Nachtleben'
    when 'culture' then 'Kultur'
    when 'outing' then 'Ausflug'
    when 'activity' then 'Aktivität'
    when 'experience' then 'Erlebnis'
    when 'hotel' then 'Hotel'
    else 'Anderes'
  end;
$$;

ALTER FUNCTION "public"."backyrd_place_type_label_v1"("p_place_type" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_refresh_all_spot_ml_documents_v13"("p_limit" integer DEFAULT 500) RETURNS TABLE("refreshed_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  s record;
  v_count integer := 0;
begin
  for s in
    select id
    from public.spots
    where status::text = 'approved'
    order by created_at desc nulls last, name asc
    limit greatest(1, least(coalesce(p_limit, 500), 5000))
  loop
    perform public.backyrd_refresh_spot_ml_document_v13(s.id);
    v_count := v_count + 1;
  end loop;

  refreshed_count := v_count;
  return next;
end;
$$;

ALTER FUNCTION "public"."backyrd_refresh_all_spot_ml_documents_v13"("p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_refresh_and_enqueue_spot_embedding_v13_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_spot_id uuid;
  v_reason text;
begin
  v_spot_id := coalesce(new.spot_id, old.spot_id);

  if v_spot_id is null then
    v_spot_id := coalesce(new.id, old.id);
  end if;

  if v_spot_id is null then
    return coalesce(new, old);
  end if;

  v_reason := tg_table_name || '_' || lower(tg_op);

  perform public.backyrd_enqueue_spot_embedding_v13(v_spot_id, v_reason);

  return coalesce(new, old);
end;
$$;

ALTER FUNCTION "public"."backyrd_refresh_and_enqueue_spot_embedding_v13_trigger"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_refresh_spot_ml_document_v13"("p_spot_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_doc record;
begin
  if p_spot_id is null then
    raise exception 'spot_id_required';
  end if;

  select b.spot_id, b.document_text, b.document_json, b.source_hash
  into v_doc
  from public.backyrd_build_spot_ml_document_v13(p_spot_id) b
  limit 1;

  if v_doc.spot_id is null then
    raise exception 'spot_ml_document_build_failed';
  end if;

  insert into public.backyrd_spot_ml_documents_v1 (
    spot_id, document_text, document_json, document_version, source_hash, updated_at
  )
  values (
    v_doc.spot_id,
    v_doc.document_text,
    v_doc.document_json,
    'v13.2-taxonomy',
    v_doc.source_hash,
    now()
  )
  on conflict on constraint backyrd_spot_ml_documents_v1_pkey
  do update set
    document_text = excluded.document_text,
    document_json = excluded.document_json,
    document_version = excluded.document_version,
    source_hash = excluded.source_hash,
    updated_at = now();

  return v_doc.spot_id;
end;
$$;

ALTER FUNCTION "public"."backyrd_refresh_spot_ml_document_v13"("p_spot_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_review_auto_decision_link_trigger_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_review_id uuid;
begin
  v_review_id := nullif(to_jsonb(new) ->> 'id', '')::uuid;

  if v_review_id is null then
    return new;
  end if;

  perform public.backyrd_try_auto_link_decision_review_v1(v_review_id, 12);

  return new;
exception
  when others then
    raise warning 'backyrd_review_auto_decision_link_trigger_v1 failed: %', sqlerrm;
    return new;
end;
$$;

ALTER FUNCTION "public"."backyrd_review_auto_decision_link_trigger_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_review_photo_to_social_moment_trigger_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_photo_json jsonb := to_jsonb(new);
  v_review_id uuid;
begin
  -- If a photo is added after the review row, refresh the social moment media.
  v_review_id := nullif(v_photo_json ->> 'review_id', '')::uuid;

  if v_review_id is null then
    return new;
  end if;

  perform public.create_social_moment_from_review_v1(
    p_review_id := v_review_id,
    p_visibility := 'public'
  );

  return new;
exception
  when others then
    -- Photo->social refresh must never break photo uploads.
    raise warning 'review_photo_to_social_moment failed: %', sqlerrm;
    return new;
end;
$$;

ALTER FUNCTION "public"."backyrd_review_photo_to_social_moment_trigger_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_review_to_social_moment_trigger_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_review_json jsonb := to_jsonb(new);
  v_review_id uuid;
  v_visibility text;
  v_share_to_social boolean;
begin
  v_review_id := nullif(v_review_json ->> 'id', '')::uuid;

  if v_review_id is null then
    return new;
  end if;

  v_visibility := lower(trim(coalesce(v_review_json ->> 'visibility', 'public')));
  v_share_to_social := coalesce((v_review_json ->> 'share_to_social')::boolean, true);

  if v_share_to_social is false or v_visibility = 'private' then
    return new;
  end if;

  perform public.create_social_moment_from_review_v1(
    p_review_id := v_review_id,
    p_visibility := coalesce(nullif(v_visibility, ''), 'public')
  );

  return new;
exception
  when others then
    raise warning 'review_to_social_moment failed: %', sqlerrm;
    return new;
end;
$$;

ALTER FUNCTION "public"."backyrd_review_to_social_moment_trigger_v1"() OWNER TO "postgres";

