CREATE OR REPLACE FUNCTION "public"."backyrd_social_post_auto_decision_link_trigger_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_review_id uuid;
begin
  v_review_id := nullif(to_jsonb(new) ->> 'review_id', '')::uuid;

  if v_review_id is null then
    return new;
