  if coalesce(new.source_type, 'manual') in ('review', 'decision_review') then
    perform public.backyrd_try_auto_link_decision_review_v1(v_review_id, 12);
  end if;

  return new;
exception
  when others then
    raise warning 'backyrd_social_post_auto_decision_link_trigger_v1 failed: %', sqlerrm;
    return new;
end;
$$;

