CREATE OR REPLACE FUNCTION "public"."backyrd_touch_category_spots_embedding_v13"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_category_id uuid;
  r record;
begin
  if tg_op = 'DELETE' then
    v_category_id := old.id;
  else
    v_category_id := new.id;
  end if;

  for r in
    select s.id as spot_id
    from public.spots s
    where s.category_id = v_category_id
  loop
    perform public.backyrd_refresh_spot_ml_document_v13(r.spot_id);
    perform public.backyrd_enqueue_spot_embedding_v13(
      r.spot_id,
      'auto_categories_' || lower(tg_op)
    );
  end loop;

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$$;

ALTER FUNCTION "public"."backyrd_touch_category_spots_embedding_v13"() OWNER TO "postgres";

