CREATE OR REPLACE FUNCTION "public"."backyrd_touch_spot_embedding_v13"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_spot_id uuid;
  v_reason text;
begin
  -- Detect affected spot_id depending on table/operation
  if tg_table_name = 'spots' then
    if tg_op = 'DELETE' then
      v_spot_id := old.id;
    else
      v_spot_id := new.id;
    end if;
  else
    if tg_op = 'DELETE' then
      v_spot_id := old.spot_id;
    else
      v_spot_id := new.spot_id;
    end if;
  end if;

  if v_spot_id is null then
    if tg_op = 'DELETE' then
      return old;
    end if;

    return new;
  end if;

  v_reason := 'auto_' || lower(tg_table_name) || '_' || lower(tg_op);

  -- Do not try to refresh deleted spots.
  if exists (
    select 1
    from public.spots s
    where s.id = v_spot_id
  ) then
    perform public.backyrd_refresh_spot_ml_document_v13(v_spot_id);
    perform public.backyrd_enqueue_spot_embedding_v13(v_spot_id, v_reason);
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$$;

ALTER FUNCTION "public"."backyrd_touch_spot_embedding_v13"() OWNER TO "postgres";

