CREATE OR REPLACE FUNCTION "public"."backyrd_trigger_enqueue_embedding_from_spot_descriptions_v13"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_spot_id uuid;
begin
  if tg_op = 'DELETE' then
    v_spot_id := old.spot_id;
  else
    v_spot_id := new.spot_id;
  end if;

  if v_spot_id is null then
    if tg_op = 'DELETE' then
      return old;
    end if;

    return new;
  end if;

  perform public.backyrd_refresh_spot_ml_document_v13(v_spot_id);

  perform public.backyrd_enqueue_spot_embedding_v13(
    v_spot_id,
    'spot_descriptions_' || lower(tg_op)
  );

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;

exception when others then
  raise warning 'backyrd spot_descriptions embedding enqueue failed for spot %: %', v_spot_id, sqlerrm;

  if tg_op = 'DELETE' then
    return old;
  end if;

  return new;
end;
$$;

