CREATE OR REPLACE FUNCTION "public"."backyrd_trigger_enqueue_embedding_from_spots_v13"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_spot_id uuid;
begin
  if tg_op = 'DELETE' then
    return old;
  end if;

  v_spot_id := new.id;

  if v_spot_id is null then
    return new;
  end if;

  -- Dokument sofort neu bauen
  perform public.backyrd_refresh_spot_ml_document_v13(v_spot_id);

  -- Embedding Job queue'n
  perform public.backyrd_enqueue_spot_embedding_v13(
    v_spot_id,
    'spots_' || lower(tg_op)
  );

  return new;

exception when others then
  -- Wichtig: App-Insert darf nie abbrechen, nur weil Queue/Embedding hängt.
  raise warning 'backyrd spots embedding enqueue failed for spot %: %', v_spot_id, sqlerrm;
  return new;
end;
$$;

