CREATE OR REPLACE FUNCTION "public"."backyrd_trigger_taxonomy_catalog_embedding_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_node_id uuid;
  v_spot_id uuid;
begin
  if tg_table_name = 'taxonomy_nodes' then
    v_node_id := case when tg_op = 'DELETE' then old.id else new.id end;
  else
    v_node_id := case when tg_op = 'DELETE'
      then old.taxonomy_node_id else new.taxonomy_node_id end;
  end if;

  for v_spot_id in
    select distinct st.spot_id
    from public.spot_taxonomies st
    where st.taxonomy_node_id = v_node_id
  loop
    begin
      perform public.backyrd_enqueue_spot_embedding_v13(
        v_spot_id,
        lower(tg_table_name) || '_' || lower(tg_op)
      );
    exception when others then
      raise warning 'taxonomy catalog refresh failed for spot %, node %: %',
        v_spot_id, v_node_id, sqlerrm;
    end;
  end loop;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;

ALTER FUNCTION "public"."backyrd_trigger_taxonomy_catalog_embedding_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_trigger_taxonomy_embedding_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_spot_id uuid;
begin
  v_spot_id := case when tg_op = 'DELETE' then old.spot_id else new.spot_id end;

  if v_spot_id is not null
     and exists (select 1 from public.spots s where s.id = v_spot_id) then
    perform public.backyrd_enqueue_spot_embedding_v13(
      v_spot_id,
      'spot_taxonomies_' || lower(tg_op)
    );
  end if;

  return case when tg_op = 'DELETE' then old else new end;

exception when others then
  raise warning 'taxonomy embedding enqueue failed for spot %: %', v_spot_id, sqlerrm;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;

