CREATE OR REPLACE FUNCTION "public"."backyrd_try_auto_link_decision_review_v1"("p_review_id" "uuid", "p_window_hours" integer DEFAULT 12) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_review jsonb;
  v_user_id uuid;
  v_spot_id uuid;
  v_review_created_at timestamptz;
  v_event record;
  v_existing_link_id uuid;
  v_link_id uuid;
  v_hours_between numeric;
  v_match_type text;
  v_signal_strength numeric;
begin
  if p_review_id is null then
    return null;
  end if;

  select to_jsonb(r)
  into v_review
  from public.reviews r
  where r.id = p_review_id
  limit 1;

  if v_review is null then
    return null;
  end if;

  v_user_id := coalesce(
    nullif(v_review ->> 'user_id', '')::uuid,
    nullif(v_review ->> 'profile_id', '')::uuid,
    nullif(v_review ->> 'created_by', '')::uuid
  );

  v_spot_id := coalesce(
    nullif(v_review ->> 'spot_id', '')::uuid,
    nullif(v_review ->> 'place_id', '')::uuid
  );

  v_review_created_at := coalesce(
    nullif(v_review ->> 'created_at', '')::timestamptz,
    now()
  );

  if v_user_id is null or v_spot_id is null then
    return null;
  end if;

  -- Find strongest recent Decision signal for same user + same spot before the review.
  -- Priority:
  -- 1) decision_like
  -- 2) decision_open
  -- 3) decision_impression
  select
    e.id as event_id,
    e.user_id,
    e.spot_id,
    e.decision_id,
    e.event_type,
    e.rank,
    e.signal_strength,
    e.context,
    e.created_at,
    case e.event_type
      when 'decision_like' then 100
      when 'decision_open' then 80
      when 'decision_impression' then 30
      else 0
    end as event_priority
  into v_event
  from public.backyrd_ml_events_v1 e
  where e.user_id = v_user_id
    and e.spot_id = v_spot_id
    and e.created_at <= v_review_created_at
    and e.created_at >= v_review_created_at - (greatest(1, coalesce(p_window_hours, 12))::text || ' hours')::interval
    and e.event_type in ('decision_like', 'decision_open', 'decision_impression')
  order by
    case e.event_type
      when 'decision_like' then 100
      when 'decision_open' then 80
      when 'decision_impression' then 30
      else 0
    end desc,
    abs(coalesce(e.signal_strength, 0)) desc,
    e.created_at desc
  limit 1;

  if v_event.event_id is null then
    return null;
  end if;

  v_hours_between :=
    extract(epoch from (v_review_created_at - v_event.created_at)) / 3600.0;

  v_match_type :=
    case v_event.event_type
      when 'decision_like' then 'auto_recent_same_spot_after_like'
      when 'decision_open' then 'auto_recent_same_spot_after_open'
      when 'decision_impression' then 'auto_recent_same_spot_after_impression'
      else 'auto_recent_same_spot'
    end;

  v_signal_strength :=
    case v_event.event_type
      when 'decision_like' then 1.00
      when 'decision_open' then 0.82
      when 'decision_impression' then 0.42
      else 0.50
    end;

  select id
  into v_existing_link_id
  from public.backyrd_decision_review_links_v1
  where review_id = p_review_id
  limit 1;

  if v_existing_link_id is not null then
    update public.backyrd_decision_review_links_v1
    set
      user_id = v_user_id,
      decision_id = v_event.decision_id,
      spot_id = v_spot_id,
      match_type = v_match_type,
      signal_strength = v_signal_strength,
      decision_created_at = v_event.created_at,
      review_created_at = v_review_created_at,
      hours_between = v_hours_between,
      context = jsonb_build_object(
        'source', 'backyrd_try_auto_link_decision_review_v1',
        'match_source', 'backyrd_ml_events_v1',
        'event_id', v_event.event_id,
        'event_type', v_event.event_type,
        'event_rank', v_event.rank,
        'event_signal_strength', v_event.signal_strength,
        'decision_id', v_event.decision_id,
        'model_version', v_event.context ->> 'model_version',
        'input_mode', coalesce(v_event.context ->> 'inputMode', v_event.context ->> 'input_mode'),
        'raw_free_text', coalesce(v_event.context ->> 'rawFreeText', v_event.context ->> 'raw_free_text'),
        'query', v_event.context ->> 'query',
        'query_text', v_event.context ->> 'query_text',
        'spot_name', v_event.context ->> 'spot_name',
        'category_name', v_event.context ->> 'category_name'
      )
    where id = v_existing_link_id
    returning id into v_link_id;
  else
    insert into public.backyrd_decision_review_links_v1 (
      user_id,
      decision_id,
      review_id,
      spot_id,
      match_type,
      signal_strength,
      decision_created_at,
      review_created_at,
      hours_between,
      context
    )
    values (
      v_user_id,
      v_event.decision_id,
      p_review_id,
      v_spot_id,
      v_match_type,
      v_signal_strength,
      v_event.created_at,
      v_review_created_at,
      v_hours_between,
      jsonb_build_object(
        'source', 'backyrd_try_auto_link_decision_review_v1',
        'match_source', 'backyrd_ml_events_v1',
        'event_id', v_event.event_id,
        'event_type', v_event.event_type,
        'event_rank', v_event.rank,
        'event_signal_strength', v_event.signal_strength,
        'decision_id', v_event.decision_id,
        'model_version', v_event.context ->> 'model_version',
        'input_mode', coalesce(v_event.context ->> 'inputMode', v_event.context ->> 'input_mode'),
        'raw_free_text', coalesce(v_event.context ->> 'rawFreeText', v_event.context ->> 'raw_free_text'),
        'query', v_event.context ->> 'query',
        'query_text', v_event.context ->> 'query_text',
        'spot_name', v_event.context ->> 'spot_name',
        'category_name', v_event.context ->> 'category_name'
      )
    )
    returning id into v_link_id;
  end if;

  -- Upgrade the already-created social post from review -> decision_review.
  update public.social_posts sp
  set
    source_type = 'decision_review',
    source_context =
      coalesce(sp.source_context, '{}'::jsonb)
      || jsonb_build_object(
        'source', 'decision_review',
        'review_id', p_review_id,
        'decision_id', v_event.decision_id,
        'decision_review_link_id', v_link_id,
        'linked_from_decision', true,
        'match_type', v_match_type,
        'match_source', 'backyrd_ml_events_v1',
        'hours_between', v_hours_between,
        'signal_strength', v_signal_strength,
        'event_id', v_event.event_id,
        'event_type', v_event.event_type,
        'model_version', v_event.context ->> 'model_version',
        'input_mode', coalesce(v_event.context ->> 'inputMode', v_event.context ->> 'input_mode'),
        'raw_free_text', coalesce(v_event.context ->> 'rawFreeText', v_event.context ->> 'raw_free_text'),
        'query', v_event.context ->> 'query',
        'query_text', v_event.context ->> 'query_text'
      )
  where sp.review_id = p_review_id;

  return v_link_id;
end;
$$;

ALTER FUNCTION "public"."backyrd_try_auto_link_decision_review_v1"("p_review_id" "uuid", "p_window_hours" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_update_place_type_preference_v1"("p_user_id" "uuid", "p_spot_id" "uuid", "p_event_type" "text", "p_signal_strength" numeric DEFAULT NULL::numeric, "p_city" "text" DEFAULT NULL::"text", "p_mood_a_text" "text" DEFAULT NULL::"text", "p_mood_b_text" "text" DEFAULT NULL::"text", "p_context" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_category_name text;
  v_place_type text;
  v_context_key text;
  v_delta numeric;
  v_global_delta numeric;
  v_context_delta numeric;
  v_cap numeric := 1.25;
  v_conf_inc numeric;
  v_now timestamptz := now();
begin
  if p_user_id is null then
    return;
  end if;

  if p_spot_id is null then
    return;
  end if;

  select c.name
    into v_category_name
  from public.spots s
  left join public.categories c on c.id = s.category_id
  where s.id = p_spot_id
  limit 1;

  v_place_type := public.backyrd_place_type_from_category_v1(v_category_name);

  if v_place_type is null then
    v_place_type := 'other';
  end if;

  v_context_key := public.backyrd_decision_context_key_v1(p_mood_a_text, p_mood_b_text);

  v_delta := public.backyrd_place_type_event_strength_v1(p_event_type, p_signal_strength);

  -- Ignore pure impressions as strong learning source, but keep tiny positive exposure.
  if abs(v_delta) < 0.001 then
    return;
  end if;

  -- Global profile should learn, but contextual should learn stronger.
  v_global_delta := v_delta * 0.55;
  v_context_delta := v_delta * 1.00;

  v_conf_inc := case
    when abs(v_delta) >= 0.20 then 0.035
    when abs(v_delta) >= 0.10 then 0.025
    when abs(v_delta) >= 0.03 then 0.012
    else 0.004
  end;

  -- Global update
  insert into public.user_place_type_preferences_v1 (
    user_id,
    context_key,
    place_type,
    weight,
    confidence,
    positive_count,
    negative_count,
    last_event_at,
    updated_at
  )
  values (
    p_user_id,
    'global',
    v_place_type,
    greatest(-v_cap, least(v_cap, v_global_delta)),
    greatest(0, least(1, v_conf_inc)),
    case when v_delta > 0 then 1 else 0 end,
    case when v_delta < 0 then 1 else 0 end,
    v_now,
    v_now
  )
  on conflict (user_id, context_key, place_type)
  do update set
    weight = greatest(
      -v_cap,
      least(
        v_cap,
        public.user_place_type_preferences_v1.weight
        + (
          v_global_delta
          * (
            1 - (
              abs(public.user_place_type_preferences_v1.weight)
              / v_cap
            )
          )
        )
      )
    ),
    confidence = greatest(
      0,
      least(
        1,
        public.user_place_type_preferences_v1.confidence + v_conf_inc
      )
    ),
    positive_count = public.user_place_type_preferences_v1.positive_count
      + case when v_delta > 0 then 1 else 0 end,
    negative_count = public.user_place_type_preferences_v1.negative_count
      + case when v_delta < 0 then 1 else 0 end,
    last_event_at = v_now,
    updated_at = v_now;

  -- Contextual update
  if v_context_key <> 'global' then
    insert into public.user_place_type_preferences_v1 (
      user_id,
      context_key,
      place_type,
      weight,
      confidence,
      positive_count,
      negative_count,
      last_event_at,
      updated_at
    )
    values (
      p_user_id,
      v_context_key,
      v_place_type,
      greatest(-v_cap, least(v_cap, v_context_delta)),
      greatest(0, least(1, v_conf_inc)),
      case when v_delta > 0 then 1 else 0 end,
      case when v_delta < 0 then 1 else 0 end,
      v_now,
      v_now
    )
    on conflict (user_id, context_key, place_type)
    do update set
      weight = greatest(
        -v_cap,
        least(
          v_cap,
          public.user_place_type_preferences_v1.weight
          + (
            v_context_delta
            * (
              1 - (
                abs(public.user_place_type_preferences_v1.weight)
                / v_cap
              )
            )
          )
        )
      ),
      confidence = greatest(
        0,
        least(
          1,
          public.user_place_type_preferences_v1.confidence + v_conf_inc
        )
      ),
      positive_count = public.user_place_type_preferences_v1.positive_count
        + case when v_delta > 0 then 1 else 0 end,
      negative_count = public.user_place_type_preferences_v1.negative_count
        + case when v_delta < 0 then 1 else 0 end,
      last_event_at = v_now,
      updated_at = v_now;
  end if;
end;
$$;

ALTER FUNCTION "public"."backyrd_update_place_type_preference_v1"("p_user_id" "uuid", "p_spot_id" "uuid", "p_event_type" "text", "p_signal_strength" numeric, "p_city" "text", "p_mood_a_text" "text", "p_mood_b_text" "text", "p_context" "jsonb") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_validate_spot_taxonomy_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_spot_category_id uuid;
  v_has_category_restrictions boolean;
begin
  select s.category_id
    into v_spot_category_id
  from public.spots s
  where s.id = new.spot_id;

  if not found then
    raise exception 'Spot % does not exist.', new.spot_id;
  end if;

  select exists (
    select 1
    from public.taxonomy_node_categories tnc
    where tnc.taxonomy_node_id = new.taxonomy_node_id
  )
  into v_has_category_restrictions;

  if v_has_category_restrictions and not exists (
    select 1
    from public.taxonomy_node_categories tnc
    where tnc.taxonomy_node_id = new.taxonomy_node_id
      and tnc.category_id = v_spot_category_id
  ) then
    raise exception
      'Taxonomy node % is not valid for the spot primary category %.',
      new.taxonomy_node_id,
      v_spot_category_id;
  end if;

  return new;
end;
$$;

ALTER FUNCTION "public"."backyrd_validate_spot_taxonomy_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_web_city_spots_v1"("p_city" "text", "p_limit" integer DEFAULT 12) RETURNS TABLE("spot_id" "uuid", "name" "text", "city" "text", "category_name" "text", "photo_url" "text", "top_moods" "text"[], "review_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with review_stats as (
    select
      r.spot_id,
      count(*)::bigint as review_count
    from public.reviews r
    group by r.spot_id
  ),
  mood_rows as (
    select r.spot_id, nullif(trim(r.mood_a), '') as mood
    from public.reviews r
    where nullif(trim(r.mood_a), '') is not null

    union all

    select r.spot_id, nullif(trim(r.mood_b), '') as mood
    from public.reviews r
    where nullif(trim(r.mood_b), '') is not null
  ),
  mood_counts as (
    select
      mr.spot_id,
      mr.mood,
      count(*) as mood_count
    from mood_rows mr
    group by mr.spot_id, mr.mood
  ),
  top_moods as (
    select
      ranked.spot_id,
      array_agg(ranked.mood order by ranked.mood_count desc, ranked.mood)
        filter (where ranked.mood_rank <= 3) as top_moods
    from (
      select
        mc.*,
        row_number() over (
          partition by mc.spot_id
          order by mc.mood_count desc, mc.mood
        ) as mood_rank
      from mood_counts mc
    ) ranked
    group by ranked.spot_id
  )
  select
    s.id as spot_id,
    s.name,
    s.city,
    c.name as category_name,
    coalesce(
      nullif(s.header_photo_path, ''),
      photo.url
    ) as photo_url,
    coalesce(tm.top_moods, array[]::text[]) as top_moods,
    coalesce(rs.review_count, 0)::bigint as review_count
  from public.spots s
  left join public.categories c on c.id = s.category_id
  left join review_stats rs on rs.spot_id = s.id
  left join top_moods tm on tm.spot_id = s.id
  left join lateral (
    select sp.url
    from public.spot_photos sp
    where sp.spot_id = s.id
      and nullif(sp.url, '') is not null
    order by sp.created_at asc nulls last
    limit 1
  ) photo on true
  where lower(trim(coalesce(s.city, ''))) = lower(trim(p_city))
    and coalesce(s.status, 'approved') = 'approved'
  order by
    case when coalesce(rs.review_count, 0) > 0 then 0 else 1 end,
    coalesce(rs.review_count, 0) desc,
    s.created_at desc
  limit greatest(1, least(coalesce(p_limit, 12), 30));
$$;

ALTER FUNCTION "public"."backyrd_web_city_spots_v1"("p_city" "text", "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_web_spot_detail_v1"("p_spot_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with selected_spot as (
    select
      s.id,
      s.name,
      s.address,
      s.city,
      s.country,
      s.header_photo_path,
      s.price_level,
      s.website,
      s.phone,
      c.id as category_id,
      c.name as category_name
    from public.spots s
    left join public.categories c on c.id = s.category_id
    where s.id = p_spot_id
      and coalesce(s.status, 'approved') = 'approved'
    limit 1
  ),
  mood_rows as (
    select nullif(trim(r.mood_a), '') as mood
    from public.reviews r
    where r.spot_id = p_spot_id
      and nullif(trim(r.mood_a), '') is not null
    union all
    select nullif(trim(r.mood_b), '') as mood
    from public.reviews r
    where r.spot_id = p_spot_id
      and nullif(trim(r.mood_b), '') is not null
  ),
  mood_counts as (
    select mood, count(*)::bigint as mood_count
    from mood_rows
    group by mood
  )
  select jsonb_build_object(
    'spot',
    jsonb_build_object(
      'id', s.id,
      'name', s.name,
      'address', s.address,
      'city', s.city,
      'country', s.country,
      'header_photo_path', s.header_photo_path,
      'price_level', s.price_level,
      'website', s.website,
      'phone', s.phone,
      'email', null,
      'category',
      case
        when s.category_id is null then null
        else jsonb_build_object(
          'id', s.category_id,
          'name', s.category_name
        )
      end
    ),
    'photos',
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', sp.id,
            'url', sp.url
          )
          order by sp.created_at asc nulls last
        )
        from public.spot_photos sp
        where sp.spot_id = s.id
          and nullif(trim(sp.url), '') is not null
      ),
      '[]'::jsonb
    ),
    'top_moods',
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'mood_id', mc.mood,
            'token', mc.mood,
            'count', mc.mood_count
          )
          order by mc.mood_count desc, mc.mood asc
        )
        from (
          select mood, mood_count
          from mood_counts
          order by mood_count desc, mood asc
          limit 8
        ) mc
      ),
      '[]'::jsonb
    ),
    'reviews',
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'id', r.id,
            'text', r.text,
            'mood_a', nullif(trim(r.mood_a), ''),
            'mood_b', nullif(trim(r.mood_b), ''),
            'created_at', r.created_at,
            'user', jsonb_build_object(
              'first_name', p.first_name
            ),
            'photos',
            case
              when nullif(trim(coalesce(r.photo_path, '')), '') is null
                then '[]'::jsonb
              else jsonb_build_array(
                jsonb_build_object('url', r.photo_path)
              )
            end
          )
          order by r.created_at desc
        )
        from public.reviews r
        left join public.profiles p on p.id = r.user_id
        where r.spot_id = s.id
      ),
      '[]'::jsonb
    )
  )
  from selected_spot s;
$$;

ALTER FUNCTION "public"."backyrd_web_spot_detail_v1"("p_spot_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_web_top_moments_v1"("p_limit" integer DEFAULT 5) RETURNS TABLE("review_id" "uuid", "spot_id" "uuid", "spot_name" "text", "city" "text", "first_name" "text", "text" "text", "mood_a" "text", "mood_b" "text", "photo_url" "text", "likes_count" bigint, "comments_count" bigint, "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with likes as (
    select
      rl.review_id,
      count(*)::bigint as likes_count
    from public.review_likes rl
    group by rl.review_id
  ),
  comments as (
    select
      rc.review_id,
      count(*)::bigint as comments_count
    from public.review_comments rc
    group by rc.review_id
  )
  select
    r.id as review_id,
    r.spot_id,
    coalesce(nullif(trim(s.name), ''), 'Backyrd Spot') as spot_name,
    s.city,
    p.first_name,
    nullif(trim(coalesce(r.text, '')), '') as text,
    nullif(trim(coalesce(r.mood_a, '')), '') as mood_a,
    nullif(trim(coalesce(r.mood_b, '')), '') as mood_b,
    nullif(trim(coalesce(r.photo_path, '')), '') as photo_url,
    coalesce(l.likes_count, 0)::bigint as likes_count,
    coalesce(cm.comments_count, 0)::bigint as comments_count,
    r.created_at
  from public.reviews r
  join public.spots s on s.id = r.spot_id
  left join public.profiles p on p.id = r.user_id
  left join likes l on l.review_id = r.id
  left join comments cm on cm.review_id = r.id
  where r.created_at >= now() - interval '7 days'
  order by
    (
      coalesce(l.likes_count, 0) * 3
      + coalesce(cm.comments_count, 0) * 5
      + case
          when nullif(trim(coalesce(r.photo_path, '')), '') is not null
          then 2
          else 0
        end
      + greatest(
          0,
          7 - floor(extract(epoch from (now() - r.created_at)) / 86400)
        )
    ) desc,
    r.created_at desc
  limit greatest(1, least(coalesce(p_limit, 5), 10));
$$;

ALTER FUNCTION "public"."backyrd_web_top_moments_v1"("p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."backyrd_web_top_spots_v1"("p_city" "text" DEFAULT 'Basel'::"text", "p_limit" integer DEFAULT 6) RETURNS TABLE("spot_id" "uuid", "name" "text", "city" "text", "category_name" "text", "photo_url" "text", "top_moods" "text"[], "review_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select *
  from public.backyrd_web_city_spots_v1(
    p_city,
    greatest(1, least(coalesce(p_limit, 6), 12))
  )
  where cardinality(top_moods) > 0
  order by review_count desc, name asc
  limit greatest(1, least(coalesce(p_limit, 6), 12));
$$;

ALTER FUNCTION "public"."backyrd_web_top_spots_v1"("p_city" "text", "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."block_user_v1"("p_user_id" "uuid") RETURNS TABLE("blocked_user_id" "uuid", "is_blocked" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'not_authenticated'
      using errcode = '28000';
  end if;

  if p_user_id is null then
    raise exception 'user_id_required';
  end if;

  if p_user_id = v_me then
    raise exception 'cannot_block_self';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_user_id
  ) then
    raise exception 'user_not_found';
  end if;

  insert into public.user_blocks (
    blocker_id,
    blocked_id
  )
  values (
    v_me,
    p_user_id
  )
  on conflict (blocker_id, blocked_id)
  do nothing;

  delete from public.follows f
  where
    (f.follower = v_me and f.following = p_user_id)
    or
    (f.follower = p_user_id and f.following = v_me);

  blocked_user_id := p_user_id;
  is_blocked := true;
  message := 'user_blocked';
  return next;
end;
$$;

ALTER FUNCTION "public"."block_user_v1"("p_user_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."bump_spot_mood_count"("p_spot_id" "uuid", "p_mood_id" integer, "p_delta" integer) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  has_updated_at boolean;
  has_rank boolean;
begin
  if p_spot_id is null or p_mood_id is null or p_delta = 0 then
    return;
  end if;

  select exists (
    select 1 from information_schema.columns
    where table_schema='public' and table_name='spot_moods_agg' and column_name='updated_at'
  ) into has_updated_at;

  select exists (
    select 1 from information_schema.columns
    where table_schema='public' and table_name='spot_moods_agg' and column_name='rank'
  ) into has_rank;

  if has_updated_at and has_rank then
    insert into public.spot_moods_agg (spot_id, mood_id, mood_count, rank, updated_at)
    values (p_spot_id, p_mood_id, greatest(p_delta,0), greatest(p_delta,0)::numeric, now())
    on conflict (spot_id, mood_id) do update
      set mood_count = greatest(public.spot_moods_agg.mood_count + p_delta, 0),
          rank = greatest((public.spot_moods_agg.mood_count + p_delta), 0)::numeric,
          updated_at = now();
  elsif has_updated_at and not has_rank then
    insert into public.spot_moods_agg (spot_id, mood_id, mood_count, updated_at)
    values (p_spot_id, p_mood_id, greatest(p_delta,0), now())
    on conflict (spot_id, mood_id) do update
      set mood_count = greatest(public.spot_moods_agg.mood_count + p_delta, 0),
          updated_at = now();
  elsif (not has_updated_at) and has_rank then
    insert into public.spot_moods_agg (spot_id, mood_id, mood_count, rank)
    values (p_spot_id, p_mood_id, greatest(p_delta,0), greatest(p_delta,0)::numeric)
    on conflict (spot_id, mood_id) do update
      set mood_count = greatest(public.spot_moods_agg.mood_count + p_delta, 0),
          rank = greatest((public.spot_moods_agg.mood_count + p_delta), 0)::numeric;
  else
    insert into public.spot_moods_agg (spot_id, mood_id, mood_count)
    values (p_spot_id, p_mood_id, greatest(p_delta,0))
    on conflict (spot_id, mood_id) do update
      set mood_count = greatest(public.spot_moods_agg.mood_count + p_delta, 0);
  end if;

  -- wenn runtergezählt auf 0 -> Row löschen (sauber halten)
  delete from public.spot_moods_agg
  where spot_id = p_spot_id
    and mood_id = p_mood_id
    and mood_count = 0;
end $$;

ALTER FUNCTION "public"."bump_spot_mood_count"("p_spot_id" "uuid", "p_mood_id" integer, "p_delta" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."can_edit_spot_v1"("p_spot_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.profiles p
    where p.id = auth.uid()
      and coalesce(p.is_admin, false) = true
  )
  or exists (
    select 1
    from public.spots s
    where s.id = p_spot_id
      and s.owner_id = auth.uid()
  )
  or exists (
    select 1
    from public.spot_claims sc
    where sc.spot_id = p_spot_id
      and sc.user_id = auth.uid()
      and sc.status = 'approved'
  );
$$;

ALTER FUNCTION "public"."can_edit_spot_v1"("p_spot_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."cancel_my_account_deletion_v1"() RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  update public.data_rights_requests r
  set
    status = 'cancelled',
    cancelled_at = now()
  where r.user_id = v_user_id
    and r.request_type = 'account_deletion'
    and r.status in ('requested', 'scheduled')
    and r.processing_started_at is null;

  return found;
end;
$$;

ALTER FUNCTION "public"."cancel_my_account_deletion_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."check_friend_achievements"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  friend_count int;
begin
  /*
    Current follows schema:
      follower  = user who follows
      following = user being followed

    Old function expected:
      follower_id
      following_id

    This version uses the real column names.
  */

  select count(*)
  into friend_count
  from public.follows
  where follower = new.follower;

  if friend_count >= 1 then
    perform public.unlock_achievement(new.follower, 'friend_1');
  end if;

  if friend_count >= 5 then
    perform public.unlock_achievement(new.follower, 'friend_5');
  end if;

  if friend_count >= 25 then
    perform public.unlock_achievement(new.follower, 'friend_25');
  end if;

  if friend_count >= 50 then
    perform public.unlock_achievement(new.follower, 'friend_50');
  end if;

  if friend_count >= 100 then
    perform public.unlock_achievement(new.follower, 'friend_100');
  end if;

  return new;
end;
$$;

ALTER FUNCTION "public"."check_friend_achievements"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."check_spot_achievements"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  spot_count int;
begin
  select count(*) into spot_count from public.spots where created_by = new.created_by;

  if spot_count >= 1 then perform public.unlock_achievement(new.created_by, 'spot_1'); end if;
  if spot_count >= 5 then perform public.unlock_achievement(new.created_by, 'spot_5'); end if;
  if spot_count >= 25 then perform public.unlock_achievement(new.created_by, 'spot_25'); end if;
  if spot_count >= 50 then perform public.unlock_achievement(new.created_by, 'spot_50'); end if;
  if spot_count >= 100 then perform public.unlock_achievement(new.created_by, 'spot_100'); end if;
  if spot_count >= 200 then perform public.unlock_achievement(new.created_by, 'spot_200'); end if;
  if spot_count >= 500 then perform public.unlock_achievement(new.created_by, 'spot_500'); end if;

  return new;
end;
$$;

ALTER FUNCTION "public"."check_spot_achievements"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."complete_decision_onboarding_v1"("p_city" "text", "p_spot_ids" "uuid"[]) RETURNS TABLE("ok" boolean, "user_id" "uuid", "city" "text", "selected_count" integer, "event_count" integer, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_city text := nullif(trim(coalesce(p_city, '')), '');
  v_spot_ids uuid[];
  v_spot_id uuid;
  v_rank integer := 0;
  v_selected_count integer := 0;
  v_event_count integer := 0;
  v_existing_count integer := 0;
  v_has_log_fn boolean := false;
begin
  if v_user_id is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  if v_city is null then
    raise exception 'city_required';
  end if;

  select coalesce(array_agg(distinct x), '{}'::uuid[])
  into v_spot_ids
  from unnest(coalesce(p_spot_ids, '{}'::uuid[])) as x
  where x is not null;

  v_selected_count := coalesce(array_length(v_spot_ids, 1), 0);

  if v_selected_count < 3 then
    raise exception 'at_least_three_spots_required';
  end if;

  if v_selected_count > 8 then
    raise exception 'maximum_eight_spots_allowed';
  end if;

  select count(*)::integer
  into v_existing_count
  from public.spots s
  where s.id = any(v_spot_ids)
    and coalesce(s.status::text, '') = 'approved';

  if v_existing_count <> v_selected_count then
    raise exception 'selected_spots_must_exist_and_be_approved';
  end if;

  -- Ensure profile exists and keep city/home city.
  insert into public.profiles (
    id,
    city,
    home_city,
    created_at,
    updated_at
  )
  values (
    v_user_id,
    v_city,
    v_city,
    now(),
    now()
  )
  on conflict (id) do update set
    city = coalesce(public.profiles.city, excluded.city),
    home_city = coalesce(public.profiles.home_city, excluded.home_city),
    updated_at = now();

  -- Keep compatibility with the existing favorite seed pipeline.
  perform public.save_favorite_spot_seeds_v1(
    p_city := v_city,
    p_spot_ids := v_spot_ids,
    p_raw_names := '{}'::text[]
  );

  perform public.apply_favorite_spot_seeds_v1(
    p_city := v_city,
    p_days := 365
  );

  select exists (
    select 1
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname = 'backyrd_ml_log_event_v1'
  )
  into v_has_log_fn;

  foreach v_spot_id in array v_spot_ids loop
    v_rank := v_rank + 1;

    if v_has_log_fn then
      perform public.backyrd_ml_log_event_v1(
        p_event_type := 'decision_like',
        p_spot_id := v_spot_id,
        p_decision_id := null,
        p_rank := v_rank,
        p_city := v_city,
        p_mood_a_text := null,
        p_mood_b_text := null,
        p_context := jsonb_build_object(
          'source', 'decision_onboarding',
          'onboarding_favorite', true,
          'seed_rank', v_rank,
          'selected_count', v_selected_count,
          'profile_phase', 'cold_start'
        ),
        p_signal_strength := 0.35
      );
    end if;

    perform public.backyrd_update_place_type_preference_v1(
      p_user_id := v_user_id,
      p_spot_id := v_spot_id,
      p_event_type := 'onboarding_favorite',
      p_signal_strength := 0.35,
      p_city := v_city,
      p_mood_a_text := null,
      p_mood_b_text := null,
      p_context := jsonb_build_object(
        'source', 'decision_onboarding',
        'profile_phase', 'cold_start',
        'seed_rank', v_rank
      )
    );

    v_event_count := v_event_count + 1;
  end loop;

  update public.profiles p
  set
    city = coalesce(p.city, v_city),
    home_city = coalesce(p.home_city, v_city),
    decision_onboarding_completed_at = now(),
    onboarding_version = 'v1',
    updated_at = now()
  where p.id = v_user_id;

  ok := true;
  user_id := v_user_id;
  city := v_city;
  selected_count := v_selected_count;
  event_count := v_event_count;
  message := 'decision_onboarding_completed';

  return next;
end;
$$;

ALTER FUNCTION "public"."complete_decision_onboarding_v1"("p_city" "text", "p_spot_ids" "uuid"[]) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."complete_profile_onboarding_v1"("p_display_name" "text", "p_username" "text", "p_age" integer, "p_city" "text" DEFAULT NULL::"text") RETURNS TABLE("ok" boolean, "user_id" "uuid", "display_name" "text", "username" "text", "age" integer, "city" "text", "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_user_id uuid := auth.uid();
  v_display_name text := nullif(trim(coalesce(p_display_name, '')), '');
  v_username text := lower(nullif(trim(coalesce(p_username, '')), ''));
  v_city text := nullif(trim(coalesce(p_city, '')), '');
  v_age integer := p_age;
  v_birthdate date;
  v_username_taken boolean := false;
begin
  if v_user_id is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  if v_display_name is null or length(v_display_name) < 2 then
    raise exception 'display_name_required';
  end if;

  if length(v_display_name) > 60 then
    raise exception 'display_name_too_long';
  end if;

  if v_username is null then
    raise exception 'username_required';
  end if;

  if v_username !~ '^[a-z0-9_.]{3,24}$' then
    raise exception 'username_invalid';
  end if;

  if v_age is null or v_age < 13 or v_age > 120 then
    raise exception 'age_invalid';
  end if;

  select exists (
    select 1
    from public.profiles p
    where lower(trim(p.username)) = v_username
      and p.id <> v_user_id
  )
  into v_username_taken;

  if v_username_taken then
    raise exception 'username_taken';
  end if;

  -- App asks for age, profiles currently stores birthdate.
  -- We store an approximate birthdate for age-based filtering.
  v_birthdate := make_date((extract(year from current_date)::integer - v_age), 1, 1);

  insert into public.profiles (
    id,
    display_name,
    username,
    birthdate,
    city,
    home_city,
    age_confirmed_at,
    profile_onboarding_completed_at,
    onboarding_version,
    created_at,
    updated_at
  )
  values (
    v_user_id,
    v_display_name,
    v_username,
    v_birthdate,
    v_city,
    v_city,
    now(),
    now(),
    'v1',
    now(),
    now()
  )
  on conflict (id) do update set
    display_name = excluded.display_name,
    username = excluded.username,
    birthdate = excluded.birthdate,
    city = coalesce(excluded.city, public.profiles.city),
    home_city = coalesce(excluded.home_city, public.profiles.home_city),
    age_confirmed_at = now(),
    profile_onboarding_completed_at = now(),
    onboarding_version = 'v1',
    updated_at = now();

  ok := true;
  user_id := v_user_id;
  display_name := v_display_name;
  username := v_username;
  age := v_age;
  city := v_city;
  message := 'profile_onboarding_completed';

  return next;
end;
$_$;

ALTER FUNCTION "public"."complete_profile_onboarding_v1"("p_display_name" "text", "p_username" "text", "p_age" integer, "p_city" "text") OWNER TO "postgres";

