CREATE OR REPLACE FUNCTION "public"."create_social_comment_v1"("p_post_id" "uuid", "p_body" "text") RETURNS TABLE("comment_id" "uuid", "post_id" "uuid", "body" "text", "created_at" timestamp with time zone, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_comment_id uuid;
  v_body text := nullif(trim(coalesce(p_body, '')), '');
begin
  if v_user_id is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  if p_post_id is null then
    raise exception 'post_id_required';
  end if;

  if v_body is null then
    raise exception 'comment_body_required';
  end if;

  if length(v_body) > 1000 then
    raise exception 'comment_too_long';
  end if;

  if not exists (
    select 1
    from public.social_posts p
    where p.id = p_post_id
      and p.status = 'published'
  ) then
    raise exception 'post_not_found';
  end if;

  insert into public.social_comments (
    post_id,
    user_id,
    body,
    status
  )
  values (
    p_post_id,
    v_user_id,
    v_body,
    'published'
  )
  returning id into v_comment_id;

  update public.social_posts p
  set
    comment_count = (
      select count(*)::integer
      from public.social_comments c
      where c.post_id = p_post_id
        and c.status = 'published'
    ),
    updated_at = now()
  where p.id = p_post_id;

  insert into public.social_feed_events (
    user_id,
    post_id,
    spot_id,
    event_type,
    context
  )
  select
    v_user_id,
    p.id,
    p.spot_id,
    'post_comment',
    jsonb_build_object('comment_id', v_comment_id)
  from public.social_posts p
  where p.id = p_post_id;

  comment_id := v_comment_id;
  post_id := p_post_id;
  body := v_body;
  created_at := now();
  message := 'comment_created';
  return next;
end;
$$;

ALTER FUNCTION "public"."create_social_comment_v1"("p_post_id" "uuid", "p_body" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."create_social_moment_from_review_v1"("p_review_id" "uuid", "p_visibility" "text" DEFAULT 'public'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_review_json jsonb;
  v_review_user_id uuid;
  v_spot_id uuid;
  v_caption text;
  v_visibility text;
  v_mood_tags text[] := '{}'::text[];
  v_occasion_tags text[] := '{}'::text[];
  v_source_type text := 'review';
  v_post_id uuid;
begin
  if auth.uid() is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  if p_review_id is null then
    raise exception 'missing_review_id' using errcode = '22023';
  end if;

  select to_jsonb(r)
  into v_review_json
  from public.reviews r
  where r.id = p_review_id
  limit 1;

  if v_review_json is null then
    raise exception 'review_not_found' using errcode = 'P0002';
  end if;

  v_review_user_id := coalesce(
    nullif(v_review_json ->> 'user_id', '')::uuid,
    nullif(v_review_json ->> 'profile_id', '')::uuid,
    nullif(v_review_json ->> 'created_by', '')::uuid,
    auth.uid()
  );

  if v_review_user_id <> auth.uid() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  v_spot_id := coalesce(
    nullif(v_review_json ->> 'spot_id', '')::uuid,
    nullif(v_review_json ->> 'place_id', '')::uuid
  );

  if v_spot_id is null then
    raise exception 'review_has_no_spot' using errcode = '22023';
  end if;

  v_visibility := lower(trim(coalesce(p_visibility, v_review_json ->> 'visibility', 'public')));

  if v_visibility not in ('public', 'followers', 'private') then
    v_visibility := 'public';
  end if;

  if v_visibility = 'private' then
    return null;
  end if;

  v_caption := coalesce(
    nullif(trim(v_review_json ->> 'caption'), ''),
    nullif(trim(v_review_json ->> 'comment'), ''),
    nullif(trim(v_review_json ->> 'description'), ''),
    nullif(trim(v_review_json ->> 'body'), ''),
    nullif(trim(v_review_json ->> 'text'), ''),
    nullif(trim(v_review_json ->> 'notes'), ''),
    nullif(trim(v_review_json ->> 'review_text'), '')
  );

  v_mood_tags := public.backyrd_jsonb_collect_texts_v1(
    v_review_json,
    array[
      'mood_tags',
      'moods',
      'mood_texts',
      'selected_moods',
      'mood_a_text',
      'mood_b_text',
      'mood_a',
      'mood_b',
      'primary_mood',
      'secondary_mood'
    ]
  );

  v_occasion_tags := public.backyrd_jsonb_collect_texts_v1(
    v_review_json,
    array[
      'occasion_tags',
      'occasions',
      'best_for',
      'context_tags'
    ]
  );

  v_source_type :=
    case
      when nullif(v_review_json ->> 'decision_id', '') is not null then 'decision_review'
      else 'review'
    end;

  insert into public.social_posts (
    user_id,
    spot_id,
    caption,
    visibility,
    mood_tags,
    occasion_tags,
    source_type,
    review_id,
    source_context,
    created_at
  )
  values (
    v_review_user_id,
    v_spot_id,
    v_caption,
    v_visibility,
    coalesce(v_mood_tags, '{}'::text[]),
    coalesce(v_occasion_tags, '{}'::text[]),
    v_source_type,
    p_review_id,
    jsonb_build_object(
      'review_id', p_review_id,
      'source', 'review',
      'decision_id', nullif(v_review_json ->> 'decision_id', ''),
      'rating', nullif(v_review_json ->> 'rating', ''),
      'score', nullif(v_review_json ->> 'score', ''),
      'created_from', 'create_social_moment_from_review_v1'
    ),
    coalesce(nullif(v_review_json ->> 'created_at', '')::timestamptz, now())
  )
  on conflict (review_id)
  where review_id is not null and source_type in ('review', 'decision_review')
  do update set
    spot_id = excluded.spot_id,
    caption = excluded.caption,
    visibility = excluded.visibility,
    mood_tags = excluded.mood_tags,
    occasion_tags = excluded.occasion_tags,
    source_type = excluded.source_type,
    source_context = excluded.source_context
  returning id into v_post_id;

  delete from public.social_post_media
  where post_id = v_post_id;

  insert into public.social_post_media (
    post_id,
    storage_path,
    public_url,
    media_type,
    width,
    height,
    sort_order,
    created_at
  )
  select
    v_post_id,
    coalesce(
      nullif(to_jsonb(rp) ->> 'storage_path', ''),
      nullif(to_jsonb(rp) ->> 'photo_path', ''),
      nullif(to_jsonb(rp) ->> 'path', ''),
      nullif(to_jsonb(rp) ->> 'public_url', ''),
      nullif(to_jsonb(rp) ->> 'photo_url', ''),
      nullif(to_jsonb(rp) ->> 'url', '')
    ) as storage_path,
    coalesce(
      nullif(to_jsonb(rp) ->> 'public_url', ''),
      nullif(to_jsonb(rp) ->> 'photo_url', ''),
      nullif(to_jsonb(rp) ->> 'url', '')
    ) as public_url,
    coalesce(nullif(to_jsonb(rp) ->> 'media_type', ''), 'image') as media_type,
    nullif(to_jsonb(rp) ->> 'width', '')::integer as width,
    nullif(to_jsonb(rp) ->> 'height', '')::integer as height,
    row_number() over (
      order by
        coalesce(nullif(to_jsonb(rp) ->> 'sort_order', '')::integer, 0) asc,
        coalesce(nullif(to_jsonb(rp) ->> 'created_at', '')::timestamptz, now()) asc
    )::integer - 1 as sort_order,
    now()
  from public.review_photos rp
  where nullif(to_jsonb(rp) ->> 'review_id', '')::uuid = p_review_id
    and coalesce(
      nullif(to_jsonb(rp) ->> 'storage_path', ''),
      nullif(to_jsonb(rp) ->> 'photo_path', ''),
      nullif(to_jsonb(rp) ->> 'path', ''),
      nullif(to_jsonb(rp) ->> 'public_url', ''),
      nullif(to_jsonb(rp) ->> 'photo_url', ''),
      nullif(to_jsonb(rp) ->> 'url', '')
    ) is not null;

  return v_post_id;
end;
$$;

ALTER FUNCTION "public"."create_social_moment_from_review_v1"("p_review_id" "uuid", "p_visibility" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."create_social_post_v1"("p_spot_id" "uuid" DEFAULT NULL::"uuid", "p_caption" "text" DEFAULT NULL::"text", "p_visibility" "text" DEFAULT 'public'::"text", "p_mood_tags" "text"[] DEFAULT '{}'::"text"[], "p_occasion_tags" "text"[] DEFAULT '{}'::"text"[], "p_media" "jsonb" DEFAULT '[]'::"jsonb") RETURNS TABLE("post_id" "uuid", "created_at" timestamp with time zone, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_post_id uuid;
  v_visibility text := lower(trim(coalesce(p_visibility, 'public')));
  v_item jsonb;
  v_order integer := 0;
begin
  if v_user_id is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  if v_visibility not in ('public', 'followers', 'private') then
    raise exception 'invalid_visibility';
  end if;

  if p_spot_id is not null and not exists (
    select 1 from public.spots s where s.id = p_spot_id
  ) then
    raise exception 'spot_not_found';
  end if;

  insert into public.social_posts (
    user_id,
    spot_id,
    caption,
    visibility,
    mood_tags,
    occasion_tags,
    status
  )
  values (
    v_user_id,
    p_spot_id,
    nullif(trim(coalesce(p_caption, '')), ''),
    v_visibility,
    coalesce(p_mood_tags, '{}'),
    coalesce(p_occasion_tags, '{}'),
    'published'
  )
  returning id into v_post_id;

  if jsonb_typeof(coalesce(p_media, '[]'::jsonb)) = 'array' then
    for v_item in select * from jsonb_array_elements(coalesce(p_media, '[]'::jsonb))
    loop
      if nullif(trim(coalesce(v_item->>'storage_path', '')), '') is not null then
        insert into public.social_post_media (
          post_id,
          storage_path,
          public_url,
          media_type,
          width,
          height,
          sort_order
        )
        values (
          v_post_id,
          trim(v_item->>'storage_path'),
          nullif(trim(coalesce(v_item->>'public_url', '')), ''),
          coalesce(nullif(trim(v_item->>'media_type'), ''), 'image'),
          nullif(v_item->>'width', '')::integer,
          nullif(v_item->>'height', '')::integer,
          v_order
        );

        v_order := v_order + 1;
      end if;
    end loop;
  end if;

  post_id := v_post_id;
  created_at := now();
  message := 'social_post_created';
  return next;
end;
$$;

ALTER FUNCTION "public"."create_social_post_v1"("p_spot_id" "uuid", "p_caption" "text", "p_visibility" "text", "p_mood_tags" "text"[], "p_occasion_tags" "text"[], "p_media" "jsonb") OWNER TO "postgres";

