CREATE OR REPLACE FUNCTION "public"."data_rights_column_exists_v1"("p_table" "text", "p_column" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  select exists (
    select 1
    from information_schema.columns c
    where c.table_schema = 'public'
      and c.table_name = p_table
      and c.column_name = p_column
  );
$$;

ALTER FUNCTION "public"."data_rights_column_exists_v1"("p_table" "text", "p_column" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."data_rights_delete_by_user_v1"("p_table" "text", "p_column" "text", "p_user_id" "uuid") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $_$
declare
  v_count bigint := 0;
begin
  if not public.data_rights_table_exists_v1(p_table)
     or not public.data_rights_column_exists_v1(p_table, p_column) then
    return 0;
  end if;

  execute format(
    'delete from public.%I where %I::text = $1::text',
    p_table,
    p_column
  )
  using p_user_id;

  get diagnostics v_count = row_count;
  return v_count;
end;
$_$;

