    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $_$
declare
  v_count bigint := 0;
begin
  if not public.data_rights_table_exists_v1(p_table)
     or not public.data_rights_column_exists_v1(p_table, p_column) then
    return 0;
  end if;

  execute format(
    'update public.%I
     set %I = null
     where %I::text = $1::text',
    p_table,
    p_column,
    p_column
  )
  using p_user_id;

  get diagnostics v_count = row_count;
  return v_count;
end;
$_$;

