CREATE OR REPLACE FUNCTION "public"."decide_spot_claim_v2"("p_claim_id" bigint, "p_decision" "text", "p_rejection_reason" "text" DEFAULT NULL::"text") RETURNS TABLE("ok" boolean, "claim_id" bigint, "spot_id" "uuid", "user_id" "uuid", "status" "text", "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_admin_id uuid := auth.uid();
  v_is_admin boolean := false;
  v_claim record;
  v_decision text := lower(trim(coalesce(p_decision, '')));
begin
  if v_admin_id is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  select coalesce(p.is_admin, false)
  into v_is_admin
  from public.profiles p
  where p.id = v_admin_id;

  if not coalesce(v_is_admin, false) then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  if p_claim_id is null then
    raise exception 'claim_id_required';
  end if;

  if v_decision not in ('approved', 'rejected') then
    raise exception 'invalid_decision';
  end if;

  select
    sc.id,
    sc.spot_id,
    sc.user_id,
    sc.status,
    sc.business_email,
    sc.business_domain,
    sc.email_verified_at
  into v_claim
  from public.spot_claims sc
  where sc.id = p_claim_id
  limit 1;

  if v_claim.id is null then
    raise exception 'claim_not_found';
  end if;

  if v_claim.email_verified_at is null then
    raise exception 'business_email_not_verified';
  end if;

  if v_decision = 'approved' then
    update public.spot_claims sc
    set
      status = 'approved',
      reviewed_by = v_admin_id,
      reviewed_at = now(),
      rejection_reason = null,
      updated_at = now()
    where sc.id = p_claim_id;

    update public.spots s
    set owner_id = v_claim.user_id
    where s.id = v_claim.spot_id;

    insert into public.spot_descriptions (
      spot_id,
      owner_user_id,
      is_verified,
      created_at,
      updated_at
    )
    values (
      v_claim.spot_id,
      v_claim.user_id,
      true,
      now(),
      now()
    )
    on conflict on constraint spot_descriptions_pkey
    do update set
      owner_user_id = excluded.owner_user_id,
      is_verified = true,
      updated_at = now();

    return query
    select
      true as ok,
      p_claim_id as claim_id,
      v_claim.spot_id as spot_id,
      v_claim.user_id as user_id,
      'approved'::text as status,
      'spot_claim_approved'::text as message;

    return;
  end if;

  update public.spot_claims sc
  set
    status = 'rejected',
    reviewed_by = v_admin_id,
    reviewed_at = now(),
    rejection_reason = nullif(trim(coalesce(p_rejection_reason, '')), ''),
    updated_at = now()
  where sc.id = p_claim_id;

  return query
  select
    true as ok,
    p_claim_id as claim_id,
    v_claim.spot_id as spot_id,
    v_claim.user_id as user_id,
    'rejected'::text as status,
    'spot_claim_rejected'::text as message;
end;
$$;

ALTER FUNCTION "public"."decide_spot_claim_v2"("p_claim_id" bigint, "p_decision" "text", "p_rejection_reason" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."disable_my_push_device_v1"("p_expo_push_token" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_count integer;
begin
  if v_user_id is null then
    raise exception 'not_authenticated'
      using errcode = '28000';
  end if;

  update public.user_push_devices d
  set
    notifications_enabled = false,
    disabled_at = now()
  where d.user_id = v_user_id
    and (
      nullif(btrim(p_expo_push_token), '') is null
      or d.expo_push_token = btrim(p_expo_push_token)
    )
    and d.notifications_enabled = true;

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

ALTER FUNCTION "public"."disable_my_push_device_v1"("p_expo_push_token" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."enforce_optional_analytics_consent_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid;
begin
  v_user_id := coalesce(new.user_id, auth.uid());

  if not public.user_has_active_consent_v1(
    v_user_id,
    'optional_product_analytics'
  ) then
    if tg_op = 'UPDATE' then
      return old;
    end if;

    return null;
  end if;

  return new;
end;
$$;

