CREATE OR REPLACE FUNCTION "public"."enqueue_message_push_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_recipient uuid;
begin
  select
    case
      when c.user_a = new.sender_id then c.user_b
      else c.user_a
    end
  into v_recipient
  from public.chats c
  where c.id = new.chat_id
    and (
      c.user_a = new.sender_id
      or c.user_b = new.sender_id
    );

  if v_recipient is null then
    return new;
  end if;

  if public.users_are_blocked_v1(new.sender_id, v_recipient) then
    return new;
  end if;

  insert into public.message_push_outbox (
    message_id,
    chat_id,
    sender_id,
    recipient_id
  )
  values (
    new.id,
    new.chat_id,
    new.sender_id,
    v_recipient
  )
  on conflict (message_id) do nothing;

  return new;
end;
$$;

ALTER FUNCTION "public"."enqueue_message_push_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."enqueue_spot_enrichment_v1"("p_spot_id" "uuid", "p_reason" "text" DEFAULT 'missing_description'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  -- only approved
  if not exists (select 1 from public.spots where id = p_spot_id and status = 'approved') then
    return;
  end if;

  if exists (
    select 1 from public.spot_enrichment_jobs
    where spot_id = p_spot_id
      and status in ('pending','processing')
      and created_at > now() - interval '2 hours'
  ) then
    return;
  end if;

  insert into public.spot_enrichment_jobs (spot_id, reason, status)
  values (p_spot_id, p_reason, 'pending');
end $$;

ALTER FUNCTION "public"."enqueue_spot_enrichment_v1"("p_spot_id" "uuid", "p_reason" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."expand_resolved_targets"("p_resolved_via" "text", "p_resolved_token_id" integer, "p_cluster_id" bigint, "p_min_confidence" numeric DEFAULT 0.65) RETURNS TABLE("mood_id" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select distinct t.mood_id
  from (
    -- exact/synonym -> one token id
    select p_resolved_token_id as mood_id
    where p_resolved_via in ('exact','synonym') and p_resolved_token_id is not null

    union all

    -- cluster -> all token ids in cluster above threshold
    select tc.token_id as mood_id
    from public.mood_token_clusters tc
    where p_resolved_via = 'cluster'
      and p_cluster_id is not null
      and tc.cluster_id = p_cluster_id
      and tc.confidence >= p_min_confidence
  ) t
  where t.mood_id is not null;
$$;

ALTER FUNCTION "public"."expand_resolved_targets"("p_resolved_via" "text", "p_resolved_token_id" integer, "p_cluster_id" bigint, "p_min_confidence" numeric) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."follow_spot_v1"("p_spot_id" "uuid") RETURNS TABLE("spot_id" "uuid", "is_following" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  if p_spot_id is null then
    raise exception 'spot_id_required';
  end if;

  if not exists (select 1 from public.spots s where s.id = p_spot_id) then
    raise exception 'spot_not_found';
  end if;

  insert into public.spot_follows (
    user_id,
    spot_id,
    created_at
  )
  values (
    v_user_id,
    p_spot_id,
    now()
  )
  on conflict (user_id, spot_id) do nothing;

  spot_id := p_spot_id;
  is_following := true;
  message := 'spot_followed';
  return next;
end;
$$;

ALTER FUNCTION "public"."follow_spot_v1"("p_spot_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."follow_user_v1"("p_user_id" "uuid") RETURNS TABLE("following_id" "uuid", "is_following" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  if p_user_id is null then
    raise exception 'user_id_required';
  end if;

  if p_user_id = v_user_id then
    raise exception 'cannot_follow_self';
  end if;

  if not exists (select 1 from auth.users u where u.id = p_user_id) then
    raise exception 'user_not_found';
  end if;

  insert into public.follows (
    follower,
    following,
    created_at
  )
  values (
    v_user_id,
    p_user_id,
    now()
  )
  on conflict (follower, following) do nothing;

  insert into public.social_feed_events (
    user_id,
    event_type,
    context
  )
  values (
    v_user_id,
    'follow_user',
    jsonb_build_object('following_id', p_user_id)
  );

  following_id := p_user_id;
  is_following := true;
  message := 'user_followed';
  return next;
end;
$$;

ALTER FUNCTION "public"."follow_user_v1"("p_user_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."follow_user_v2"("p_user_id" "uuid") RETURNS TABLE("following_id" "uuid", "is_following" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'not_authenticated'
      using errcode = '28000';
  end if;

  if p_user_id is null then
    raise exception 'user_id_required';
  end if;

  if p_user_id = v_me then
    raise exception 'cannot_follow_self';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_user_id
  ) then
    raise exception 'user_not_found';
  end if;

  if exists (
    select 1
    from public.profiles p
    where p.id = p_user_id
      and p.is_private = true
  ) then
    raise exception 'private_profile_not_followable';
  end if;

  if public.users_are_blocked_v1(v_me, p_user_id) then
    raise exception 'interaction_blocked';
  end if;

  insert into public.follows (
    follower,
    following,
    created_at
  )
  values (
    v_me,
    p_user_id,
    now()
  )
  on conflict (follower, following)
  do nothing;

  following_id := p_user_id;
  is_following := true;
  message := 'user_followed';
  return next;
end;
$$;

ALTER FUNCTION "public"."follow_user_v2"("p_user_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_active_legal_documents_v1"("p_locale" "text" DEFAULT 'de-CH'::"text") RETURNS TABLE("document_id" "uuid", "document_type" "text", "version" "text", "locale" "text", "title" "text", "summary" "text", "content_markdown" "text", "content_hash" "text", "requires_acceptance" boolean, "requires_reacceptance" boolean, "effective_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
