CREATE OR REPLACE FUNCTION "public"."get_decision_context_v1"("p_city" "text", "p_mood_a_text" "text" DEFAULT NULL::"text", "p_mood_b_text" "text" DEFAULT NULL::"text") RETURNS TABLE("decision_mode" "text", "title" "text", "body" "text", "weekday_name" "text", "time_bucket" "text", "user_confidence" numeric, "is_fallback" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid;
  v_conf numeric := 0;

  v_weekday int;
  v_weekday_name text;
  v_hour int;
  v_bucket text;
  v_time_phrase text;
  v_city text := coalesce(nullif(trim(p_city), ''), 'deiner Stadt');

  a text := lower(coalesce(nullif(trim(p_mood_a_text), ''), ''));
  b text := lower(coalesce(nullif(trim(p_mood_b_text), ''), ''));

  v_tone_1 text := null;
  v_tone_2 text := null;

  v_is_fallback boolean := false;

  sample record;
  sample_why text := '';
begin
  v_uid := auth.uid();

  -- Zurich time context
  v_weekday := extract(dow from timezone('Europe/Zurich', now()));
  v_hour := extract(hour from timezone('Europe/Zurich', now()));

  v_weekday_name := case v_weekday
    when 0 then 'Sonntag'
    when 1 then 'Montag'
    when 2 then 'Dienstag'
    when 3 then 'Mittwoch'
    when 4 then 'Donnerstag'
    when 5 then 'Freitag'
    when 6 then 'Samstag'
    else 'Heute'
  end;

  v_bucket := case
    when v_hour between 6 and 11 then 'morning'
    when v_hour between 12 and 16 then 'afternoon'
    when v_hour between 17 and 22 then 'evening'
    else 'night'
  end;

  v_time_phrase := case
    when v_bucket = 'morning' then 'morgens'
    when v_bucket = 'afternoon' then 'tagsüber'
    when v_bucket = 'evening' then 'abends'
    else 'spät'
  end;

  -- user confidence
  if v_uid is not null then
    select coalesce(p.confidence, 0)
      into v_conf
    from public.user_taste_profile_v1 p
    where p.user_id = v_uid;
  end if;

  -- tone mapping (deterministic, non-marketing)
  if a in ('crazy','wild','party','rave','laut') or b in ('crazy','wild','party','rave','laut') then
    v_tone_1 := 'lebendige';
  end if;

  if a in ('cozy','gemütlich','entspannt','chillig','ruhig') or b in ('cozy','gemütlich','entspannt','chillig','ruhig') then
    v_tone_2 := 'gemütliche';
  end if;

  if v_tone_1 is null and v_tone_2 is null then
    v_tone_1 := 'passende';
  end if;

  -- ✅ NEW: Fallback depends on decision output, not resolver "none"
  -- If user not logged in, we still can compute a sample using p_user_id = null is impossible.
  -- So: if not logged in -> never show "fallback" wording; show orientation.
  if v_uid is null then
    v_is_fallback := false;
  else
    select * into sample
    from public.get_decision_spots_v8(
      p_city => v_city,
      p_user_id => v_uid,
      p_limit => 1,
      p_mood_a_text => p_mood_a_text,
      p_mood_b_text => p_mood_b_text,
      p_seen_spot_ids => '{}'::uuid[],
      p_min_cluster_confidence => 0.65,
      p_min_token_count => 1
    )
    limit 1;

    sample_why := coalesce(sample.why_this, '');

    -- fallback only if we truly don't have mood-based suggestions
    -- heuristic: if why_this does NOT contain a signal count and/or contains generic fallback phrasing
    v_is_fallback :=
      (sample is null)
      or (
        sample_why !~ '\([0-9]+×\)'  -- no "(6×)" style evidence
        and lower(sample_why) like '%häufig gewählt%' -- generic popularity line
      );
  end if;

  -- decide mode
  if v_uid is null then
    decision_mode := 'orientation';
  elsif v_is_fallback then
    decision_mode := 'fallback';
  elsif v_conf >= 0.80 then
    decision_mode := 'strong_personalized';
  elsif v_conf >= 0.50 then
    decision_mode := 'weak_personalized';
  else
    decision_mode := 'orientation';
  end if;

  title := 'Wohin jetzt?';

  if decision_mode = 'fallback' then
    body :=
      'Dafür habe ich gerade keine sinnvolle Empfehlung. ' ||
      'Das sind Orte, die aktuell in ' || v_city || ' gut besucht sind – vielleicht passt etwas davon trotzdem.';
  elsif decision_mode = 'strong_personalized' then
    body :=
      'In ähnlichen Situationen hast du dich häufig für genau solche Orte entschieden. ' ||
      'Diese Auswahl passt gut zu deinem bisherigen Verhalten.';
  elsif decision_mode = 'weak_personalized' then
    body :=
      'Basierend auf dem, was du bisher bestätigt hast, funktionieren ' ||
      v_time_phrase || ' oft ' ||
      coalesce(v_tone_2, coalesce(v_tone_1,'passende')) || ' Orte für dich. ' ||
      'Diese Auswahl geht in diese Richtung.';
  else
    body :=
      'Ich habe noch zu wenig Feedback von dir, um dir etwas wirklich Persönliches vorzuschlagen. ' ||
      'Für ' || v_weekday_name || ' ' || v_time_phrase || ' in ' || v_city ||
      ' entscheiden sich viele gerade für ' ||
      trim(coalesce(v_tone_1,'') || ' ' || coalesce(v_tone_2,'')) ||
      ' Orte – deshalb diese Auswahl.';
  end if;

  weekday_name := v_weekday_name;
  time_bucket := v_bucket;
  user_confidence := v_conf;
  is_fallback := v_is_fallback;

  return next;
end;
$$;

ALTER FUNCTION "public"."get_decision_context_v1"("p_city" "text", "p_mood_a_text" "text", "p_mood_b_text" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_decision_debug_v1"("p_city" "text", "p_mood_a_text" "text", "p_mood_b_text" "text", "p_seen_spot_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_min_cluster_confidence" numeric DEFAULT 0.65, "p_min_token_count" integer DEFAULT 2, "p_open_now_epsilon" numeric DEFAULT 0.12, "p_limit" integer DEFAULT 10) RETURNS TABLE("spot_id" "uuid", "name" "text", "city" "text", "mood_strength" integer, "mood_match_count" integer, "text_match_score" integer, "is_open_now" boolean, "final_score" numeric, "matched_tokens" "text"[], "matched_counts" integer[], "matched_terms" "text"[], "why_this" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
with
ra as (select * from public.resolve_mood_input_v2(p_mood_a_text)),
rb as (select * from public.resolve_mood_input_v2(p_mood_b_text)),

ta as (
  select mood_id from public.expand_resolved_targets(
    (select resolved_via from ra),
    (select resolved_token_id from ra),
    (select cluster_id from ra),
    p_min_cluster_confidence
  )
),
tb as (
  select mood_id from public.expand_resolved_targets(
    (select resolved_via from rb),
    (select resolved_token_id from rb),
    (select cluster_id from rb),
    p_min_cluster_confidence
  )
),
selected as (
  select distinct mood_id from ta
  union
  select distinct mood_id from tb
),

base_all as (
  select s.id, s.name, s.city, s.created_at
  from public.spots s
  where s.status = 'approved'
    and s.city is not null
    and lower(s.city) = lower(trim(p_city))
),

base_unseen as (
  select *
  from base_all
  where p_seen_spot_ids is null
     or array_length(p_seen_spot_ids, 1) is null
     or not (id = any(p_seen_spot_ids))
),

terms_raw as (
  select trim(
    coalesce(p_mood_a_text,'') || ' ' ||
    coalesce(p_mood_b_text,'') || ' ' ||
    coalesce((select resolved_label from ra),'') || ' ' ||
    coalesce((select resolved_label from rb),'')
  ) as q
),
terms as (
  select array(
    select distinct t
    from unnest(
      regexp_split_to_array(
        lower(regexp_replace((select q from terms_raw), '\s+', ' ', 'g')),
        ' '
      )
    ) as t
    where t is not null
      and length(t) >= 3
      and t not in ('und','oder','der','die','das','mit','für','auf','im','in','am','an','zu','ein','eine')
    limit 12
  ) as arr
),

spot_text as (
  select
    b.id as spot_id,
    coalesce(nullif(sd.owner_description, ''), nullif(sd.enriched_description, '')) as effective_description,
    coalesce(sd.owner_keywords, sd.enriched_keywords, '{}'::text[]) as effective_keywords
  from base_all b
  left join public.spot_descriptions sd on sd.spot_id = b.id
),

per_token as (
  select
    sma.spot_id,
    sma.mood_id,
    mt.token,
    sma.mood_count::integer as token_count
  from public.spot_moods_agg_reviews_v1 sma
  join selected sel on sel.mood_id = sma.mood_id
  left join public.mood_tokens mt on mt.id = sma.mood_id
  where sma.spot_id in (select id from base_all)
    and sma.mood_count >= greatest(p_min_token_count, 1)
),

mood_agg as (
  select
    b.id as spot_id,
    count(distinct pt.mood_id) as mood_match_count,
    coalesce(sum(pt.token_count), 0)::integer as mood_strength,
    coalesce(
      array_agg(pt.token order by pt.token_count desc) filter (where pt.token is not null),
      '{}'::text[]
    ) as matched_tokens,
    coalesce(
      array_agg(pt.token_count order by pt.token_count desc) filter (where pt.token_count is not null),
      '{}'::integer[]
    ) as matched_counts
  from base_all b
  left join per_token pt on pt.spot_id = b.id
  group by b.id
),

text_agg as (
  select
    b.id as spot_id,
    coalesce((
      select sum(
        case
          when t is null or t = '' then 0
          when (
            (st.effective_description is not null and lower(st.effective_description) like ('%' || t || '%'))
            or (st.effective_keywords is not null and exists (
              select 1 from unnest(st.effective_keywords) k
              where lower(k) = t
            ))
          ) then 1
          else 0
        end
      )
      from unnest((select arr from terms)) as t
    ), 0)::integer as text_match_score,
    coalesce(
      array(
        select t
        from unnest((select arr from terms)) as t
        where t is not null and t <> ''
          and (
            (st.effective_description is not null and lower(st.effective_description) like ('%' || t || '%'))
            or (st.effective_keywords is not null and exists (
              select 1 from unnest(st.effective_keywords) k
              where lower(k) = t
            ))
          )
      ),
      '{}'::text[]
    ) as matched_terms
  from base_all b
  left join spot_text st on st.spot_id = b.id
),

open_now_agg as (
  select
    b.id as spot_id,
    public.spot_is_open_now_safe_v1(b.id) as is_open_now
  from base_all b
),

scored_all as (
  select
    b.id as spot_id,
    b.name,
    b.city,
    b.created_at,
    ma.mood_match_count,
    ma.mood_strength,
    tx.text_match_score,
    tx.matched_terms,
    onow.is_open_now,
    (
      ln(1 + greatest(ma.mood_strength, 0))::numeric * 1.0
      + (greatest(ma.mood_match_count, 0)::numeric * 0.15)
      + (greatest(tx.text_match_score, 0)::numeric * 0.05)
    ) as final_score,
    ma.matched_tokens,
    ma.matched_counts
  from base_all b
  left join mood_agg ma on ma.spot_id = b.id
  left join text_agg tx on tx.spot_id = b.id
  left join open_now_agg onow on onow.spot_id = b.id
),

unseen_has_signal as (
  select exists(
    select 1
    from scored_all sa
    where sa.spot_id in (select id from base_unseen)
      and (sa.mood_strength > 0 or sa.text_match_score > 0)
  ) as yes
),

base_scored as (
  select sa.*
  from scored_all sa, unseen_has_signal uhs
  where (uhs.yes = true and sa.spot_id in (select id from base_unseen))
     or (uhs.yes = false)
),

ranked as (
  select
    b.*,
    case
      when b.is_open_now is true
       and (select max(final_score) from base_scored) - b.final_score <= greatest(p_open_now_epsilon, 0)
      then 1 else 0
    end as open_now_near_tie
  from base_scored b
  order by
    b.final_score desc,
    b.mood_strength desc,
    b.text_match_score desc,
    open_now_near_tie desc,
    b.created_at desc
  limit greatest(1, least(p_limit, 50))
)

select
  r.spot_id,
  r.name,
  r.city,
  r.mood_strength,
  r.mood_match_count,
  r.text_match_score,
  r.is_open_now,
  r.final_score,
  r.matched_tokens,
  r.matched_counts,
  r.matched_terms,
  case
    when r.mood_strength > 0 and r.mood_match_count >= 2 then
      'Beide Moods passen, v.a. ' ||
      coalesce(r.matched_tokens[1], '…') || ' (' || coalesce(r.matched_counts[1], 0)::text || '×) und ' ||
      coalesce(r.matched_tokens[2], '…') || ' (' || coalesce(r.matched_counts[2], 0)::text || '×).'
    when r.mood_strength > 0 and r.mood_match_count = 1 then
      'Starkes ' || coalesce(r.matched_tokens[1], '…') || '-Signal (' || coalesce(r.matched_counts[1], 0)::text || '×).'
    when r.mood_strength = 0 and r.text_match_score > 0 then
      'Keine starken Review-Moods, aber Text passt zu: ' ||
      coalesce(array_to_string(r.matched_terms[1:3], ', '), '…') || '.'
    else
      'Gerade häufig gewählt in deiner Stadt.'
  end as why_this
from ranked r;
$$;

ALTER FUNCTION "public"."get_decision_debug_v1"("p_city" "text", "p_mood_a_text" "text", "p_mood_b_text" "text", "p_seen_spot_ids" "uuid"[], "p_min_cluster_confidence" numeric, "p_min_token_count" integer, "p_open_now_epsilon" numeric, "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_decision_followup_v1"("p_limit" integer DEFAULT 80) RETURNS TABLE("decision_id" "uuid", "created_at" timestamp with time zone, "city" "text", "mood_a_text" "text", "mood_b_text" "text", "spot_id" "uuid", "spot_name" "text", "spot_city" "text", "rank" integer, "why_this" "text", "last_action" "text", "last_action_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with my_sessions as (
    select s.id, s.created_at, s.city, s.mood_a_text, s.mood_b_text
    from public.decision_sessions s
    where s.user_id = auth.uid()
    order by s.created_at desc
    limit p_limit
  ),

  -- only spots that have at least one action (tapped or vote)
  acted as (
    select
      a.decision_id,
      a.spot_id,
      max(a.created_at) as last_action_at,
      (array_agg(a.action order by a.created_at desc))[1] as last_action
    from public.decision_actions a
    join my_sessions s on s.id = a.decision_id
    where a.action in ('tapped','was_here','exact_mood','not_there')
    group by a.decision_id, a.spot_id
  )

  select
    s.id as decision_id,
    s.created_at,
    s.city,
    s.mood_a_text,
    s.mood_b_text,
    di.spot_id,
    sp.name as spot_name,
    sp.city as spot_city,
    di.rank::integer as rank,
    di.why_this,
    acted.last_action,
    acted.last_action_at
  from my_sessions s
  join acted
    on acted.decision_id = s.id
  join public.decision_impressions di
    on di.decision_id = s.id
   and di.spot_id = acted.spot_id
  join public.spots sp on sp.id = di.spot_id
  order by s.created_at desc, di.rank asc;
$$;

ALTER FUNCTION "public"."get_decision_followup_v1"("p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_decision_followup_v2"("p_limit" integer DEFAULT 80, "p_tapped_ttl_hours" integer DEFAULT 24) RETURNS TABLE("decision_id" "uuid", "created_at" timestamp with time zone, "city" "text", "mood_a_text" "text", "mood_b_text" "text", "spot_id" "uuid", "spot_name" "text", "spot_city" "text", "rank" integer, "why_this" "text", "last_action" "text", "last_action_at" timestamp with time zone, "is_voted" boolean)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with my_sessions as (
    select s.id, s.created_at, s.city, s.mood_a_text, s.mood_b_text
    from public.decision_sessions s
    where s.user_id = auth.uid()
    order by s.created_at desc
    limit p_limit
  ),

  acted as (
    select
      a.decision_id,
      a.spot_id,
      max(a.created_at) as last_action_at,
      (array_agg(a.action order by a.created_at desc))[1] as last_action,
      bool_or(a.action in ('was_here','exact_mood','not_there')) as has_vote
    from public.decision_actions a
    join my_sessions s on s.id = a.decision_id
    where a.action in ('tapped','was_here','exact_mood','not_there')
    group by a.decision_id, a.spot_id
  ),

  filtered as (
    select *
    from acted
    where
      has_vote = true
      or (
        last_action = 'tapped'
        and last_action_at >= now() - (p_tapped_ttl_hours::text || ' hours')::interval
      )
  )

  select
    s.id as decision_id,
    s.created_at,
    s.city,
    s.mood_a_text,
    s.mood_b_text,
    di.spot_id,
    sp.name as spot_name,
    sp.city as spot_city,
    di.rank::integer as rank,
    di.why_this,
    f.last_action,
    f.last_action_at,
    f.has_vote as is_voted
  from my_sessions s
  join filtered f on f.decision_id = s.id
  join public.decision_impressions di
    on di.decision_id = s.id
   and di.spot_id = f.spot_id
  join public.spots sp on sp.id = di.spot_id
  order by s.created_at desc, di.rank asc;
$$;

ALTER FUNCTION "public"."get_decision_followup_v2"("p_limit" integer, "p_tapped_ttl_hours" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_decision_history_v1"("p_limit" integer DEFAULT 50) RETURNS TABLE("decision_id" "uuid", "created_at" timestamp with time zone, "city" "text", "mood_a_text" "text", "mood_b_text" "text", "spot_id" "uuid", "spot_name" "text", "spot_city" "text", "rank" integer, "why_this" "text", "last_action" "text", "last_action_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with my_sessions as (
    select *
    from public.decision_sessions
    where user_id = auth.uid()
    order by created_at desc
    limit greatest(1, least(p_limit, 200))
  ),
  im as (
    select di.*
    from public.decision_impressions di
    join my_sessions ds on ds.id = di.decision_id
  ),
  last_act as (
    select
      da.decision_id,
      da.spot_id,
      (array_agg(da.action order by da.created_at desc))[1] as last_action,
      (max(da.created_at)) as last_action_at
    from public.decision_actions da
    join my_sessions ds on ds.id = da.decision_id
    group by da.decision_id, da.spot_id
  )
  select
    ds.id as decision_id,
    ds.created_at,
    ds.city,
    ds.mood_a_text,
    ds.mood_b_text,
    im.spot_id,
    sp.name as spot_name,
    sp.city as spot_city,
    im.rank,
    im.why_this,
    la.last_action,
    la.last_action_at
  from my_sessions ds
  join im on im.decision_id = ds.id
  join public.spots sp on sp.id = im.spot_id
  left join last_act la on la.decision_id = ds.id and la.spot_id = im.spot_id
  order by ds.created_at desc, im.rank asc;
$$;

ALTER FUNCTION "public"."get_decision_history_v1"("p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_decision_spots"("p_city" "text", "p_user_id" "uuid", "p_limit" integer DEFAULT 3) RETURNS TABLE("id" "uuid", "name" "text", "city" "text", "why_this" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with base as (
    select
      s.id,
      s.name,
      s.city,
      s.created_at
    from public.spots s
    where s.status = 'approved'
      and s.city is not null
      and lower(s.city) = lower(trim(p_city))
    order by s.created_at desc
    limit greatest(1, least(p_limit, 3))
  ),
  moods as (
    select
      sma.spot_id,
      array_agg(mt.token order by sma.mood_count desc) as tokens
    from public.spot_moods_agg sma
    join public.mood_tokens mt on mt.id = sma.mood_id
    where sma.spot_id in (select id from base)
    group by sma.spot_id
  )
  select
    b.id,
    b.name,
    b.city,
    case
      when m.tokens is not null and array_length(m.tokens, 1) >= 2
        then 'Viele Reviews sagen: ' || m.tokens[1] || ' + ' || m.tokens[2] || '.'
      when m.tokens is not null and array_length(m.tokens, 1) = 1
        then 'Viele Reviews sagen: ' || m.tokens[1] || '.'
      else
        'Passt gut in deine Stadt — und ist approved.'
    end as why_this
  from base b
  left join moods m on m.spot_id = b.id;
$$;

ALTER FUNCTION "public"."get_decision_spots"("p_city" "text", "p_user_id" "uuid", "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_decision_spots_v2"("p_city" "text", "p_user_id" "uuid", "p_limit" integer DEFAULT 3, "p_mood_a_id" integer DEFAULT NULL::integer, "p_mood_b_id" integer DEFAULT NULL::integer) RETURNS TABLE("id" "uuid", "name" "text", "city" "text", "why_this" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with base as (
    select s.id, s.name, s.city, s.created_at
    from public.spots s
    where s.status = 'approved'
      and s.city is not null
      and lower(s.city) = lower(trim(p_city))
  ),
  selected_moods as (
    select unnest(array_remove(array[p_mood_a_id, p_mood_b_id], null))::int as mood_id
  ),
  matched as (
    select
      b.id as spot_id,
      array_remove(array_agg(mt.token order by sma.mood_count desc), null) as matched_tokens,
      count(*) filter (where sma.mood_id is not null) as match_count,
      coalesce(sum(sma.mood_count), 0) as score
    from base b
    left join selected_moods sm on true
    left join public.spot_moods_agg sma
      on sma.spot_id = b.id
     and sma.mood_id = sm.mood_id
    left join public.mood_tokens mt on mt.id = sma.mood_id
    group by b.id
  ),
  candidates as (
    select b.*, m.score, m.match_count, m.matched_tokens
    from base b
    join matched m on m.spot_id = b.id
  ),
  has_full as (
    select exists (select 1 from candidates where match_count >= 2) as any_full
  ),
  ranked as (
    select c.*
    from candidates c, has_full hf
    where
      -- If we have at least one 2/2 match, only consider 2/2 matches.
      (hf.any_full = false)
      or (hf.any_full = true and c.match_count >= 2)
    order by
      c.match_count desc,
      c.score desc,
      c.created_at desc
    limit greatest(1, least(p_limit, 3))
  ),
  top_moods as (
    select
      sma.spot_id,
      array_agg(mt.token order by sma.mood_count desc) as tokens
    from public.spot_moods_agg sma
    join public.mood_tokens mt on mt.id = sma.mood_id
    where sma.spot_id in (select id from ranked)
      and coalesce(mt.valid, true) = true
    group by sma.spot_id
  )
  select
    r.id,
    r.name,
    r.city,
    case
      when p_mood_a_id is not null and p_mood_b_id is not null and r.match_count >= 2 then
        'Matcht deine Moods: ' || r.matched_tokens[1] || ' + ' || r.matched_tokens[2] || '.'
      when p_mood_a_id is not null and p_mood_b_id is not null and r.match_count = 1 then
        'Matcht einen deiner Moods: ' || r.matched_tokens[1] || '.'
      when tm.tokens is not null and array_length(tm.tokens, 1) >= 2 then
        'Viele Reviews sagen: ' || tm.tokens[1] || ' + ' || tm.tokens[2] || '.'
      when tm.tokens is not null and array_length(tm.tokens, 1) = 1 then
        'Viele Reviews sagen: ' || tm.tokens[1] || '.'
      else
        'Passt gut in deine Stadt — und ist approved.'
    end as why_this
  from ranked r
  left join top_moods tm on tm.spot_id = r.id;
$$;

ALTER FUNCTION "public"."get_decision_spots_v2"("p_city" "text", "p_user_id" "uuid", "p_limit" integer, "p_mood_a_id" integer, "p_mood_b_id" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_decision_spots_v2"("p_city" "text", "p_user_id" "uuid", "p_limit" integer DEFAULT 3, "p_mood_a_id" integer DEFAULT NULL::integer, "p_mood_b_id" integer DEFAULT NULL::integer, "p_seen_spot_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS TABLE("id" "uuid", "name" "text", "city" "text", "why_this" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with selected_moods as (
    select distinct unnest(array_remove(array[p_mood_a_id, p_mood_b_id], null))::int as mood_id
  ),

  base_all as (
    select s.id, s.name, s.city, s.created_at
    from public.spots s
    where s.status = 'approved'
      and s.city is not null
      and lower(s.city) = lower(trim(p_city))
  ),

  base_unseen as (
    select *
    from base_all
    where
      p_seen_spot_ids is null
      or array_length(p_seen_spot_ids, 1) is null
      or not (id = any(p_seen_spot_ids))
  ),

  matched_unseen as (
    select
      b.id as spot_id,
      array_remove(array_agg(mt.token order by sma.mood_count desc), null) as matched_tokens,
      count(*) filter (where sma.mood_id is not null) as match_count,
      coalesce(sum(sma.mood_count), 0) as score,
      b.created_at
    from base_unseen b
    left join selected_moods sm on true
    left join public.spot_moods_agg sma
      on sma.spot_id = b.id
     and sma.mood_id = sm.mood_id
    left join public.mood_tokens mt on mt.id = sma.mood_id
    group by b.id, b.created_at
  ),

  unseen_has_full as (
    select exists (select 1 from matched_unseen where match_count >= 2) as any_full
  ),
  unseen_has_partial as (
    select exists (select 1 from matched_unseen where match_count = 1) as any_partial
  ),

  -- ✅ Decision: Wenn unseen keine Matches hat, relaxen wir Anti-repeat und nehmen base_all
  use_all as (
    select
      (case
        when (select any_full from unseen_has_full) = true then false
        when (select any_partial from unseen_has_partial) = true then false
        else true
      end) as yes
  ),

  base as (
    select * from base_all where (select yes from use_all) = true
    union all
    select * from base_unseen where (select yes from use_all) = false
  ),

  matched as (
    select
      b.id as spot_id,
      b.name,
      b.city,
      b.created_at,
      array_remove(array_agg(mt.token order by sma.mood_count desc), null) as matched_tokens,
      count(*) filter (where sma.mood_id is not null) as match_count,
      coalesce(sum(sma.mood_count), 0) as score
    from base b
    left join selected_moods sm on true
    left join public.spot_moods_agg sma
      on sma.spot_id = b.id
     and sma.mood_id = sm.mood_id
    left join public.mood_tokens mt on mt.id = sma.mood_id
    group by b.id, b.name, b.city, b.created_at
  ),

  has_full as (
    select exists (select 1 from matched where match_count >= 2) as any_full
  ),
  has_partial as (
    select exists (select 1 from matched where match_count = 1) as any_partial
  ),

  ranked as (
    select *
    from matched m, has_full hf, has_partial hp
    where
      (hf.any_full = true and m.match_count >= 2)
      or (hf.any_full = false and hp.any_partial = true and m.match_count = 1)
      or (hf.any_full = false and hp.any_partial = false)
    order by
      m.match_count desc,
      m.score desc,
      m.created_at desc
    limit greatest(1, least(p_limit, 3))
  ),

  top_moods as (
    select
      sma.spot_id,
      array_agg(mt.token order by sma.mood_count desc) as tokens
    from public.spot_moods_agg sma
    join public.mood_tokens mt on mt.id = sma.mood_id
    where sma.spot_id in (select spot_id from ranked)
      and coalesce(mt.valid, true) = true
    group by sma.spot_id
  )

  select
    r.spot_id as id,
    r.name,
    r.city,
    case
      when p_mood_a_id is not null and p_mood_b_id is not null and r.match_count >= 2 then
        'Matcht deine Moods: ' || r.matched_tokens[1] || ' + ' || r.matched_tokens[2] || '.'
      when p_mood_a_id is not null and p_mood_b_id is not null and r.match_count = 1 then
        'Matcht einen deiner Moods: ' || r.matched_tokens[1] || '.'
      when tm.tokens is not null and array_length(tm.tokens, 1) >= 2 then
        'Viele Reviews sagen: ' || tm.tokens[1] || ' + ' || tm.tokens[2] || '.'
      when tm.tokens is not null and array_length(tm.tokens, 1) = 1 then
        'Viele Reviews sagen: ' || tm.tokens[1] || '.'
      else
        'Passt gut in deine Stadt — und ist approved.'
    end as why_this
  from ranked r
  left join top_moods tm on tm.spot_id = r.spot_id;
$$;

ALTER FUNCTION "public"."get_decision_spots_v2"("p_city" "text", "p_user_id" "uuid", "p_limit" integer, "p_mood_a_id" integer, "p_mood_b_id" integer, "p_seen_spot_ids" "uuid"[]) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_decision_spots_v3"("p_city" "text", "p_user_id" "uuid", "p_limit" integer DEFAULT 3, "p_mood_a_text" "text" DEFAULT NULL::"text", "p_mood_b_text" "text" DEFAULT NULL::"text", "p_seen_spot_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS TABLE("id" "uuid", "name" "text", "city" "text", "why_this" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with base as (
    select s.id, s.name, s.city, s.created_at
    from public.spots s
    where s.status = 'approved'
      and s.city is not null
      and lower(s.city) = lower(trim(p_city))
      and (
        p_seen_spot_ids is null
        or array_length(p_seen_spot_ids, 1) is null
        or not (s.id = any(p_seen_spot_ids))
      )
  ),

  a as (
    select * from public.resolve_mood_input(p_mood_a_text)
  ),
  b as (
    select * from public.resolve_mood_input(p_mood_b_text)
  ),

  -- Tokens, die wir matchen wollen (exact/synonym)
  token_targets as (
    select token_id as mood_id, 'a'::text as which
    from a where token_id is not null
    union all
    select token_id, 'b' from b where token_id is not null
  ),

  -- Cluster targets: expand cluster -> token ids (alle tokens im cluster)
  cluster_targets as (
    select mtc.token_id as mood_id, 'a'::text as which
    from a
    join public.mood_token_clusters mtc on mtc.cluster_id = a.cluster_id
    where a.cluster_id is not null
    union all
    select mtc.token_id, 'b'
    from b
    join public.mood_token_clusters mtc on mtc.cluster_id = b.cluster_id
    where b.cluster_id is not null
  ),

  targets as (
    select * from token_targets
    union
    select * from cluster_targets
  ),

  matched as (
    select
      b0.id as spot_id,
      count(distinct t.which) as match_count,              -- 0,1,2 (A/B)
      coalesce(sum(sma.mood_count),0) as score,
      array_remove(array_agg(distinct mt.token), null) as matched_tokens
    from base b0
    left join targets t on true
    left join public.spot_moods_agg sma
      on sma.spot_id = b0.id
     and sma.mood_id = t.mood_id
    left join public.mood_tokens mt on mt.id = sma.mood_id
    group by b0.id
  ),

  candidates as (
    select b.*, m.match_count, m.score, m.matched_tokens
    from base b
    join matched m on m.spot_id = b.id
  ),

  has_full as (select exists(select 1 from candidates where match_count=2) as any_full),
  has_partial as (select exists(select 1 from candidates where match_count=1) as any_partial),

  ranked as (
    select c.*
    from candidates c, has_full hf, has_partial hp
    where
      (hf.any_full and c.match_count=2)
      or (not hf.any_full and hp.any_partial and c.match_count=1)
      or (not hf.any_full and not hp.any_partial)
    order by c.match_count desc, c.score desc, c.created_at desc
    limit greatest(1, least(p_limit, 3))
  )

  select
    r.id,
    r.name,
    r.city,
    case
      when r.match_count = 2 then
        'Matcht beide Moods.'
      when r.match_count = 1 then
        'Matcht einen deiner Moods.'
      else
        'Noch keine Spots mit deinen Moods — hier sind approved Optionen.'
    end as why_this
  from ranked r;
$$;

ALTER FUNCTION "public"."get_decision_spots_v3"("p_city" "text", "p_user_id" "uuid", "p_limit" integer, "p_mood_a_text" "text", "p_mood_b_text" "text", "p_seen_spot_ids" "uuid"[]) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_decision_spots_v4"("p_city" "text", "p_user_id" "uuid", "p_limit" integer DEFAULT 3, "p_mood_a_text" "text" DEFAULT NULL::"text", "p_mood_b_text" "text" DEFAULT NULL::"text", "p_seen_spot_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_min_cluster_confidence" numeric DEFAULT 0.65) RETURNS TABLE("id" "uuid", "name" "text", "city" "text", "why_this" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with
  ra as (select * from public.resolve_mood_input_v2(p_mood_a_text)),
  rb as (select * from public.resolve_mood_input_v2(p_mood_b_text)),

  ta as (
    select mood_id from public.expand_resolved_targets(
      (select resolved_via from ra),
      (select resolved_token_id from ra),
      (select cluster_id from ra),
      p_min_cluster_confidence
    )
  ),
  tb as (
    select mood_id from public.expand_resolved_targets(
      (select resolved_via from rb),
      (select resolved_token_id from rb),
      (select cluster_id from rb),
      p_min_cluster_confidence
    )
  ),

  selected as (
    select distinct mood_id from ta
    union
    select distinct mood_id from tb
  ),

  base_all as (
    select s.id, s.name, s.city, s.created_at
    from public.spots s
    where s.status = 'approved'
      and s.city is not null
      and lower(s.city) = lower(trim(p_city))
  ),
  base_unseen as (
    select *
    from base_all
    where p_seen_spot_ids is null
      or array_length(p_seen_spot_ids, 1) is null
      or not (id = any(p_seen_spot_ids))
  ),

  -- IMPORTANT: match_count must count REAL matches (= sma rows), not selected targets
  matched_unseen as (
    with per_token as (
      select
        b0.id as spot_id,
        sma.mood_id,
        mt.token,
        max(sma.mood_count) as token_count
      from base_unseen b0
      left join selected sel on true
      left join public.spot_moods_agg sma
        on sma.spot_id = b0.id
      and sma.mood_id = sel.mood_id
      left join public.mood_tokens mt on mt.id = sma.mood_id
      where sma.mood_id is not null
      group by b0.id, sma.mood_id, mt.token
    )
    select
      b0.id as spot_id,
      count(distinct pt.mood_id) as match_count,
      coalesce(sum(pt.token_count), 0) as score,
      coalesce(
        array_agg(pt.token order by pt.token_count desc) filter (where pt.token is not null),
        '{}'::text[]
      ) as matched_tokens,
      b0.created_at
    from base_unseen b0
    left join per_token pt on pt.spot_id = b0.id
    group by b0.id, b0.created_at
  ),
  unseen_has_any_match as (
    select exists (select 1 from matched_unseen where match_count > 0) as yes
  ),
  use_all as (
    select not (select yes from unseen_has_any_match) as yes
  ),

  base as (
    select * from base_all where (select yes from use_all) = true
    union all
    select * from base_unseen where (select yes from use_all) = false
  ),

  matched as (
    with per_token as (
      select
        b0.id as spot_id,
        sma.mood_id,
        mt.token,
        max(sma.mood_count) as token_count
      from base b0
      left join selected sel on true
      left join public.spot_moods_agg sma
        on sma.spot_id = b0.id
      and sma.mood_id = sel.mood_id
      left join public.mood_tokens mt on mt.id = sma.mood_id
      where sma.mood_id is not null
      group by b0.id, sma.mood_id, mt.token
    )
    select
      b0.id as spot_id,
      b0.name,
      b0.city,
      b0.created_at,
      count(distinct pt.mood_id) as match_count,
      coalesce(sum(pt.token_count), 0) as score,
      coalesce(
        array_agg(pt.token order by pt.token_count desc) filter (where pt.token is not null),
        '{}'::text[]
      ) as matched_tokens
    from base b0
    left join per_token pt on pt.spot_id = b0.id
    group by b0.id, b0.name, b0.city, b0.created_at
  ),

  has_full as (select exists(select 1 from matched where match_count >= 2) as any_full),
  has_partial as (select exists(select 1 from matched where match_count = 1) as any_partial),

  ranked as (
    select m.*
    from matched m, has_full hf, has_partial hp
    where
      (hf.any_full and m.match_count >= 2)
      or (not hf.any_full and hp.any_partial and m.match_count = 1)
      or (not hf.any_full and not hp.any_partial)
    order by m.match_count desc, m.score desc, m.created_at desc
    limit greatest(1, least(p_limit, 3))
  )

  select
    r.spot_id as id,
    r.name,
    r.city,

    -- NULL-SAFE why_this (never returns null)
    (
      case
        when (select resolved_via from ra) = 'none'
          or (select resolved_via from rb) = 'none' then
          'Deine Moods sind neu — ich lerne sie gerade.'

        when r.match_count >= 2 then
          'Matcht deine Moods: ' ||
          coalesce(r.matched_tokens[1], '…') || ' + ' ||
          coalesce(r.matched_tokens[2], '…') || '.'

        when r.match_count = 1 then
          'Matcht einen deiner Moods: ' || coalesce(r.matched_tokens[1], '…') || '.'

        else
          'Ich habe deine Moods verstanden — aber dafür gibt es noch keine Reviews. Hier sind gute Optionen in deiner Stadt.'
      end
    )
    ||
    coalesce(
      case
        when (select resolved_via from ra) = 'synonym' then
          ' (Mood A via Synonym → ' || (select resolved_label from ra) || ')'
        when (select resolved_via from ra) = 'cluster' then
          ' (Mood A via Cluster → ' || (select resolved_label from ra) || ')'
        else ''
      end,
      ''
    )
    ||
    coalesce(
      case
        when (select resolved_via from rb) = 'synonym' then
          ' (Mood B via Synonym → ' || (select resolved_label from rb) || ')'
        when (select resolved_via from rb) = 'cluster' then
          ' (Mood B via Cluster → ' || (select resolved_label from rb) || ')'
        else ''
      end,
      ''
    )
    as why_this
  from ranked r;
$$;

ALTER FUNCTION "public"."get_decision_spots_v4"("p_city" "text", "p_user_id" "uuid", "p_limit" integer, "p_mood_a_text" "text", "p_mood_b_text" "text", "p_seen_spot_ids" "uuid"[], "p_min_cluster_confidence" numeric) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_decision_spots_v5"("p_city" "text", "p_user_id" "uuid", "p_limit" integer DEFAULT 3, "p_mood_a_text" "text" DEFAULT NULL::"text", "p_mood_b_text" "text" DEFAULT NULL::"text", "p_seen_spot_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_min_cluster_confidence" numeric DEFAULT 0.65) RETURNS TABLE("id" "uuid", "name" "text", "city" "text", "why_this" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with
  ra as (select * from public.resolve_mood_input_v2(p_mood_a_text)),
  rb as (select * from public.resolve_mood_input_v2(p_mood_b_text)),

  ta as (
    select mood_id from public.expand_resolved_targets(
      (select resolved_via from ra),
      (select resolved_token_id from ra),
      (select cluster_id from ra),
      p_min_cluster_confidence
    )
  ),
  tb as (
    select mood_id from public.expand_resolved_targets(
      (select resolved_via from rb),
      (select resolved_token_id from rb),
      (select cluster_id from rb),
      p_min_cluster_confidence
    )
  ),
  selected as (
    select distinct mood_id from ta
    union
    select distinct mood_id from tb
  ),

  base_all as (
    select s.id, s.name, s.city, s.created_at, s.category_id, s.price_level
    from public.spots s
    where s.status = 'approved'
      and s.city is not null
      and lower(s.city) = lower(trim(p_city))
  ),
  base_unseen as (
    select *
    from base_all
    where p_seen_spot_ids is null
      or array_length(p_seen_spot_ids, 1) is null
      or not (id = any(p_seen_spot_ids))
  ),

  matched_unseen as (
    with per_token as (
      select
        b0.id as spot_id,
        sma.mood_id,
        mt.token,
        max(sma.mood_count) as token_count
      from base_unseen b0
      left join selected sel on true
      left join public.spot_moods_agg sma
        on sma.spot_id = b0.id
       and sma.mood_id = sel.mood_id
      left join public.mood_tokens mt on mt.id = sma.mood_id
      where sma.mood_id is not null
      group by b0.id, sma.mood_id, mt.token
    )
    select
      b0.id as spot_id,
      count(distinct pt.mood_id) as match_count,
      coalesce(sum(pt.token_count), 0) as score,
      coalesce(
        array_agg(pt.token order by pt.token_count desc)
          filter (where pt.token is not null),
        '{}'::text[]
      ) as matched_tokens,
      b0.created_at,
      b0.category_id,
      b0.price_level
    from base_unseen b0
    left join per_token pt on pt.spot_id = b0.id
    group by b0.id, b0.created_at, b0.category_id, b0.price_level
  ),
  unseen_has_any_match as (
    select exists (select 1 from matched_unseen where match_count > 0) as yes
  ),
  use_all as (
    select not (select yes from unseen_has_any_match) as yes
  ),

  base as (
    select * from base_all where (select yes from use_all) = true
    union all
    select * from base_unseen where (select yes from use_all) = false
  ),

  matched as (
    with per_token as (
      select
        b0.id as spot_id,
        sma.mood_id,
        mt.token,
        max(sma.mood_count) as token_count
      from base b0
      left join selected sel on true
      left join public.spot_moods_agg sma
        on sma.spot_id = b0.id
       and sma.mood_id = sel.mood_id
      left join public.mood_tokens mt on mt.id = sma.mood_id
      where sma.mood_id is not null
      group by b0.id, sma.mood_id, mt.token
    )
    select
      b0.id as spot_id,
      b0.name,
      b0.city,
      b0.created_at,
      b0.category_id,
      b0.price_level,
      count(distinct pt.mood_id) as match_count,
      coalesce(sum(pt.token_count), 0) as score,
      coalesce(
        array_agg(pt.token order by pt.token_count desc)
          filter (where pt.token is not null),
        '{}'::text[]
      ) as matched_tokens
    from base b0
    left join per_token pt on pt.spot_id = b0.id
    group by b0.id, b0.name, b0.city, b0.created_at, b0.category_id, b0.price_level
  ),

  has_full as (select exists(select 1 from matched where match_count >= 2) as any_full),
  has_partial as (select exists(select 1 from matched where match_count = 1) as any_partial),

  ranked_mood as (
    select m.*
    from matched m, has_full hf, has_partial hp
    where
      (hf.any_full and m.match_count >= 2)
      or (not hf.any_full and hp.any_partial and m.match_count = 1)
      or (not hf.any_full and not hp.any_partial)
    order by m.match_count desc, m.score desc, m.created_at desc
    limit greatest(1, least(p_limit, 3))
  ),

  mood_result as (
    select
      r.spot_id as id,
      r.name,
      r.city,
      (
        case
          when r.match_count >= 2 then
            'Matcht deine Moods: ' ||
            coalesce(r.matched_tokens[1], '…') || ' + ' || coalesce(r.matched_tokens[2], '…') || '.'
          when r.match_count = 1 then
            'Matcht einen deiner Moods: ' || coalesce(r.matched_tokens[1], '…') || '.'
          else
            'Ich habe noch keine passenden Review-Signale – aber hier sind starke Optionen in deiner Stadt.'
        end
      )
      ||
      coalesce(
        case
          when (select resolved_via from ra) = 'synonym' then ' (Mood A via Synonym → ' || (select resolved_label from ra) || ')'
          when (select resolved_via from ra) = 'cluster' then ' (Mood A via Cluster → ' || (select resolved_label from ra) || ')'
          else ''
        end, ''
      )
      ||
      coalesce(
        case
          when (select resolved_via from rb) = 'synonym' then ' (Mood B via Synonym → ' || (select resolved_label from rb) || ')'
          when (select resolved_via from rb) = 'cluster' then ' (Mood B via Cluster → ' || (select resolved_label from rb) || ')'
          else ''
        end, ''
      )
      as why_this,
      r.match_count as match_count
    from ranked_mood r
  ),

  need_semantic as (
    select
      (
        (select resolved_via from ra) = 'none'
        or (select resolved_via from rb) = 'none'
        or not exists (select 1 from mood_result where match_count > 0)
      ) as yes
  ),

  semantic_query as (
    select trim(coalesce(p_mood_a_text,'') || ' ' || coalesce(p_mood_b_text,'')) as q
  ),

  -- ✅ IMPORTANT: Only add semantic results when we actually need semantic.
  -- ✅ Also: Avoid duplicates if mood_result already returned the spot.
  semantic as (
    select
      s.spot_id as id,
      sp.name,
      sp.city,
      s.why_semantic as why_this
    from need_semantic ns
    join semantic_query sq on true
    join public.match_spots_semantic_v1(p_city, sq.q, p_limit, p_seen_spot_ids) s
      on ns.yes = true
    join public.spots sp on sp.id = s.spot_id
    where not exists (
      select 1 from mood_result mr where mr.id = s.spot_id
    )
  )

  select id, name, city, why_this from mood_result
  union all
  select id, name, city, why_this from semantic
  limit greatest(1, least(p_limit, 3));
$$;

ALTER FUNCTION "public"."get_decision_spots_v5"("p_city" "text", "p_user_id" "uuid", "p_limit" integer, "p_mood_a_text" "text", "p_mood_b_text" "text", "p_seen_spot_ids" "uuid"[], "p_min_cluster_confidence" numeric) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_decision_spots_v6"("p_city" "text", "p_user_id" "uuid", "p_limit" integer DEFAULT 3, "p_mood_a_text" "text" DEFAULT NULL::"text", "p_mood_b_text" "text" DEFAULT NULL::"text", "p_seen_spot_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_min_cluster_confidence" numeric DEFAULT 0.65) RETURNS TABLE("id" "uuid", "name" "text", "city" "text", "result_type" "text", "confidence" numeric, "evidence_tokens" "text"[], "evidence_clusters" "text"[], "why_this" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
with
ra as (select * from public.resolve_mood_input_v2(p_mood_a_text)),
rb as (select * from public.resolve_mood_input_v2(p_mood_b_text)),

ta as (
  select mood_id from public.expand_resolved_targets(
    (select resolved_via from ra),
    (select resolved_token_id from ra),
    (select cluster_id from ra),
    p_min_cluster_confidence
  )
),
tb as (
  select mood_id from public.expand_resolved_targets(
    (select resolved_via from rb),
    (select resolved_token_id from rb),
    (select cluster_id from rb),
    p_min_cluster_confidence
  )
),

selected as (
  select distinct mood_id from ta
  union
  select distinct mood_id from tb
),

base_all as (
  select s.id, s.name, s.city, s.created_at
  from public.spots s
  where s.status = 'approved'
    and s.city is not null
    and lower(s.city) = lower(trim(p_city))
),

base_unseen as (
  select *
  from base_all
  where p_seen_spot_ids is null
     or array_length(p_seen_spot_ids, 1) is null
     or not (id = any(p_seen_spot_ids))
),

per_match as (
  select
    b.id as spot_id,
    sma.mood_id,
    max(sma.mood_count) as token_count
  from base_unseen b
  join selected sel on true
  join public.spot_moods_agg sma
    on sma.spot_id = b.id
   and sma.mood_id = sel.mood_id
  group by b.id, sma.mood_id
),

matched as (
  select
    b.id,
    b.name,
    b.city,
    b.created_at,
    count(distinct pm.mood_id) as match_count,
    coalesce(sum(pm.token_count), 0) as score
  from base_unseen b
  left join per_match pm on pm.spot_id = b.id
  group by b.id, b.name, b.city, b.created_at
),

has_full as (select exists(select 1 from matched where match_count >= 2) as yes),
has_partial as (select exists(select 1 from matched where match_count = 1) as yes),

ranked as (
  select m.*
  from matched m, has_full hf, has_partial hp
  where
    (hf.yes and m.match_count >= 2)
    or (not hf.yes and hp.yes and m.match_count = 1)
    or (not hf.yes and not hp.yes)
  order by m.match_count desc, m.score desc, m.created_at desc
  limit greatest(1, least(p_limit, 3))
),

evidence as (
  select
    r.id as spot_id,
    coalesce((
      select array_agg(t.token order by x.mood_count desc)
      from (
        select sma.mood_id, sma.mood_count
        from public.spot_moods_agg sma
        where sma.spot_id = r.id
        order by sma.mood_count desc
        limit 3
      ) x
      join public.mood_tokens t on t.id = x.mood_id
    ), '{}'::text[]) as evidence_tokens,

    coalesce((
      select array_agg(distinct c.name_norm)
      from public.spot_moods_agg sma
      join public.mood_token_clusters tc on tc.token_id = sma.mood_id
      join public.mood_clusters c on c.id = tc.cluster_id
      where sma.spot_id = r.id
        and tc.confidence >= p_min_cluster_confidence
    ), '{}'::text[]) as evidence_clusters
  from ranked r
)

select
  r.id,
  r.name,
  r.city,

  case
    when r.match_count >= 2 then 'full_match'
    when r.match_count = 1 then 'partial_match'
    else 'fallback'
  end as result_type,

  case
    when r.match_count >= 2 then least(1, 0.65 + (r.score::numeric / 60))
    when r.match_count = 1 then least(0.6, 0.35 + (r.score::numeric / 60))
    else 0.2
  end as confidence,

  e.evidence_tokens,
  e.evidence_clusters,

  -- honest baseline why_this (client may overwrite for fallback with AI reasons)
  (
    case
      when r.match_count >= 2 then
        'Passt zu beiden deiner Moods (basierend auf Reviews).'
      when r.match_count = 1 then
        'Passt zu einem deiner Moods (basierend auf Reviews).'
      else
        'Kein direkter Mood-Match – ich zeige dir plausible Spots in deiner Stadt (basierend auf Reviews).'
    end
  )
  ||
  case
    when (select resolved_via from ra) in ('synonym','cluster') then
      ' (Mood A via ' ||
      case when (select resolved_via from ra) = 'synonym' then 'Synonym' else 'Cluster' end ||
      ' → ' || coalesce((select resolved_label from ra), '…') || ')'
    else ''
  end
  ||
  case
    when (select resolved_via from rb) in ('synonym','cluster') then
      ' (Mood B via ' ||
      case when (select resolved_via from rb) = 'synonym' then 'Synonym' else 'Cluster' end ||
      ' → ' || coalesce((select resolved_label from rb), '…') || ')'
    else ''
  end
  as why_this

from ranked r
join evidence e on e.spot_id = r.id;

$$;

ALTER FUNCTION "public"."get_decision_spots_v6"("p_city" "text", "p_user_id" "uuid", "p_limit" integer, "p_mood_a_text" "text", "p_mood_b_text" "text", "p_seen_spot_ids" "uuid"[], "p_min_cluster_confidence" numeric) OWNER TO "postgres";

