  from base_unseen b
  left join per_match pm on pm.spot_id = b.id
  group by b.id, b.name, b.city, b.category_id, b.price_level, b.created_at
),

has_full as (select exists(select 1 from matched where match_count >= 2) as yes),
has_partial as (select exists(select 1 from matched where match_count = 1) as yes),

ranked as (
  select m.*
  from matched m, has_full hf, has_partial hp
  where
    (hf.yes and m.match_count >= 2)
    or (not hf.yes and hp.yes and m.match_count = 1)
    or (not hf.yes and not hp.yes)
  order by m.match_count desc, m.score desc, m.created_at desc
  limit greatest(1, least(p_limit, 3))
),

cat as (
  select id, name
  from public.categories
),

evidence as (
  select
    r.id as spot_id,

    coalesce((
      select array_agg(t.token order by x.mood_count desc)
      from (
        select sma.mood_id, sma.mood_count
        from public.spot_moods_agg sma
        where sma.spot_id = r.id
        order by sma.mood_count desc
        limit 4
      ) x
      join public.mood_tokens t on t.id = x.mood_id
    ), '{}'::text[]) as evidence_tokens,

    coalesce((
      select array_agg(distinct c.name_norm order by c.name_norm)
      from public.spot_moods_agg sma
      join public.mood_token_clusters tc on tc.token_id = sma.mood_id
      join public.mood_clusters c on c.id = tc.cluster_id
      where sma.spot_id = r.id
        and tc.confidence >= p_min_cluster_confidence
    ), '{}'::text[]) as evidence_clusters
  from ranked r
)

select
  r.id,
  r.name,
  r.city,
  c.name as category_name,
  r.price_level,

  case
    when r.match_count >= 2 then 'full_match'
    when r.match_count = 1 then 'partial_match'
    else 'fallback'
  end as result_type,

  case
    when r.match_count >= 2 then least(1, 0.65 + (r.score::numeric / 60))
    when r.match_count = 1 then least(0.6, 0.35 + (r.score::numeric / 60))
    else 0.2
  end as confidence,

  e.evidence_tokens,
  e.evidence_clusters,

  -- baseline why (client/edge will overwrite for fallback)
  (
    case
      when r.match_count >= 2 then
        'Passt zu beiden deiner Moods (basierend auf Reviews).'
      when r.match_count = 1 then
        'Passt zu einem deiner Moods (basierend auf Reviews).'
      else
        'Kein direkter Mood-Match – ich entscheide mit den vorhandenen Vibes dieses Spots (aus Reviews).'
    end
  )
  ||
  case
    when (select resolved_via from ra) in ('synonym','cluster') then
      ' (Mood A via ' ||
      case when (select resolved_via from ra) = 'synonym' then 'Synonym' else 'Cluster' end ||
      ' → ' || coalesce((select resolved_label from ra), '…') || ')'
    else ''
  end
  ||
  case
    when (select resolved_via from rb) in ('synonym','cluster') then
      ' (Mood B via ' ||
      case when (select resolved_via from rb) = 'synonym' then 'Synonym' else 'Cluster' end ||
      ' → ' || coalesce((select resolved_label from rb), '…') || ')'
    else ''
  end
  as why_this

from ranked r
left join cat c on c.id = r.category_id
join evidence e on e.spot_id = r.id;

$$;

ALTER FUNCTION "public"."get_decision_spots_v7"("p_city" "text", "p_user_id" "uuid", "p_limit" integer, "p_mood_a_text" "text", "p_mood_b_text" "text", "p_seen_spot_ids" "uuid"[], "p_min_cluster_confidence" numeric) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_decision_spots_v8"("p_city" "text", "p_user_id" "uuid", "p_limit" integer DEFAULT 3, "p_mood_a_text" "text" DEFAULT NULL::"text", "p_mood_b_text" "text" DEFAULT NULL::"text", "p_seen_spot_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_min_cluster_confidence" numeric DEFAULT 0.65, "p_min_token_count" integer DEFAULT 2, "p_open_now_epsilon" numeric DEFAULT 0.12) RETURNS TABLE("id" "uuid", "name" "text", "city" "text", "why_this" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
with
ra as (select * from public.resolve_mood_input_v2(p_mood_a_text)),
rb as (select * from public.resolve_mood_input_v2(p_mood_b_text)),

ta as (
  select mood_id from public.expand_resolved_targets(
    (select resolved_via from ra),
    (select resolved_token_id from ra),
    (select cluster_id from ra),
    p_min_cluster_confidence
  )
),
tb as (
  select mood_id from public.expand_resolved_targets(
    (select resolved_via from rb),
    (select resolved_token_id from rb),
    (select cluster_id from rb),
    p_min_cluster_confidence
  )
),

selected as (
  select distinct mood_id from ta
  union
  select distinct mood_id from tb
),

base_all as (
  select s.id, s.name, s.city, s.created_at
  from public.spots s
  where s.status = 'approved'
    and s.city is not null
    and lower(s.city) = lower(trim(p_city))
),

base_unseen as (
  select *
  from base_all
  where p_seen_spot_ids is null
     or array_length(p_seen_spot_ids, 1) is null
     or not (id = any(p_seen_spot_ids))
),

terms_raw as (
  select trim(
    coalesce(p_mood_a_text,'') || ' ' ||
    coalesce(p_mood_b_text,'') || ' ' ||
    coalesce((select resolved_label from ra),'') || ' ' ||
    coalesce((select resolved_label from rb),'')
  ) as q
),
terms as (
  select array(
    select distinct t
    from unnest(
      regexp_split_to_array(
        lower(regexp_replace((select q from terms_raw), '\s+', ' ', 'g')),
        ' '
      )
    ) as t
    where t is not null
      and length(t) >= 3
      and t not in ('und','oder','der','die','das','mit','für','auf','im','in','am','an','zu','ein','eine')
    limit 12
  ) as arr
),

spot_text as (
  select
    b.id as spot_id,
    coalesce(nullif(sd.owner_description, ''), nullif(sd.enriched_description, '')) as effective_description,
    coalesce(sd.owner_keywords, sd.enriched_keywords, '{}'::text[]) as effective_keywords
  from base_all b
  left join public.spot_descriptions sd on sd.spot_id = b.id
),

per_token as (
  select
    sma.spot_id,
    sma.mood_id,
    mt.token,
    sma.mood_count::integer as token_count
  from public.spot_moods_agg_reviews_v1 sma
  join selected sel on sel.mood_id = sma.mood_id
  left join public.mood_tokens mt on mt.id = sma.mood_id
  where sma.spot_id in (select id from base_all)
    and sma.mood_count >= greatest(p_min_token_count, 1)
),

mood_agg as (
  select
    b.id as spot_id,
    count(distinct pt.mood_id) as mood_match_count,
    coalesce(sum(pt.token_count), 0)::integer as mood_strength,
    coalesce(
      array_agg(pt.token order by pt.token_count desc)
        filter (where pt.token is not null),
      '{}'::text[]
    ) as matched_tokens,
    coalesce(
      array_agg(pt.token_count order by pt.token_count desc)
        filter (where pt.token_count is not null),
      '{}'::integer[]
    ) as matched_counts
  from base_all b
  left join per_token pt on pt.spot_id = b.id
  group by b.id
),

text_agg as (
  select
    b.id as spot_id,
    coalesce(
      (
        select sum(
          case
            when t is null or t = '' then 0
            when (
              (st.effective_description is not null and lower(st.effective_description) like ('%' || t || '%'))
              or (st.effective_keywords is not null and exists (
                select 1 from unnest(st.effective_keywords) k
                where lower(k) = t
              ))
            ) then 1
            else 0
          end
        )
        from unnest((select arr from terms)) as t
      ),
      0
    )::integer as text_match_score,
    coalesce(
      array(
        select t
        from unnest((select arr from terms)) as t
        where t is not null
          and t <> ''
          and (
            (st.effective_description is not null and lower(st.effective_description) like ('%' || t || '%'))
            or (st.effective_keywords is not null and exists (
              select 1 from unnest(st.effective_keywords) k
              where lower(k) = t
            ))
          )
      ),
      '{}'::text[]
    ) as matched_terms
  from base_all b
  left join spot_text st on st.spot_id = b.id
),

open_now_agg as (
  select
    b.id as spot_id,
    public.spot_is_open_now_safe_v1(b.id) as is_open_now
  from base_all b
),

scored_all as (
  select
    b.id,
    b.name,
    b.city,
    b.created_at,

    ma.mood_match_count,
    ma.mood_strength,
    ln(1 + greatest(ma.mood_strength, 0))::numeric as mood_strength_norm,

    tx.text_match_score,
    tx.matched_terms,

    onow.is_open_now,

    (
      ln(1 + greatest(ma.mood_strength, 0))::numeric * 1.0
      + (greatest(ma.mood_match_count, 0)::numeric * 0.15)
      + (greatest(tx.text_match_score, 0)::numeric * 0.05)
    ) as final_score,

    ma.matched_tokens,
    ma.matched_counts
  from base_all b
  left join mood_agg ma on ma.spot_id = b.id
  left join text_agg tx on tx.spot_id = b.id
  left join open_now_agg onow on onow.spot_id = b.id
),

unseen_has_signal as (
  select exists(
    select 1
    from scored_all sa
    where sa.id in (select id from base_unseen)
      and (sa.mood_strength > 0 or sa.text_match_score > 0)
  ) as yes
),

base_scored as (
  select sa.*
  from scored_all sa, unseen_has_signal uhs
  where (uhs.yes = true and sa.id in (select id from base_unseen))
     or (uhs.yes = false)
),

max_score as (
  select max(final_score) as top_score from base_scored
),

ranked as (
  select
    b.*,
    case
      when b.is_open_now is true
       and (select top_score from max_score) - b.final_score <= greatest(p_open_now_epsilon, 0)
      then 1 else 0
    end as open_now_near_tie
  from base_scored b
  order by
    b.final_score desc,
    b.mood_strength desc,
    b.text_match_score desc,
    open_now_near_tie desc,
    b.created_at desc
  limit greatest(1, least(p_limit, 3))
),

mood_result as (
  select
    r.id,
    r.name,
    r.city,
    (
      case
        when r.mood_strength > 0 and r.mood_match_count >= 2 then
          'Beide Moods passen, v.a. ' ||
          coalesce(r.matched_tokens[1], '…') || ' (' || coalesce(r.matched_counts[1], 0)::text || '×) und ' ||
          coalesce(r.matched_tokens[2], '…') || ' (' || coalesce(r.matched_counts[2], 0)::text || '×).'
        when r.mood_strength > 0 and r.mood_match_count = 1 then
          'Starkes ' || coalesce(r.matched_tokens[1], '…') || '-Signal (' || coalesce(r.matched_counts[1], 0)::text || '×).'
        when r.mood_strength = 0 and r.text_match_score > 0 then
          'Keine starken Review-Moods, aber Text passt zu: ' ||
          coalesce(array_to_string(r.matched_terms[1:3], ', '), '…') || '.'
        else
          'Gerade häufig gewählt in deiner Stadt.'
      end
    ) as why_this
  from ranked r
),

need_semantic as (
  select
    (
      (select resolved_via from ra) = 'none'
      or (select resolved_via from rb) = 'none'
      or not exists (select 1 from mood_result)
    ) as yes
),

semantic_query as (
  select trim(coalesce(p_mood_a_text,'') || ' ' || coalesce(p_mood_b_text,'')) as q
),

semantic as (
  select
    s.spot_id as id,
    sp.name,
    sp.city,
    s.why_semantic as why_this
  from need_semantic ns
  join semantic_query sq on true
  join public.match_spots_semantic_v1(p_city, sq.q, greatest(1, least(p_limit, 3)), p_seen_spot_ids) s
    on ns.yes = true
  join public.spots sp on sp.id = s.spot_id
  where not exists (
    select 1 from mood_result mr where mr.id = s.spot_id
  )
)

select id, name, city, why_this from mood_result
union all
select id, name, city, why_this from semantic
limit greatest(1, least(p_limit, 3));
$$;

ALTER FUNCTION "public"."get_decision_spots_v8"("p_city" "text", "p_user_id" "uuid", "p_limit" integer, "p_mood_a_text" "text", "p_mood_b_text" "text", "p_seen_spot_ids" "uuid"[], "p_min_cluster_confidence" numeric, "p_min_token_count" integer, "p_open_now_epsilon" numeric) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_decision_visit_candidates_v1"("p_limit" integer DEFAULT 40, "p_window_hours" integer DEFAULT 24) RETURNS TABLE("decision_id" "uuid", "spot_id" "uuid", "spot_name" "text", "spot_city" "text", "category_name" "text", "rank" integer, "last_event_type" "text", "last_event_at" timestamp with time zone, "signal_strength" numeric, "model_version" "text", "input_mode" "text", "raw_free_text" "text", "query_text" "text", "human_reason" "text", "review_id" "uuid", "social_post_id" "uuid", "social_source_type" "text", "decision_review_link_id" "uuid", "match_type" "text", "status" "text", "cta_label" "text", "subtitle" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with event_candidates as (
    select
      e.*,
      s.name as spot_name,
      s.city as spot_city,
      c.name as category_name,
      row_number() over (
        partition by e.user_id, e.spot_id, e.decision_id
        order by
          case e.event_type
            when 'decision_like' then 100
            when 'decision_open' then 80
            when 'decision_impression' then 30
            else 0
          end desc,
          abs(coalesce(e.signal_strength, 0)) desc,
          e.created_at desc
      ) as rn
    from public.backyrd_ml_events_v1 e
    join public.spots s on s.id = e.spot_id
    left join public.categories c on c.id = s.category_id
    where e.user_id = auth.uid()
      and e.spot_id is not null
      and e.created_at >= now() - (greatest(1, coalesce(p_window_hours, 24))::text || ' hours')::interval
      and e.event_type in ('decision_like', 'decision_open', 'decision_impression')
  ),

  strongest as (
    select *
    from event_candidates
    where rn = 1
  ),

  linked as (
    select
      l.*,
      row_number() over (
        partition by l.user_id, l.spot_id, l.decision_id
        order by l.signal_strength desc, l.created_at desc
      ) as rn
    from public.backyrd_decision_review_links_v1 l
    where l.user_id = auth.uid()
  ),

  review_posts as (
    select
      sp.id as social_post_id,
      sp.review_id,
      sp.spot_id,
      sp.source_type,
      sp.created_at,
      row_number() over (
        partition by sp.review_id
        order by sp.created_at desc
      ) as rn
    from public.social_posts sp
    where sp.user_id = auth.uid()
      and sp.review_id is not null
  )

  select
    st.decision_id,
    st.spot_id,
    st.spot_name,
    st.spot_city,
    st.category_name,
    st.rank::integer as rank,
    st.event_type as last_event_type,
    st.created_at as last_event_at,
    coalesce(st.signal_strength, 0)::numeric as signal_strength,
    st.context ->> 'model_version' as model_version,
    coalesce(st.context ->> 'inputMode', st.context ->> 'input_mode') as input_mode,
    coalesce(st.context ->> 'rawFreeText', st.context ->> 'raw_free_text') as raw_free_text,
    coalesce(st.context ->> 'query_text', st.context ->> 'query') as query_text,
    st.context ->> 'human_reason' as human_reason,
    l.review_id,
    rp.social_post_id,
    rp.source_type as social_source_type,
    l.id as decision_review_link_id,
    l.match_type,

    case
      when l.id is not null then 'review_confirmed'
      when st.event_type = 'decision_like' then 'strong_candidate'
      when st.event_type = 'decision_open' then 'opened_candidate'
      else 'soft_candidate'
    end as status,

    case
      when l.id is not null then 'Besuch erkannt'
      when st.event_type = 'decision_like' then 'Kurz bewerten'
      when st.event_type = 'decision_open' then 'Wie war es?'
      else 'Vielleicht besucht?'
    end as cta_label,

    case
      when l.id is not null then 'Aus deiner Decision wurde ein Backyrd Moment.'
      when st.event_type = 'decision_like' then 'Du hast diesen Spot als Treffer markiert.'
      when st.event_type = 'decision_open' then 'Du hast dir diesen Spot genauer angeschaut.'
      else 'Backyrd hat dir diesen Spot vorgeschlagen.'
    end as subtitle

  from strongest st
  left join linked l
    on l.user_id = st.user_id
   and l.spot_id = st.spot_id
   and (
      l.decision_id = st.decision_id
      or l.decision_id is null
      or st.decision_id is null
   )
   and l.rn = 1
  left join review_posts rp
    on rp.review_id = l.review_id
   and rp.rn = 1
  order by
    case
      when l.id is not null then 0
      when st.event_type = 'decision_like' then 1
      when st.event_type = 'decision_open' then 2
      else 3
    end asc,
    st.created_at desc
  limit greatest(1, least(coalesce(p_limit, 40), 100));
$$;

ALTER FUNCTION "public"."get_decision_visit_candidates_v1"("p_limit" integer, "p_window_hours" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_decision_visit_candidates_v1"("p_limit" integer DEFAULT 40, "p_review_window_hours" integer DEFAULT 12, "p_candidate_ttl_hours" integer DEFAULT 72) RETURNS TABLE("decision_id" "uuid", "decision_created_at" timestamp with time zone, "city" "text", "mood_a_text" "text", "mood_b_text" "text", "spot_id" "uuid", "spot_name" "text", "spot_city" "text", "category_name" "text", "rank" integer, "why_this" "text", "last_action" "text", "last_action_at" timestamp with time zone, "review_id" "uuid", "reviewed_at" timestamp with time zone, "status" "text", "prompt_title" "text", "prompt_body" "text", "signal_score" numeric)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with my_sessions as (
    select s.id, s.created_at, s.city, s.mood_a_text, s.mood_b_text
    from public.decision_sessions s
    where s.user_id = auth.uid()
      and s.created_at >= now() - (p_candidate_ttl_hours::text || ' hours')::interval
    order by s.created_at desc
    limit greatest(p_limit, 10) * 4
  ),

  action_summary as (
    select
      a.decision_id,
      a.spot_id,
      max(a.created_at) as last_action_at,
      (array_agg(a.action order by a.created_at desc))[1] as last_action,
      max(
        case
          when a.action = 'exact_mood' then 1.00
          when a.action = 'was_here' then 0.95
          when a.action = 'tapped' then 0.72
          when a.action = 'not_there' then -1.00
          else 0.10
        end
      )::numeric as action_score
    from public.decision_actions a
    join my_sessions s on s.id = a.decision_id
    group by a.decision_id, a.spot_id
  ),

  impressions as (
    select
      s.id as decision_id,
      s.created_at as decision_created_at,
      s.city,
      s.mood_a_text,
      s.mood_b_text,
      di.spot_id,
      sp.name as spot_name,
      sp.city as spot_city,
      c.name as category_name,
      di.rank::integer as rank,
      di.why_this,
      a.last_action,
      a.last_action_at,
      coalesce(a.action_score, case when di.rank <= 3 then 0.42 else 0.12 end)::numeric
        + greatest(0, (12 - coalesce(di.rank, 12))::numeric) * 0.025 as signal_score
    from my_sessions s
    join public.decision_impressions di on di.decision_id = s.id
    join public.spots sp on sp.id = di.spot_id
    left join public.categories c on c.id = sp.category_id
    left join action_summary a
      on a.decision_id = di.decision_id
     and a.spot_id = di.spot_id
    where coalesce(a.last_action, '') <> 'not_there'
      and (
        a.last_action is not null
        or di.rank <= 3
      )
  ),

  matched_reviews as (
    select
      i.*,
      r.id as review_id,
      r.created_at as reviewed_at,
      row_number() over (
        partition by i.decision_id, i.spot_id
        order by r.created_at asc
      ) as review_rn
    from impressions i
    left join public.reviews r
      on r.user_id = auth.uid()
     and r.spot_id = i.spot_id
     and r.created_at >= i.decision_created_at
     and r.created_at <= i.decision_created_at + (p_review_window_hours::text || ' hours')::interval
  ),

  deduped as (
    select *
    from matched_reviews
    where review_rn = 1 or review_rn is null
  )

  select
    d.decision_id,
    d.decision_created_at,
    d.city,
    d.mood_a_text,
    d.mood_b_text,
    d.spot_id,
    d.spot_name,
    d.spot_city,
    d.category_name,
    d.rank,
    d.why_this,
    d.last_action,
    d.last_action_at,
    d.review_id,
    d.reviewed_at,
    case
      when d.review_id is not null then 'visited_reviewed'
      when d.last_action in ('was_here','exact_mood') then 'confirmed_needs_review'
      when d.last_action = 'tapped' then 'opened_needs_review'
      else 'suggested_needs_review'
    end as status,
    case
      when d.review_id is not null then 'Besuch erkannt'
      when d.last_action in ('was_here','exact_mood') then 'Wie war es wirklich?'
      when d.last_action = 'tapped' then 'Warst du inzwischen da?'
      else 'Hat der Tipp gepasst?'
    end as prompt_title,
    case
      when d.review_id is not null then 'Backyrd hat erkannt: Aus deiner Decision wurde ein echter Moment. Magisch.'
      when d.last_action in ('was_here','exact_mood') then 'Du hast diesen Spot markiert. Eine kurze Review macht daraus einen Backyrd Treffer.'
      when d.last_action = 'tapped' then 'Du hast dir diesen Spot genauer angeschaut. Falls du dort warst, speichere den Moment.'
      else 'Dieser Spot war oben in deiner Auswahl. Hilf Backyrd zu lernen, ob er wirklich gepasst hat.'
    end as prompt_body,
    d.signal_score
  from deduped d
  order by
    case when d.review_id is not null then 2 else 1 end asc,
    d.signal_score desc,
    d.decision_created_at desc,
    d.rank asc
  limit p_limit;
$$;

ALTER FUNCTION "public"."get_decision_visit_candidates_v1"("p_limit" integer, "p_review_window_hours" integer, "p_candidate_ttl_hours" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_mobile_spot_taxonomy_v1"("p_spot_id" "uuid", "p_locale" "text" DEFAULT 'de'::"text") RETURNS TABLE("taxonomy_node_id" "uuid", "slug" "text", "node_type" "text", "label" "text", "icon" "text", "color" "text", "sort_order" integer, "source" "text", "confidence" numeric, "is_verified" boolean, "ml_weight" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    n.id,
    n.slug,
    n.node_type,
    coalesce(tr.label, de.label, n.slug),
    n.icon,
    n.color,
    n.sort_order,
    st.source,
    st.confidence,
    st.is_verified,
    n.ml_weight
  from public.spot_taxonomies st
  join public.taxonomy_nodes n on n.id = st.taxonomy_node_id
  left join public.taxonomy_node_translations tr
    on tr.taxonomy_node_id = n.id
   and tr.locale = coalesce(nullif(trim(p_locale), ''), 'de')
  left join public.taxonomy_node_translations de
    on de.taxonomy_node_id = n.id and de.locale = 'de'
  where st.spot_id = p_spot_id
    and n.is_active = true
  order by
    case n.node_type
      when 'subcategory' then 1
      when 'feature' then 2
      when 'offering' then 3
      when 'service' then 4
      else 5
    end,
    st.is_verified desc,
    n.ml_weight desc,
    n.sort_order,
    coalesce(tr.label, de.label, n.slug);
$$;

ALTER FUNCTION "public"."get_mobile_spot_taxonomy_v1"("p_spot_id" "uuid", "p_locale" "text") OWNER TO "postgres";

