CREATE OR REPLACE FUNCTION "public"."get_my_direct_chats_v1"() RETURNS TABLE("chat_id" "uuid", "other_user_id" "uuid", "other_display_name" "text", "other_first_name" "text", "other_username" "text", "other_avatar_url" "text", "chat_created_at" timestamp with time zone, "last_message_text" "text", "last_message_at" timestamp with time zone, "last_message_sender_id" "uuid", "unread_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  with my_chats as (
    select
      c.id as chat_id,
      case
        when c.user_a = auth.uid() then c.user_b
        else c.user_a
      end as other_user_id,
      c.created_at as chat_created_at
    from public.chats c
    where auth.uid() is not null
      and (
        c.user_a = auth.uid()
        or c.user_b = auth.uid()
      )
  )
  select
    mc.chat_id,
    mc.other_user_id,
    coalesce(
      nullif(btrim(p.display_name), ''),
      nullif(btrim(p.first_name), ''),
      nullif(btrim(p.username), ''),
      'Backyrd User'
    ) as other_display_name,
    nullif(btrim(p.first_name), '') as other_first_name,
    nullif(btrim(p.username), '') as other_username,
    nullif(btrim(p.avatar_url), '') as other_avatar_url,
    mc.chat_created_at,
    lm.text as last_message_text,
    lm.created_at as last_message_at,
    lm.sender_id as last_message_sender_id,
    coalesce((
      select count(*)::integer
      from public.messages um
      where um.chat_id = mc.chat_id
        and um.sender_id <> auth.uid()
        and um.seen_at is null
    ), 0) as unread_count
  from my_chats mc
  left join public.profiles p
    on p.id = mc.other_user_id
  left join lateral (
    select
      m.text,
      m.created_at,
      m.sender_id
    from public.messages m
    where m.chat_id = mc.chat_id
    order by m.created_at desc
    limit 1
  ) lm on true
  order by
    coalesce(lm.created_at, mc.chat_created_at) desc;
$$;

ALTER FUNCTION "public"."get_my_direct_chats_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_my_legal_documents_overview_v1"("p_locale" "text" DEFAULT 'de-CH'::"text") RETURNS TABLE("document_id" "uuid", "document_type" "text", "version" "text", "locale" "text", "title" "text", "summary" "text", "content_markdown" "text", "content_hash" "text", "requires_acceptance" boolean, "accepted" boolean, "accepted_at" timestamp with time zone, "effective_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  select
    d.id,
    d.document_type,
    d.version,
    d.locale,
    d.title,
    d.summary,
    d.content_markdown,
    d.content_hash,
    d.requires_acceptance,
    ula.document_id is not null,
    ula.accepted_at,
    d.effective_at
  from public.legal_documents d
  left join public.user_legal_acceptances ula
    on ula.user_id = auth.uid()
   and ula.document_id = d.id
  where auth.uid() is not null
    and d.status = 'published'
    and d.retired_at is null
    and d.effective_at <= now()
    and d.locale = coalesce(nullif(btrim(p_locale), ''), 'de-CH')
  order by d.document_type, d.effective_at desc;
$$;

ALTER FUNCTION "public"."get_my_legal_documents_overview_v1"("p_locale" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_my_legal_gate_status_v1"("p_locale" "text" DEFAULT 'de-CH'::"text") RETURNS TABLE("logged_in" boolean, "gate_required" boolean, "pending_count" integer, "pending_document_ids" "uuid"[], "pending_document_types" "text"[], "latest_effective_at" timestamp with time zone, "next_route" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  with pending as (
    select d.id,d.document_type,d.effective_at
    from public.legal_documents d
    where d.status='published'
      and d.retired_at is null
      and d.effective_at<=now()
      and d.locale=coalesce(nullif(btrim(p_locale),''),'de-CH')
      and d.requires_acceptance=true
      and auth.uid() is not null
      and not exists (
        select 1 from public.user_legal_acceptances ula
        where ula.user_id=auth.uid() and ula.document_id=d.id
      )
  )
  select
    auth.uid() is not null,
    auth.uid() is not null and exists(select 1 from pending),
    (select count(*)::integer from pending),
    coalesce((select array_agg(id order by effective_at,document_type) from pending),'{}'::uuid[]),
    coalesce((select array_agg(document_type order by effective_at,document_type) from pending),'{}'::text[]),
    (select max(effective_at) from pending),
    case
      when auth.uid() is null then '/login'
      when exists(select 1 from pending) then '/legal-consent'
      else '/(tabs)'
    end;
$$;

ALTER FUNCTION "public"."get_my_legal_gate_status_v1"("p_locale" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_my_onboarding_status_v1"() RETURNS TABLE("logged_in" boolean, "user_id" "uuid", "has_profile" boolean, "profile_onboarding_completed" boolean, "decision_onboarding_completed" boolean, "needs_profile_onboarding" boolean, "needs_decision_onboarding" boolean, "display_name" "text", "username" "text", "city" "text", "birthdate" "date", "taste_qualified_actions" integer, "favorite_seed_count" integer, "place_type_profile_count" integer, "next_route" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_profile public.profiles%rowtype;
  v_has_profile boolean := false;
  v_profile_completed boolean := false;
  v_decision_completed boolean := false;
  v_taste_actions integer := 0;
  v_seed_count integer := 0;
  v_place_type_count integer := 0;
begin
  if v_user_id is null then
    logged_in := false;
    user_id := null;
    has_profile := false;

    profile_onboarding_completed := false;
    decision_onboarding_completed := false;

    needs_profile_onboarding := false;
    needs_decision_onboarding := false;

    display_name := null;
    username := null;
    city := null;
    birthdate := null;

    taste_qualified_actions := 0;
    favorite_seed_count := 0;
    place_type_profile_count := 0;

    next_route := '/auth/login';
    return next;
    return;
  end if;

  /*
    WICHTIG:
    Kein Insert in profiles innerhalb dieses Status-Checks.
    profiles.id hat einen Foreign Key auf auth.users.id.
    Profil-Erstellung passiert über:
    - auth.users trigger handle_new_user()
    - oder gezielt im Profil-Onboarding
  */

  select *
  into v_profile
  from public.profiles p
  where p.id = v_user_id
  limit 1;

  v_has_profile := v_profile.id is not null;

  if not v_has_profile then
    logged_in := true;
    user_id := v_user_id;
    has_profile := false;

    profile_onboarding_completed := false;
    decision_onboarding_completed := false;

    needs_profile_onboarding := true;
    needs_decision_onboarding := false;

    display_name := null;
    username := null;
    city := null;
    birthdate := null;

    taste_qualified_actions := 0;
    favorite_seed_count := 0;
    place_type_profile_count := 0;

    next_route := '/onboarding/profile';
    return next;
    return;
  end if;

  select coalesce(max(tp.qualified_actions), 0)::integer
  into v_taste_actions
  from public.user_taste_profile_v1 tp
  where tp.user_id = v_user_id;

  select count(*)::integer
  into v_seed_count
  from public.user_favorite_spot_seeds s
  where s.user_id = v_user_id
    and s.spot_id is not null;

  select count(*)::integer
  into v_place_type_count
  from public.user_place_type_preferences_v1 pt
  where pt.user_id = v_user_id;

  v_profile_completed :=
    v_profile.profile_onboarding_completed_at is not null
    or (
      nullif(trim(coalesce(v_profile.display_name, '')), '') is not null
      and nullif(trim(coalesce(v_profile.username, '')), '') is not null
      and v_profile.birthdate is not null
    );

  v_decision_completed :=
    v_profile.decision_onboarding_completed_at is not null
    or v_taste_actions >= 3
    or v_seed_count >= 3
    or v_place_type_count >= 3;

  logged_in := true;
  user_id := v_user_id;
  has_profile := v_has_profile;

  profile_onboarding_completed := v_profile_completed;
  decision_onboarding_completed := v_decision_completed;

  needs_profile_onboarding := not v_profile_completed;
  needs_decision_onboarding := v_profile_completed and not v_decision_completed;

  display_name := v_profile.display_name;
  username := v_profile.username;
  city := coalesce(v_profile.city, v_profile.home_city);
  birthdate := v_profile.birthdate;

  taste_qualified_actions := v_taste_actions;
  favorite_seed_count := v_seed_count;
  place_type_profile_count := v_place_type_count;

  next_route := case
    when not v_profile_completed then '/onboarding/profile'
    when not v_decision_completed then '/onboarding/decision'
    else '/(tabs)'
  end;

  return next;
end;
$$;

ALTER FUNCTION "public"."get_my_onboarding_status_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_my_owned_spots_v1"() RETURNS TABLE("spot_id" "uuid", "name" "text", "city" "text", "category_name" "text")
