CREATE OR REPLACE FUNCTION "public"."get_my_spot_claim_status_v2"("p_spot_id" "uuid") RETURNS TABLE("spot_id" "uuid", "claim_id" bigint, "status" "text", "business_email" "text", "business_domain" "text", "email_verified_at" timestamp with time zone, "is_approved" boolean, "is_verified_operator" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with me as (
    select auth.uid() as user_id
  ),
  my_claim as (
    select sc.*
    from public.spot_claims sc, me
    where sc.spot_id = p_spot_id
      and sc.user_id = me.user_id
    order by sc.created_at desc
    limit 1
  ),
  spot_owner as (
    select
      s.id as spot_id,
      s.owner_id
    from public.spots s
    where s.id = p_spot_id
  ),
  desc_owner as (
    select
      sd.spot_id,
      sd.owner_user_id,
      coalesce(sd.is_verified, false) as is_verified
    from public.spot_descriptions sd
    where sd.spot_id = p_spot_id
  )
  select
    p_spot_id as spot_id,
    mc.id as claim_id,
    mc.status,
    mc.business_email,
    mc.business_domain,
    mc.email_verified_at,
    coalesce(mc.status = 'approved', false) as is_approved,
    coalesce(
      so.owner_id = (select user_id from me)
      and d.is_verified = true,
      false
    ) as is_verified_operator
  from me
  left join my_claim mc on true
  left join spot_owner so on so.spot_id = p_spot_id
  left join desc_owner d on d.spot_id = p_spot_id;
$$;

ALTER FUNCTION "public"."get_my_spot_claim_status_v2"("p_spot_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_my_taste_profile_status_v1"() RETURNS TABLE("qualified_actions" integer, "confidence" numeric, "needs_onboarding" boolean)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    coalesce(p.qualified_actions, 0) as qualified_actions,
    coalesce(p.confidence, 0) as confidence,
    (coalesce(p.qualified_actions, 0) < 5) as needs_onboarding
  from public.user_taste_profile_v1 p
  where p.user_id = auth.uid()
  union all
  select 0, 0, true
  where auth.uid() is not null
    and not exists (select 1 from public.user_taste_profile_v1 p2 where p2.user_id = auth.uid());
$$;

ALTER FUNCTION "public"."get_my_taste_profile_status_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_or_create_direct_chat_v1"("p_other_user_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_me uuid := auth.uid();
  v_user_a uuid;
  v_user_b uuid;
  v_chat_id uuid;
begin
  if v_me is null then
    raise exception 'not_authenticated'
      using errcode = '28000';
  end if;

  if p_other_user_id is null then
    raise exception 'other_user_required'
      using errcode = '22023';
  end if;

  if p_other_user_id = v_me then
    raise exception 'self_chat_not_allowed'
      using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_other_user_id
  ) then
    raise exception 'user_not_found'
      using errcode = '22023';
  end if;

  v_user_a := least(v_me, p_other_user_id);
  v_user_b := greatest(v_me, p_other_user_id);

  insert into public.chats (
    user_a,
    user_b
  )
  values (
    v_user_a,
    v_user_b
  )
  on conflict (user_a, user_b)
  do update
  set user_a = excluded.user_a
  returning id into v_chat_id;

  insert into public.chat_participants (
    chat_id,
    user_id
  )
  values
    (v_chat_id, v_user_a),
    (v_chat_id, v_user_b)
  on conflict (chat_id, user_id)
  do nothing;

  return v_chat_id;
end;
$$;

ALTER FUNCTION "public"."get_or_create_direct_chat_v1"("p_other_user_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_or_create_direct_chat_v2"("p_other_user_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_me uuid := auth.uid();
  v_user_a uuid;
  v_user_b uuid;
  v_chat_id uuid;
begin
  if v_me is null then
    raise exception 'not_authenticated'
      using errcode = '28000';
  end if;

  if p_other_user_id is null then
    raise exception 'other_user_required';
  end if;

  if p_other_user_id = v_me then
    raise exception 'self_chat_not_allowed';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_other_user_id
  ) then
    raise exception 'user_not_found';
  end if;

  if public.users_are_blocked_v1(v_me, p_other_user_id) then
    raise exception 'interaction_blocked';
  end if;

  if exists (
    select 1
    from public.profiles p
    where p.id = p_other_user_id
      and p.is_private = true
  ) then
    raise exception 'private_profile_not_messageable';
  end if;

  v_user_a := least(v_me, p_other_user_id);
  v_user_b := greatest(v_me, p_other_user_id);

  select c.id
  into v_chat_id
  from public.chats c
  where c.user_a = v_user_a
    and c.user_b = v_user_b;

  if v_chat_id is null then
    insert into public.chats (
      user_a,
      user_b
    )
    values (
      v_user_a,
      v_user_b
    )
    returning id into v_chat_id;

    insert into public.chat_participants (
      chat_id,
      user_id
    )
    values
      (v_chat_id, v_user_a),
      (v_chat_id, v_user_b)
    on conflict (chat_id, user_id)
    do nothing;
  end if;

  return v_chat_id;
end;
$$;

ALTER FUNCTION "public"."get_or_create_direct_chat_v2"("p_other_user_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_owner_spot_detail_v1"("p_spot_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_result jsonb;
begin
  perform public.backyrd_owner_assert_spot_v1(p_spot_id);

  select jsonb_build_object(
    'spot', jsonb_build_object(
      'id', s.id,
      'name', s.name,
      'address', s.address,
      'city', s.city,
      'country', s.country,
      'status', s.status::text,
      'website', s.website,
      'phone', s.phone,
      'email', s.email,
      'price_level', s.price_level,
      'header_photo_path', s.header_photo_path,
      'category_id', s.category_id,
      'category_name', c.name,
      'created_at', s.created_at
    ),
    'description', jsonb_build_object(
      'owner_description', sd.owner_description,
      'owner_keywords', coalesce(sd.owner_keywords, '{}'::text[]),
      'admin_description', sd.admin_description,
      'admin_keywords', coalesce(sd.admin_keywords, '{}'::text[]),
      'enriched_description', sd.enriched_description,
      'enriched_keywords', coalesce(sd.enriched_keywords, '{}'::text[]),
      'content_status', sd.content_status,
      'quality_score', sd.quality_score,
      'is_verified', sd.is_verified,
      'updated_at', sd.updated_at
    ),
    'intelligence', jsonb_build_object(
      'best_for', coalesce(si.best_for, '{}'::text[]),
      'occasion_tags', coalesce(si.occasion_tags, '{}'::text[]),
      'atmosphere_tags', coalesce(si.atmosphere_tags, '{}'::text[]),
      'avoid_if_tags', coalesce(si.avoid_if_tags, '{}'::text[]),
      'good_for_time', coalesce(si.good_for_time, '{}'::text[]),
      'noise_level', si.noise_level,
      'crowd_type', coalesce(si.crowd_type, '{}'::text[]),
      'dress_code', si.dress_code,
      'reservation_recommended', si.reservation_recommended,
      'average_duration_minutes', si.average_duration_minutes,
      'signature_items', coalesce(si.signature_items, '{}'::text[]),
      'special_notes', si.special_notes,
      'source', si.source,
      'is_verified', si.is_verified,
      'updated_at', si.updated_at
    ),
    'metrics', jsonb_build_object(
      'review_count', (
        select count(*)::integer from public.reviews r where r.spot_id = s.id
      ),
      'social_post_count', (
        select count(*)::integer from public.social_posts sp where sp.spot_id = s.id
      ),
      'decision_review_count', (
        select count(*)::integer
        from public.social_posts sp
        where sp.spot_id = s.id
          and sp.source_type = 'decision_review'
      )
    )
  )
  into v_result
  from public.spots s
  left join public.categories c on c.id = s.category_id
  left join public.spot_descriptions sd on sd.spot_id = s.id
  left join public.spot_intelligence_v1 si on si.spot_id = s.id
  where s.id = p_spot_id
  limit 1;

  if v_result is null then
    raise exception 'Spot not found';
  end if;

  return v_result;
end;
$$;

ALTER FUNCTION "public"."get_owner_spot_detail_v1"("p_spot_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_owner_spots_v1"("p_limit" integer DEFAULT 80) RETURNS TABLE("spot_id" "uuid", "name" "text", "city" "text", "address" "text", "category_name" "text", "price_level" integer, "status" "text", "header_photo_path" "text", "website" "text", "phone" "text", "email" "text", "content_status" "text", "quality_score" numeric, "updated_at" timestamp with time zone, "created_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    s.id as spot_id,
    s.name,
    s.city,
    s.address,
    c.name as category_name,
    s.price_level,
    s.status::text as status,
    s.header_photo_path,
    s.website,
    s.phone,
    s.email,
    sd.content_status,
    sd.quality_score,
    coalesce(sd.updated_at, si.updated_at, s.created_at) as updated_at,
    s.created_at
  from public.spots s
  left join public.categories c on c.id = s.category_id
  left join public.spot_descriptions sd on sd.spot_id = s.id
  left join public.spot_intelligence_v1 si on si.spot_id = s.id
  where s.owner_id = auth.uid()
  order by s.created_at desc
  limit greatest(1, least(coalesce(p_limit, 80), 200));
$$;

ALTER FUNCTION "public"."get_owner_spots_v1"("p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_recent_seen_spot_ids_v1"("p_days" integer DEFAULT 7, "p_limit" integer DEFAULT 80) RETURNS "uuid"[]
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with recent as (
    select
      di.spot_id,
      max(di.created_at) as last_seen_at
    from public.decision_impressions di
    join public.decision_sessions ds on ds.id = di.decision_id
    where ds.user_id = auth.uid()
      and di.created_at >= now() - make_interval(days => greatest(p_days, 0))
    group by di.spot_id
    order by last_seen_at desc
    limit greatest(1, least(p_limit, 500))
  )
  select coalesce(array_agg(spot_id), '{}'::uuid[])
  from recent;
$$;

