CREATE OR REPLACE FUNCTION "public"."get_social_comments_v1"("p_post_id" "uuid", "p_limit" integer DEFAULT 50) RETURNS TABLE("comment_id" "uuid", "post_id" "uuid", "user_id" "uuid", "display_name" "text", "username" "text", "avatar_url" "text", "body" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 100));
begin
  if v_user_id is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  return query
  select
    c.id as comment_id,
    c.post_id,
    c.user_id,

    coalesce(
      nullif(to_jsonb(pr)->>'display_name', ''),
      nullif(to_jsonb(pr)->>'first_name', ''),
      nullif(to_jsonb(pr)->>'username', ''),
      'User'
    ) as display_name,
    nullif(to_jsonb(pr)->>'username', '') as username,
    nullif(to_jsonb(pr)->>'avatar_url', '') as avatar_url,

    c.body,
    c.created_at
  from public.social_comments c
  left join public.profiles pr on pr.id = c.user_id
  where c.post_id = p_post_id
    and c.status = 'published'
  order by c.created_at asc
  limit v_limit;
end;
$$;

ALTER FUNCTION "public"."get_social_comments_v1"("p_post_id" "uuid", "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_social_feed_v1"("p_limit" integer DEFAULT 30, "p_cursor" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_city" "text" DEFAULT NULL::"text", "p_feed_mode" "text" DEFAULT 'for_you'::"text") RETURNS TABLE("post_id" "uuid", "user_id" "uuid", "display_name" "text", "username" "text", "avatar_url" "text", "spot_id" "uuid", "spot_name" "text", "spot_city" "text", "category_name" "text", "caption" "text", "visibility" "text", "mood_tags" "text"[], "occasion_tags" "text"[], "media" "jsonb", "like_count" integer, "comment_count" integer, "save_count" integer, "viewer_has_liked" boolean, "viewer_has_saved" boolean, "viewer_follows_author" boolean, "created_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with limited_posts as (
    select sp.*
    from public.social_posts sp
    left join public.spots s on s.id = sp.spot_id
    where
      auth.uid() is not null
      and coalesce((to_jsonb(sp)->>'is_deleted')::boolean, false) = false
      and (p_cursor is null or sp.created_at < p_cursor)
      and (
        p_city is null
        or trim(p_city) = ''
        or lower(coalesce(s.city, '')) = lower(trim(p_city))
      )
      and (
        case
          when lower(coalesce(p_feed_mode, 'for_you')) = 'following' then
            exists (
              select 1
              from public.follows f
              where f.follower = auth.uid()
                and f.following = sp.user_id
            )
          else
            (
              coalesce(sp.visibility, 'public') = 'public'
              or sp.user_id = auth.uid()
              or (
                coalesce(sp.visibility, 'public') = 'followers'
                and exists (
                  select 1
                  from public.follows f
                  where f.follower = auth.uid()
                    and f.following = sp.user_id
                )
              )
            )
        end
      )
    order by sp.created_at desc
    limit greatest(1, least(coalesce(p_limit, 30), 80))
  )

  select
    sp.id as post_id,
    sp.user_id,

    coalesce(
      nullif(trim(to_jsonb(p)->>'display_name'), ''),
      nullif(trim(to_jsonb(p)->>'first_name'), ''),
      nullif(trim(to_jsonb(p)->>'name'), ''),
      nullif(trim(to_jsonb(p)->>'full_name'), ''),
      'Backyrd User'
    ) as display_name,

    nullif(trim(to_jsonb(p)->>'username'), '') as username,
    nullif(trim(to_jsonb(p)->>'avatar_url'), '') as avatar_url,

    s.id as spot_id,
    s.name as spot_name,
    s.city as spot_city,
    c.name as category_name,

    sp.caption,
    coalesce(sp.visibility, 'public') as visibility,
    coalesce(sp.mood_tags, '{}'::text[]) as mood_tags,
    coalesce(sp.occasion_tags, '{}'::text[]) as occasion_tags,

    coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', m.id,
          'storage_path', to_jsonb(m)->>'storage_path',
          'public_url', to_jsonb(m)->>'public_url',
          'media_type', to_jsonb(m)->>'media_type',
          'width', nullif(to_jsonb(m)->>'width', '')::integer,
          'height', nullif(to_jsonb(m)->>'height', '')::integer,
          'sort_order', nullif(to_jsonb(m)->>'sort_order', '')::integer
        )
        order by
          coalesce(nullif(to_jsonb(m)->>'sort_order', '')::integer, 0) asc,
          m.created_at asc
      )
      from public.social_post_media m
      where m.post_id = sp.id
    ), '[]'::jsonb) as media,

    (
      select count(*)::integer
      from public.social_post_reactions r
      where r.post_id = sp.id
        and r.reaction_type = 'like'
        and coalesce((to_jsonb(r)->>'active')::boolean, true) = true
    ) as like_count,

    (
      select count(*)::integer
      from public.social_comments cm
      where cm.post_id = sp.id
        and coalesce((to_jsonb(cm)->>'is_deleted')::boolean, false) = false
    ) as comment_count,

    (
      select count(*)::integer
      from public.social_post_reactions r
      where r.post_id = sp.id
        and r.reaction_type = 'save'
        and coalesce((to_jsonb(r)->>'active')::boolean, true) = true
    ) as save_count,

    exists (
      select 1
      from public.social_post_reactions r
      where r.post_id = sp.id
        and r.user_id = auth.uid()
        and r.reaction_type = 'like'
        and coalesce((to_jsonb(r)->>'active')::boolean, true) = true
    ) as viewer_has_liked,

    exists (
      select 1
      from public.social_post_reactions r
      where r.post_id = sp.id
        and r.user_id = auth.uid()
        and r.reaction_type = 'save'
        and coalesce((to_jsonb(r)->>'active')::boolean, true) = true
    ) as viewer_has_saved,

    exists (
      select 1
      from public.follows f
      where f.follower = auth.uid()
        and f.following = sp.user_id
    ) as viewer_follows_author,

    sp.created_at
  from limited_posts sp
  join public.profiles p on p.id = sp.user_id
  left join public.spots s on s.id = sp.spot_id
  left join public.categories c on c.id = s.category_id
  order by sp.created_at desc;
$$;

ALTER FUNCTION "public"."get_social_feed_v1"("p_limit" integer, "p_cursor" timestamp with time zone, "p_city" "text", "p_feed_mode" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_social_feed_v2"("p_limit" integer DEFAULT 30, "p_cursor" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_city" "text" DEFAULT NULL::"text", "p_feed_mode" "text" DEFAULT 'for_you'::"text") RETURNS TABLE("post_id" "uuid", "user_id" "uuid", "display_name" "text", "username" "text", "avatar_url" "text", "spot_id" "uuid", "spot_name" "text", "spot_city" "text", "category_name" "text", "caption" "text", "visibility" "text", "mood_tags" "text"[], "occasion_tags" "text"[], "media" "jsonb", "like_count" integer, "comment_count" integer, "save_count" integer, "viewer_has_liked" boolean, "viewer_has_saved" boolean, "viewer_follows_author" boolean, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_me uuid := auth.uid();
  v_limit integer := greatest(1, least(coalesce(p_limit, 30), 100));
begin
  if v_me is null then
    raise exception 'not_authenticated'
      using errcode = '28000';
  end if;

  return query
  select f.*
  from public.get_social_feed_v1(
    least(v_limit * 4, 200),
    p_cursor,
    p_city,
    p_feed_mode
  ) f
  join public.profiles p
    on p.id = f.user_id
  where
    (
      f.user_id = v_me
      or p.is_private = false
    )
    and not public.users_are_blocked_v1(v_me, f.user_id)
  order by f.created_at desc
  limit v_limit;
end;
$$;

ALTER FUNCTION "public"."get_social_feed_v2"("p_limit" integer, "p_cursor" timestamp with time zone, "p_city" "text", "p_feed_mode" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_social_profile_v1"("p_user_id" "uuid") RETURNS TABLE("user_id" "uuid", "display_name" "text", "username" "text", "avatar_url" "text", "city" "text", "post_count" integer, "follower_count" integer, "following_count" integer, "viewer_follows_user" boolean, "is_me" boolean)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    p.id as user_id,

    coalesce(
      nullif(trim(to_jsonb(p)->>'display_name'), ''),
      nullif(trim(to_jsonb(p)->>'first_name'), ''),
      nullif(trim(to_jsonb(p)->>'name'), ''),
      nullif(trim(to_jsonb(p)->>'full_name'), ''),
      'Backyrd User'
    ) as display_name,

    nullif(trim(to_jsonb(p)->>'username'), '') as username,
    nullif(trim(to_jsonb(p)->>'avatar_url'), '') as avatar_url,

    coalesce(
      nullif(trim(to_jsonb(p)->>'city'), ''),
      nullif(trim(to_jsonb(p)->>'home_city'), '')
    ) as city,

    (
      select count(*)::integer
      from public.social_posts sp
      where sp.user_id = p.id
        and coalesce((to_jsonb(sp)->>'is_deleted')::boolean, false) = false
        and coalesce(sp.visibility, 'public') in ('public', 'followers')
    ) as post_count,

    (
      select count(*)::integer
      from public.follows f
      where f.following = p.id
    ) as follower_count,

    (
      select count(*)::integer
      from public.follows f
      where f.follower = p.id
    ) as following_count,

    exists (
      select 1
      from public.follows f
      where f.follower = auth.uid()
        and f.following = p.id
    ) as viewer_follows_user,

    auth.uid() = p.id as is_me
  from public.profiles p
  where p.id = p_user_id
  limit 1;
$$;

ALTER FUNCTION "public"."get_social_profile_v1"("p_user_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_social_profile_v2"("p_user_id" "uuid") RETURNS TABLE("user_id" "uuid", "display_name" "text", "username" "text", "avatar_url" "text", "header_photo_url" "text", "bio" "text", "city" "text", "is_local" boolean, "is_private" boolean, "post_count" integer, "follower_count" integer, "following_count" integer, "viewer_follows_user" boolean, "is_me" boolean, "can_follow" boolean, "can_message" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'not_authenticated'
      using errcode = '28000';
  end if;

  if p_user_id is null then
    raise exception 'user_id_required';
  end if;

  if not public.social_profile_is_accessible_v1(p_user_id) then
    return;
  end if;

  return query
  select
    p.id,
    coalesce(
      nullif(btrim(p.display_name), ''),
      nullif(btrim(p.first_name), ''),
      nullif(btrim(p.username), ''),
      'Backyrd User'
    ),
    nullif(btrim(p.username), ''),
    nullif(btrim(p.avatar_url), ''),
    nullif(btrim(p.header_photo_url), ''),
    nullif(btrim(p.bio), ''),
    nullif(btrim(p.city), ''),
    coalesce(p.is_local, false),
    p.is_private,
    (
      select count(*)::integer
      from public.social_posts sp
      where sp.user_id = p.id
        and sp.status = 'published'
        and (
          p.id = v_me
          or p.is_private = false
        )
    ),
    (
      select count(*)::integer
      from public.follows f
      where f.following = p.id
    ),
    (
      select count(*)::integer
      from public.follows f
      where f.follower = p.id
    ),
    exists (
      select 1
      from public.follows f
      where f.follower = v_me
        and f.following = p.id
    ),
    p.id = v_me,
    p.id <> v_me
      and p.is_private = false
      and not public.users_are_blocked_v1(v_me, p.id),
    p.id <> v_me
      and p.is_private = false
      and not public.users_are_blocked_v1(v_me, p.id)
  from public.profiles p
  where p.id = p_user_id;
end;
$$;

ALTER FUNCTION "public"."get_social_profile_v2"("p_user_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_social_user_posts_v1"("p_user_id" "uuid", "p_limit" integer DEFAULT 40, "p_cursor" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("post_id" "uuid", "user_id" "uuid", "display_name" "text", "username" "text", "avatar_url" "text", "spot_id" "uuid", "spot_name" "text", "spot_city" "text", "category_name" "text", "caption" "text", "visibility" "text", "mood_tags" "text"[], "occasion_tags" "text"[], "media" "jsonb", "like_count" integer, "comment_count" integer, "save_count" integer, "viewer_has_liked" boolean, "viewer_has_saved" boolean, "viewer_follows_author" boolean, "created_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with limited_posts as (
