    c.name as category_name,

    sp.caption,
    coalesce(sp.visibility, 'public') as visibility,
    coalesce(sp.mood_tags, '{}'::text[]) as mood_tags,
    coalesce(sp.occasion_tags, '{}'::text[]) as occasion_tags,

    coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', m.id,
          'storage_path', m.storage_path,
          'public_url', to_jsonb(m)->>'public_url',
          'media_type', to_jsonb(m)->>'media_type',
          'width', nullif(to_jsonb(m)->>'width', '')::integer,
          'height', nullif(to_jsonb(m)->>'height', '')::integer,
          'sort_order', nullif(to_jsonb(m)->>'sort_order', '')::integer
        )
        order by
          coalesce(nullif(to_jsonb(m)->>'sort_order', '')::integer, 0) asc,
          m.created_at asc
      )
      from public.social_post_media m
      where m.post_id = sp.id
    ), '[]'::jsonb) as media,

    (
      select count(*)::integer
      from public.social_post_reactions r
      where r.post_id = sp.id
        and r.reaction_type = 'like'
        and coalesce((to_jsonb(r)->>'active')::boolean, true) = true
    ) as like_count,

    (
      select count(*)::integer
      from public.social_comments cm
      where cm.post_id = sp.id
        and coalesce((to_jsonb(cm)->>'is_deleted')::boolean, false) = false
    ) as comment_count,

    (
      select count(*)::integer
      from public.social_post_reactions r
      where r.post_id = sp.id
        and r.reaction_type = 'save'
        and coalesce((to_jsonb(r)->>'active')::boolean, true) = true
    ) as save_count,

    exists (
      select 1
      from public.social_post_reactions r
      where r.post_id = sp.id
        and r.user_id = auth.uid()
        and r.reaction_type = 'like'
        and coalesce((to_jsonb(r)->>'active')::boolean, true) = true
    ) as viewer_has_liked,

    exists (
      select 1
      from public.social_post_reactions r
      where r.post_id = sp.id
        and r.user_id = auth.uid()
        and r.reaction_type = 'save'
        and coalesce((to_jsonb(r)->>'active')::boolean, true) = true
    ) as viewer_has_saved,

    exists (
      select 1
      from public.follows f
      where f.follower = auth.uid()
        and f.following = sp.user_id
    ) as viewer_follows_author,

    sp.created_at
  from limited_posts sp
  join public.profiles p on p.id = sp.user_id
  left join public.spots s on s.id = sp.spot_id
  left join public.categories c on c.id = s.category_id
  order by sp.created_at desc;
$$;

ALTER FUNCTION "public"."get_social_user_posts_v1"("p_user_id" "uuid", "p_limit" integer, "p_cursor" timestamp with time zone) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_social_user_posts_v2"("p_user_id" "uuid", "p_limit" integer DEFAULT 40, "p_cursor" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("post_id" "uuid", "user_id" "uuid", "display_name" "text", "username" "text", "avatar_url" "text", "spot_id" "uuid", "spot_name" "text", "spot_city" "text", "category_name" "text", "caption" "text", "visibility" "text", "mood_tags" "text"[], "occasion_tags" "text"[], "media" "jsonb", "like_count" integer, "comment_count" integer, "save_count" integer, "viewer_has_liked" boolean, "viewer_has_saved" boolean, "viewer_follows_author" boolean, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then
    raise exception 'not_authenticated'
      using errcode = '28000';
  end if;

  if not public.social_profile_is_accessible_v1(p_user_id) then
    return;
  end if;

  return query
  select f.*
  from public.get_social_user_posts_v1(
    p_user_id,
    greatest(1, least(coalesce(p_limit, 40), 100)),
    p_cursor
  ) f
  where
    f.user_id = v_me
    or exists (
      select 1
      from public.profiles p
      where p.id = f.user_id
        and p.is_private = false
        and not public.users_are_blocked_v1(v_me, p.id)
    );
end;
$$;

ALTER FUNCTION "public"."get_social_user_posts_v2"("p_user_id" "uuid", "p_limit" integer, "p_cursor" timestamp with time zone) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_spot_claim_queue_v2"("p_status" "text" DEFAULT 'pending'::"text", "p_limit" integer DEFAULT 50) RETURNS TABLE("claim_id" bigint, "claim_status" "text", "spot_id" "uuid", "spot_name" "text", "spot_city" "text", "spot_address" "text", "user_id" "uuid", "claimant_name" "text", "claimant_role" "text", "business_email" "text", "business_domain" "text", "email_verified_at" timestamp with time zone, "domain_match_score" numeric, "domain_match_reason" "text", "note" "text", "submitted_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_is_admin boolean := false;
  v_status text := nullif(trim(coalesce(p_status, '')), '');
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 200));
begin
  if v_user_id is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  select coalesce(p.is_admin, false)
  into v_is_admin
  from public.profiles p
  where p.id = v_user_id;

  if not coalesce(v_is_admin, false) then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  return query
  select
    sc.id as claim_id,
    sc.status as claim_status,
    sc.spot_id,
    s.name as spot_name,
    s.city as spot_city,
    s.address as spot_address,
    sc.user_id,
    sc.claimant_name,
    sc.claimant_role,
    sc.business_email,
    sc.business_domain,
    sc.email_verified_at,
    sc.domain_match_score,
    sc.domain_match_reason,
    sc.note,
    sc.submitted_at,
    sc.created_at,
    sc.updated_at
  from public.spot_claims sc
  join public.spots s
    on s.id = sc.spot_id
  where v_status is null
     or sc.status = v_status
  order by
    case when sc.status = 'pending' then 0 else 1 end,
    sc.submitted_at desc nulls last,
    sc.created_at desc
  limit v_limit;
end;
$$;

ALTER FUNCTION "public"."get_spot_claim_queue_v2"("p_status" "text", "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_spot_description_status_v1"("p_spot_id" "uuid") RETURNS TABLE("spot_id" "uuid", "has_owner" boolean, "has_enriched" boolean, "effective_source" "text", "effective_description" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    sd.spot_id,
    (sd.owner_description is not null and length(trim(sd.owner_description)) > 0) as has_owner,
    (sd.enriched_description is not null and length(trim(sd.enriched_description)) > 0) as has_enriched,
    case
      when sd.owner_description is not null and length(trim(sd.owner_description)) > 0 then 'owner'
      when sd.enriched_description is not null and length(trim(sd.enriched_description)) > 0 then coalesce(sd.enriched_source,'crawl')
      else null
    end as effective_source,
    case
      when sd.owner_description is not null and length(trim(sd.owner_description)) > 0 then sd.owner_description
      when sd.enriched_description is not null and length(trim(sd.enriched_description)) > 0 then sd.enriched_description
      else null
    end as effective_description
  from public.spot_descriptions sd
  where sd.spot_id = p_spot_id;
$$;

ALTER FUNCTION "public"."get_spot_description_status_v1"("p_spot_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_spot_description_v1"("p_spot_id" "uuid") RETURNS TABLE("spot_id" "uuid", "source" "text", "description" "text", "keywords" "text"[], "is_verified" boolean, "quality_score" numeric)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    sd.spot_id,
    case
      when sd.owner_description is not null and length(trim(sd.owner_description)) > 0 then 'owner'
      when sd.enriched_description is not null and length(trim(sd.enriched_description)) > 0 then coalesce(sd.enriched_source,'crawl')
      else null
    end as source,
    case
      when sd.owner_description is not null and length(trim(sd.owner_description)) > 0 then sd.owner_description
      when sd.enriched_description is not null and length(trim(sd.enriched_description)) > 0 then sd.enriched_description
      else null
    end as description,
    case
      when sd.owner_description is not null and length(trim(sd.owner_description)) > 0 then sd.owner_keywords
      else sd.enriched_keywords
    end as keywords,
    sd.is_verified,
    sd.quality_score
  from public.spot_descriptions sd
  where sd.spot_id = p_spot_id;
$$;

ALTER FUNCTION "public"."get_spot_description_v1"("p_spot_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_spot_intelligence_v1"("p_spot_id" "uuid") RETURNS TABLE("spot_id" "uuid", "best_for" "text"[], "occasion_tags" "text"[], "atmosphere_tags" "text"[], "avoid_if_tags" "text"[], "good_for_time" "text"[], "noise_level" "text", "crowd_type" "text"[], "dress_code" "text", "reservation_recommended" boolean, "average_duration_minutes" integer, "signature_items" "text"[], "special_notes" "text", "admin_notes" "text", "source" "text", "is_verified" boolean, "can_edit" boolean, "updated_by" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    si.spot_id,
    si.best_for,
    si.occasion_tags,
    si.atmosphere_tags,
    si.avoid_if_tags,
    si.good_for_time,
    si.noise_level,
    si.crowd_type,
    si.dress_code,
    si.reservation_recommended,
    si.average_duration_minutes,
    si.signature_items,
    si.special_notes,
    si.admin_notes,
    si.source,
    si.is_verified,
    public.can_edit_spot_v1(si.spot_id) as can_edit,
    si.updated_by,
    si.created_at,
    si.updated_at
  from public.spot_intelligence_v1 si
  where si.spot_id = p_spot_id;
