ALTER FUNCTION "public"."get_spot_intelligence_v1"("p_spot_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_spot_owner_context_v1"("p_spot_id" "uuid") RETURNS TABLE("spot_id" "uuid", "spot_name" "text", "city" "text", "address" "text", "website" "text", "phone" "text", "email" "text", "price_level" integer, "category_id" "uuid", "category_name" "text", "claim_status" "text", "is_verified_owner" boolean, "description_source" "text", "effective_description" "text", "effective_keywords" "text"[])
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with me as (
    select auth.uid() as user_id
  ),

  s as (
    select
      sp.id as spot_id,
      sp.name as spot_name,
      sp.city,
      sp.address,
      sp.website,
      sp.phone,
      sp.email,
      sp.price_level,
      sp.category_id,
      sp.owner_id
    from public.spots sp
    where sp.id = p_spot_id
    limit 1
  ),

  my_claim as (
    select sc.status
    from public.spot_claims sc, me
    where sc.spot_id = p_spot_id
      and sc.user_id = me.user_id
    order by sc.created_at desc
    limit 1
  ),

  sd as (
    select
      d.spot_id,
      d.owner_user_id,
      coalesce(d.is_verified, false) as is_verified
    from public.spot_descriptions d
    where d.spot_id = p_spot_id
    limit 1
  ),

  eff as (
    select
      ec.spot_id,
      ec.description_source,
      ec.effective_description,
      ec.effective_keywords
    from public.spot_effective_content_v1 ec
    where ec.spot_id = p_spot_id
    limit 1
  )

  select
    s.spot_id,
    s.spot_name,
    s.city,
    s.address,
    s.website,
    s.phone,
    s.email,
    s.price_level,
    s.category_id,
    c.name as category_name,

    (select status from my_claim) as claim_status,

    coalesce(
      (select user_id from me) is not null
      and s.owner_id = (select user_id from me)
      and sd.owner_user_id = (select user_id from me)
      and sd.is_verified = true,
      false
    ) as is_verified_owner,

    eff.description_source,
    eff.effective_description,
    coalesce(eff.effective_keywords, '{}'::text[]) as effective_keywords

  from s
  left join public.categories c
    on c.id = s.category_id
  left join sd
    on sd.spot_id = s.spot_id
  left join eff
    on eff.spot_id = s.spot_id;
$$;

ALTER FUNCTION "public"."get_spot_owner_context_v1"("p_spot_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_spot_taxonomies_v1"("p_spot_id" "uuid", "p_locale" "text" DEFAULT 'de'::"text") RETURNS TABLE("taxonomy_node_id" "uuid", "slug" "text", "node_type" "text", "label" "text", "source" "text", "confidence" numeric, "is_verified" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select
    st.taxonomy_node_id,
    tn.slug,
    tn.node_type,
    coalesce(req.label, de.label, en.label, tn.slug) as label,
    st.source,
    st.confidence,
    st.is_verified
  from public.spot_taxonomies st
  join public.taxonomy_nodes tn
    on tn.id = st.taxonomy_node_id
  left join public.taxonomy_node_translations req
    on req.taxonomy_node_id = tn.id
   and req.locale = case
     when p_locale in ('de', 'en', 'fr', 'it') then p_locale
     else 'de'
   end
  left join public.taxonomy_node_translations de
    on de.taxonomy_node_id = tn.id and de.locale = 'de'
  left join public.taxonomy_node_translations en
    on en.taxonomy_node_id = tn.id and en.locale = 'en'
  where st.spot_id = p_spot_id
    and tn.is_active = true
  order by tn.node_type, label, st.source;
$$;

ALTER FUNCTION "public"."get_spot_taxonomies_v1"("p_spot_id" "uuid", "p_locale" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_spot_top_moods_v1"("p_spot_id" "uuid", "p_limit" integer DEFAULT 10) RETURNS TABLE("token" "text", "count" integer)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    mt.token,
    sma.mood_count::integer as count
  from public.spot_moods_agg sma
  join public.mood_tokens mt on mt.id = sma.mood_id
  where sma.spot_id = p_spot_id
  order by sma.mood_count desc, mt.token asc
  limit greatest(1, least(p_limit, 30));
$$;

ALTER FUNCTION "public"."get_spot_top_moods_v1"("p_spot_id" "uuid", "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_spot_verified_badge_v1"("p_spot_id" "uuid") RETURNS TABLE("spot_id" "uuid", "is_operator_verified" boolean, "badge_label" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    s.id as spot_id,
    coalesce(sd.is_verified, false)
      and sd.owner_user_id is not null
      and s.owner_id = sd.owner_user_id
      as is_operator_verified,
    case
      when coalesce(sd.is_verified, false)
        and sd.owner_user_id is not null
        and s.owner_id = sd.owner_user_id
      then 'Vom Betreiber verifiziert'
      else null
    end as badge_label
  from public.spots s
  left join public.spot_descriptions sd
    on sd.spot_id = s.id
  where s.id = p_spot_id;
$$;

ALTER FUNCTION "public"."get_spot_verified_badge_v1"("p_spot_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."get_taxonomy_catalog_v1"("p_locale" "text" DEFAULT 'de'::"text", "p_category_id" "uuid" DEFAULT NULL::"uuid", "p_owner_selectable_only" boolean DEFAULT false) RETURNS TABLE("id" "uuid", "slug" "text", "node_type" "text", "parent_id" "uuid", "label" "text", "icon" "text", "color" "text", "sort_order" integer, "category_ids" "uuid"[])
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select
    tn.id,
    tn.slug,
    tn.node_type,
    tn.parent_id,
    coalesce(req.label, de.label, en.label, tn.slug) as label,
    tn.icon,
    tn.color,
    tn.sort_order,
    array_remove(array_agg(distinct tnc.category_id), null) as category_ids
  from public.taxonomy_nodes tn
  left join public.taxonomy_node_translations req
    on req.taxonomy_node_id = tn.id
   and req.locale = case
     when p_locale in ('de', 'en', 'fr', 'it') then p_locale
     else 'de'
   end
  left join public.taxonomy_node_translations de
    on de.taxonomy_node_id = tn.id and de.locale = 'de'
  left join public.taxonomy_node_translations en
    on en.taxonomy_node_id = tn.id and en.locale = 'en'
  left join public.taxonomy_node_categories tnc
    on tnc.taxonomy_node_id = tn.id
  where tn.is_active = true
    and (not p_owner_selectable_only or tn.is_owner_selectable = true)
    and (
      p_category_id is null
      or not exists (
        select 1
        from public.taxonomy_node_categories x
        where x.taxonomy_node_id = tn.id
      )
      or exists (
        select 1
        from public.taxonomy_node_categories x
        where x.taxonomy_node_id = tn.id
          and x.category_id = p_category_id
      )
    )
  group by
    tn.id, tn.slug, tn.node_type, tn.parent_id,
    req.label, de.label, en.label,
    tn.icon, tn.color, tn.sort_order
  order by tn.node_type, tn.sort_order, label;
$$;

ALTER FUNCTION "public"."get_taxonomy_catalog_v1"("p_locale" "text", "p_category_id" "uuid", "p_owner_selectable_only" boolean) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_first_name text;
  v_last_name text;
  v_display_name text;
  v_avatar_url text;
  v_email text;
begin
  v_first_name := nullif(trim(coalesce(new.raw_user_meta_data->>'first_name', '')), '');
  v_last_name := nullif(trim(coalesce(new.raw_user_meta_data->>'last_name', '')), '');
  v_avatar_url := nullif(trim(coalesce(new.raw_user_meta_data->>'avatar_url', '')), '');
  v_email := nullif(trim(coalesce(new.email, new.raw_user_meta_data->>'email', '')), '');

  v_display_name := nullif(
    trim(
      concat_ws(
        ' ',
        v_first_name,
        v_last_name
      )
    ),
    ''
  );

  insert into public.profiles (
    id,
    first_name,
    last_name,
    display_name,
    avatar_url,
    contact_email,
    created_at,
    updated_at
  )
  values (
    new.id,
    v_first_name,
    v_last_name,
    v_display_name,
    v_avatar_url,
    v_email,
    now(),
    now()
  )
  on conflict (id) do update set
    first_name = coalesce(public.profiles.first_name, excluded.first_name),
    last_name = coalesce(public.profiles.last_name, excluded.last_name),
    display_name = coalesce(public.profiles.display_name, excluded.display_name),
    avatar_url = coalesce(public.profiles.avatar_url, excluded.avatar_url),
    contact_email = coalesce(public.profiles.contact_email, excluded.contact_email),
    updated_at = now();

  return new;
end;
$$;

ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."handle_new_user_profile"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.profiles (
    id,
    contact_email,
    created_at,
    updated_at
  )
  values (
    new.id,
    new.email,
    now(),
    now()
  )
  on conflict (id) do nothing;

  return new;
end;
$$;

