CREATE OR REPLACE FUNCTION "public"."has_active_consent_v1"("p_purpose_key" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_requires_consent boolean;
begin
  select cp.requires_consent
  into v_requires_consent
  from public.consent_purposes cp
  where cp.key = p_purpose_key
    and cp.is_active = true;

  if not found then
    return false;
  end if;

  if v_requires_consent = false then
    return true;
  end if;

  if auth.uid() is null then
    return false;
  end if;

  return exists (
    select 1
    from public.user_consents uc
    where uc.user_id = auth.uid()
      and uc.purpose_key = p_purpose_key
      and uc.status = 'granted'
  );
end;
$$;

ALTER FUNCTION "public"."has_active_consent_v1"("p_purpose_key" "text") OWNER TO "postgres";

