CREATE OR REPLACE FUNCTION "public"."is_admin_v1"("p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.profiles p
    where p.id = coalesce(p_user_id, auth.uid())
      and coalesce(p.is_admin, false) = true
  );
$$;

ALTER FUNCTION "public"."is_admin_v1"("p_user_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."is_super_admin"() RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $$
  select exists (
    select 1
    from public.admin_users a
    where a.user_id = auth.uid()
      and a.role = 'super_admin'
  );
$$;

ALTER FUNCTION "public"."is_super_admin"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."legal_document_content_hash_v1"("p_document_type" "text", "p_version" "text", "p_locale" "text", "p_title" "text", "p_summary" "text", "p_content_markdown" "text", "p_requires_acceptance" boolean, "p_requires_reacceptance" boolean) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  select pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(
        pg_catalog.concat_ws(
          E'\n---\n',
          coalesce(p_document_type, ''),
          coalesce(p_version, ''),
          coalesce(p_locale, ''),
          coalesce(p_title, ''),
          coalesce(p_summary, ''),
          coalesce(p_content_markdown, ''),
          coalesce(p_requires_acceptance, false)::text,
          coalesce(p_requires_reacceptance, false)::text
        ),
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;

ALTER FUNCTION "public"."legal_document_content_hash_v1"("p_document_type" "text", "p_version" "text", "p_locale" "text", "p_title" "text", "p_summary" "text", "p_content_markdown" "text", "p_requires_acceptance" boolean, "p_requires_reacceptance" boolean) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."legal_documents_protect_published_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'legal_documents_cannot_be_deleted' using errcode = '42501';
  end if;

  if old.status in ('published', 'retired') and (
    new.document_type is distinct from old.document_type
    or new.version is distinct from old.version
    or new.locale is distinct from old.locale
    or new.title is distinct from old.title
    or new.summary is distinct from old.summary
    or new.content_markdown is distinct from old.content_markdown
    or new.content_hash is distinct from old.content_hash
    or new.requires_acceptance is distinct from old.requires_acceptance
    or new.requires_reacceptance is distinct from old.requires_reacceptance
    or new.effective_at is distinct from old.effective_at
    or new.supersedes_document_id is distinct from old.supersedes_document_id
  ) then
    raise exception 'published_legal_document_is_immutable' using errcode = '42501';
  end if;

  return new;
end;
$$;

ALTER FUNCTION "public"."legal_documents_protect_published_v1"() OWNER TO "postgres";

-- Canonical hardening: track SELECT results without dereferencing an unassigned record.
CREATE OR REPLACE FUNCTION "public"."link_decision_review_v1"("p_review_id" "uuid", "p_decision_id" "uuid" DEFAULT NULL::"uuid", "p_source_context" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("linked" boolean, "decision_id" "uuid", "match_type" "text", "signal_strength" numeric, "hours_between" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_review record;
  v_candidate record;
  v_candidate_found boolean := false;
  v_match_type text := 'auto_recent_same_spot';
  v_signal numeric := 0.92;
  v_hours numeric := null;
begin
  select
    r.id,
    r.user_id,
    r.spot_id,
    r.created_at
  into v_review
  from public.reviews r
  where r.id = p_review_id
    and r.user_id = auth.uid();

  if not found then
    return query select false, null::uuid, 'review_not_found_or_not_owned'::text, 0::numeric, null::numeric;
    return;
  end if;

  if p_decision_id is not null then
    select
      s.id as decision_id,
      s.created_at as decision_created_at,
      di.rank,
      di.why_this,
      (
        select a.action
        from public.decision_actions a
        where a.decision_id = s.id
          and a.spot_id = v_review.spot_id
        order by a.created_at desc
        limit 1
      ) as last_action
    into v_candidate
    from public.decision_sessions s
    join public.decision_impressions di
      on di.decision_id = s.id
     and di.spot_id = v_review.spot_id
    where s.id = p_decision_id
      and s.user_id = v_review.user_id
    limit 1;

    v_candidate_found := found;

    if v_candidate_found then
      v_match_type := 'explicit_decision_review';
      v_signal := 1.45;
      v_hours := extract(epoch from (v_review.created_at - v_candidate.decision_created_at)) / 3600.0;
    end if;
  end if;

  -- Auto magic: if no explicit decision was passed, find the strongest recent same-spot decision signal.
  if not v_candidate_found then
    select
      s.id as decision_id,
      s.created_at as decision_created_at,
      di.rank,
      di.why_this,
      (
        select a.action
        from public.decision_actions a
        where a.decision_id = s.id
          and a.spot_id = v_review.spot_id
        order by a.created_at desc
        limit 1
      ) as last_action
    into v_candidate
    from public.decision_sessions s
    join public.decision_impressions di
      on di.decision_id = s.id
     and di.spot_id = v_review.spot_id
    where s.user_id = v_review.user_id
      and s.created_at <= v_review.created_at
      and s.created_at >= v_review.created_at - interval '12 hours'
    order by
      case
        when exists (
          select 1 from public.decision_actions a
          where a.decision_id = s.id
            and a.spot_id = v_review.spot_id
            and a.action in ('was_here','exact_mood')
        ) then 5
        when exists (
          select 1 from public.decision_actions a
          where a.decision_id = s.id
            and a.spot_id = v_review.spot_id
            and a.action = 'tapped'
        ) then 4
        else 2
      end desc,
      di.rank asc,
      s.created_at desc
    limit 1;

    v_candidate_found := found;

    if v_candidate_found then
      v_match_type := 'auto_recent_same_spot';
      v_signal := case
        when v_candidate.last_action in ('was_here','exact_mood') then 1.25
        when v_candidate.last_action = 'tapped' then 1.10
        else 0.92
      end;
      v_hours := extract(epoch from (v_review.created_at - v_candidate.decision_created_at)) / 3600.0;
    end if;
  end if;

  if not v_candidate_found then
    return query select false, null::uuid, 'no_recent_decision_match'::text, 0::numeric, null::numeric;
    return;
  end if;

  insert into public.backyrd_decision_review_links_v1 (
    user_id,
    decision_id,
    review_id,
    spot_id,
    match_type,
    signal_strength,
    decision_created_at,
    review_created_at,
    hours_between,
    context
  )
  values (
    v_review.user_id,
    v_candidate.decision_id,
    v_review.id,
    v_review.spot_id,
    v_match_type,
    v_signal,
    v_candidate.decision_created_at,
    v_review.created_at,
    v_hours,
    coalesce(p_source_context, '{}'::jsonb)
      || jsonb_build_object(
        'decision_rank', v_candidate.rank,
        'decision_why_this', v_candidate.why_this,
        'decision_last_action', v_candidate.last_action,
        'linked_by', 'link_decision_review_v1'
      )
  )
  on conflict (review_id) do update set
    decision_id = excluded.decision_id,
    spot_id = excluded.spot_id,
    match_type = excluded.match_type,
    signal_strength = greatest(public.backyrd_decision_review_links_v1.signal_strength, excluded.signal_strength),
    decision_created_at = excluded.decision_created_at,
    review_created_at = excluded.review_created_at,
    hours_between = excluded.hours_between,
    context = public.backyrd_decision_review_links_v1.context || excluded.context;

  -- Upgrade the feed moment if this review already has a social post.
  update public.social_posts sp
  set
    source_type = 'decision_review',
    source_context = coalesce(sp.source_context, '{}'::jsonb)
      || coalesce(p_source_context, '{}'::jsonb)
      || jsonb_build_object(
        'decision_id', v_candidate.decision_id,
        'decision_rank', v_candidate.rank,
        'decision_match_type', v_match_type,
        'decision_signal_strength', v_signal,
        'hours_between_decision_and_review', v_hours
      )
  where sp.review_id = v_review.id;

  return query select true, v_candidate.decision_id, v_match_type, v_signal, v_hours;
end;
$$;

ALTER FUNCTION "public"."link_decision_review_v1"("p_review_id" "uuid", "p_decision_id" "uuid", "p_source_context" "jsonb") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."list_city_moods"("p_city" "text", "p_limit" integer DEFAULT 30, "p_q" "text" DEFAULT NULL::"text") RETURNS TABLE("token" "text", "token_norm" "text", "usage_count" bigint)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with base as (
    select
      mt.token,
      mt.token_norm,
      sum(sma.mood_count)::bigint as usage_count
    from public.spots s
    join public.spot_moods_agg sma on sma.spot_id = s.id
    join public.mood_tokens mt on mt.id = sma.mood_id
    where s.status = 'approved'
      and s.city is not null
      and lower(s.city) = lower(trim(p_city))
      and (
        p_q is null
        or mt.token_norm like (lower(trim(p_q)) || '%')
        or mt.token like (trim(p_q) || '%')
      )
    group by mt.token, mt.token_norm
  )
  select *
  from base
  order by usage_count desc, token asc
  limit greatest(1, least(p_limit, 50));
$$;

ALTER FUNCTION "public"."list_city_moods"("p_city" "text", "p_limit" integer, "p_q" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."list_city_moods"("p_city" "text", "p_q" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 30) RETURNS TABLE("token" "text", "token_norm" "text", "uses" integer)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with city_spots as (
    select id
    from public.spots
    where status = 'approved'
      and city is not null
      and lower(city) = lower(trim(p_city))
  ),
  city_moods as (
    select
      sma.mood_id,
      sum(sma.mood_count)::int as uses
    from public.spot_moods_agg sma
    join city_spots cs on cs.id = sma.spot_id
    group by sma.mood_id
  )
  select
    mt.token,
    mt.token_norm,
    cm.uses
  from city_moods cm
  join public.mood_tokens mt on mt.id = cm.mood_id
  where
    p_q is null
    or mt.token_norm like lower(trim(p_q)) || '%'
  order by
    cm.uses desc,
    mt.token_norm asc
  limit greatest(1, least(p_limit, 50));
$$;

ALTER FUNCTION "public"."list_city_moods"("p_city" "text", "p_q" "text", "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."log_decision_action_v1"("p_decision_id" "uuid", "p_spot_id" "uuid", "p_action" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.backyrd_log_decision_action_v1(
    p_decision_id := p_decision_id,
    p_spot_id := p_spot_id,
    p_action := p_action
  );
end;
$$;

ALTER FUNCTION "public"."log_decision_action_v1"("p_decision_id" "uuid", "p_spot_id" "uuid", "p_action" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."log_decision_impressions_v1"("p_decision_id" "uuid", "p_spot_ids" "uuid"[], "p_why_this" "text"[] DEFAULT NULL::"text"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  i int;
  v_user uuid;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'not_authenticated' using errcode = 'P0001';
  end if;

  -- ownership check
  if not exists (
    select 1 from public.decision_sessions ds
    where ds.id = p_decision_id and ds.user_id = v_user
  ) then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;

  if p_spot_ids is null or array_length(p_spot_ids,1) is null then
    return;
  end if;

  for i in 1..array_length(p_spot_ids,1) loop
    insert into public.decision_impressions(decision_id, spot_id, rank, why_this)
    values (
      p_decision_id,
      p_spot_ids[i],
      i,
      case
        when p_why_this is null then null
        when array_length(p_why_this,1) is null then null
        else p_why_this[i]
      end
    )
    on conflict (decision_id, spot_id)
    do update set rank = excluded.rank, why_this = excluded.why_this;
  end loop;
end;
$$;

ALTER FUNCTION "public"."log_decision_impressions_v1"("p_decision_id" "uuid", "p_spot_ids" "uuid"[], "p_why_this" "text"[]) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."log_social_feed_event_v1"("p_event_type" "text", "p_post_id" "uuid" DEFAULT NULL::"uuid", "p_spot_id" "uuid" DEFAULT NULL::"uuid", "p_context" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_event_type text := lower(trim(coalesce(p_event_type, '')));
  v_id uuid;
  v_spot_id uuid := p_spot_id;
begin
  if v_user_id is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  if v_event_type not in (
    'post_impression',
    'post_open',
    'post_like',
    'post_unlike',
    'post_save',
    'post_unsave',
    'post_comment',
    'spot_open_from_post',
    'follow_user',
    'unfollow_user',
    'hide_post'
  ) then
    raise exception 'invalid_event_type';
  end if;

  if p_post_id is not null and v_spot_id is null then
    select p.spot_id
    into v_spot_id
    from public.social_posts p
    where p.id = p_post_id;
  end if;

  insert into public.social_feed_events (
    user_id,
    post_id,
    spot_id,
    event_type,
    context
  )
  values (
    v_user_id,
    p_post_id,
    v_spot_id,
    v_event_type,
    coalesce(p_context, '{}'::jsonb)
  )
  returning id into v_id;

  return v_id;
end;
$$;

ALTER FUNCTION "public"."log_social_feed_event_v1"("p_event_type" "text", "p_post_id" "uuid", "p_spot_id" "uuid", "p_context" "jsonb") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."map_shadow_user_v1"("p_handle" "text", "p_real_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare v_shadow_id uuid;
begin
  select id into v_shadow_id from public.shadow_users where handle = p_handle;
  if v_shadow_id is null then
    raise exception 'shadow_user_not_found';
  end if;

  insert into public.shadow_user_map(shadow_user_id, real_user_id)
  values (v_shadow_id, p_real_user_id)
  on conflict (shadow_user_id) do update
    set real_user_id = excluded.real_user_id;
end;
$$;

ALTER FUNCTION "public"."map_shadow_user_v1"("p_handle" "text", "p_real_user_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."mark_chat_read_v1"("p_chat_id" "uuid") RETURNS TABLE("chat_id" "uuid", "marked_count" integer, "read_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_me uuid := auth.uid();
  v_now timestamptz := now();
  v_count integer := 0;
begin
  if v_me is null then
    raise exception 'not_authenticated'
      using errcode = '28000';
  end if;

  if p_chat_id is null then
    raise exception 'chat_id_required';
  end if;

  if not exists (
    select 1
    from public.chats c
    where c.id = p_chat_id
      and (
        c.user_a = v_me
        or c.user_b = v_me
      )
  ) then
    raise exception 'chat_not_accessible'
      using errcode = '42501';
  end if;

  update public.messages m
  set seen_at = v_now
  where m.chat_id = p_chat_id
    and m.sender_id <> v_me
    and m.seen_at is null;

  get diagnostics v_count = row_count;

  chat_id := p_chat_id;
  marked_count := v_count;
  read_at := v_now;
  return next;
end;
$$;

ALTER FUNCTION "public"."mark_chat_read_v1"("p_chat_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."match_mood"("input" "text") RETURNS integer
    LANGUAGE "plpgsql" STABLE
    AS $$
declare
  norm text := lower(trim(input));
  mid integer;
begin
  -- 1) direct match with token
  select id into mid
  from mood_tokens
  where lower(token) = norm
  limit 1;

  if mid is not null then
    return mid;
  end if;

  -- 2) match synonyms
  select token_id into mid
  from mood_synonyms
  where lower(synonym) = norm
  limit 1;

  return mid;
end;
$$;

ALTER FUNCTION "public"."match_mood"("input" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."match_spots_semantic_v1"("p_city" "text", "p_query" "text", "p_limit" integer DEFAULT 3, "p_seen_spot_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS TABLE("spot_id" "uuid", "score" integer, "matched_terms" "text"[], "why_semantic" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with
  q as (
    select
      lower(trim(coalesce(p_query,''))) as query_norm
  ),
  terms as (
    -- split on whitespace + commas, keep terms length >= 3
    select distinct t as term
    from q,
    unnest(regexp_split_to_array(q.query_norm, '[\s,]+')) as t
    where length(trim(t)) >= 3
  ),
  base as (
    select s.id, s.name, s.city, s.category_id, s.price_level, s.created_at
    from public.spots s
    where s.status = 'approved'
      and s.city is not null
      and lower(s.city) = lower(trim(p_city))
      and (
        p_seen_spot_ids is null
        or array_length(p_seen_spot_ids, 1) is null
        or not (s.id = any(p_seen_spot_ids))
      )
  ),
  content as (
    select
      b.*,
      ec.description_source,
      ec.effective_description,
      ec.effective_keywords
    from base b
    left join public.spot_effective_content_v1 ec on ec.spot_id = b.id
  ),
  hits as (
    select
      c.id as spot_id,
      c.name,
      c.category_id,
      c.price_level,
      c.description_source,
      c.effective_description,
      c.effective_keywords,

      -- count keyword hits
      coalesce((
        select count(*)
        from terms t
        where c.effective_keywords is not null
          and exists (
            select 1
            from unnest(c.effective_keywords) kw
            where lower(trim(kw)) = t.term
               or lower(trim(kw)) like t.term || '%'
               or t.term like lower(trim(kw)) || '%'
          )
      ), 0) as kw_hits,

      -- count description hits
      coalesce((
        select count(*)
        from terms t
        where c.effective_description is not null
          and lower(c.effective_description) like '%' || t.term || '%'
      ), 0) as desc_hits,

      -- collect matched terms (best-effort)
      coalesce((
        select array_agg(t.term order by t.term)
        from terms t
        where
          (c.effective_keywords is not null and exists (
            select 1 from unnest(c.effective_keywords) kw
            where lower(trim(kw)) = t.term
               or lower(trim(kw)) like t.term || '%'
               or t.term like lower(trim(kw)) || '%'
          ))
          or (c.effective_description is not null and lower(c.effective_description) like '%' || t.term || '%')
      ), '{}'::text[]) as matched_terms

    from content c
  ),
  scored as (
    select
      h.spot_id,
      (h.kw_hits * 3 + h.desc_hits) as score,
      h.matched_terms,
      (
        'Ich kenne deine Moods noch nicht als Review-Signal — aber ich habe "' || coalesce((select query_norm from q), '') || '" '
        || 'mit ' || coalesce((select name from public.categories c where c.id = h.category_id), 'dem Ort') || ' abgeglichen'
        || case when h.price_level is not null then ' (Preis: ' || repeat('€', greatest(1, least(h.price_level, 4))) || ')' else '' end
        || case
            when array_length(h.matched_terms, 1) is not null and array_length(h.matched_terms, 1) > 0
              then '. Passt wegen: ' || array_to_string(h.matched_terms[1:least(array_length(h.matched_terms,1),3)], ', ') || '.'
            else '. Ich habe keinen exakten Begriff getroffen – aber das ist ein plausibler Tipp in deiner Stadt.'
           end
        || case
            when h.description_source is not null
              then ' (Quelle: ' || h.description_source || ')'
            else ' (Quelle: keine Description vorhanden)'
           end
      ) as why_semantic
    from hits h
  )
  select
    s.spot_id,
    s.score,
    s.matched_terms,
    s.why_semantic
  from scored s
  where s.score > 0
  order by s.score desc
  limit greatest(1, least(p_limit, 3));
$$;

ALTER FUNCTION "public"."match_spots_semantic_v1"("p_city" "text", "p_query" "text", "p_limit" integer, "p_seen_spot_ids" "uuid"[]) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."mood_tokens_set_token_norm"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  new.token_norm := lower(trim(new.token));
  return new;
end;
$$;

ALTER FUNCTION "public"."mood_tokens_set_token_norm"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."normalize_mood_text"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select lower(trim(regexp_replace(coalesce(p_text,''), '\s+', ' ', 'g')));
$$;

