CREATE OR REPLACE FUNCTION "public"."owner_decision_intelligence_v1"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare v_owner uuid:=auth.uid(); r jsonb;
begin
 if v_owner is null then raise exception 'not_authenticated' using errcode='42501'; end if;
 with owned as (select id,name from public.spots where owner_id::text=v_owner::text), ev as (
  select e.*,o.name spot_name from public.analytics_events e join owned o on o.id::text=e.spot_id::text
  where e.occurred_at>=p_from and e.occurred_at<p_to and e.event_name like 'decision_%'
 ), spots as (
  select spot_id,max(spot_name) spot_name,
   count(*) filter(where event_name='decision_spot_impression') impressions,
   count(*) filter(where event_name='decision_spot_opened') opens,
   count(*) filter(where event_name='decision_like') likes,
   count(*) filter(where event_name='decision_dislike') dislikes,
   case when count(*) filter(where event_name='decision_spot_impression')>0 then round(count(*) filter(where event_name='decision_spot_opened')*100.0/count(*) filter(where event_name='decision_spot_impression'),1) else 0 end ctr
  from ev group by spot_id order by impressions desc
 ), daily as (
  select date_trunc('day',occurred_at)::date metric_day,
   count(*) filter(where event_name='decision_spot_impression') impressions,
   count(*) filter(where event_name='decision_spot_opened') opens,
   count(*) filter(where event_name='decision_like') likes,
   count(*) filter(where event_name='decision_dislike') dislikes
  from ev group by 1 order by 1
 )
 select jsonb_build_object('summary',jsonb_build_object(
  'impressions',(select count(*) from ev where event_name='decision_spot_impression'),
  'opens',(select count(*) from ev where event_name='decision_spot_opened'),
  'likes',(select count(*) from ev where event_name='decision_like'),
  'dislikes',(select count(*) from ev where event_name='decision_dislike'),
  'ctr',(select case when count(*) filter(where event_name='decision_spot_impression')>0 then round(count(*) filter(where event_name='decision_spot_opened')*100.0/count(*) filter(where event_name='decision_spot_impression'),1) else 0 end from ev),
  'positive_rate',(select case when count(*) filter(where event_name in('decision_like','decision_dislike'))>0 then round(count(*) filter(where event_name='decision_like')*100.0/count(*) filter(where event_name in('decision_like','decision_dislike')),1) else 0 end from ev)
 ),'spots',coalesce((select jsonb_agg(to_jsonb(x)) from spots x),'[]'::jsonb),'daily',coalesce((select jsonb_agg(to_jsonb(x) order by x.metric_day) from daily x),'[]'::jsonb)) into r;
 return r;
end; $$;

ALTER FUNCTION "public"."owner_decision_intelligence_v1"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."owner_intelligence_overview_v1"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare
  v_owner uuid := auth.uid();
  r jsonb;
begin
  if v_owner is null then raise exception 'not_authenticated' using errcode='42501'; end if;
  if p_from is null or p_to is null or p_from >= p_to then raise exception 'invalid_period'; end if;

  with owned as (
    select id,name,city,status,header_photo_path from public.spots where owner_id::text=v_owner::text
  ), ev as (
    select e.* from public.analytics_events e join owned o on o.id::text=e.spot_id::text
    where e.occurred_at>=p_from and e.occurred_at<p_to
  ), daily as (
    select date_trunc('day',occurred_at)::date metric_day,
      count(*) filter(where event_name in('spot_opened','spot_detail_opened','decision_spot_opened','map_spot_opened','feed_spot_opened','profile_spot_opened','profile_favorite_spot_opened','nearby_spot_opened')) views,
      count(distinct user_id) visitors,
      count(*) filter(where event_name='decision_spot_impression') impressions,
      count(*) filter(where event_name='decision_spot_opened') decision_opens,
      count(*) filter(where event_name in('spot_route_clicked','spot_website_clicked','spot_phone_clicked')) intent
    from ev group by 1 order by 1
  ), spot_rows as (
    select o.id spot_id,o.name,o.city,o.status,o.header_photo_path,
      count(e.*) filter(where e.event_name in('spot_opened','spot_detail_opened','decision_spot_opened','map_spot_opened','feed_spot_opened','profile_spot_opened','profile_favorite_spot_opened','nearby_spot_opened')) views,
      count(distinct e.user_id) visitors,
      count(e.*) filter(where e.event_name='decision_spot_impression') impressions,
      count(e.*) filter(where e.event_name='decision_spot_opened') decision_opens,
      count(e.*) filter(where e.event_name='spot_route_clicked') route_clicks,
      count(e.*) filter(where e.event_name='spot_website_clicked') website_clicks,
      count(e.*) filter(where e.event_name='spot_phone_clicked') phone_clicks,
      (select count(*) from public.reviews rv where rv.spot_id::text=o.id::text and rv.created_at>=p_from and rv.created_at<p_to) reviews
    from owned o left join ev e on e.spot_id::text=o.id::text group by o.id,o.name,o.city,o.status,o.header_photo_path
  )
  select jsonb_build_object(
    'summary',jsonb_build_object(
      'spots',(select count(*) from owned),
      'views',(select count(*) from ev where event_name in('spot_opened','spot_detail_opened','decision_spot_opened','map_spot_opened','feed_spot_opened','profile_spot_opened','profile_favorite_spot_opened','nearby_spot_opened')),
      'visitors',(select count(distinct user_id) from ev),
      'impressions',(select count(*) from ev where event_name='decision_spot_impression'),
      'decision_opens',(select count(*) from ev where event_name='decision_spot_opened'),
      'decision_ctr',(select case when count(*) filter(where event_name='decision_spot_impression')>0 then round(count(*) filter(where event_name='decision_spot_opened')*100.0/count(*) filter(where event_name='decision_spot_impression'),1) else 0 end from ev),
      'reviews',(select count(*) from public.reviews rv join owned o on o.id::text=rv.spot_id::text where rv.created_at>=p_from and rv.created_at<p_to),
      'route_clicks',(select count(*) from ev where event_name='spot_route_clicked'),
      'website_clicks',(select count(*) from ev where event_name='spot_website_clicked'),
      'phone_clicks',(select count(*) from ev where event_name='spot_phone_clicked')
    ),
    'daily',coalesce((select jsonb_agg(to_jsonb(x) order by x.metric_day) from daily x),'[]'::jsonb),
    'spots',coalesce((select jsonb_agg(to_jsonb(x) order by x.views desc,x.name) from spot_rows x),'[]'::jsonb),
    'sources',coalesce((select jsonb_agg(to_jsonb(x)) from (
      select coalesce(nullif(properties->>'source',''),screen_name,'direct') source,count(*) events,count(distinct user_id) visitors
      from ev where event_name in('spot_opened','spot_detail_opened','decision_spot_opened','map_spot_opened','feed_spot_opened','profile_spot_opened','profile_favorite_spot_opened','nearby_spot_opened')
      group by 1 order by 2 desc
    ) x),'[]'::jsonb)
  ) into r;
  return r;
end; $$;

