CREATE OR REPLACE FUNCTION "public"."owner_moments_intelligence_v1"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare v_owner uuid:=auth.uid(); r jsonb;
begin
 if v_owner is null then raise exception 'not_authenticated' using errcode='42501'; end if;
 with owned as (select id,name from public.spots where owner_id::text=v_owner::text), posts as (
  select p.*,o.name spot_name from public.social_posts p join owned o on o.id::text=p.spot_id::text where p.created_at>=p_from and p.created_at<p_to
 ), shares as (
  select a.entity_id::text post_id,count(*) shares from public.analytics_events a where a.event_name='feed_post_shared' and a.occurred_at>=p_from and a.occurred_at<p_to group by 1
 ), rows as (
  select p.id post_id,p.spot_id,p.spot_name,p.caption,p.created_at,coalesce(p.like_count,0) likes,coalesce(p.comment_count,0) comments,coalesce(p.save_count,0) saves,coalesce(s.shares,0) shares,
   coalesce(p.like_count,0)+coalesce(p.comment_count,0)*2+coalesce(p.save_count,0)*2+coalesce(s.shares,0)*2 engagement_score
  from posts p left join shares s on s.post_id=p.id::text order by engagement_score desc,p.created_at desc
 )
 select jsonb_build_object('summary',jsonb_build_object(
  'posts',(select count(*) from posts),'likes',(select coalesce(sum(like_count),0) from posts),'comments',(select coalesce(sum(comment_count),0) from posts),'saves',(select coalesce(sum(save_count),0) from posts),'shares',(select coalesce(sum(shares),0) from shares where post_id in(select id::text from posts)),
  'engagement',(select coalesce(sum(engagement_score),0) from rows)
 ),'posts',coalesce((select jsonb_agg(to_jsonb(x)) from rows x),'[]'::jsonb)) into r;
 return r;
end; $$;

