CREATE OR REPLACE FUNCTION "public"."owner_spot_performance_v1"("p_spot_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
declare v_owner uuid:=auth.uid(); r jsonb;
begin
 if v_owner is null then raise exception 'not_authenticated' using errcode='42501'; end if;
 if not exists(select 1 from public.spots where id::text=p_spot_id::text and owner_id::text=v_owner::text) then raise exception 'not_authorized' using errcode='42501'; end if;
 with ev as (select * from public.analytics_events where spot_id::text=p_spot_id::text and occurred_at>=p_from and occurred_at<p_to), daily as (
  select date_trunc('day',occurred_at)::date metric_day,
   count(*) filter(where event_name in('spot_opened','spot_detail_opened','decision_spot_opened','map_spot_opened','feed_spot_opened','profile_spot_opened','profile_favorite_spot_opened','nearby_spot_opened')) views,
   count(distinct user_id) visitors,count(*) filter(where event_name='decision_spot_impression') impressions,count(*) filter(where event_name='decision_spot_opened') opens,
   count(*) filter(where event_name in('spot_route_clicked','spot_website_clicked','spot_phone_clicked')) intent
  from ev group by 1 order by 1
 )
 select jsonb_build_object('spot',(select to_jsonb(x) from(select id,name,city,status,header_photo_path from public.spots where id::text=p_spot_id::text)x),
 'summary',jsonb_build_object(
  'views',(select count(*) from ev where event_name in('spot_opened','spot_detail_opened','decision_spot_opened','map_spot_opened','feed_spot_opened','profile_spot_opened','profile_favorite_spot_opened','nearby_spot_opened')),
  'visitors',(select count(distinct user_id) from ev),'impressions',(select count(*) from ev where event_name='decision_spot_impression'),'opens',(select count(*) from ev where event_name='decision_spot_opened'),
  'ctr',(select case when count(*) filter(where event_name='decision_spot_impression')>0 then round(count(*) filter(where event_name='decision_spot_opened')*100.0/count(*) filter(where event_name='decision_spot_impression'),1) else 0 end from ev),
  'reviews',(select count(*) from public.reviews where spot_id::text=p_spot_id::text and created_at>=p_from and created_at<p_to),
  'favorites',(select count(*) from public.favorites where spot_id::text=p_spot_id::text),
  'route_clicks',(select count(*) from ev where event_name='spot_route_clicked'),'website_clicks',(select count(*) from ev where event_name='spot_website_clicked'),'phone_clicks',(select count(*) from ev where event_name='spot_phone_clicked')
 ),'daily',coalesce((select jsonb_agg(to_jsonb(x) order by x.metric_day) from daily x),'[]'::jsonb),
 'sources',coalesce((select jsonb_agg(to_jsonb(x)) from(select coalesce(nullif(properties->>'source',''),screen_name,'direct') source,count(*) events from ev group by 1 order by 2 desc)x),'[]'::jsonb)) into r;
 return r;
end; $$;

