CREATE OR REPLACE FUNCTION "public"."privacy_is_admin_v1"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.profiles p
    where p.id = auth.uid()
      and coalesce(p.is_admin, false) = true
  );
$$;

ALTER FUNCTION "public"."privacy_is_admin_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."private_start_spot_claim_email_verification_v1"("p_user_id" "uuid", "p_spot_id" "uuid", "p_business_email" "text", "p_claimant_name" "text" DEFAULT NULL::"text", "p_claimant_role" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text") RETURNS TABLE("ok" boolean, "verification_id" "uuid", "spot_id" "uuid", "business_email" "text", "business_domain" "text", "code" "text", "expires_at" timestamp with time zone, "domain_match_score" numeric, "domain_match_reason" "text", "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $$
declare
  v_role text := coalesce(
    nullif(auth.role(), ''),
    nullif(current_setting('request.jwt.claim.role', true), ''),
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role',
    ''
  );

  v_auth_uid uuid := auth.uid();
  v_is_admin boolean := false;

  v_code text;
  v_hash text;
  v_match record;
  v_verification_id uuid;
  v_expires_at timestamptz := now() + interval '15 minutes';
begin
  if v_auth_uid is not null then
    select coalesce(p.is_admin, false)
    into v_is_admin
    from public.profiles p
    where p.id = v_auth_uid;
  end if;

  if v_role <> 'service_role'
     and coalesce(v_is_admin, false) is not true then
    raise exception 'service_role_required'
      using errcode = '42501';
  end if;

  if p_user_id is null then
    raise exception 'user_id_required';
  end if;

  if p_spot_id is null then
    raise exception 'spot_id_required';
  end if;

  if p_business_email is null
     or trim(p_business_email) = '' then
    raise exception 'business_email_required';
  end if;

  if not exists (
    select 1
    from public.profiles p
    where p.id = p_user_id
  ) then
    raise exception 'user_not_found';
  end if;

  if not exists (
    select 1
    from public.spots s
    where s.id = p_spot_id
  ) then
    raise exception 'spot_not_found';
  end if;

  select *
  into v_match
  from public.backyrd_claim_domain_match_v1(
    p_spot_id,
    lower(trim(p_business_email))
  )
  limit 1;

  if not coalesce(v_match.allowed, false) then
    raise exception '%', coalesce(v_match.reason, 'business_domain_not_allowed')
      using errcode = '42501';
  end if;

  v_code := lpad(floor(random() * 1000000)::integer::text, 6, '0');

  v_hash := encode(
    extensions.digest(convert_to(v_code, 'UTF8'), 'sha256'),
    'hex'
  );

  insert into public.spot_claim_email_verifications_v1 (
    spot_id,
    user_id,
    claimant_name,
    claimant_role,
    note,
    email,
    email_domain,
    code_hash,
    expires_at,
    attempts,
    status,
    domain_match_score,
    domain_match_reason,
    created_at,
    updated_at
  )
  values (
    p_spot_id,
    p_user_id,
    nullif(trim(coalesce(p_claimant_name, '')), ''),
    nullif(trim(coalesce(p_claimant_role, '')), ''),
    nullif(trim(coalesce(p_note, '')), ''),
    lower(trim(p_business_email)),
    v_match.email_domain,
    v_hash,
    v_expires_at,
    0,
    'pending',
    v_match.score,
    v_match.reason,
    now(),
    now()
  )
  returning id into v_verification_id;

  ok := true;
  verification_id := v_verification_id;
  spot_id := p_spot_id;
  business_email := lower(trim(p_business_email));
  business_domain := v_match.email_domain;
  code := v_code;
  expires_at := v_expires_at;
  domain_match_score := v_match.score;
  domain_match_reason := v_match.reason;
  message := 'claim_email_verification_started';

  return next;
end;
$$;

ALTER FUNCTION "public"."private_start_spot_claim_email_verification_v1"("p_user_id" "uuid", "p_spot_id" "uuid", "p_business_email" "text", "p_claimant_name" "text", "p_claimant_role" "text", "p_note" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."profiles_protect_privileged_fields_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  -- Service-role/database administration is allowed.
  -- Normal authenticated users may never change privileged fields.
  if auth.uid() is not null
     and not public.privacy_is_admin_v1() then

    if tg_op = 'INSERT' then
      new.is_admin := false;
    elsif tg_op = 'UPDATE' then
      new.is_admin := old.is_admin;
    end if;
  end if;

  return new;
end;
$$;

