CREATE OR REPLACE FUNCTION "public"."rebuild_user_taste_profile_v1"("p_user_id" "uuid", "p_min_cluster_confidence" numeric DEFAULT 0.65, "p_min_qualified_actions" integer DEFAULT 5) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_user_id is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  delete from public.user_taste_moods_v1 where user_id = p_user_id;
  delete from public.user_taste_time_v1 where user_id = p_user_id;
  delete from public.user_taste_profile_v1 where user_id = p_user_id;

  with
  qa as (
    select
      a.decision_id,
      a.spot_id,
      a.action,
      a.created_at as action_at
    from public.decision_actions a
    join public.decision_sessions s on s.id = a.decision_id
    where s.user_id = p_user_id
      and a.action in ('exact_mood','was_here','not_there')
  ),

  weighted as (
    select
      q.*,
      case q.action
        when 'exact_mood' then 1.0
        when 'was_here' then 0.6
        when 'not_there' then -0.8
        else 0
      end::numeric as base_w,

      case
        when (now() - q.action_at) <= interval '14 days' then 1.0
        when (now() - q.action_at) <= interval '60 days' then 0.6
        else 0.3
      end::numeric as decay,

      case
        when extract(hour from timezone('Europe/Zurich', q.action_at)) between 6 and 11 then 'morning'
        when extract(hour from timezone('Europe/Zurich', q.action_at)) between 12 and 16 then 'afternoon'
        when extract(hour from timezone('Europe/Zurich', q.action_at)) between 17 and 22 then 'evening'
        else 'night'
      end::text as time_bucket
    from qa q
  ),

  act_sessions as (
    select
      w.*,
      (w.base_w * w.decay) as w_eff,
      s.mood_a_text,
      s.mood_b_text
    from weighted w
    join public.decision_sessions s on s.id = w.decision_id
  ),

  ra as (
    select
      a.decision_id,
      public.resolve_mood_input_v2(a.mood_a_text) as r
    from (select distinct decision_id, mood_a_text from act_sessions) a
  ),
  rb as (
    select
      a.decision_id,
      public.resolve_mood_input_v2(a.mood_b_text) as r
    from (select distinct decision_id, mood_b_text from act_sessions) a
  ),

  ta as (
    select
      ra.decision_id,
      t.mood_id
    from ra
    join lateral public.expand_resolved_targets(
      (ra.r).resolved_via,
      (ra.r).resolved_token_id,
      (ra.r).cluster_id,
      p_min_cluster_confidence
    ) t on true
  ),
  tb as (
    select
      rb.decision_id,
      t.mood_id
    from rb
    join lateral public.expand_resolved_targets(
      (rb.r).resolved_via,
      (rb.r).resolved_token_id,
      (rb.r).cluster_id,
      p_min_cluster_confidence
    ) t on true
  ),

  decision_spots as (
    select distinct decision_id, spot_id
    from act_sessions
  ),

  a_strength as (
    select
      ds.decision_id,
      ds.spot_id,
      coalesce(sum(v.mood_count),0)::numeric as a_cnt
    from decision_spots ds
    left join ta on ta.decision_id = ds.decision_id
    left join public.spot_moods_agg_reviews_v1 v
      on v.spot_id = ds.spot_id and v.mood_id = ta.mood_id
    group by ds.decision_id, ds.spot_id
  ),
  b_strength as (
    select
      ds.decision_id,
      ds.spot_id,
      coalesce(sum(v.mood_count),0)::numeric as b_cnt
    from decision_spots ds
    left join tb on tb.decision_id = ds.decision_id
    left join public.spot_moods_agg_reviews_v1 v
      on v.spot_id = ds.spot_id and v.mood_id = tb.mood_id
    group by ds.decision_id, ds.spot_id
  ),

  act_enriched as (
    select
      a.*,
      coalesce(asg.a_cnt,0) as a_cnt,
      coalesce(bsg.b_cnt,0) as b_cnt,
      greatest(coalesce(asg.a_cnt,0) + coalesce(bsg.b_cnt,0), 0)::numeric as sum_cnt
    from act_sessions a
    left join a_strength asg on asg.decision_id = a.decision_id and asg.spot_id = a.spot_id
    left join b_strength bsg on bsg.decision_id = a.decision_id and bsg.spot_id = a.spot_id
  ),

  mood_contrib as (
    select
      ta.mood_id,
      ae.action_at,
      case when ae.sum_cnt > 0 then ae.w_eff * (ae.a_cnt / ae.sum_cnt) else null end as contrib
    from act_enriched ae
    join ta on ta.decision_id = ae.decision_id

    union all

    select
      tb.mood_id,
      ae.action_at,
      case when ae.sum_cnt > 0 then ae.w_eff * (ae.b_cnt / ae.sum_cnt) else null end as contrib
    from act_enriched ae
    join tb on tb.decision_id = ae.decision_id
  ),

  mood_agg as (
    select
      p_user_id as user_id,
      mc.mood_id,
      sum(mc.contrib)::numeric as affinity_raw,
      count(*)::integer as signals_count,
      sum(case when mc.contrib > 0 then 1 else 0 end)::integer as positive_count,
      sum(case when mc.contrib < 0 then 1 else 0 end)::integer as negative_count,
      max(mc.action_at) as last_signal_at
    from mood_contrib mc
    where mc.contrib is not null
    group by mc.mood_id
  ),

  mood_norm as (
    select
      m.*,
      greatest(-2.0, least(2.0, m.affinity_raw))::numeric as affinity_score
    from mood_agg m
  ),

  time_agg as (
    select
      p_user_id as user_id,
      ae.time_bucket,
      sum(ae.w_eff)::numeric as affinity_raw,
      count(*)::integer as signals_count,
      sum(case when ae.w_eff > 0 then 1 else 0 end)::integer as positive_count,
      sum(case when ae.w_eff < 0 then 1 else 0 end)::integer as negative_count,
      max(ae.action_at) as last_signal_at
    from act_enriched ae
    group by ae.time_bucket
  ),

  time_norm as (
    select
      t.*,
      greatest(-2.0, least(2.0, t.affinity_raw))::numeric as affinity_score
    from time_agg t
  ),

  overall as (
    select
      count(*)::integer as qualified_actions,
      case
        when count(*) < p_min_qualified_actions then 0::numeric
        else least(1::numeric, (ln(1 + count(*)::numeric) / ln(1 + 25::numeric)))
      end as confidence
    from qa
  ),

  ins_moods as (
    insert into public.user_taste_moods_v1(
      user_id, mood_id, affinity_score, confidence,
      signals_count, positive_count, negative_count, last_signal_at, updated_at
    )
    select
      mn.user_id,
      mn.mood_id,
      mn.affinity_score,
      case
        when (select qualified_actions from overall) < p_min_qualified_actions then 0::numeric
        else least(1::numeric, (ln(1 + mn.signals_count::numeric) / ln(1 + 12::numeric)))
      end as confidence,
      mn.signals_count,
      mn.positive_count,
      mn.negative_count,
      mn.last_signal_at,
      now()
    from mood_norm mn
    returning 1
  ),

  ins_time as (
    insert into public.user_taste_time_v1(
      user_id, time_bucket, affinity_score, confidence,
      signals_count, positive_count, negative_count, last_signal_at, updated_at
    )
    select
      tn.user_id,
      tn.time_bucket,
      tn.affinity_score,
      case
        when (select qualified_actions from overall) < p_min_qualified_actions then 0::numeric
        else least(1::numeric, (ln(1 + tn.signals_count::numeric) / ln(1 + 10::numeric)))
      end as confidence,
      tn.signals_count,
      tn.positive_count,
      tn.negative_count,
      tn.last_signal_at,
      now()
    from time_norm tn
    returning 1
  )

  insert into public.user_taste_profile_v1(user_id, qualified_actions, last_rebuild_at, confidence, notes)
  select
    p_user_id,
    (select qualified_actions from overall),
    now(),
    (select confidence from overall),
    case
      when (select qualified_actions from overall) < p_min_qualified_actions
        then 'Not enough signals yet; profile is neutral.'
      else 'OK'
    end;

end;
$$;

ALTER FUNCTION "public"."rebuild_user_taste_profile_v1"("p_user_id" "uuid", "p_min_cluster_confidence" numeric, "p_min_qualified_actions" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."rebuild_user_taste_profile_v2"("p_user_id" "uuid", "p_min_cluster_confidence" numeric DEFAULT 0.65, "p_min_qualified_actions" integer DEFAULT 5) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_user_id is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  -- reset
  delete from public.user_taste_moods_v1 where user_id = p_user_id;
  delete from public.user_taste_time_v1 where user_id = p_user_id;
  delete from public.user_taste_profile_v1 where user_id = p_user_id;

  --------------------------------------------------------------------
  -- INSERT moods (single statement with full CTE chain)
  --------------------------------------------------------------------
  with
  qa as (
    select
      a.decision_id,
      a.spot_id,
      a.action,
      a.created_at as action_at
    from public.decision_actions a
    join public.decision_sessions s on s.id = a.decision_id
    where s.user_id = p_user_id
      and a.action in ('exact_mood','was_here','not_there')
  ),
  weighted as (
    select
      q.*,
      case q.action
        when 'exact_mood' then 1.0
        when 'was_here' then 0.6
        when 'not_there' then -0.8
        else 0
      end::numeric as base_w,
      case
        when (now() - q.action_at) <= interval '14 days' then 1.0
        when (now() - q.action_at) <= interval '60 days' then 0.6
        else 0.3
      end::numeric as decay,
      case
        when extract(hour from timezone('Europe/Zurich', q.action_at)) between 6 and 11 then 'morning'
        when extract(hour from timezone('Europe/Zurich', q.action_at)) between 12 and 16 then 'afternoon'
        when extract(hour from timezone('Europe/Zurich', q.action_at)) between 17 and 22 then 'evening'
        else 'night'
      end::text as time_bucket
    from qa q
  ),
  act_sessions as (
    select
      w.*,
      (w.base_w * w.decay) as w_eff,
      s.mood_a_text,
      s.mood_b_text
    from weighted w
    join public.decision_sessions s on s.id = w.decision_id
  ),
  ra as (
    select distinct
      a.decision_id,
      public.resolve_mood_input_v2(a.mood_a_text) as r
    from act_sessions a
    where nullif(trim(coalesce(a.mood_a_text,'')), '') is not null
  ),
  rb as (
    select distinct
      a.decision_id,
      public.resolve_mood_input_v2(a.mood_b_text) as r
    from act_sessions a
    where nullif(trim(coalesce(a.mood_b_text,'')), '') is not null
  ),
  ta as (
    select ra.decision_id, t.mood_id
    from ra
    join lateral public.expand_resolved_targets(
      (ra.r).resolved_via,
      (ra.r).resolved_token_id,
      (ra.r).cluster_id,
      p_min_cluster_confidence
    ) t on true
  ),
  tb as (
    select rb.decision_id, t.mood_id
    from rb
    join lateral public.expand_resolved_targets(
      (rb.r).resolved_via,
      (rb.r).resolved_token_id,
      (rb.r).cluster_id,
      p_min_cluster_confidence
    ) t on true
  ),
  targets as (
    select decision_id, mood_id from ta
    union all
    select decision_id, mood_id from tb
  ),
  target_counts as (
    select decision_id, count(*)::numeric as n
    from targets
    group by decision_id
  ),
  mood_contrib as (
    select
      t.mood_id,
      a.action_at,
      (a.w_eff / nullif(tc.n,0))::numeric as contrib
    from act_sessions a
    join targets t on t.decision_id = a.decision_id
    join target_counts tc on tc.decision_id = a.decision_id
  ),
  mood_agg as (
    select
      p_user_id as user_id,
      mc.mood_id,
      sum(mc.contrib)::numeric as affinity_raw,
      count(*)::integer as signals_count,
      sum(case when mc.contrib > 0 then 1 else 0 end)::integer as positive_count,
      sum(case when mc.contrib < 0 then 1 else 0 end)::integer as negative_count,
      max(mc.action_at) as last_signal_at
    from mood_contrib mc
    group by mc.mood_id
  ),
  mood_norm as (
    select
      m.*,
      greatest(-2.0, least(2.0, m.affinity_raw))::numeric as affinity_score
    from mood_agg m
  ),
  overall as (
    select
      count(*)::integer as qualified_actions,
      case
        when count(*) < p_min_qualified_actions then 0::numeric
        else least(1::numeric, (ln(1 + count(*)::numeric) / ln(1 + 25::numeric)))
      end as confidence
    from qa
  )
  insert into public.user_taste_moods_v1(
    user_id, mood_id, affinity_score, confidence,
    signals_count, positive_count, negative_count, last_signal_at, updated_at
  )
  select
    mn.user_id,
    mn.mood_id,
    mn.affinity_score,
    case
      when (select qualified_actions from overall) < p_min_qualified_actions then 0::numeric
      else least(1::numeric, (ln(1 + mn.signals_count::numeric) / ln(1 + 12::numeric)))
    end as confidence,
    mn.signals_count,
    mn.positive_count,
    mn.negative_count,
    mn.last_signal_at,
    now()
  from mood_norm mn;

  --------------------------------------------------------------------
  -- INSERT time (own CTE chain; no cross-statement CTE references)
  --------------------------------------------------------------------
  with
  qa as (
    select
      a.decision_id,
      a.spot_id,
      a.action,
      a.created_at as action_at
    from public.decision_actions a
    join public.decision_sessions s on s.id = a.decision_id
    where s.user_id = p_user_id
      and a.action in ('exact_mood','was_here','not_there')
  ),
  weighted as (
    select
      q.*,
      case q.action
        when 'exact_mood' then 1.0
        when 'was_here' then 0.6
        when 'not_there' then -0.8
        else 0
      end::numeric as base_w,
      case
        when (now() - q.action_at) <= interval '14 days' then 1.0
        when (now() - q.action_at) <= interval '60 days' then 0.6
        else 0.3
      end::numeric as decay,
      case
        when extract(hour from timezone('Europe/Zurich', q.action_at)) between 6 and 11 then 'morning'
        when extract(hour from timezone('Europe/Zurich', q.action_at)) between 12 and 16 then 'afternoon'
        when extract(hour from timezone('Europe/Zurich', q.action_at)) between 17 and 22 then 'evening'
        else 'night'
      end::text as time_bucket
    from qa q
  ),
  act_sessions as (
    select
      w.*,
      (w.base_w * w.decay) as w_eff
    from weighted w
  ),
  time_agg as (
    select
      p_user_id as user_id,
      a.time_bucket,
      sum(a.w_eff)::numeric as affinity_raw,
      count(*)::integer as signals_count,
      sum(case when a.w_eff > 0 then 1 else 0 end)::integer as positive_count,
      sum(case when a.w_eff < 0 then 1 else 0 end)::integer as negative_count,
      max(a.action_at) as last_signal_at
    from act_sessions a
    group by a.time_bucket
  ),
  time_norm as (
    select
      t.*,
      greatest(-2.0, least(2.0, t.affinity_raw))::numeric as affinity_score
    from time_agg t
  ),
  overall as (
    select
      count(*)::integer as qualified_actions,
      case
        when count(*) < p_min_qualified_actions then 0::numeric
        else least(1::numeric, (ln(1 + count(*)::numeric) / ln(1 + 25::numeric)))
      end as confidence
    from qa
  )
  insert into public.user_taste_time_v1(
    user_id, time_bucket, affinity_score, confidence,
    signals_count, positive_count, negative_count, last_signal_at, updated_at
  )
  select
    tn.user_id,
    tn.time_bucket,
    tn.affinity_score,
    case
      when (select qualified_actions from overall) < p_min_qualified_actions then 0::numeric
      else least(1::numeric, (ln(1 + tn.signals_count::numeric) / ln(1 + 10::numeric)))
    end as confidence,
    tn.signals_count,
    tn.positive_count,
    tn.negative_count,
    tn.last_signal_at,
    now()
  from time_norm tn;

  --------------------------------------------------------------------
  -- INSERT overall profile
  --------------------------------------------------------------------
  with
  qa as (
    select
      a.decision_id,
      a.spot_id,
      a.action,
      a.created_at as action_at
    from public.decision_actions a
    join public.decision_sessions s on s.id = a.decision_id
    where s.user_id = p_user_id
      and a.action in ('exact_mood','was_here','not_there')
  ),
  overall as (
    select
      count(*)::integer as qualified_actions,
      case
        when count(*) < p_min_qualified_actions then 0::numeric
        else least(1::numeric, (ln(1 + count(*)::numeric) / ln(1 + 25::numeric)))
      end as confidence
    from qa
  )
  insert into public.user_taste_profile_v1(user_id, qualified_actions, last_rebuild_at, confidence, notes)
  select
    p_user_id,
    (select qualified_actions from overall),
    now(),
    (select confidence from overall),
    case
      when (select qualified_actions from overall) < p_min_qualified_actions
        then 'Not enough signals yet; profile is neutral.'
      else 'OK'
    end;

end;
$$;

ALTER FUNCTION "public"."rebuild_user_taste_profile_v2"("p_user_id" "uuid", "p_min_cluster_confidence" numeric, "p_min_qualified_actions" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."rebuild_user_taste_profile_v3"("p_decay_lambda" numeric DEFAULT 0.05, "p_cap" numeric DEFAULT 0.4) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_uid uuid := auth.uid();
  v_lambda numeric := greatest(0.0, least(1.0, coalesce(p_decay_lambda, 0.05)));
  v_cap numeric := greatest(0.05, least(2.0, coalesce(p_cap, 0.4)));
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  update public.user_taste_concepts_v2 utc
  set
    weight = greatest(
      -v_cap,
      least(
        v_cap,
        utc.weight * exp(-v_lambda * (extract(epoch from (now() - utc.updated_at)) / 86400.0))
      )
    )::numeric,
    updated_at = now()
  where utc.user_id = v_uid;

end;
$$;

ALTER FUNCTION "public"."rebuild_user_taste_profile_v3"("p_decay_lambda" numeric, "p_cap" numeric) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."refresh_spot_moods_agg_for_review"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  -- mood_a_id
  if new.mood_a_id is not null then
    insert into public.spot_moods_agg (spot_id, mood_id, mood_count, rank)
    values (new.spot_id, new.mood_a_id, 1, 0)
    on conflict (spot_id, mood_id)
    do update set
      mood_count = public.spot_moods_agg.mood_count + 1,
      updated_at = now();
  end if;

  -- mood_b_id
  if new.mood_b_id is not null then
    insert into public.spot_moods_agg (spot_id, mood_id, mood_count, rank)
    values (new.spot_id, new.mood_b_id, 1, 0)
    on conflict (spot_id, mood_id)
    do update set
      mood_count = public.spot_moods_agg.mood_count + 1,
      updated_at = now();
  end if;

  return new;
end;
$$;

ALTER FUNCTION "public"."refresh_spot_moods_agg_for_review"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."register_my_push_device_v1"("p_expo_push_token" "text", "p_platform" "text" DEFAULT NULL::"text", "p_device_name" "text" DEFAULT NULL::"text", "p_app_version" "text" DEFAULT NULL::"text", "p_project_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_device_id uuid;
begin
  if v_user_id is null then
    raise exception 'not_authenticated'
      using errcode = '28000';
  end if;

  if nullif(btrim(p_expo_push_token), '') is null then
    raise exception 'push_token_required'
      using errcode = '22023';
  end if;

  insert into public.user_push_devices (
    user_id,
    expo_push_token,
    platform,
    device_name,
    app_version,
    project_id,
    notifications_enabled,
    last_registered_at,
    disabled_at
  )
  values (
    v_user_id,
    btrim(p_expo_push_token),
    nullif(btrim(p_platform), ''),
    nullif(btrim(p_device_name), ''),
    nullif(btrim(p_app_version), ''),
    nullif(btrim(p_project_id), ''),
    true,
    now(),
    null
  )
  on conflict (expo_push_token)
  do update set
    user_id = excluded.user_id,
    platform = excluded.platform,
    device_name = excluded.device_name,
    app_version = excluded.app_version,
    project_id = excluded.project_id,
    notifications_enabled = true,
    last_registered_at = now(),
    disabled_at = null
  returning id into v_device_id;

  return v_device_id;
end;
$$;

ALTER FUNCTION "public"."register_my_push_device_v1"("p_expo_push_token" "text", "p_platform" "text", "p_device_name" "text", "p_app_version" "text", "p_project_id" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."request_my_account_deletion_v1"("p_user_note" "text" DEFAULT NULL::"text") RETURNS TABLE("request_id" "uuid", "scheduled_for" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_request_id uuid;
  v_scheduled_for timestamptz;
begin
  if v_user_id is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  if exists (
    select 1
    from public.profiles p
    where p.id = v_user_id
      and coalesce(p.is_admin, false) = true
  ) then
    raise exception 'admin_account_requires_manual_transfer'
      using errcode = '42501';
  end if;

  select r.id, r.scheduled_for
  into v_request_id, v_scheduled_for
  from public.data_rights_requests r
  where r.user_id = v_user_id
    and r.request_type = 'account_deletion'
    and r.status in ('requested', 'scheduled', 'processing')
  order by r.requested_at desc
  limit 1;

  if v_request_id is not null then
    return query select v_request_id, v_scheduled_for;
    return;
  end if;

  v_scheduled_for := now() + interval '14 days';

  insert into public.data_rights_requests (
    user_id,
    request_type,
    status,
    scheduled_for,
    user_note,
    metadata
  )
  values (
    v_user_id,
    'account_deletion',
    'scheduled',
    v_scheduled_for,
    nullif(btrim(p_user_note), ''),
    jsonb_build_object(
      'cooling_off_days', 14,
      'requested_source', 'mobile'
    )
  )
  returning id into v_request_id;

  return query select v_request_id, v_scheduled_for;
end;
$$;

ALTER FUNCTION "public"."request_my_account_deletion_v1"("p_user_note" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."request_my_data_export_v1"() RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_request_id uuid;
begin
  if v_user_id is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  select r.id into v_request_id
  from public.data_rights_requests r
  where r.user_id = v_user_id
    and r.request_type = 'data_export'
    and r.status in ('requested', 'processing', 'ready')
  order by r.requested_at desc
  limit 1;

  if v_request_id is not null then
    return v_request_id;
  end if;

  insert into public.data_rights_requests (
    user_id,
    request_type,
    status,
    metadata
  )
  values (
    v_user_id,
    'data_export',
    'requested',
    jsonb_build_object(
      'requested_source', 'mobile',
      'format', 'json'
    )
  )
  returning id into v_request_id;

  return v_request_id;
end;
$$;

