CREATE OR REPLACE FUNCTION "public"."resolve_mood_input"("p_text" "text") RETURNS TABLE("input_norm" "text", "match_type" "text", "token_id" integer, "cluster_id" bigint)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  tnorm text := public.normalize_mood_text(p_text);
  tid integer;
  cid bigint;
begin
  input_norm := tnorm;

  -- 1) exact token match
  select mt.id into tid
  from public.mood_tokens mt
  where mt.token_norm = tnorm
    and coalesce(mt.valid,true) = true
  limit 1;

  if tid is not null then
    match_type := 'exact';
    token_id := tid;
    cluster_id := null;
    return next;
    return;
  end if;

  -- 2) synonym match
  select ms.token_id into tid
  from public.mood_synonyms ms
  where ms.synonym_norm = tnorm
  limit 1;

  if tid is not null then
    match_type := 'synonym';
    token_id := tid;
    cluster_id := null;
    return next;
    return;
  end if;

  -- 3) cluster match (input maps to cluster name)
  select c.id into cid
  from public.mood_clusters c
  where c.name_norm = tnorm
  limit 1;

  if cid is not null then
    match_type := 'cluster';
    token_id := null;
    cluster_id := cid;
    return next;
    return;
  end if;

  -- 4) none
  match_type := 'none';
  token_id := null;
  cluster_id := null;
  return next;
end $$;

ALTER FUNCTION "public"."resolve_mood_input"("p_text" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."resolve_mood_input_v2"("p_text" "text") RETURNS TABLE("input_norm" "text", "resolved_via" "text", "resolved_token_id" integer, "resolved_label" "text", "cluster_id" bigint)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  tnorm text := public.normalize_mood_text(p_text);
  tid integer;
  cid bigint;
  clabel text;
begin
  input_norm := tnorm;

  if tnorm is null or tnorm = '' then
    resolved_via := 'none';
    resolved_token_id := null;
    resolved_label := null;
    cluster_id := null;
    return next;
    return;
  end if;

  -- 1) exact token_norm
  select mt.id into tid
  from public.mood_tokens mt
  where mt.token_norm = tnorm
  limit 1;

  if tid is not null then
    resolved_via := 'exact';
    resolved_token_id := tid;
    resolved_label := tnorm;
    cluster_id := null;
    return next;
    return;
  end if;

  -- 2) synonym -> canonical token
  select ms.token_id into tid
  from public.mood_synonyms ms
  where ms.synonym_norm = tnorm
  limit 1;

  if tid is not null then
    resolved_via := 'synonym';
    resolved_token_id := tid;
    select mt.token_norm into clabel from public.mood_tokens mt where mt.id = tid;
    resolved_label := clabel;
    cluster_id := null;
    return next;
    return;
  end if;

  -- 3) cluster by token mapping (AI/rules filled mood_token_clusters)
  select tc.cluster_id into cid
  from public.mood_tokens mt
  join public.mood_token_clusters tc on tc.token_id = mt.id
  where mt.token_norm = tnorm
  order by tc.confidence desc, tc.created_at desc
  limit 1;

  if cid is not null then
    select c.name_norm into clabel from public.mood_clusters c where c.id = cid;

    resolved_via := 'cluster';
    resolved_token_id := null;  -- cluster can map to many tokens; token_id not unique
    resolved_label := clabel;
    cluster_id := cid;
    return next;
    return;
  end if;

  resolved_via := 'none';
  resolved_token_id := null;
  resolved_label := null;
  cluster_id := null;
  return next;
end $$;

ALTER FUNCTION "public"."resolve_mood_input_v2"("p_text" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."resolve_mood_token_id"("p_text" "text") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_norm text;
  v_id int;
  v_has_synonyms boolean;
begin
  if p_text is null then
    return null;
  end if;

  v_norm := lower(trim(p_text));
  if v_norm = '' then
    return null;
  end if;

  -- 1) direct token match (via token_norm)
  select id into v_id
  from public.mood_tokens
  where token_norm = v_norm
  limit 1;

  if v_id is not null then
    return v_id;
  end if;

  -- 2) optional synonyms table (synonym -> token_id)
  select exists (
    select 1
    from information_schema.tables
    where table_schema='public' and table_name='mood_synonyms'
  ) into v_has_synonyms;

  if v_has_synonyms then
    -- assume columns: synonym (text), token_id (int)
    -- if your columns differ, this will error; in that case, send me the columns and I adapt in 1 go.
    select token_id into v_id
    from public.mood_synonyms
    where lower(trim(synonym)) = v_norm
    limit 1;

    if v_id is not null then
      return v_id;
    end if;
  end if;

  return null;
end;
$$;

ALTER FUNCTION "public"."resolve_mood_token_id"("p_text" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."resolve_or_create_mood_token"("p_text" "text", "p_locale" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  t_raw text := nullif(trim(p_text), '');
  tnorm text;
  tid integer;
  loc text := coalesce(nullif(trim(p_locale), ''), 'de');
begin
  if t_raw is null then
    return null;
  end if;

  tnorm := public.normalize_mood_text(t_raw);

  -- 1) synonym -> canonical token
  select ms.token_id into tid
  from public.mood_synonyms ms
  where ms.synonym_norm = tnorm
  limit 1;

  if tid is not null then
    return tid;
  end if;

  -- 2) exact token_norm
  select mt.id into tid
  from public.mood_tokens mt
  where mt.token_norm = tnorm
  limit 1;

  if tid is not null then
    return tid;
  end if;

  -- 3) create new token (only created from reviews)
  insert into public.mood_tokens (token, token_norm, locale, valid)
  values (t_raw, tnorm, loc, true)
  returning id into tid;

  return tid;
end $$;

ALTER FUNCTION "public"."resolve_or_create_mood_token"("p_text" "text", "p_locale" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."reviews_agg_after_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  perform public.bump_spot_mood_count(old.spot_id, old.mood_a_id, -1);
  perform public.bump_spot_mood_count(old.spot_id, old.mood_b_id, -1);
  return old;
end $$;

ALTER FUNCTION "public"."reviews_agg_after_delete"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."reviews_agg_after_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  perform public.bump_spot_mood_count(new.spot_id, new.mood_a_id, 1);
  perform public.bump_spot_mood_count(new.spot_id, new.mood_b_id, 1);
  return new;
end $$;

ALTER FUNCTION "public"."reviews_agg_after_insert"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."reviews_agg_after_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  -- nur reagieren, wenn sich spot_id oder mood ids ändern
  if (old.spot_id is distinct from new.spot_id)
     or (old.mood_a_id is distinct from new.mood_a_id)
     or (old.mood_b_id is distinct from new.mood_b_id) then

    -- alte Werte runter
    perform public.bump_spot_mood_count(old.spot_id, old.mood_a_id, -1);
    perform public.bump_spot_mood_count(old.spot_id, old.mood_b_id, -1);

    -- neue Werte rauf
    perform public.bump_spot_mood_count(new.spot_id, new.mood_a_id, 1);
    perform public.bump_spot_mood_count(new.spot_id, new.mood_b_id, 1);
  end if;

  return new;
end $$;

ALTER FUNCTION "public"."reviews_agg_after_update"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."reviews_set_mood_ids"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  a_id integer;
  b_id integer;
begin
  -- nur wenn Text da ist (frei)
  a_id := public.resolve_or_create_mood_token(new.mood_a, null);
  b_id := public.resolve_or_create_mood_token(new.mood_b, null);

  -- optional: gleiche Mood zweimal verhindern (wir nullen mood_b dann)
  if a_id is not null and b_id is not null and a_id = b_id then
    -- behalten A, droppen B (oder umgekehrt – aber konsistent!)
    new.mood_b := null;
    new.mood_b_id := null;
  else
    new.mood_a_id := a_id;
    new.mood_b_id := b_id;
  end if;

  -- falls A leer war, aber B gesetzt: trotzdem übernehmen
  if new.mood_a_id is null and a_id is not null then
    new.mood_a_id := a_id;
  end if;
  if new.mood_b_id is null and b_id is not null then
    new.mood_b_id := b_id;
  end if;

  return new;
end $$;

ALTER FUNCTION "public"."reviews_set_mood_ids"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."revoke_spot_operator_access_v1"("p_claim_id" bigint, "p_reason" "text" DEFAULT NULL::"text") RETURNS TABLE("ok" boolean, "claim_id" bigint, "spot_id" "uuid", "user_id" "uuid", "status" "text", "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_admin_id uuid := auth.uid();
  v_is_admin boolean := false;
  v_claim record;
begin
  if v_admin_id is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  select coalesce(p.is_admin, false)
  into v_is_admin
  from public.profiles p
  where p.id = v_admin_id;

  if not coalesce(v_is_admin, false) then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  select
    sc.id,
    sc.spot_id,
    sc.user_id,
    sc.status
  into v_claim
  from public.spot_claims sc
  where sc.id = p_claim_id
  limit 1;

  if v_claim.id is null then
    raise exception 'claim_not_found';
  end if;

  if v_claim.status <> 'approved' then
    raise exception 'claim_not_approved';
  end if;

  update public.spot_claims sc
  set
    status = 'revoked',
    reviewed_by = v_admin_id,
    reviewed_at = now(),
    rejection_reason = nullif(trim(coalesce(p_reason, '')), ''),
    updated_at = now()
  where sc.id = p_claim_id;

  update public.spots s
  set owner_id = null
  where s.id = v_claim.spot_id
    and s.owner_id = v_claim.user_id;

  update public.spot_descriptions sd
  set
    owner_user_id = null,
    is_verified = false,
    owner_description = null,
    owner_keywords = null,
    owner_updated_at = null,
    updated_at = now()
  where sd.spot_id = v_claim.spot_id
    and sd.owner_user_id = v_claim.user_id;

  begin
    perform public.backyrd_refresh_spot_ml_document_v13(v_claim.spot_id);
    perform public.backyrd_enqueue_spot_embedding_v13(
      v_claim.spot_id,
      'spot_operator_access_revoked'
    );
  exception
    when undefined_function then
      null;
    when others then
      null;
  end;

  return query
  select
    true as ok,
    p_claim_id as claim_id,
    v_claim.spot_id as spot_id,
    v_claim.user_id as user_id,
    'revoked'::text as status,
    'spot_operator_access_revoked'::text as message;
end;
$$;

ALTER FUNCTION "public"."revoke_spot_operator_access_v1"("p_claim_id" bigint, "p_reason" "text") OWNER TO "postgres";

