CREATE OR REPLACE FUNCTION "public"."run_shadow_user_simulation_v1"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  r record;
begin
  for r in
    select
      e.*,
      m.real_user_id
    from public.shadow_user_events e
    join public.shadow_user_map m on m.shadow_user_id = e.shadow_user_id
    order by e.occurred_at asc
  loop
    if not exists (select 1 from auth.users au where au.id = r.real_user_id) then
      raise notice 'skip: mapped user_id not in auth.users: % (handle=%)', r.real_user_id,
        (select su.handle from public.shadow_users su where su.id = r.shadow_user_id);
      continue;
    end if;

    perform public.apply_shadow_event_to_user_v1(
      r.real_user_id,
      r.event_type,
      r.spot_id,
      r.mood_text,
      r.time_bucket,
      r.occurred_at,
      'Basel'
    );
  end loop;
end;
$$;

ALTER FUNCTION "public"."run_shadow_user_simulation_v1"() OWNER TO "postgres";

