CREATE OR REPLACE FUNCTION "public"."safety_admin_appeals_queue_v1"("p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 200) RETURNS TABLE("appeal_id" "uuid", "case_id" "uuid", "appeal_status" "text", "appeal_outcome" "text", "appeal_reason" "text", "statement" "text", "appellant_user_id" "uuid", "appellant_name" "text", "original_action" "text", "original_category" "text", "original_severity" integer, "original_policy_version" "text", "replacement_action" "text", "content_type" "text", "spot_id" "uuid", "text_content" "text", "submitted_at" timestamp with time zone, "reviewed_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.safety_is_admin_v1() then
    raise exception 'admin_required';
  end if;

  return query
  select
    a.id,
    a.case_id,
    a.status,
    a.outcome,
    a.appeal_reason,
    a.statement,
    a.appellant_user_id,
    coalesce(
      p.display_name,
      p.username,
      concat_ws(' ', p.first_name, p.last_name),
      a.appellant_user_id::text
    ),
    a.original_action,
    a.original_category,
    a.original_severity,
    a.original_policy_version,
    a.replacement_action,
    i.content_type,
    i.spot_id,
    i.text_content,
    a.submitted_at,
    a.reviewed_at
  from public.safety_appeals a
  join public.safety_cases c
    on c.id = a.case_id
  join public.safety_content_items i
    on i.id = c.content_item_id
  left join public.profiles p
    on p.id = a.appellant_user_id
  where p_status is null
     or a.status = p_status
  order by
    case
      when a.status = 'submitted' then 0
      when a.status = 'in_review' then 1
      else 2
    end,
    a.submitted_at asc
  limit greatest(
    1,
    least(coalesce(p_limit, 200), 1000)
  );
end;
$$;

ALTER FUNCTION "public"."safety_admin_appeals_queue_v1"("p_status" "text", "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_admin_case_detail_v1"("p_case_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_result jsonb;
begin
  if auth.uid() is null
     or not public.safety_is_admin_v1(auth.uid()) then
    raise exception 'admin_access_required' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'case', to_jsonb(c),
    'content', to_jsonb(i),
    'actor', case when p.id is null then null else jsonb_build_object(
      'id', p.id,
      'display_name', coalesce(p.display_name, nullif(trim(concat_ws(' ', p.first_name, p.last_name)), ''), p.username, 'Unbekannter Nutzer'),
      'username', p.username,
      'avatar_url', p.avatar_url,
      'is_admin', coalesce(p.is_admin, false)
    ) end,
    'signals', coalesce((select jsonb_agg(to_jsonb(s) order by s.created_at desc) from public.safety_signals s where s.case_id = c.id), '[]'::jsonb),
    'decision_events', coalesce((select jsonb_agg(to_jsonb(d) order by d.created_at desc) from public.safety_decision_events d where d.case_id = c.id), '[]'::jsonb),
    'reports', coalesce((select jsonb_agg(to_jsonb(r) order by r.created_at desc) from public.safety_user_reports r where r.case_id = c.id), '[]'::jsonb),
    'appeals', coalesce((select jsonb_agg(to_jsonb(a) order by a.submitted_at desc) from public.safety_appeals a where a.case_id = c.id), '[]'::jsonb),
    'text_jobs', coalesce((select jsonb_agg(to_jsonb(j) order by j.created_at desc) from public.safety_text_evaluation_jobs j where j.case_id = c.id), '[]'::jsonb),
    'image_jobs', coalesce((select jsonb_agg(to_jsonb(j) order by j.image_index asc, j.created_at desc) from public.safety_image_evaluation_jobs j where j.case_id = c.id), '[]'::jsonb)
  )
  into v_result
  from public.safety_cases c
  join public.safety_content_items i on i.id = c.content_item_id
  left join public.profiles p on p.id = i.actor_user_id
  where c.id = p_case_id;

  if v_result is null then
    raise exception 'case_not_found' using errcode = 'P0002';
  end if;

  return v_result;
end;
$$;

ALTER FUNCTION "public"."safety_admin_case_detail_v1"("p_case_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_admin_case_timings_v1"("p_limit" integer DEFAULT 1000) RETURNS TABLE("case_id" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "decided_at" timestamp with time zone, "case_status" "text", "priority" integer, "final_action" "text", "final_category" "text", "final_severity" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if auth.uid() is null
     or not public.safety_is_admin_v1(auth.uid()) then
    raise exception 'admin_access_required'
      using errcode='42501';
  end if;

  return query
  select
    c.id,
    c.created_at,
    c.updated_at,
    c.decided_at,
    c.case_status,
    c.priority,
    c.final_action,
    c.final_category,
    c.final_severity
  from public.safety_cases c
  order by coalesce(c.decided_at,c.updated_at,c.created_at) desc
  limit greatest(1,least(coalesce(p_limit,1000),5000));
end;
$$;

