CREATE OR REPLACE FUNCTION "public"."safety_admin_decide_appeal_v1"("p_appeal_id" "uuid", "p_outcome" "text", "p_reviewer_note" "text", "p_replacement_action" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_appeal public.safety_appeals%rowtype;
  v_case public.safety_cases%rowtype;
  v_item public.safety_content_items%rowtype;
  v_new_action text;
  v_lifecycle_status text;
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;

  if not public.safety_is_admin_v1() then
    raise exception 'admin_required';
  end if;

  select *
  into v_appeal
  from public.safety_appeals
  where id = p_appeal_id
  for update;

  if v_appeal.id is null then
    raise exception 'appeal_not_found';
  end if;

  if v_appeal.status not in (
    'submitted',
    'in_review'
  ) then
    raise exception 'appeal_already_resolved';
  end if;

  if p_outcome not in (
    'upheld',
    'overturned',
    'modified'
  ) then
    raise exception 'invalid_appeal_outcome';
  end if;

  select *
  into v_case
  from public.safety_cases
  where id = v_appeal.case_id
  for update;

  if v_case.id is null then
    raise exception 'case_not_found';
  end if;

  select *
  into v_item
  from public.safety_content_items
  where id = v_case.content_item_id
  for update;

  if v_item.id is null then
    raise exception 'content_item_not_found';
  end if;

  if v_item.entity_type = 'spot_owner_change' then
    raise exception 'owner_change_appeal_not_supported_v1';
  end if;

  if p_outcome = 'upheld' then
    v_new_action := v_case.final_action;

  elsif p_outcome = 'overturned' then
    v_new_action := 'allow';

  else
    if p_replacement_action not in (
      'allow',
      'limit',
      'temporary_hide',
      'remove'
    ) then
      raise exception 'replacement_action_required';
    end if;

    v_new_action := p_replacement_action;
  end if;

  v_lifecycle_status := case v_new_action
    when 'allow' then 'live'
    when 'limit' then 'limited'
    when 'temporary_hide' then 'hidden'
    when 'remove' then 'removed'
    else v_item.lifecycle_status
  end;

  update public.safety_appeals
  set
    status = 'decided',
    outcome = p_outcome,
    reviewer_id = auth.uid(),
    reviewer_note = nullif(
      trim(coalesce(p_reviewer_note, '')),
      ''
    ),
    replacement_action = case
      when p_outcome = 'modified'
        then v_new_action
      else null
    end,
    reviewed_at = now(),
    updated_at = now()
  where id = p_appeal_id;

  update public.safety_content_items
  set lifecycle_status = v_lifecycle_status
  where id = v_item.id;

  update public.safety_cases
  set
    final_action = v_new_action,
    decision_source = 'appeal_human',
    explanation_code = concat(
      'APPEAL_',
      upper(p_outcome)
    ),
    explanation_public = nullif(
      trim(coalesce(p_reviewer_note, '')),
      ''
    ),
    decided_by = auth.uid(),
    decided_at = now(),
    updated_at = now()
  where id = v_appeal.case_id;

  insert into public.safety_decision_events(
    case_id,
    action,
    category,
    severity,
    confidence,
    source,
    policy_snapshot,
    reason_codes,
    metadata
  )
  values(
    v_appeal.case_id,
    v_new_action,
    v_case.final_category,
    v_case.final_severity,
    v_case.final_confidence,
    'appeal_human',
    '{}'::jsonb,
    array[
      'APPEAL_REVIEWED',
      concat(
        'APPEAL_OUTCOME_',
        upper(p_outcome)
      )
    ]::text[],
    jsonb_build_object(
      'appeal_id', p_appeal_id,
      'outcome', p_outcome,
      'original_action', v_appeal.original_action,
      'new_action', v_new_action,
      'content_item_id', v_item.id,
      'entity_type', v_item.entity_type,
      'entity_id', v_item.entity_id,
      'lifecycle_status', v_lifecycle_status,
      'reviewer_user_id', auth.uid()
    )
  );

  return jsonb_build_object(
    'ok', true,
    'appeal_id', p_appeal_id,
    'status', 'decided',
    'outcome', p_outcome,
    'case_id', v_appeal.case_id,
    'final_action', v_new_action,
    'lifecycle_status', v_lifecycle_status,
    'content_restoration_pending', false
  );
end;
$$;

ALTER FUNCTION "public"."safety_admin_decide_appeal_v1"("p_appeal_id" "uuid", "p_outcome" "text", "p_reviewer_note" "text", "p_replacement_action" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_admin_decide_user_content_v1"("p_case_id" "uuid", "p_action" "text", "p_category" "text" DEFAULT NULL::"text", "p_severity" integer DEFAULT NULL::integer, "p_confidence" numeric DEFAULT NULL::numeric, "p_public_explanation" "text" DEFAULT NULL::"text", "p_internal_explanation" "text" DEFAULT NULL::"text", "p_reason_codes" "text"[] DEFAULT '{}'::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_case public.safety_cases%rowtype;
  v_item public.safety_content_items%rowtype;
  v_lifecycle_status text;
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;

  if not public.safety_is_admin_v1() then
    raise exception 'admin_required';
  end if;

  if p_action not in (
    'allow',
    'limit',
    'temporary_hide',
    'remove'
  ) then
    raise exception 'invalid_action';
  end if;

  select *
  into v_case
  from public.safety_cases
  where id = p_case_id
  for update;

  if v_case.id is null then
    raise exception 'case_not_found';
  end if;

  if v_case.case_status = 'decided' then
    raise exception 'case_already_decided';
  end if;

  select *
  into v_item
  from public.safety_content_items
  where id = v_case.content_item_id
  for update;

  if v_item.id is null then
    raise exception 'content_item_not_found';
  end if;

  if v_item.entity_type = 'spot_owner_change' then
    raise exception 'owner_change_requires_owner_enforcement';
  end if;

  v_lifecycle_status := case p_action
    when 'allow' then 'live'
    when 'limit' then 'limited'
    when 'temporary_hide' then 'hidden'
    when 'remove' then 'removed'
  end;

  update public.safety_content_items
  set lifecycle_status = v_lifecycle_status
  where id = v_item.id;

  update public.safety_cases
  set
    case_status = 'decided',
    final_action = p_action,
    final_category = coalesce(
      p_category,
      final_category
    ),
    final_severity = coalesce(
      p_severity,
      final_severity
    ),
    final_confidence = coalesce(
      p_confidence,
      final_confidence
    ),
    decision_source = 'human',
    explanation_code = concat(
      'HUMAN_USER_CONTENT_',
      upper(p_action)
    ),
    explanation_public = nullif(
      trim(coalesce(p_public_explanation, '')),
      ''
    ),
    explanation_internal = nullif(
      trim(coalesce(p_internal_explanation, '')),
      ''
    ),
    decided_by = auth.uid(),
    decided_at = now(),
    updated_at = now()
  where id = p_case_id;

  insert into public.safety_decision_events(
    case_id,
    action,
    category,
    severity,
    confidence,
    source,
    policy_snapshot,
    reason_codes,
    metadata
  )
  values(
    p_case_id,
    p_action,
    coalesce(p_category, v_case.final_category),
    coalesce(p_severity, v_case.final_severity),
    coalesce(p_confidence, v_case.final_confidence),
    'human',
    '{}'::jsonb,
    case
      when coalesce(array_length(p_reason_codes, 1), 0) = 0
        then array[
          'HUMAN_REVIEW',
          concat(
            'HUMAN_ACTION_',
            upper(p_action)
          )
        ]::text[]
      else p_reason_codes
    end,
    jsonb_build_object(
      'content_item_id', v_item.id,
      'entity_type', v_item.entity_type,
      'entity_id', v_item.entity_id,
      'spot_id', v_item.spot_id,
      'lifecycle_status', v_lifecycle_status
    )
  );

  update public.safety_user_reports
  set
    report_status = case
      when p_action = 'allow'
        then 'resolved_no_violation'
      else 'resolved_actioned'
    end,
    reviewed_by = auth.uid(),
    reviewed_at = now(),
    resolution_note = nullif(
      trim(coalesce(p_public_explanation, '')),
      ''
    ),
    updated_at = now()
  where case_id = p_case_id
    and report_status in (
      'submitted',
      'attached_to_case',
      'under_review'
    );

  return jsonb_build_object(
    'ok', true,
    'case_id', p_case_id,
    'content_item_id', v_item.id,
    'entity_type', v_item.entity_type,
    'entity_id', v_item.entity_id,
    'final_action', p_action,
    'lifecycle_status', v_lifecycle_status
  );
end;
$$;

ALTER FUNCTION "public"."safety_admin_decide_user_content_v1"("p_case_id" "uuid", "p_action" "text", "p_category" "text", "p_severity" integer, "p_confidence" numeric, "p_public_explanation" "text", "p_internal_explanation" "text", "p_reason_codes" "text"[]) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_admin_decide_v1"("p_case_id" "uuid", "p_action" "text", "p_category" "text" DEFAULT NULL::"text", "p_severity" integer DEFAULT NULL::integer, "p_confidence" numeric DEFAULT NULL::numeric, "p_public_explanation" "text" DEFAULT NULL::"text", "p_internal_explanation" "text" DEFAULT NULL::"text", "p_reason_codes" "text"[] DEFAULT '{}'::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_case public.safety_cases%rowtype;
  v_item public.safety_content_items%rowtype;
  v_event public.spot_owner_change_events%rowtype;
  v_action text := lower(trim(coalesce(p_action, '')));
  v_lifecycle text;
  v_restore_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;

  if public.safety_is_admin_v1() is not true then
    raise exception 'admin_required';
  end if;

  if v_action not in (
    'allow',
    'allow_log',
    'limit',
    'temporary_hide',
    'remove',
    'block_submit',
    'escalate'
  ) then
    raise exception 'invalid_action';
  end if;

  select *
  into v_case
  from public.safety_cases
  where id = p_case_id
  for update;

  if v_case.id is null then
    raise exception 'case_not_found';
  end if;

  select *
  into v_item
  from public.safety_content_items
  where id = v_case.content_item_id
  for update;

  if v_item.id is null then
    raise exception 'content_item_not_found';
  end if;

  if v_item.entity_type <> 'spot_owner_change'
     or v_item.entity_id is null then
    raise exception 'unsupported_entity_type:%', v_item.entity_type;
  end if;

  select *
  into v_event
  from public.spot_owner_change_events
  where id = v_item.entity_id
  for update;

  if v_event.id is null then
    raise exception 'owner_change_event_not_found';
  end if;

  v_lifecycle := case v_action
    when 'allow' then 'live'
    when 'allow_log' then 'live'
    when 'limit' then 'limited'
    when 'temporary_hide' then 'hidden'
    when 'remove' then 'removed'
    when 'block_submit' then 'removed'
    when 'escalate' then 'hidden'
    else 'live'
  end;

  if v_action in ('allow', 'allow_log') then
    update public.spot_owner_change_events
    set
      moderation_status = 'approved',
      moderation_note = nullif(trim(coalesce(p_public_explanation, '')), ''),
      reviewed_by = auth.uid(),
      reviewed_at = now()
    where id = v_event.id;

    if v_event.change_area in ('profile', 'mobile_profile') then
      update public.spot_descriptions
      set
        content_status = 'published',
        updated_at = now()
      where spot_id = v_event.spot_id;
    end if;
  else
    v_restore_result :=
      public.safety_restore_last_allowed_owner_state_v1(v_event.id);

    update public.spot_owner_change_events
    set
      moderation_note = coalesce(
        nullif(trim(coalesce(p_public_explanation, '')), ''),
        moderation_note
      )
    where id = v_event.id;
  end if;

  update public.safety_content_items
  set
    lifecycle_status = v_lifecycle,
    updated_at = now()
  where id = v_item.id;

  update public.safety_cases
  set
    case_status = 'decided',
    final_action = v_action,
    final_category = coalesce(p_category, final_category),
    final_severity = coalesce(p_severity, final_severity),
    final_confidence = coalesce(p_confidence, final_confidence),
    decision_source = 'human',
    explanation_public = p_public_explanation,
    explanation_internal = coalesce(
      p_internal_explanation,
      explanation_internal
    ),
    decided_by = auth.uid(),
    decided_at = now(),
    updated_at = now()
  where id = p_case_id
  returning *
  into v_case;

  insert into public.safety_decision_events(
    case_id,
    action,
    category,
    severity,
    confidence,
    source,
    reason_codes,
    actor_user_id,
    metadata
  )
  values(
    p_case_id,
    v_action,
    v_case.final_category,
    v_case.final_severity,
    v_case.final_confidence,
    'human',
    coalesce(p_reason_codes, '{}'::text[]),
    auth.uid(),
    jsonb_strip_nulls(
      jsonb_build_object(
        'content_item_id', v_item.id,
        'owner_change_event_id', v_event.id,
        'spot_id', v_event.spot_id,
        'change_area', v_event.change_area,
        'lifecycle_status', v_lifecycle,
        'restore_result', v_restore_result
      )
    )
  );

  return jsonb_build_object(
    'ok', true,
    'case_id', p_case_id,
    'action', v_action,
    'lifecycle_status', v_lifecycle,
    'owner_change_event_id', v_event.id,
    'restore_result', v_restore_result
  );
end;
$$;

ALTER FUNCTION "public"."safety_admin_decide_v1"("p_case_id" "uuid", "p_action" "text", "p_category" "text", "p_severity" integer, "p_confidence" numeric, "p_public_explanation" "text", "p_internal_explanation" "text", "p_reason_codes" "text"[]) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_admin_enforcement_queue_v1"("p_limit" integer DEFAULT 250) RETURNS TABLE("user_id" "uuid", "display_name" "text", "active_points" integer, "confirmed_violations" integer, "active_measure_id" "uuid", "active_measure_type" "text", "active_measure_status" "text", "active_measure_ends_at" timestamp with time zone, "trust_score" numeric, "total_reports" integer, "actioned_reports" integer, "no_violation_reports" integer, "report_restricted_until" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.safety_is_admin_v1() then
    raise exception 'forbidden';
  end if;

  perform public.safety_expire_account_measures_v1(null);

  return query
  with users as (
    select distinct event.user_id
    from public.safety_user_enforcement_events event

    union

    select reputation.user_id
    from public.safety_reporter_reputation reputation

    union

    select measure.user_id
    from public.safety_account_measures measure
  ),
  point_totals as (
    select
      event.user_id,
      coalesce(sum(event.points), 0)::integer as points,
      count(*) filter (
        where event.event_type = 'violation_confirmed'
          and event.points > 0
      )::integer as violations,
      max(event.created_at) as updated_at
    from public.safety_user_enforcement_events event
    where event.created_at >= now() - interval '90 days'
    group by event.user_id
  ),
  active_measure as (
    select distinct on (measure.user_id)
      measure.user_id,
      measure.id,
      measure.measure_type,
      measure.status,
      measure.ends_at,
      measure.updated_at
    from public.safety_account_measures measure
    where measure.status = 'active'
      and (
        measure.ends_at is null
        or measure.ends_at > now()
      )
    order by
      measure.user_id,
      measure.created_at desc
  )
  select
    users.user_id,
    coalesce(
      nullif(profile.display_name, ''),
      nullif(
        concat_ws(
          ' ',
          profile.first_name,
          profile.last_name
        ),
        ''
      ),
      'Backyrd User'
    ),
    coalesce(point_totals.points, 0),
    coalesce(point_totals.violations, 0),
    active_measure.id,
    active_measure.measure_type,
    active_measure.status,
    active_measure.ends_at,
    coalesce(reputation.trust_score, 1.0000),
    coalesce(reputation.total_reports, 0),
    coalesce(reputation.actioned_reports, 0),
    coalesce(reputation.no_violation_reports, 0),
    reputation.report_restricted_until,
    greatest(
      coalesce(point_totals.updated_at, '-infinity'::timestamptz),
      coalesce(active_measure.updated_at, '-infinity'::timestamptz),
      coalesce(reputation.updated_at, '-infinity'::timestamptz)
    )
  from users
  left join public.profiles profile
    on profile.id = users.user_id
  left join point_totals
    on point_totals.user_id = users.user_id
  left join active_measure
    on active_measure.user_id = users.user_id
  left join public.safety_reporter_reputation reputation
    on reputation.user_id = users.user_id
  order by
    coalesce(point_totals.points, 0) desc,
    coalesce(reputation.trust_score, 1.0000) asc,
    greatest(
      coalesce(point_totals.updated_at, '-infinity'::timestamptz),
      coalesce(active_measure.updated_at, '-infinity'::timestamptz),
      coalesce(reputation.updated_at, '-infinity'::timestamptz)
    ) desc
  limit greatest(1, least(p_limit, 1000));
end;
$$;

ALTER FUNCTION "public"."safety_admin_enforcement_queue_v1"("p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_admin_enforcements_v1"("p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 500) RETURNS TABLE("enforcement_id" "uuid", "user_id" "uuid", "user_name" "text", "case_id" "uuid", "enforcement_type" "text", "status" "text", "reason_code" "text", "public_explanation" "text", "internal_note" "text", "starts_at" timestamp with time zone, "ends_at" timestamp with time zone, "issued_by" "uuid", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
#variable_conflict use_column
DECLARE
  v_status text;
BEGIN
  IF auth.uid() IS NULL
     OR public.safety_is_admin_v1() IS NOT TRUE THEN
    RAISE EXCEPTION 'admin_required';
  END IF;

  /*
   * Zeitlich abgelaufene aktive Maßnahmen zuerst sauber
   * auf "expired" setzen.
   */
  UPDATE public.safety_account_enforcements
  SET
    status = 'expired',
    updated_at = now()
  WHERE status = 'active'
    AND ends_at IS NOT NULL
    AND ends_at <= now();

  /*
   * Eingabe normalisieren.
   *
   * NULL / leer / "all" = kein Statusfilter
   */
  v_status := lower(btrim(coalesce(p_status, '')));

  RETURN QUERY
  SELECT
    e.id,
    e.user_id,
    coalesce(
      p.display_name,
      p.username,
      concat_ws(' ', p.first_name, p.last_name),
      e.user_id::text
    ),
    e.case_id,
    e.enforcement_type,
    e.status,
    e.reason_code,
    e.public_explanation,
    e.internal_note,
    e.starts_at,
    e.ends_at,
    e.issued_by,
    e.created_at
  FROM public.safety_account_enforcements e
  LEFT JOIN public.profiles p
    ON p.id = e.user_id
  WHERE
    v_status IN ('', 'all')
    OR e.status = v_status
  ORDER BY
    CASE e.status
      WHEN 'active' THEN 0
      WHEN 'expired' THEN 1
      WHEN 'revoked' THEN 2
      ELSE 3
    END,
    e.created_at DESC
  LIMIT greatest(
    1,
    least(coalesce(p_limit, 500), 5000)
  );
END;
$$;

ALTER FUNCTION "public"."safety_admin_enforcements_v1"("p_status" "text", "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_admin_issue_enforcement_v1"("p_user_id" "uuid", "p_case_id" "uuid", "p_enforcement_type" "text", "p_reason_code" "text", "p_public_explanation" "text", "p_internal_note" "text" DEFAULT NULL::"text", "p_ends_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_id uuid;
  v_measure_id uuid;
  v_measure_type text;
  v_metadata jsonb := coalesce(p_metadata,'{}'::jsonb);
begin
  if auth.uid() is null or public.safety_is_admin_v1() is not true then
    raise exception 'admin_required';
  end if;

  if p_enforcement_type not in (
    'information','warning','strike','posting_restriction',
    'commenting_restriction','messaging_restriction',
    'owner_edit_restriction','temporary_suspension','permanent_suspension'
  ) then raise exception 'invalid_enforcement_type'; end if;

  if nullif(trim(coalesce(p_public_explanation,'')),'') is null then
    raise exception 'public_explanation_required';
  end if;

  if p_enforcement_type in (
    'posting_restriction','commenting_restriction','messaging_restriction',
    'owner_edit_restriction','temporary_suspension'
  ) and (p_ends_at is null or p_ends_at<=now()) then
    raise exception 'future_end_required';
  end if;

  v_measure_type := case
    when p_enforcement_type in ('warning','strike') then 'warning'
    when p_enforcement_type in ('temporary_suspension','permanent_suspension')
      then 'account_restricted'
    else null
  end;

  if v_measure_type is not null then
    insert into public.safety_account_measures(
      user_id,measure_type,status,starts_at,ends_at,source_case_id,
      reason_code,public_explanation,internal_note,created_by,metadata
    ) values(
      p_user_id,v_measure_type,'active',now(),
      case when p_enforcement_type='permanent_suspension' then null else p_ends_at end,
      p_case_id,p_reason_code,trim(p_public_explanation),
      nullif(trim(coalesce(p_internal_note,'')),''),
      auth.uid(),
      jsonb_build_object(
        'source','safety_account_enforcements',
        'enforcement_type',p_enforcement_type
      ) || v_metadata
    )
    returning id into v_measure_id;

    v_metadata := v_metadata || jsonb_build_object('bridge_measure_id',v_measure_id);
  end if;

  insert into public.safety_account_enforcements(
    user_id,case_id,enforcement_type,status,reason_code,
    public_explanation,internal_note,starts_at,ends_at,issued_by,metadata
  ) values(
    p_user_id,p_case_id,p_enforcement_type,'active',p_reason_code,
    trim(p_public_explanation),nullif(trim(coalesce(p_internal_note,'')),''),
    now(),p_ends_at,auth.uid(),v_metadata
  )
  returning id into v_id;

  if v_measure_id is not null then
    update public.safety_account_measures
    set metadata=metadata||jsonb_build_object('enforcement_id',v_id)
    where id=v_measure_id;
  end if;

  insert into public.safety_enforcement_events(
    enforcement_id,user_id,event_type,actor_user_id,reason,metadata
  ) values(v_id,p_user_id,'issued',auth.uid(),p_internal_note,v_metadata);

  insert into public.safety_user_notices(
    user_id,case_id,notice_type,title,body,action_label,action_path,metadata
  ) values(
    p_user_id,p_case_id,
    case
      when p_enforcement_type in ('warning','strike') then 'warning'
      when p_enforcement_type in ('temporary_suspension','permanent_suspension')
        then 'account_suspended'
      when p_enforcement_type='information' then 'information'
      else 'restriction_started'
    end,
    case p_enforcement_type
      when 'information' then 'Hinweis zu deinem Backyrd-Konto'
      when 'warning' then 'Du hast eine Verwarnung erhalten'
      when 'strike' then 'Du hast einen Strike erhalten'
      when 'posting_restriction' then 'Du kannst vorübergehend nichts veröffentlichen'
      when 'commenting_restriction' then 'Deine Kommentarfunktion wurde eingeschränkt'
      when 'messaging_restriction' then 'Deine Nachrichtenfunktion wurde eingeschränkt'
      when 'owner_edit_restriction' then 'Owner-Bearbeitungen wurden eingeschränkt'
      when 'temporary_suspension' then 'Dein Konto wurde vorübergehend gesperrt'
      when 'permanent_suspension' then 'Dein Konto wurde gesperrt'
      else 'Eine Kontomaßnahme wurde ausgesprochen'
    end,
    trim(p_public_explanation),'Details ansehen','/safety-center',
    jsonb_build_object(
      'enforcement_id',v_id,
      'enforcement_type',p_enforcement_type,
      'ends_at',p_ends_at,
      'bridge_measure_id',v_measure_id
    )
  );

  return jsonb_build_object(
    'ok',true,
    'enforcement_id',v_id,
    'bridge_measure_id',v_measure_id,
    'enforcement_type',p_enforcement_type
  );
end;
$$;

ALTER FUNCTION "public"."safety_admin_issue_enforcement_v1"("p_user_id" "uuid", "p_case_id" "uuid", "p_enforcement_type" "text", "p_reason_code" "text", "p_public_explanation" "text", "p_internal_note" "text", "p_ends_at" timestamp with time zone, "p_metadata" "jsonb") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_admin_metrics_v1"("p_from" timestamp with time zone DEFAULT ("now"() - '30 days'::interval), "p_to" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if auth.uid() is null
     or public.safety_is_admin_v1() is not true then
    raise exception 'admin_required';
  end if;

  return jsonb_build_object(
    'period', jsonb_build_object('from', p_from, 'to', p_to),
    'cases', jsonb_build_object(
      'created', (
        select count(*) from public.safety_cases c
        where c.created_at >= p_from and c.created_at < p_to
      ),
      'decided', (
        select count(*) from public.safety_cases c
        where c.decided_at >= p_from and c.decided_at < p_to
      ),
      'needs_review', (
        select count(*) from public.safety_cases c
        where c.case_status = 'needs_review'
      ),
      'average_resolution_hours', (
        select round(
          avg(extract(epoch from (c.decided_at - c.created_at)) / 3600.0)::numeric,
          2
        )
        from public.safety_cases c
        where c.decided_at >= p_from
          and c.decided_at < p_to
          and c.decided_at is not null
      )
    ),
    'decisions_by_action', (
      select coalesce(jsonb_object_agg(x.action, x.total), '{}'::jsonb)
      from (
        select coalesce(d.action, 'unknown') as action, count(*) as total
        from public.safety_decision_events d
        where d.created_at >= p_from and d.created_at < p_to
        group by coalesce(d.action, 'unknown')
      ) x
    ),
    'decisions_by_source', (
      select coalesce(jsonb_object_agg(x.source, x.total), '{}'::jsonb)
      from (
        select coalesce(d.source, 'unknown') as source, count(*) as total
        from public.safety_decision_events d
        where d.created_at >= p_from and d.created_at < p_to
        group by coalesce(d.source, 'unknown')
      ) x
    ),
    'appeals', jsonb_build_object(
      'submitted', (
        select count(*) from public.safety_appeals a
        where a.submitted_at >= p_from and a.submitted_at < p_to
      ),
      'open', (
        select count(*) from public.safety_appeals a
        where coalesce(
          to_jsonb(a) ->> 'appeal_status',
          to_jsonb(a) ->> 'status'
        ) in ('submitted', 'in_review')
      ),
      'overturned', (
        select count(*) from public.safety_appeals a
        where a.reviewed_at >= p_from and a.reviewed_at < p_to
          and coalesce(
            to_jsonb(a) ->> 'appeal_outcome',
            to_jsonb(a) ->> 'outcome'
          ) = 'overturned'
      ),
      'modified', (
        select count(*) from public.safety_appeals a
        where a.reviewed_at >= p_from and a.reviewed_at < p_to
          and coalesce(
            to_jsonb(a) ->> 'appeal_outcome',
            to_jsonb(a) ->> 'outcome'
          ) = 'modified'
      ),
      'upheld', (
        select count(*) from public.safety_appeals a
        where a.reviewed_at >= p_from and a.reviewed_at < p_to
          and coalesce(
            to_jsonb(a) ->> 'appeal_outcome',
            to_jsonb(a) ->> 'outcome'
          ) = 'upheld'
      )
    ),
    'enforcements', jsonb_build_object(
      'active', (
        select count(*) from public.safety_account_enforcements e
        where e.status = 'active'
          and (e.ends_at is null or e.ends_at > now())
      ),
      'issued_in_period', (
        select count(*) from public.safety_account_enforcements e
        where e.created_at >= p_from and e.created_at < p_to
      )
    )
  );
end;
$$;

ALTER FUNCTION "public"."safety_admin_metrics_v1"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_admin_queue_v1"("p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 200) RETURNS TABLE("case_id" "uuid", "content_item_id" "uuid", "content_type" "text", "entity_type" "text", "entity_id" "uuid", "spot_id" "uuid", "actor_user_id" "uuid", "actor_name" "text", "case_status" "text", "priority" integer, "final_action" "text", "final_category" "text", "final_severity" integer, "final_confidence" numeric, "explanation_public" "text", "text_content" "text", "image_urls" "text"[], "locale" "text", "context" "jsonb", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.safety_is_admin_v1() then raise exception 'admin_required'; end if;
  return query
  select c.id,i.id,i.content_type,i.entity_type,i.entity_id,i.spot_id,i.actor_user_id,
    coalesce(p.display_name,p.username,concat_ws(' ',p.first_name,p.last_name),i.actor_user_id::text),
    c.case_status,c.priority,c.final_action,c.final_category,c.final_severity,c.final_confidence,
    c.explanation_public,i.text_content,i.image_urls,i.locale,i.context,c.created_at
  from public.safety_cases c
  join public.safety_content_items i on i.id=c.content_item_id
  left join public.profiles p on p.id=i.actor_user_id
  where p_status is null or c.case_status=p_status
  order by c.priority desc,c.created_at asc
  limit greatest(1,least(coalesce(p_limit,200),1000));
end;
$$;

ALTER FUNCTION "public"."safety_admin_queue_v1"("p_status" "text", "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_admin_queue_v2"("p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 200) RETURNS TABLE("case_id" "uuid", "content_item_id" "uuid", "content_type" "text", "entity_type" "text", "entity_id" "uuid", "spot_id" "uuid", "actor_user_id" "uuid", "actor_name" "text", "case_status" "text", "priority" integer, "final_action" "text", "final_category" "text", "final_severity" integer, "final_confidence" numeric, "decision_source" "text", "explanation_code" "text", "explanation_public" "text", "explanation_internal" "text", "text_content" "text", "image_urls" "text"[], "locale" "text", "context" "jsonb", "lifecycle_status" "text", "latest_reason_codes" "text"[], "latest_metadata" "jsonb", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.safety_is_admin_v1() then
    raise exception 'admin_required';
  end if;

  return query
  select
    c.id,
    i.id,
    i.content_type,
    i.entity_type,
    i.entity_id,
    i.spot_id,
    i.actor_user_id,
    coalesce(
      p.display_name,
      p.username,
      concat_ws(' ', p.first_name, p.last_name),
      i.actor_user_id::text
    ),
    c.case_status,
    c.priority,
    c.final_action,
    c.final_category,
    c.final_severity,
    c.final_confidence,
    c.decision_source,
    c.explanation_code,
    c.explanation_public,
    c.explanation_internal,
    i.text_content,
    i.image_urls,
    i.locale,
    i.context,
    i.lifecycle_status,
    coalesce(latest.reason_codes, '{}'::text[]),
    coalesce(latest.metadata, '{}'::jsonb),
    c.created_at
  from public.safety_cases c
  join public.safety_content_items i
    on i.id = c.content_item_id
  left join public.profiles p
    on p.id = i.actor_user_id
  left join lateral (
    select
      d.reason_codes,
      d.metadata
    from public.safety_decision_events d
    where d.case_id = c.id
    order by d.created_at desc
    limit 1
  ) latest on true
  where p_status is null
     or c.case_status = p_status
  order by
    case
      when c.case_status = 'needs_review' then 0
      when c.case_status = 'failed' then 1
      when c.case_status = 'queued' then 2
      else 3
    end,
    c.priority desc,
    c.created_at desc
  limit greatest(
    1,
    least(coalesce(p_limit, 200), 1000)
  );
end;
$$;

ALTER FUNCTION "public"."safety_admin_queue_v2"("p_status" "text", "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_admin_queue_v3"("p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 200) RETURNS TABLE("case_id" "uuid", "content_item_id" "uuid", "content_type" "text", "entity_type" "text", "entity_id" "uuid", "spot_id" "uuid", "actor_user_id" "uuid", "actor_name" "text", "case_status" "text", "priority" integer, "final_action" "text", "final_category" "text", "final_severity" integer, "final_confidence" numeric, "decision_source" "text", "explanation_code" "text", "explanation_public" "text", "explanation_internal" "text", "text_content" "text", "image_urls" "text"[], "locale" "text", "context" "jsonb", "lifecycle_status" "text", "latest_reason_codes" "text"[], "latest_metadata" "jsonb", "created_at" timestamp with time zone, "has_integrity_signal" boolean, "integrity_signal_count" integer, "integrity_signal_types" "text"[], "integrity_risk_level" "text", "integrity_score" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $_$
begin

  if not public.safety_is_admin_v1() then
    raise exception 'admin_required';
  end if;


  return query

  select
    c.id,
    i.id,
    i.content_type,
    i.entity_type,
    i.entity_id,
    i.spot_id,
    i.actor_user_id,

    coalesce(
      p.display_name,
      p.username,
      concat_ws(' ', p.first_name, p.last_name),
      i.actor_user_id::text
    ),

    c.case_status,
    c.priority,
    c.final_action,
    c.final_category,
    c.final_severity,
    c.final_confidence,
    c.decision_source,
    c.explanation_code,
    c.explanation_public,
    c.explanation_internal,
    i.text_content,
    i.image_urls,
    i.locale,
    i.context,
    i.lifecycle_status,

    coalesce(
      latest.reason_codes,
      '{}'::text[]
    ),

    coalesce(
      latest.metadata,
      '{}'::jsonb
    ),

    c.created_at,


    -- ========================================================
    -- REVIEW INTEGRITY SUMMARY
    -- ========================================================

    coalesce(
      integrity.signal_count,
      0
    ) > 0
      as has_integrity_signal,


    coalesce(
      integrity.signal_count,
      0
    )::integer
      as integrity_signal_count,


    coalesce(
      integrity.signal_types,
      '{}'::text[]
    )
      as integrity_signal_types,


    integrity.risk_level
      as integrity_risk_level,


    integrity.integrity_score
      as integrity_score


  from public.safety_cases c

  join public.safety_content_items i
    on i.id = c.content_item_id

  left join public.profiles p
    on p.id = i.actor_user_id


  -- ----------------------------------------------------------
  -- Letztes Decision Event
  -- ----------------------------------------------------------

  left join lateral (

    select
      d.reason_codes,
      d.metadata

    from public.safety_decision_events d

    where d.case_id = c.id

    order by d.created_at desc

    limit 1

  ) latest on true


  -- ----------------------------------------------------------
  -- Review Integrity Signals dieses Cases
  -- ----------------------------------------------------------

  left join lateral (

    select

      count(*)::integer
        as signal_count,


      array_agg(
        distinct s.signal_type
        order by s.signal_type
      )
        as signal_types,


      case

        when bool_or(
          s.categories ->> 'risk_level'
          = 'high_risk'
        )
          then 'high_risk'

        when bool_or(
          s.categories ->> 'risk_level'
          = 'suspicious'
        )
          then 'suspicious'

        else null

      end
        as risk_level,


      max(
        case
          when
            s.scores ->> 'integrity_score'
            ~ '^[0-9]+(\.[0-9]+)?$'
          then
            (s.scores ->> 'integrity_score')::numeric
          else null
        end
      )
        as integrity_score


    from public.safety_signals s

    where s.case_id = c.id

      and (
        s.provider = 'backyrd_integrity'
        or s.signal_type like 'review_integrity_%'
      )

  ) integrity on true


  where
    p_status is null
    or c.case_status = p_status


  order by

    case
      when c.case_status = 'needs_review' then 0
      when c.case_status = 'failed' then 1
      when c.case_status = 'queued' then 2
      else 3
    end,

    c.priority desc,
    c.created_at desc


  limit greatest(
    1,
    least(
      coalesce(p_limit, 200),
      1000
    )
  );

end;
$_$;

ALTER FUNCTION "public"."safety_admin_queue_v3"("p_status" "text", "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_admin_reports_queue_v1"("p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 200) RETURNS TABLE("report_id" "uuid", "case_id" "uuid", "content_item_id" "uuid", "report_status" "text", "report_reason" "text", "report_details" "text", "reporter_user_id" "uuid", "reporter_name" "text", "source_surface" "text", "content_type" "text", "entity_type" "text", "entity_id" "uuid", "spot_id" "uuid", "text_content" "text", "lifecycle_status" "text", "case_status" "text", "final_action" "text", "final_category" "text", "final_severity" integer, "report_count" bigint, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.safety_is_admin_v1() then
    raise exception 'admin_required';
  end if;

  return query
  select
    r.id,
    r.case_id,
    r.content_item_id,
    r.report_status,
    r.report_reason,
    r.report_details,
    r.reporter_user_id,
    coalesce(
      p.display_name,
      p.username,
      concat_ws(' ', p.first_name, p.last_name),
      r.reporter_user_id::text
    ),
    r.source_surface,
    i.content_type,
    i.entity_type,
    i.entity_id,
    i.spot_id,
    i.text_content,
    i.lifecycle_status,
    c.case_status,
    c.final_action,
    c.final_category,
    c.final_severity,
    count(*) over (
      partition by r.content_item_id
    ),
    r.created_at
  from public.safety_user_reports r
  join public.safety_content_items i
    on i.id = r.content_item_id
  left join public.safety_cases c
    on c.id = r.case_id
  left join public.profiles p
    on p.id = r.reporter_user_id
  where p_status is null
     or r.report_status = p_status
  order by
    count(*) over (
      partition by r.content_item_id
    ) desc,
    r.created_at asc
  limit greatest(
    1,
    least(coalesce(p_limit, 200), 1000)
  );
end;
$$;

ALTER FUNCTION "public"."safety_admin_reports_queue_v1"("p_status" "text", "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_admin_revoke_account_measure_v1"("p_measure_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.safety_is_admin_v1() then
    raise exception 'forbidden';
  end if;

  update public.safety_account_measures measure
  set
    status = 'revoked',
    revoked_by = auth.uid(),
    revoked_at = now(),
    internal_note = concat_ws(
      E'\n',
      measure.internal_note,
      p_note
    ),
    updated_at = now()
  where measure.id = p_measure_id
    and measure.status = 'active';

  return found;
end;
$$;

ALTER FUNCTION "public"."safety_admin_revoke_account_measure_v1"("p_measure_id" "uuid", "p_note" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_admin_revoke_enforcement_v1"("p_enforcement_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_row public.safety_account_enforcements%rowtype;
  v_measure_id uuid;
begin
  if auth.uid() is null or public.safety_is_admin_v1() is not true then
    raise exception 'admin_required';
  end if;

  update public.safety_account_enforcements
  set status='revoked',revoked_by=auth.uid(),revoked_at=now(),updated_at=now()
  where id=p_enforcement_id and status in ('scheduled','active')
  returning * into v_row;

  if v_row.id is null then raise exception 'active_enforcement_not_found'; end if;

  begin
    v_measure_id := nullif(v_row.metadata->>'bridge_measure_id','')::uuid;
  exception when others then
    v_measure_id := null;
  end;

  if v_measure_id is not null then
    update public.safety_account_measures
    set status='revoked',revoked_by=auth.uid(),revoked_at=now(),updated_at=now(),
        internal_note=concat_ws(E'\n',internal_note,
          nullif(trim(coalesce(p_reason,'')),''),
          'Revoked through safety_account_enforcements bridge.')
    where id=v_measure_id and status='active';
  end if;

  insert into public.safety_enforcement_events(
    enforcement_id,user_id,event_type,actor_user_id,reason,metadata
  ) values(
    v_row.id,v_row.user_id,'revoked',auth.uid(),
    nullif(trim(coalesce(p_reason,'')),''),
    jsonb_build_object('bridge_measure_id',v_measure_id)
  );

  insert into public.safety_user_notices(
    user_id,case_id,notice_type,title,body,action_label,action_path,metadata
  ) values(
    v_row.user_id,v_row.case_id,'account_restored',
    'Eine Kontomaßnahme wurde aufgehoben',
    coalesce(nullif(trim(coalesce(p_reason,'')),''),
      'Die Einschränkung ist nicht mehr aktiv.'),
    'Safety Center öffnen','/safety-center',
    jsonb_build_object(
      'enforcement_id',v_row.id,
      'bridge_measure_id',v_measure_id
    )
  );

  return jsonb_build_object(
    'ok',true,
    'enforcement_id',v_row.id,
    'bridge_measure_id',v_measure_id,
    'status','revoked'
  );
end;
$$;

ALTER FUNCTION "public"."safety_admin_revoke_enforcement_v1"("p_enforcement_id" "uuid", "p_reason" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_admin_set_account_measure_v1"("p_user_id" "uuid", "p_measure_type" "text", "p_duration_hours" integer DEFAULT NULL::integer, "p_reason_code" "text" DEFAULT 'ADMIN_ACCOUNT_MEASURE'::"text", "p_public_explanation" "text" DEFAULT NULL::"text", "p_internal_note" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
begin
  if not public.safety_is_admin_v1() then
    raise exception 'forbidden';
  end if;

  if p_measure_type not in (
    'warning',
    'write_suspension',
    'account_restricted',
    'account_review'
  ) then
    raise exception 'invalid_measure_type';
  end if;

  insert into public.safety_account_measures(
    user_id,
    measure_type,
    status,
    starts_at,
    ends_at,
    reason_code,
    public_explanation,
    internal_note,
    created_by,
    metadata
  )
  values(
    p_user_id,
    p_measure_type,
    'active',
    now(),
    case
      when p_duration_hours is null then null
      else now() + make_interval(hours => p_duration_hours)
    end,
    p_reason_code,
    p_public_explanation,
    p_internal_note,
    auth.uid(),
    jsonb_build_object(
      'source', 'admin_manual',
      'duration_hours', p_duration_hours
    )
  )
  returning id into v_id;

  return v_id;
end;
$$;

ALTER FUNCTION "public"."safety_admin_set_account_measure_v1"("p_user_id" "uuid", "p_measure_type" "text", "p_duration_hours" integer, "p_reason_code" "text", "p_public_explanation" "text", "p_internal_note" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_admin_set_case_priority_v1"("p_case_id" "uuid", "p_priority" integer, "p_internal_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_case public.safety_cases%rowtype;
  v_priority integer;
begin
  if auth.uid() is null
     or not public.safety_is_admin_v1(auth.uid()) then
    raise exception 'admin_access_required' using errcode = '42501';
  end if;

  v_priority := greatest(0, least(coalesce(p_priority, 0), 100));

  update public.safety_cases
  set
    priority = v_priority,
    explanation_internal = case
      when nullif(trim(coalesce(p_internal_note, '')), '') is null then explanation_internal
      else concat_ws(E'\n', nullif(explanation_internal, ''), concat('[Admin priority update] ', trim(p_internal_note)))
    end,
    updated_at = now()
  where id = p_case_id
  returning * into v_case;

  if v_case.id is null then
    raise exception 'case_not_found' using errcode = 'P0002';
  end if;

  insert into public.safety_decision_events(
    case_id, action, category, severity, confidence, source, reason_codes, metadata
  ) values (
    v_case.id,
    coalesce(v_case.final_action, 'allow_log'),
    v_case.final_category,
    v_case.final_severity,
    v_case.final_confidence,
    'human_admin',
    array['CASE_PRIORITY_UPDATED'],
    jsonb_build_object('priority', v_priority, 'internal_note', nullif(trim(coalesce(p_internal_note, '')), ''), 'admin_user_id', auth.uid())
  );

  return jsonb_build_object('ok', true, 'case_id', v_case.id, 'priority', v_priority);
end;
$$;

ALTER FUNCTION "public"."safety_admin_set_case_priority_v1"("p_case_id" "uuid", "p_priority" integer, "p_internal_note" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_apply_registry_lifecycle_to_source_v2"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $_$
begin
  if new.lifecycle_status is not distinct from old.lifecycle_status then
    return new;
  end if;

  if new.entity_type = 'social_post' then
    update public.social_posts
    set status = case new.lifecycle_status
      when 'hidden' then 'hidden'
      when 'removed' then 'deleted'
      else 'published'
    end
    where id = new.entity_id
      and status is distinct from case new.lifecycle_status
        when 'hidden' then 'hidden'
        when 'removed' then 'deleted'
        else 'published'
      end;

  elsif new.entity_type = 'social_comment' then
    update public.social_comments
    set status = case new.lifecycle_status
      when 'hidden' then 'hidden'
      when 'removed' then 'deleted'
      else 'published'
    end
    where id = new.entity_id
      and status is distinct from case new.lifecycle_status
        when 'hidden' then 'hidden'
        when 'removed' then 'deleted'
        else 'published'
      end;

  elsif new.entity_type = 'review' then
    if exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and table_name = 'reviews'
        and column_name = 'moderation_status'
    ) then
      execute format(
        'update public.reviews
         set moderation_status = $1
         where id = $2
           and moderation_status is distinct from $1'
      )
      using
        case new.lifecycle_status
          when 'hidden' then 'hidden'
          when 'removed' then 'hidden'
          when 'limited' then 'flagged'
          else 'visible'
        end,
        new.entity_id;
    end if;
  end if;

  return new;
end;
$_$;

ALTER FUNCTION "public"."safety_apply_registry_lifecycle_to_source_v2"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_apply_repeat_offender_policy_v1"("p_user_id" "uuid", "p_source_case_id" "uuid" DEFAULT NULL::"uuid", "p_source_event_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_points integer := 0;
  v_measure_type text := null;
  v_duration interval := null;
  v_reason text := null;
  v_measure_id uuid := null;
begin
  select coalesce(sum(event.points), 0)::integer
  into v_points
  from public.safety_user_enforcement_events event
  where event.user_id = p_user_id
    and event.created_at >= now() - interval '90 days';

  if v_points >= 12 then
    v_measure_type := 'account_review';
    v_reason := 'REPEAT_OFFENDER_ACCOUNT_REVIEW';
  elsif v_points >= 8 then
    v_measure_type := 'write_suspension';
    v_duration := interval '7 days';
    v_reason := 'REPEAT_OFFENDER_7_DAY_WRITE_SUSPENSION';
  elsif v_points >= 5 then
    v_measure_type := 'write_suspension';
    v_duration := interval '24 hours';
    v_reason := 'REPEAT_OFFENDER_24_HOUR_WRITE_SUSPENSION';
  elsif v_points >= 3 then
    v_measure_type := 'warning';
    v_reason := 'REPEAT_OFFENDER_WARNING';
  end if;

  if v_measure_type is null then
    return jsonb_build_object(
      'ok', true,
      'points', v_points,
      'measure_created', false
    );
  end if;

  if not exists (
    select 1
    from public.safety_account_measures measure
    where measure.user_id = p_user_id
      and measure.status = 'active'
      and measure.measure_type = v_measure_type
      and (
        measure.ends_at is null
        or measure.ends_at > now()
      )
      and measure.reason_code = v_reason
  ) then
    insert into public.safety_account_measures(
      user_id,
      measure_type,
      status,
      starts_at,
      ends_at,
      source_case_id,
      source_event_id,
      reason_code,
      public_explanation,
      internal_note,
      metadata
    )
    values(
      p_user_id,
      v_measure_type,
      'active',
      now(),
      case
        when v_duration is null then null
        else now() + v_duration
      end,
      p_source_case_id,
      p_source_event_id,
      v_reason,
      case v_measure_type
        when 'warning' then
          'Dein Account wurde wegen wiederholter Richtlinienverstöße verwarnt.'
        when 'write_suspension' then
          'Du kannst vorübergehend keine neuen Reviews, Moments oder Kommentare veröffentlichen.'
        when 'account_review' then
          'Dein Account wird aufgrund wiederholter Richtlinienverstöße überprüft.'
        else
          'Für deinen Account gilt derzeit eine Safety-Maßnahme.'
      end,
      concat(
        'Rolling 90-day points: ',
        v_points
      ),
      jsonb_build_object(
        'points_at_creation', v_points,
        'policy_version', 'v4.5'
      )
    )
    returning id into v_measure_id;

    insert into public.safety_user_enforcement_events(
      user_id,
      case_id,
      event_type,
      points,
      action,
      reason,
      metadata
    )
    values(
      p_user_id,
      p_source_case_id,
      case
        when v_measure_type = 'warning'
          then 'warning_issued'
        else 'measure_started'
      end,
      0,
      v_measure_type,
      v_reason,
      jsonb_build_object(
        'measure_id', v_measure_id,
        'points', v_points
      )
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'points', v_points,
    'measure_created', v_measure_id is not null,
    'measure_id', v_measure_id,
    'measure_type', v_measure_type
  );
end;
$$;

ALTER FUNCTION "public"."safety_apply_repeat_offender_policy_v1"("p_user_id" "uuid", "p_source_case_id" "uuid", "p_source_event_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_assert_user_can_perform_v2"("p_user_id" "uuid", "p_capability" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := coalesce(p_user_id, auth.uid());
  v_type text;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  if p_capability not in (
    'can_post','can_comment','can_message',
    'can_edit_owner_content','account_access'
  ) then
    raise exception 'invalid_capability';
  end if;

  perform public.safety_expire_account_measures_v1(v_user_id);

  if exists (
    select 1
    from public.safety_account_measures m
    where m.user_id = v_user_id
      and m.status = 'active'
      and m.measure_type = 'account_restricted'
      and (m.ends_at is null or m.ends_at > now())
  ) then
    raise exception 'SAFETY_ACCOUNT_RESTRICTED';
  end if;

  if p_capability in ('can_post','can_comment','can_edit_owner_content')
  and exists (
    select 1
    from public.safety_account_measures m
    where m.user_id = v_user_id
      and m.status = 'active'
      and m.measure_type = 'write_suspension'
      and (m.ends_at is null or m.ends_at > now())
  ) then
    raise exception 'SAFETY_WRITE_RESTRICTED';
  end if;

  select e.enforcement_type
  into v_type
  from public.safety_account_enforcements e
  where e.user_id = v_user_id
    and e.status = 'active'
    and e.starts_at <= now()
    and (e.ends_at is null or e.ends_at > now())
    and (
      e.enforcement_type in ('temporary_suspension','permanent_suspension')
      or (p_capability='can_post' and e.enforcement_type='posting_restriction')
      or (p_capability='can_comment' and e.enforcement_type='commenting_restriction')
      or (p_capability='can_message' and e.enforcement_type='messaging_restriction')
      or (p_capability='can_edit_owner_content' and e.enforcement_type='owner_edit_restriction')
    )
  order by
    case e.enforcement_type
      when 'permanent_suspension' then 100
      when 'temporary_suspension' then 90
      else 50
    end desc,
    e.created_at desc
  limit 1;

  if v_type is null then return; end if;

  case
    when v_type in ('temporary_suspension','permanent_suspension')
      then raise exception 'SAFETY_ACCOUNT_RESTRICTED';
    when v_type='posting_restriction'
      then raise exception 'SAFETY_POSTING_RESTRICTED';
    when v_type='commenting_restriction'
      then raise exception 'SAFETY_COMMENTING_RESTRICTED';
    when v_type='messaging_restriction'
      then raise exception 'SAFETY_MESSAGING_RESTRICTED';
    when v_type='owner_edit_restriction'
      then raise exception 'SAFETY_OWNER_EDIT_RESTRICTED';
    else raise exception 'SAFETY_ACTION_RESTRICTED';
  end case;
end;
$$;

ALTER FUNCTION "public"."safety_assert_user_can_perform_v2"("p_user_id" "uuid", "p_capability" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_assert_user_can_write_v1"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  perform public.safety_assert_user_can_perform_v2(p_user_id,'can_post');
end;
$$;

