CREATE OR REPLACE FUNCTION "public"."safety_backfill_owner_changes_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_event record;
  v_content_type text;
  v_text text;
  v_item_id uuid;
  v_policy_id uuid;
  v_created integer := 0;
begin
  if not public.safety_is_admin_v1() then
    raise exception 'admin_required';
  end if;

  select id into v_policy_id
  from public.safety_policy_versions
  where policy_key = 'backyrd-global'
    and status in ('active', 'shadow')
  order by case status when 'active' then 0 else 1 end,
           activated_at desc nulls last,
           created_at desc
  limit 1;

  for v_event in
    select *
    from public.spot_owner_change_events
    where change_area in ('profile', 'mobile_profile', 'intelligence')
    order by created_at
  loop
    v_content_type := case
      when v_event.change_area in ('profile', 'mobile_profile') then 'owner_spot_profile'
      else 'owner_spot_intelligence'
    end;

    v_text := public.safety_owner_change_text_v1(v_event.change_area, v_event.new_data);
    if v_text is null then continue; end if;

    insert into public.safety_content_items(
      content_type, entity_type, entity_id, spot_id, actor_user_id,
      locale, text_content, context, lifecycle_status
    )
    values(
      v_content_type, 'spot_owner_change', v_event.id, v_event.spot_id,
      v_event.changed_by, 'de-CH', v_text,
      jsonb_build_object(
        'surface', v_event.change_source,
        'change_area', v_event.change_area,
        'owner_change_event_id', v_event.id,
        'old_data', v_event.old_data,
        'new_data', v_event.new_data
      ),
      'live'
    )
    on conflict (content_type, entity_type, entity_id)
    where entity_id is not null
    do update set text_content = excluded.text_content,
                  context = excluded.context,
                  updated_at = now()
    returning id into v_item_id;

    if not exists(select 1 from public.safety_cases where content_item_id = v_item_id) then
      insert into public.safety_cases(
        content_item_id, policy_version_id, case_status, priority
      )
      values(
        v_item_id, v_policy_id, 'queued',
        case when v_event.moderation_status = 'flagged' then 80 else 50 end
      );
      v_created := v_created + 1;
    end if;
  end loop;

  return jsonb_build_object('ok', true, 'cases_created', v_created);
end;
$$;

ALTER FUNCTION "public"."safety_backfill_owner_changes_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_block_owner_self_review_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_owner_id uuid;
begin

  -- Ohne Spot/User gibt es hier nichts zu prüfen.
  if new.spot_id is null
     or new.user_id is null then
    return new;
  end if;


  -- ----------------------------------------------------------
  -- Aktuellen verifizierten Owner direkt vom Spot holen.
  -- Source of Truth = spots.owner_id
  -- ----------------------------------------------------------

  select s.owner_id
  into v_owner_id
  from public.spots s
  where s.id = new.spot_id
  limit 1;


  -- Kein Owner -> normaler Review
  if v_owner_id is null then
    return new;
  end if;


  -- ----------------------------------------------------------
  -- HARD BLOCK
  --
  -- Wir prüfen sowohl den Review-Actor als auch auth.uid().
  -- Dadurch kann die Regel nicht dadurch umgangen werden,
  -- dass ein Client versucht, user_id anders zu setzen.
  -- ----------------------------------------------------------

  if new.user_id = v_owner_id
     or auth.uid() = v_owner_id then

    raise exception using
      errcode = 'P0001',
      message = 'SAFETY_OWNER_SELF_REVIEW';

  end if;


  return new;

end;
$$;

ALTER FUNCTION "public"."safety_block_owner_self_review_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_block_restricted_user_write_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_row jsonb := to_jsonb(new);
  v_user_id uuid;
  v_capability text;
begin
  v_user_id := coalesce(
    nullif(v_row->>'user_id','')::uuid,
    nullif(v_row->>'sender_id','')::uuid,
    nullif(v_row->>'changed_by','')::uuid,
    auth.uid()
  );

  v_capability := case tg_table_name
    when 'reviews' then 'can_post'
    when 'social_posts' then 'can_post'
    when 'social_comments' then 'can_comment'
    when 'review_comments' then 'can_comment'
    when 'messages' then 'can_message'
    when 'spot_owner_change_events' then 'can_edit_owner_content'
    else 'can_post'
  end;

  if v_user_id is not null then
    perform public.safety_assert_user_can_perform_v2(v_user_id,v_capability);
  end if;

  return new;
end;
$$;

ALTER FUNCTION "public"."safety_block_restricted_user_write_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_can_perform_v1"("p_capability" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare v_status jsonb;
begin
  if auth.uid() is null then return false; end if;
  if p_capability not in (
    'can_post','can_comment','can_message',
    'can_edit_owner_content','account_access'
  ) then raise exception 'invalid_capability'; end if;
  v_status:=public.safety_my_account_status_v1();
  return coalesce((v_status->'capabilities'->>p_capability)::boolean,false);
end;
$$;

