CREATE OR REPLACE FUNCTION "public"."safety_capture_human_violation_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid;
  v_case_id uuid;
  v_points integer;
  v_event_id uuid;
  v_is_human boolean;
begin
  v_is_human :=
    coalesce(new.source, '') ilike 'human%'
    or coalesce(new.reason_codes, '{}'::text[])
      && array['HUMAN_REVIEW']::text[];

  if not v_is_human then
    return new;
  end if;

  if new.action not in (
    'limit',
    'temporary_hide',
    'remove'
  ) then
    return new;
  end if;

  v_case_id := new.case_id;

  select content.actor_user_id
  into v_user_id
  from public.safety_cases safety_case
  join public.safety_content_items content
    on content.id = safety_case.content_item_id
  where safety_case.id = v_case_id;

  if v_user_id is null then
    return new;
  end if;

  v_points :=
    case new.action
      when 'limit' then 1
      when 'temporary_hide' then 2
      when 'remove' then 3
      else 0
    end
    + case
        when coalesce(new.severity, 0) >= 4 then 1
        else 0
      end;

  insert into public.safety_user_enforcement_events(
    user_id,
    case_id,
    decision_event_id,
    event_type,
    points,
    category,
    severity,
    action,
    reason,
    metadata
  )
  values(
    v_user_id,
    v_case_id,
    new.id,
    'violation_confirmed',
    v_points,
    new.category,
    new.severity,
    new.action,
    'Confirmed human moderation decision',
    jsonb_build_object(
      'source', new.source,
      'reason_codes', new.reason_codes,
      'policy_snapshot', new.policy_snapshot
    )
  )
  on conflict do nothing
  returning id into v_event_id;

  if v_event_id is not null then
    perform public.safety_apply_repeat_offender_policy_v1(
      v_user_id,
      v_case_id,
      v_event_id
    );
  end if;

  return new;
end;
$$;

ALTER FUNCTION "public"."safety_capture_human_violation_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_claim_image_jobs_v1"("p_worker_id" "text", "p_limit" integer DEFAULT 5) RETURNS TABLE("job_id" "uuid", "case_id" "uuid", "content_item_id" "uuid", "image_index" integer, "image_reference" "text", "attempt_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  return query
  with candidates as (
    select j.id
    from public.safety_image_evaluation_jobs j
    where j.status in ('pending', 'failed')
      and j.available_at <= now()
      and j.attempt_count < 5
    order by j.created_at
    for update skip locked
    limit greatest(
      1,
      least(coalesce(p_limit, 5), 20)
    )
  ),
  claimed as (
    update public.safety_image_evaluation_jobs j
    set
      status = 'processing',
      attempt_count = j.attempt_count + 1,
      locked_at = now(),
      locked_by =
        nullif(trim(coalesce(p_worker_id, '')), ''),
      updated_at = now()
    from candidates c
    where j.id = c.id
    returning
      j.id,
      j.case_id,
      j.content_item_id,
      j.image_index,
      j.image_reference,
      j.attempt_count
  )
  select
    claimed.id,
    claimed.case_id,
    claimed.content_item_id,
    claimed.image_index,
    claimed.image_reference,
    claimed.attempt_count
  from claimed;
end;
$$;

ALTER FUNCTION "public"."safety_claim_image_jobs_v1"("p_worker_id" "text", "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_claim_text_jobs_v1"("p_worker_id" "text", "p_limit" integer DEFAULT 10) RETURNS TABLE("job_id" "uuid", "case_id" "uuid", "content_item_id" "uuid", "attempt_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
 return query with candidates as (select j.id from public.safety_text_evaluation_jobs j where j.status in ('pending','failed') and j.available_at<=now() and j.attempt_count<5 order by j.created_at for update skip locked limit greatest(1,least(coalesce(p_limit,10),50))), claimed as (update public.safety_text_evaluation_jobs j set status='processing',attempt_count=j.attempt_count+1,locked_at=now(),locked_by=nullif(trim(coalesce(p_worker_id,'')),''),updated_at=now() from candidates c where j.id=c.id returning j.id,j.case_id,j.content_item_id,j.attempt_count) select claimed.id,claimed.case_id,claimed.content_item_id,claimed.attempt_count from claimed;
end; $$;

