CREATE OR REPLACE FUNCTION "public"."safety_create_appeal_notice_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_new jsonb := to_jsonb(new);
  v_old jsonb := case when tg_op = 'UPDATE' then to_jsonb(old) else '{}'::jsonb end;
  v_status text;
  v_old_status text;
  v_outcome text;
  v_reviewer_note text;
  v_replacement_action text;
begin
  v_status := coalesce(v_new ->> 'appeal_status', v_new ->> 'status');
  v_old_status := coalesce(v_old ->> 'appeal_status', v_old ->> 'status');
  v_outcome := coalesce(v_new ->> 'appeal_outcome', v_new ->> 'outcome');
  v_reviewer_note := coalesce(v_new ->> 'reviewer_note', v_new ->> 'resolution_note');
  v_replacement_action := coalesce(v_new ->> 'replacement_action', v_new ->> 'new_action');

  if tg_op = 'INSERT' then
    insert into public.safety_user_notices(
      user_id, case_id, appeal_id, notice_type, title, body,
      action_label, action_path, metadata
    ) values(
      new.appellant_user_id,
      new.case_id,
      new.id,
      'appeal_received',
      'Dein Einspruch ist eingegangen',
      'Wir prüfen die ursprüngliche Moderationsentscheidung erneut.',
      'Status ansehen',
      '/safety-center',
      jsonb_build_object('appeal_status', v_status)
    );
  elsif tg_op = 'UPDATE'
    and v_status = 'decided'
    and v_old_status is distinct from v_status
  then
    insert into public.safety_user_notices(
      user_id, case_id, appeal_id, notice_type, title, body,
      action_label, action_path, metadata
    ) values(
      new.appellant_user_id,
      new.case_id,
      new.id,
      'appeal_decided',
      case v_outcome
        when 'overturned' then 'Deinem Einspruch wurde stattgegeben'
        when 'modified' then 'Die Maßnahme wurde angepasst'
        else 'Dein Einspruch wurde entschieden'
      end,
      coalesce(
        nullif(trim(coalesce(v_reviewer_note, '')), ''),
        'Öffne das Safety Center, um das Ergebnis anzusehen.'
      ),
      'Ergebnis ansehen',
      '/safety-center',
      jsonb_build_object(
        'appeal_status', v_status,
        'appeal_outcome', v_outcome,
        'replacement_action', v_replacement_action
      )
    );
  end if;

  return new;
end;
$$;

ALTER FUNCTION "public"."safety_create_appeal_notice_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_create_case_for_owner_change_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_content_type text;
  v_text text;
  v_item_id uuid;
  v_policy_id uuid;
begin
  if new.change_area not in ('profile', 'mobile_profile', 'intelligence') then
    return new;
  end if;

  v_content_type := case
    when new.change_area in ('profile', 'mobile_profile') then 'owner_spot_profile'
    else 'owner_spot_intelligence'
  end;

  v_text := public.safety_owner_change_text_v1(new.change_area, new.new_data);

  if v_text is null then
    return new;
  end if;

  select id into v_policy_id
  from public.safety_policy_versions
  where policy_key = 'backyrd-global'
    and status in ('active', 'shadow')
  order by
    case status when 'active' then 0 else 1 end,
    activated_at desc nulls last,
    created_at desc
  limit 1;

  insert into public.safety_content_items(
    content_type,
    entity_type,
    entity_id,
    spot_id,
    actor_user_id,
    locale,
    text_content,
    context,
    lifecycle_status
  )
  values(
    v_content_type,
    'spot_owner_change',
    new.id,
    new.spot_id,
    new.changed_by,
    'de-CH',
    v_text,
    jsonb_build_object(
      'surface', new.change_source,
      'change_area', new.change_area,
      'owner_change_event_id', new.id,
      'old_data', new.old_data,
      'new_data', new.new_data
    ),
    'live'
  )
  on conflict (content_type, entity_type, entity_id)
  where entity_id is not null
  do update set
    text_content = excluded.text_content,
    context = excluded.context,
    updated_at = now()
  returning id into v_item_id;

  insert into public.safety_cases(
    content_item_id,
    policy_version_id,
    case_status,
    priority
  )
  select
    v_item_id,
    v_policy_id,
    'queued',
    case
      when new.moderation_status = 'flagged' then 80
      else 50
    end
  where not exists (
    select 1
    from public.safety_cases c
    where c.content_item_id = v_item_id
  );

  return new;
end;
$$;

ALTER FUNCTION "public"."safety_create_case_for_owner_change_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_create_decision_notice_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare v_user_id uuid; v_case public.safety_cases%rowtype;
begin
  if new.source not in ('human','human_admin') then return new; end if;
  select * into v_case from public.safety_cases where id=new.case_id;
  select i.actor_user_id into v_user_id from public.safety_content_items i
  where i.id=v_case.content_item_id;
  if v_user_id is null then return new; end if;

  insert into public.safety_user_notices(
    user_id,case_id,notice_type,title,body,action_label,action_path,metadata
  ) values(
    v_user_id,new.case_id,'moderation_decision',
    case new.action
      when 'allow' then 'Dein Inhalt wurde freigegeben'
      when 'limit' then 'Die Sichtbarkeit deines Inhalts wurde begrenzt'
      when 'temporary_hide' then 'Dein Inhalt wurde vorübergehend ausgeblendet'
      when 'remove' then 'Dein Inhalt wurde entfernt'
      else 'Zu deinem Inhalt wurde entschieden' end,
    coalesce(nullif(trim(v_case.explanation_public),''),
             'Öffne das Safety Center, um die Entscheidung anzusehen.'),
    'Entscheidung ansehen','/safety-center',
    jsonb_build_object('decision_event_id',new.id,'action',new.action,
                       'category',new.category,'severity',new.severity)
  ) on conflict do nothing;
  return new;
end;
$$;

ALTER FUNCTION "public"."safety_create_decision_notice_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_enqueue_image_evaluations_v1"("p_content_item_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_item public.safety_content_items%rowtype;
  v_case_id uuid;
  v_reference text;
  v_index integer;
  v_count integer := 0;
begin
  select *
  into v_item
  from public.safety_content_items
  where id = p_content_item_id;

  if v_item.id is null then
    raise exception 'content_item_not_found';
  end if;

  -- Private chat content must never be bulk-enqueued.
  if v_item.entity_type in (
    'message',
    'chat_message',
    'chat_upload'
  ) then
    return jsonb_build_object(
      'ok', true,
      'queued', 0,
      'reason', 'private_chat_excluded'
    );
  end if;

  if v_item.lifecycle_status = 'removed' then
    return jsonb_build_object(
      'ok', true,
      'queued', 0,
      'reason', 'content_removed'
    );
  end if;

  if coalesce(
    cardinality(v_item.image_urls),
    0
  ) = 0 then
    return jsonb_build_object(
      'ok', true,
      'queued', 0,
      'reason', 'no_images'
    );
  end if;

  v_case_id :=
    public.safety_ensure_text_case_v1(v_item.id);

  for v_index in
    1..cardinality(v_item.image_urls)
  loop
    v_reference :=
      nullif(trim(v_item.image_urls[v_index]), '');

    if v_reference is null then
      continue;
    end if;

    insert into public.safety_image_evaluation_jobs(
      content_item_id,
      case_id,
      image_index,
      image_reference,
      image_hash,
      status,
      available_at,
      updated_at
    )
    values(
      v_item.id,
      v_case_id,
      v_index - 1,
      v_reference,
      public.safety_image_reference_hash_v1(
        v_item.id,
        v_index - 1,
        v_reference
      ),
      'pending',
      now(),
      now()
    )
    on conflict(
      content_item_id,
      image_index,
      image_hash
    )
    do update set
      case_id = excluded.case_id,
      status = case
        when public.safety_image_evaluation_jobs.status =
          'succeeded'
          then public.safety_image_evaluation_jobs.status
        else 'pending'
      end,
      available_at = case
        when public.safety_image_evaluation_jobs.status =
          'succeeded'
          then public.safety_image_evaluation_jobs.available_at
        else now()
      end,
      last_error = case
        when public.safety_image_evaluation_jobs.status =
          'succeeded'
          then public.safety_image_evaluation_jobs.last_error
        else null
      end,
      updated_at = now();

    v_count := v_count + 1;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'queued', v_count,
    'case_id', v_case_id
  );
end;
$$;

ALTER FUNCTION "public"."safety_enqueue_image_evaluations_v1"("p_content_item_id" "uuid") OWNER TO "postgres";

