    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if nullif(trim(coalesce(new.text_content,'')),'') is null then return new; end if;
  if tg_op='INSERT' or old.text_content is distinct from new.text_content or old.locale is distinct from new.locale then perform public.safety_enqueue_text_evaluation_v1(new.id); end if;
  return new;
end; $$;

