CREATE OR REPLACE FUNCTION "public"."safety_enqueue_text_evaluation_v1"("p_content_item_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare v_item public.safety_content_items%rowtype; v_case_id uuid; v_hash text; v_job_id uuid;
begin
  select * into v_item from public.safety_content_items where id=p_content_item_id;
  if v_item.id is null then raise exception 'content_item_not_found'; end if;
  if nullif(trim(coalesce(v_item.text_content,'')),'') is null then return jsonb_build_object('ok',true,'queued',false,'reason','no_text'); end if;
  if v_item.lifecycle_status='removed' then return jsonb_build_object('ok',true,'queued',false,'reason','content_removed'); end if;
  v_case_id:=public.safety_ensure_text_case_v1(v_item.id);
  v_hash:=public.safety_text_content_hash_v1(v_item.id,v_item.text_content,coalesce(v_item.locale,'de-CH'));
  insert into public.safety_text_evaluation_jobs(content_item_id,case_id,content_hash,status,available_at,updated_at)
  values(v_item.id,v_case_id,v_hash,'pending',now(),now())
  on conflict(content_item_id,content_hash) do update set case_id=excluded.case_id,status=case when public.safety_text_evaluation_jobs.status='succeeded' then public.safety_text_evaluation_jobs.status else 'pending' end,available_at=case when public.safety_text_evaluation_jobs.status='succeeded' then public.safety_text_evaluation_jobs.available_at else now() end,last_error=case when public.safety_text_evaluation_jobs.status='succeeded' then public.safety_text_evaluation_jobs.last_error else null end,updated_at=now() returning id into v_job_id;
  return jsonb_build_object('ok',true,'queued',true,'job_id',v_job_id,'case_id',v_case_id,'content_hash',v_hash);
end; $$;

ALTER FUNCTION "public"."safety_enqueue_text_evaluation_v1"("p_content_item_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_ensure_text_case_v1"("p_content_item_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare v_case_id uuid; v_policy_version_id uuid;
begin
  select c.id into v_case_id from public.safety_cases c where c.content_item_id=p_content_item_id and c.case_status in ('queued','evaluating','needs_review') order by c.created_at desc limit 1;
  if v_case_id is not null then return v_case_id; end if;
  select p.id into v_policy_version_id from public.safety_policy_versions p where p.policy_key='backyrd-global' and p.status in ('shadow','active') order by p.activated_at desc nulls last,p.created_at desc limit 1;
  if v_policy_version_id is null then raise exception 'active_or_shadow_safety_policy_missing'; end if;
  insert into public.safety_cases(content_item_id,policy_version_id,case_status,priority,final_action,decision_source,explanation_code,explanation_internal)
  values(p_content_item_id,v_policy_version_id,'queued',20,'allow_log','automated_shadow','TEXT_EVALUATION_QUEUED','Automatically queued by Sprint 7.4 text moderation.') returning id into v_case_id;
  return v_case_id;
end; $$;

ALTER FUNCTION "public"."safety_ensure_text_case_v1"("p_content_item_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_evaluate_review_burst_v1"("p_review_id" "uuid") RETURNS TABLE("signal_type" "text", "risk_level" "text", "integrity_score" numeric, "case_id" "uuid", "signal_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog', 'extensions'
    AS $$
declare
  v_review public.reviews%rowtype;

  v_users_15m integer := 0;
  v_reviews_15m integer := 0;

  v_users_60m integer := 0;
  v_reviews_60m integer := 0;

  v_normalized_text text;
  v_copy_users_30m integer := 0;

  v_risk text;
  v_score numeric;

  v_case_id uuid;
  v_signal_id uuid;
  v_case_status text;
  v_priority integer;
begin

  -- ----------------------------------------------------------
  -- Review laden
  -- ----------------------------------------------------------

  select *
  into v_review
  from public.reviews
  where id = p_review_id;

  if not found then
    raise exception 'review_not_found';
  end if;


  -- ==========================================================
  -- RULE A
  -- MULTI-ACCOUNT SPOT BURST / 15 MINUTES
  -- ==========================================================

  select
    count(distinct r.user_id),
    count(*)
  into
    v_users_15m,
    v_reviews_15m
  from public.reviews r
  where r.spot_id = v_review.spot_id
    and r.user_id is not null
    and r.created_at between
        v_review.created_at - interval '15 minutes'
        and v_review.created_at;


  if v_users_15m >= 5 then

    if v_users_15m >= 10 then
      v_risk := 'high_risk';
      v_score := 0.95;
    else
      v_risk := 'suspicious';
      v_score := 0.82;
    end if;


    select
      x.case_id,
      x.signal_id,
      x.case_status,
      x.priority
    into
      v_case_id,
      v_signal_id,
      v_case_status,
      v_priority
    from public.safety_raise_review_integrity_signal_v1(
      p_review_id,
      'review_integrity_spot_burst_15m',
      v_risk,
      v_score,
      jsonb_build_object(
        'distinct_users_15m', v_users_15m,
        'reviews_15m', v_reviews_15m,
        'window_minutes', 15
      ),
      jsonb_build_object(
        'spot_id', v_review.spot_id,
        'rule_version', 'review-burst-v1'
      )
    ) x;


    signal_type := 'review_integrity_spot_burst_15m';
    risk_level := v_risk;
    integrity_score := v_score;
    case_id := v_case_id;
    signal_id := v_signal_id;

    return next;
  end if;



  -- ==========================================================
  -- RULE B
  -- MULTI-ACCOUNT SPOT BURST / 60 MINUTES
  -- ==========================================================

  select
    count(distinct r.user_id),
    count(*)
  into
    v_users_60m,
    v_reviews_60m
  from public.reviews r
  where r.spot_id = v_review.spot_id
    and r.user_id is not null
    and r.created_at between
        v_review.created_at - interval '60 minutes'
        and v_review.created_at;


  if v_users_60m >= 10 then

    if v_users_60m >= 20 then
      v_risk := 'high_risk';
      v_score := 0.96;
    else
      v_risk := 'suspicious';
      v_score := 0.84;
    end if;


    select
      x.case_id,
      x.signal_id,
      x.case_status,
      x.priority
    into
      v_case_id,
      v_signal_id,
      v_case_status,
      v_priority
    from public.safety_raise_review_integrity_signal_v1(
      p_review_id,
      'review_integrity_spot_burst_60m',
      v_risk,
      v_score,
      jsonb_build_object(
        'distinct_users_60m', v_users_60m,
        'reviews_60m', v_reviews_60m,
        'window_minutes', 60
      ),
      jsonb_build_object(
        'spot_id', v_review.spot_id,
        'rule_version', 'review-burst-v1'
      )
    ) x;


    signal_type := 'review_integrity_spot_burst_60m';
    risk_level := v_risk;
    integrity_score := v_score;
    case_id := v_case_id;
    signal_id := v_signal_id;

    return next;
  end if;



  -- ==========================================================
  -- RULE C
  -- COORDINATED COPY/PASTE ACROSS MULTIPLE ACCOUNTS
  --
  -- Mindestens 12 normalisierte Zeichen.
  -- Exakt gleicher Text.
  -- Derselbe Spot.
  -- Innerhalb von 30 Minuten.
  -- ==========================================================

  v_normalized_text :=
    public.safety_normalize_review_text_v1(v_review.text);


  if length(v_normalized_text) >= 12 then

    select count(distinct r.user_id)
    into v_copy_users_30m
    from public.reviews r
    where r.spot_id = v_review.spot_id
      and r.user_id is not null

      and r.created_at between
          v_review.created_at - interval '30 minutes'
          and v_review.created_at

      and public.safety_normalize_review_text_v1(r.text)
          = v_normalized_text;


    if v_copy_users_30m >= 3 then

      if v_copy_users_30m >= 5 then
        v_risk := 'high_risk';
        v_score := 0.97;
      else
        v_risk := 'suspicious';
        v_score := 0.88;
      end if;


      select
        x.case_id,
        x.signal_id,
        x.case_status,
        x.priority
      into
        v_case_id,
        v_signal_id,
        v_case_status,
        v_priority
      from public.safety_raise_review_integrity_signal_v1(
        p_review_id,
        'review_integrity_coordinated_copy',
        v_risk,
        v_score,
        jsonb_build_object(
          'distinct_users_same_text_30m',
          v_copy_users_30m,
          'window_minutes', 30
        ),
        jsonb_build_object(
          'spot_id', v_review.spot_id,
          'rule_version', 'review-burst-v1'
        )
      ) x;


      signal_type := 'review_integrity_coordinated_copy';
      risk_level := v_risk;
      integrity_score := v_score;
      case_id := v_case_id;
      signal_id := v_signal_id;

      return next;
    end if;

  end if;


  return;

end;
$$;

ALTER FUNCTION "public"."safety_evaluate_review_burst_v1"("p_review_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_evaluate_review_integrity_v1"("p_review_id" "uuid") RETURNS TABLE("signal_type" "text", "risk_level" "text", "integrity_score" numeric, "case_id" "uuid", "signal_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog', 'extensions'
    AS $$
declare
  v_review public.reviews%rowtype;

  v_normalized_text text;

  v_same_spot_24h integer := 0;
  v_velocity_10m integer := 0;

  v_exact_same_spot integer := 0;
  v_exact_other_spots integer := 0;

  v_max_similarity numeric := 0;

  v_case_id uuid;
  v_signal_id uuid;

  v_risk text;
  v_score numeric;
begin

  -- ----------------------------------------------------------
  -- Review laden
  -- ----------------------------------------------------------

  select *
  into v_review
  from public.reviews
  where id = p_review_id;

  if not found then
    raise exception 'review_not_found';
  end if;

  -- Anonyme / gelöschte Actoren können nicht sinnvoll
  -- auf User-Verhalten geprüft werden.
  if v_review.user_id is null then
    return;
  end if;

  v_normalized_text :=
    public.safety_normalize_review_text_v1(v_review.text);


  -- ==========================================================
  -- CHECK A
  -- REPEAT SAME SPOT WITHIN 24 HOURS
  -- ==========================================================

  select count(*)::integer
  into v_same_spot_24h
  from public.reviews r
  where r.user_id = v_review.user_id
    and r.spot_id = v_review.spot_id
    and r.created_at
        between v_review.created_at - interval '24 hours'
            and v_review.created_at
    and r.id <> v_review.id;


  -- +1 = aktueller Review selbst
  v_same_spot_24h := v_same_spot_24h + 1;


  if v_same_spot_24h >= 3 then

    if v_same_spot_24h >= 5 then
      v_risk := 'high_risk';
      v_score := 0.90;
    else
      v_risk := 'suspicious';
      v_score := 0.70;
    end if;

    select
      x.case_id,
      x.signal_id
    into
      v_case_id,
      v_signal_id
    from public.safety_raise_review_integrity_signal_v1(
      p_review_id,
      'review_integrity_repeat_same_spot',
      v_risk,
      v_score,
      jsonb_build_object(
        'same_spot_reviews_24h',
        v_same_spot_24h
      ),
      jsonb_build_object(
        'spot_id',
        v_review.spot_id,
        'window_hours',
        24,
        'suspicious_threshold',
        3,
        'high_risk_threshold',
        5
      )
    ) x;

    return query
    select
      'review_integrity_repeat_same_spot'::text,
      v_risk,
      v_score,
      v_case_id,
      v_signal_id;

  end if;


  -- ==========================================================
  -- CHECK B
  -- REVIEW VELOCITY
  -- ==========================================================

  select count(*)::integer
  into v_velocity_10m
  from public.reviews r
  where r.user_id = v_review.user_id
    and r.created_at
        between v_review.created_at - interval '10 minutes'
            and v_review.created_at
    and r.id <> v_review.id;


  v_velocity_10m := v_velocity_10m + 1;


  if v_velocity_10m >= 5 then

    if v_velocity_10m >= 10 then
      v_risk := 'high_risk';
      v_score := 0.92;
    else
      v_risk := 'suspicious';
      v_score := 0.72;
    end if;

    select
      x.case_id,
      x.signal_id
    into
      v_case_id,
      v_signal_id
    from public.safety_raise_review_integrity_signal_v1(
      p_review_id,
      'review_integrity_high_velocity',
      v_risk,
      v_score,
      jsonb_build_object(
        'reviews_10m',
        v_velocity_10m
      ),
      jsonb_build_object(
        'window_minutes',
        10,
        'suspicious_threshold',
        5,
        'high_risk_threshold',
        10
      )
    ) x;

    return query
    select
      'review_integrity_high_velocity'::text,
      v_risk,
      v_score,
      v_case_id,
      v_signal_id;

  end if;


  -- ==========================================================
  -- TEXT CHECKS
  --
  -- Sehr kurze Texte wie "gut", "cool" oder "nice" sollen
  -- keine Duplicate-Alarme produzieren.
  -- ==========================================================

  if char_length(v_normalized_text) >= 8 then


    -- ========================================================
    -- CHECK C
    -- EXACT DUPLICATE – SAME USER + SAME SPOT
    -- ========================================================

    select count(*)::integer
    into v_exact_same_spot
    from public.reviews r
    where r.user_id = v_review.user_id
      and r.spot_id = v_review.spot_id
      and r.id <> v_review.id
      and r.created_at
          between v_review.created_at - interval '30 days'
              and v_review.created_at
      and public.safety_normalize_review_text_v1(r.text)
          = v_normalized_text;


    if v_exact_same_spot >= 1 then

      if v_exact_same_spot >= 2 then
        v_risk := 'high_risk';
        v_score := 0.92;
      else
        v_risk := 'suspicious';
        v_score := 0.78;
      end if;

      select
        x.case_id,
        x.signal_id
      into
        v_case_id,
        v_signal_id
      from public.safety_raise_review_integrity_signal_v1(
        p_review_id,
        'review_integrity_exact_duplicate',
        v_risk,
        v_score,
        jsonb_build_object(
          'previous_exact_duplicates',
          v_exact_same_spot
        ),
        jsonb_build_object(
          'spot_id',
          v_review.spot_id,
          'window_days',
          30,
          'normalized_length',
          char_length(v_normalized_text)
        )
      ) x;

      return query
      select
        'review_integrity_exact_duplicate'::text,
        v_risk,
        v_score,
        v_case_id,
        v_signal_id;

    end if;


    -- ========================================================
    -- CHECK D
    -- COPY/PASTE ACROSS DIFFERENT SPOTS
    -- ========================================================

    if char_length(v_normalized_text) >= 12 then

      select count(distinct r.spot_id)::integer
      into v_exact_other_spots
      from public.reviews r
      where r.user_id = v_review.user_id
        and r.spot_id <> v_review.spot_id
        and r.id <> v_review.id
        and r.created_at
            between v_review.created_at - interval '7 days'
                and v_review.created_at
        and public.safety_normalize_review_text_v1(r.text)
            = v_normalized_text;


      if v_exact_other_spots >= 1 then

        if v_exact_other_spots >= 3 then
          v_risk := 'high_risk';
          v_score := 0.94;
        else
          v_risk := 'suspicious';
          v_score := 0.80;
        end if;

        select
          x.case_id,
          x.signal_id
        into
          v_case_id,
          v_signal_id
        from public.safety_raise_review_integrity_signal_v1(
          p_review_id,
          'review_integrity_copy_paste',
          v_risk,
          v_score,
          jsonb_build_object(
            'other_spots_with_exact_text',
            v_exact_other_spots
          ),
          jsonb_build_object(
            'window_days',
            7,
            'high_risk_threshold',
            3
          )
        ) x;

        return query
        select
          'review_integrity_copy_paste'::text,
          v_risk,
          v_score,
          v_case_id,
          v_signal_id;

      end if;

    end if;


    -- ========================================================
    -- CHECK E
    -- NEAR DUPLICATE
    --
    -- Nur längere Texte.
    -- pg_trgm similarity >= 0.92
    -- ========================================================

    if char_length(v_normalized_text) >= 20 then

      select
        coalesce(
          max(
            similarity(
              public.safety_normalize_review_text_v1(r.text),
              v_normalized_text
            )
          ),
          0
        )
      into v_max_similarity
      from public.reviews r
      where r.user_id = v_review.user_id
        and r.id <> v_review.id
        and r.created_at
            between v_review.created_at - interval '30 days'
                and v_review.created_at
        and char_length(
          public.safety_normalize_review_text_v1(r.text)
        ) >= 20

        -- exakte Duplikate wurden oben bereits geprüft
        and public.safety_normalize_review_text_v1(r.text)
            <> v_normalized_text;


      if v_max_similarity >= 0.92 then

        v_risk := 'suspicious';

        v_score :=
          least(
            0.89::numeric,
            greatest(
              0.75::numeric,
              round(v_max_similarity::numeric, 4)
            )
          );

        select
          x.case_id,
          x.signal_id
        into
          v_case_id,
          v_signal_id
        from public.safety_raise_review_integrity_signal_v1(
          p_review_id,
          'review_integrity_near_duplicate',
          v_risk,
          v_score,
          jsonb_build_object(
            'max_similarity',
            round(v_max_similarity::numeric, 4)
          ),
          jsonb_build_object(
            'window_days',
            30,
            'similarity_threshold',
            0.92,
            'minimum_text_length',
            20
          )
        ) x;

        return query
        select
          'review_integrity_near_duplicate'::text,
          v_risk,
          v_score,
          v_case_id,
          v_signal_id;

      end if;

    end if;

  end if;


  return;

end;
$$;

ALTER FUNCTION "public"."safety_evaluate_review_integrity_v1"("p_review_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_evaluate_review_new_account_brigade_v1"("p_review_id" "uuid", "p_new_account_days" integer DEFAULT 7, "p_very_new_hours" integer DEFAULT 48) RETURNS TABLE("signal_type" "text", "risk_level" "text", "integrity_score" numeric, "case_id" "uuid", "signal_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_review public.reviews%rowtype;

  v_total_users_60m integer := 0;
  v_new_users_60m integer := 0;
  v_very_new_users_60m integer := 0;

  v_new_ratio numeric := 0;
  v_very_new_ratio numeric := 0;

  v_risk text;
  v_score numeric;

  v_case_id uuid;
  v_signal_id uuid;
  v_case_status text;
  v_priority integer;
begin

  -- ----------------------------------------------------------
  -- Review laden
  -- ----------------------------------------------------------

  select *
  into v_review
  from public.reviews
  where id = p_review_id;

  if not found then
    raise exception 'review_not_found';
  end if;


  -- Reviews ohne User gehören nicht in Account-Brigading.
  if v_review.user_id is null then
    return;
  end if;


  -- Sicherheitsgrenzen für interne Parameter
  if p_new_account_days < 1 then
    raise exception 'invalid_new_account_days';
  end if;

  if p_very_new_hours < 1 then
    raise exception 'invalid_very_new_hours';
  end if;


  -- ==========================================================
  -- Beteiligte unterschiedliche Accounts am selben Spot
  -- innerhalb der letzten 60 Minuten.
  --
  -- Account-Alter basiert auf auth.users.created_at.
  -- ==========================================================

  select
    count(distinct r.user_id),

    count(
      distinct r.user_id
    ) filter (
      where u.created_at >=
        v_review.created_at
        - make_interval(days => p_new_account_days)
    ),

    count(
      distinct r.user_id
    ) filter (
      where u.created_at >=
        v_review.created_at
        - make_interval(hours => p_very_new_hours)
    )

  into
    v_total_users_60m,
    v_new_users_60m,
    v_very_new_users_60m

  from public.reviews r

  join auth.users u
    on u.id = r.user_id

  where r.spot_id = v_review.spot_id
    and r.user_id is not null

    and r.created_at between
        v_review.created_at - interval '60 minutes'
        and v_review.created_at;


  if v_total_users_60m <= 0 then
    return;
  end if;


  v_new_ratio :=
    v_new_users_60m::numeric
    / v_total_users_60m::numeric;

  v_very_new_ratio :=
    v_very_new_users_60m::numeric
    / v_total_users_60m::numeric;


  -- ==========================================================
  -- HIGH RISK
  --
  -- A:
  -- mindestens 5 Accounts <= 7 Tage
  --
  -- ODER
  --
  -- B:
  -- mindestens 4 Accounts <= 48 Stunden
  -- und >= 80 % des Bursts extrem frisch
  -- ==========================================================

  if
    v_new_users_60m >= 5

    or (
      v_very_new_users_60m >= 4
      and v_very_new_ratio >= 0.80
    )
  then

    v_risk := 'high_risk';
    v_score := 0.95;


  -- ==========================================================
  -- SUSPICIOUS
  --
  -- mindestens 3 Accounts <= 7 Tage
  -- und >= 60 % aller Accounts im Fenster sind neu
  -- ==========================================================

  elsif
    v_new_users_60m >= 3
    and v_new_ratio >= 0.60
  then

    v_risk := 'suspicious';
    v_score := 0.86;

  else

    return;

  end if;


  -- ==========================================================
  -- Bestehende Integrity -> Safety Pipeline verwenden
  -- ==========================================================

  select
    x.case_id,
    x.signal_id,
    x.case_status,
    x.priority
  into
    v_case_id,
    v_signal_id,
    v_case_status,
    v_priority
  from public.safety_raise_review_integrity_signal_v1(
    p_review_id,
    'review_integrity_new_account_brigade',
    v_risk,
    v_score,

    jsonb_build_object(
      'total_users_60m',
      v_total_users_60m,

      'new_users_60m',
      v_new_users_60m,

      'very_new_users_60m',
      v_very_new_users_60m,

      'new_user_ratio',
      round(v_new_ratio, 4),

      'very_new_user_ratio',
      round(v_very_new_ratio, 4),

      'new_account_days',
      p_new_account_days,

      'very_new_hours',
      p_very_new_hours,

      'window_minutes',
      60
    ),

    jsonb_build_object(
      'spot_id',
      v_review.spot_id,

      'account_age_source',
      'auth.users.created_at',

      'rule_version',
      'new-account-brigade-v1'
    )
  ) x;


  signal_type :=
    'review_integrity_new_account_brigade';

  risk_level :=
    v_risk;

  integrity_score :=
    v_score;

  case_id :=
    v_case_id;

  signal_id :=
    v_signal_id;

  return next;

end;
$$;

ALTER FUNCTION "public"."safety_evaluate_review_new_account_brigade_v1"("p_review_id" "uuid", "p_new_account_days" integer, "p_very_new_hours" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_evaluate_review_repeated_group_v1"("p_review_id" "uuid") RETURNS TABLE("signal_type" "text", "risk_level" "text", "integrity_score" numeric, "case_id" "uuid", "signal_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_review public.reviews%rowtype;

  v_current_group_users integer := 0;
  v_prior_coordinated_spots integer := 0;

  v_risk text;
  v_score numeric;

  v_case_id uuid;
  v_signal_id uuid;
  v_case_status text;
  v_priority integer;
begin

  select *
  into v_review
  from public.reviews
  where id = p_review_id;

  if not found then
    raise exception 'review_not_found';
  end if;

  if v_review.user_id is null then
    return;
  end if;


  -- ==========================================================
  -- Aktuelle Gruppe am aktuellen Spot / 60 Minuten
  -- ==========================================================

  select count(distinct r.user_id)
  into v_current_group_users
  from public.reviews r
  where r.spot_id = v_review.spot_id
    and r.user_id is not null
    and r.created_at between
        v_review.created_at - interval '60 minutes'
        and v_review.created_at;


  if v_current_group_users < 3 then
    return;
  end if;


  -- ==========================================================
  -- Dieselben Accounts an früheren ANDEREN Spots suchen
  --
  -- WICHTIGE KORREKTUR:
  -- <= statt <
  --
  -- PostgreSQL now() ist innerhalb einer Transaktion konstant.
  -- Unterschiedliche Inserts können deshalb exakt denselben
  -- created_at-Wert besitzen.
  -- ==========================================================

  with current_group as (
    select distinct r.user_id
    from public.reviews r
    where r.spot_id = v_review.spot_id
      and r.user_id is not null
      and r.created_at between
          v_review.created_at - interval '60 minutes'
          and v_review.created_at
  ),

  prior_anchors as (
    select
      anchor.id,
      anchor.spot_id,
      anchor.created_at
    from public.reviews anchor
    where anchor.spot_id <> v_review.spot_id
      and anchor.user_id is not null
      and anchor.created_at >=
          v_review.created_at - interval '7 days'
      and anchor.created_at <= v_review.created_at
  ),

  prior_coordinated_spots as (
    select distinct pa.spot_id
    from prior_anchors pa
    where (
      select count(distinct r.user_id)
      from public.reviews r
      join current_group cg
        on cg.user_id = r.user_id
      where r.spot_id = pa.spot_id
        and r.created_at between
            pa.created_at - interval '60 minutes'
            and pa.created_at
    ) >= 3
  )

  select count(*)
  into v_prior_coordinated_spots
  from prior_coordinated_spots;


  if v_prior_coordinated_spots < 1 then
    return;
  end if;


  -- ==========================================================
  -- Risk
  -- ==========================================================

  if
    v_prior_coordinated_spots >= 2
    or v_current_group_users >= 5
  then
    v_risk := 'high_risk';
    v_score := 0.96;
  else
    v_risk := 'suspicious';
    v_score := 0.90;
  end if;


  -- ==========================================================
  -- Existing Integrity / Safety pipeline
  -- ==========================================================

  select
    x.case_id,
    x.signal_id,
    x.case_status,
    x.priority
  into
    v_case_id,
    v_signal_id,
    v_case_status,
    v_priority
  from public.safety_raise_review_integrity_signal_v1(
    p_review_id,
    'review_integrity_repeated_group_pattern',
    v_risk,
    v_score,

    jsonb_build_object(
      'current_group_users',
      v_current_group_users,

      'prior_coordinated_spots',
      v_prior_coordinated_spots,

      'group_window_minutes',
      60,

      'history_days',
      7,

      'minimum_shared_users',
      3
    ),

    jsonb_build_object(
      'spot_id',
      v_review.spot_id,

      'rule_version',
      'repeated-group-v1'
    )
  ) x;


  signal_type :=
    'review_integrity_repeated_group_pattern';

  risk_level := v_risk;
  integrity_score := v_score;
  case_id := v_case_id;
  signal_id := v_signal_id;

  return next;

end;
$$;

ALTER FUNCTION "public"."safety_evaluate_review_repeated_group_v1"("p_review_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_expire_account_measures_v1"("p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_count integer;
begin
  update public.safety_account_measures measure
  set
    status = 'expired',
    updated_at = now()
  where measure.status = 'active'
    and measure.ends_at is not null
    and measure.ends_at <= now()
    and (
      p_user_id is null
      or measure.user_id = p_user_id
    );

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

ALTER FUNCTION "public"."safety_expire_account_measures_v1"("p_user_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_fail_image_job_v1"("p_job_id" "uuid", "p_error" "text", "p_permanent" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  update public.safety_image_evaluation_jobs
  set
    status = case
      when p_permanent then 'skipped'
      when attempt_count >= 5 then 'dead_letter'
      else 'failed'
    end,
    available_at = case
      when p_permanent or attempt_count >= 5
        then available_at
      else now() + make_interval(
        mins => least(
          60,
          greatest(1, attempt_count * 5)
        )
      )
    end,
    locked_at = null,
    locked_by = null,
    completed_at = case
      when p_permanent then now()
      else completed_at
    end,
    last_error = left(
      coalesce(p_error, 'unknown_image_worker_error'),
      4000
    ),
    updated_at = now()
  where id = p_job_id;

  return found;
end;
$$;

ALTER FUNCTION "public"."safety_fail_image_job_v1"("p_job_id" "uuid", "p_error" "text", "p_permanent" boolean) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_fail_text_job_v1"("p_job_id" "uuid", "p_error" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin update public.safety_text_evaluation_jobs set status=case when attempt_count>=5 then 'dead_letter' else 'failed' end,available_at=case when attempt_count>=5 then available_at else now()+make_interval(mins=>least(60,greatest(1,attempt_count*5))) end,locked_at=null,locked_by=null,last_error=left(coalesce(p_error,'unknown_worker_error'),4000),updated_at=now() where id=p_job_id; return found; end; $$;

ALTER FUNCTION "public"."safety_fail_text_job_v1"("p_job_id" "uuid", "p_error" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_get_case_for_owner_change_v1"("p_owner_change_event_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_result jsonb;
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;

  select jsonb_build_object(
    'case_id', c.id,
    'case_status', c.case_status,
    'content_item_id', i.id,
    'content_type', i.content_type
  )
  into v_result
  from public.safety_content_items i
  join public.safety_cases c on c.content_item_id = i.id
  where i.entity_type = 'spot_owner_change'
    and i.entity_id = p_owner_change_event_id
    and (
      i.actor_user_id = auth.uid()
      or public.safety_is_admin_v1()
    )
  order by c.created_at desc
  limit 1;

  return v_result;
end;
$$;

ALTER FUNCTION "public"."safety_get_case_for_owner_change_v1"("p_owner_change_event_id" "uuid") OWNER TO "postgres";

CREATE TABLE IF NOT EXISTS "public"."safety_policy_versions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "policy_key" "text" NOT NULL,
    "version" "text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "policy" "jsonb" NOT NULL,
    "created_by" "uuid",
    "activated_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "safety_policy_versions_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'shadow'::"text", 'active'::"text", 'retired'::"text"])))
);

ALTER TABLE "public"."safety_policy_versions" OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_get_current_policy_v1"("p_policy_key" "text" DEFAULT 'backyrd-global'::"text") RETURNS "public"."safety_policy_versions"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select *
  from public.safety_policy_versions
  where policy_key=p_policy_key and status in ('active','shadow')
  order by case status when 'active' then 0 else 1 end, activated_at desc nulls last, created_at desc
  limit 1;
$$;

ALTER FUNCTION "public"."safety_get_current_policy_v1"("p_policy_key" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_get_or_create_reportable_content_v1"("p_content_type" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_spot_id" "uuid" DEFAULT NULL::"uuid", "p_text_content" "text" DEFAULT NULL::"text", "p_image_urls" "text"[] DEFAULT '{}'::"text"[], "p_locale" "text" DEFAULT 'de-CH'::"text", "p_context" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_content_item_id uuid;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  if p_entity_id is null then
    raise exception 'entity_id_required';
  end if;

  if p_content_type not in (
    'review',
    'moment',
    'comment',
    'profile',
    'spot',
    'owner_spot_profile'
  ) then
    raise exception 'unsupported_content_type';
  end if;

  select id
  into v_content_item_id
  from public.safety_content_items
  where entity_type = p_entity_type
    and entity_id = p_entity_id
  order by created_at desc
  limit 1;

  if v_content_item_id is null then
    insert into public.safety_content_items(
      content_type,
      entity_type,
      entity_id,
      actor_user_id,
      spot_id,
      text_content,
      image_urls,
      locale,
      context,
      lifecycle_status
    )
    values(
      p_content_type,
      p_entity_type,
      p_entity_id,
      p_actor_user_id,
      p_spot_id,
      nullif(trim(coalesce(p_text_content, '')), ''),
      coalesce(p_image_urls, '{}'::text[]),
      nullif(trim(coalesce(p_locale, '')), ''),
      coalesce(p_context, '{}'::jsonb),
      'live'
    )
    returning id into v_content_item_id;
  else
    update public.safety_content_items
    set
      content_type = p_content_type,
      actor_user_id = coalesce(
        p_actor_user_id,
        actor_user_id
      ),
      spot_id = coalesce(p_spot_id, spot_id),
      text_content = case
        when p_text_content is not null
          then nullif(trim(p_text_content), '')
        else text_content
      end,
      image_urls = case
        when cardinality(
          coalesce(p_image_urls, '{}'::text[])
        ) > 0
          then p_image_urls
        else image_urls
      end,
      locale = coalesce(
        nullif(trim(coalesce(p_locale, '')), ''),
        locale
      ),
      context = coalesce(context, '{}'::jsonb)
        || coalesce(p_context, '{}'::jsonb)
    where id = v_content_item_id;
  end if;

  return jsonb_build_object(
    'ok', true,
    'content_item_id', v_content_item_id,
    'entity_type', p_entity_type,
    'entity_id', p_entity_id
  );
end;
$$;

ALTER FUNCTION "public"."safety_get_or_create_reportable_content_v1"("p_content_type" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_actor_user_id" "uuid", "p_spot_id" "uuid", "p_text_content" "text", "p_image_urls" "text"[], "p_locale" "text", "p_context" "jsonb") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_guard_user_report_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_burst_count integer;
  v_daily_count integer;
  v_restricted_until timestamptz;
begin
  if new.reporter_user_id is null then
    new.reporter_user_id := auth.uid();
  end if;

  if new.reporter_user_id is null then
    raise exception 'not_authenticated';
  end if;

  select reputation.report_restricted_until
  into v_restricted_until
  from public.safety_reporter_reputation reputation
  where reputation.user_id = new.reporter_user_id;

  if v_restricted_until is not null
     and v_restricted_until > now() then
    raise exception using
      errcode = 'P0001',
      message = 'SAFETY_REPORTING_RESTRICTED',
      detail = jsonb_build_object(
        'restricted_until', v_restricted_until
      )::text;
  end if;

  if exists (
    select 1
    from public.safety_user_reports report
    where report.reporter_user_id = new.reporter_user_id
      and report.content_item_id = new.content_item_id
      and report.created_at >= now() - interval '30 days'
  ) then
    insert into public.safety_report_abuse_events(
      reporter_user_id,
      event_type,
      content_item_id,
      limit_window,
      threshold
    )
    values(
      new.reporter_user_id,
      'duplicate_report_blocked',
      new.content_item_id,
      '30_days',
      1
    );

    update public.safety_reporter_reputation
    set
      duplicate_attempts = duplicate_attempts + 1,
      updated_at = now()
    where user_id = new.reporter_user_id;

    raise exception 'SAFETY_DUPLICATE_REPORT';
  end if;

  select count(*)::integer
  into v_burst_count
  from public.safety_user_reports report
  where report.reporter_user_id = new.reporter_user_id
    and report.created_at >= now() - interval '10 minutes';

  if v_burst_count >= 5 then
    insert into public.safety_report_abuse_events(
      reporter_user_id,
      event_type,
      content_item_id,
      limit_window,
      current_count,
      threshold
    )
    values(
      new.reporter_user_id,
      'burst_limit_blocked',
      new.content_item_id,
      '10_minutes',
      v_burst_count,
      5
    );

    insert into public.safety_reporter_reputation(
      user_id,
      rate_limit_hits,
      report_restricted_until,
      updated_at
    )
    values(
      new.reporter_user_id,
      1,
      now() + interval '60 minutes',
      now()
    )
    on conflict(user_id)
    do update set
      rate_limit_hits =
        public.safety_reporter_reputation.rate_limit_hits + 1,
      report_restricted_until =
        greatest(
          coalesce(
            public.safety_reporter_reputation.report_restricted_until,
            now()
          ),
          now() + interval '60 minutes'
        ),
      updated_at = now();

    raise exception 'SAFETY_REPORT_RATE_LIMIT_10_MINUTES';
  end if;

  select count(*)::integer
  into v_daily_count
  from public.safety_user_reports report
  where report.reporter_user_id = new.reporter_user_id
    and report.created_at >= now() - interval '24 hours';

  if v_daily_count >= 20 then
    insert into public.safety_report_abuse_events(
      reporter_user_id,
      event_type,
      content_item_id,
      limit_window,
      current_count,
      threshold
    )
    values(
      new.reporter_user_id,
      'daily_limit_blocked',
      new.content_item_id,
      '24_hours',
      v_daily_count,
      20
    );

    insert into public.safety_reporter_reputation(
      user_id,
      rate_limit_hits,
      report_restricted_until,
      updated_at
    )
    values(
      new.reporter_user_id,
      1,
      now() + interval '24 hours',
      now()
    )
    on conflict(user_id)
    do update set
      rate_limit_hits =
        public.safety_reporter_reputation.rate_limit_hits + 1,
      report_restricted_until =
        greatest(
          coalesce(
            public.safety_reporter_reputation.report_restricted_until,
            now()
          ),
          now() + interval '24 hours'
        ),
      updated_at = now();

    raise exception 'SAFETY_REPORT_RATE_LIMIT_24_HOURS';
  end if;

  insert into public.safety_reporter_reputation(
    user_id,
    total_reports,
    last_report_at,
    updated_at
  )
  values(
    new.reporter_user_id,
    1,
    now(),
    now()
  )
  on conflict(user_id)
  do update set
    total_reports =
      public.safety_reporter_reputation.total_reports + 1,
    last_report_at = now(),
    updated_at = now();

  return new;
end;
$$;

ALTER FUNCTION "public"."safety_guard_user_report_v1"() OWNER TO "postgres";

