CREATE OR REPLACE FUNCTION "public"."safety_my_account_status_v1"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare v_result jsonb;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;

  update public.safety_account_enforcements
  set status='expired',updated_at=now()
  where user_id=auth.uid() and status='active'
    and ends_at is not null and ends_at<=now();

  select jsonb_build_object(
    'active',coalesce(jsonb_agg(jsonb_build_object(
      'id',e.id,'type',e.enforcement_type,
      'public_explanation',e.public_explanation,
      'starts_at',e.starts_at,'ends_at',e.ends_at,'case_id',e.case_id
    ) order by e.starts_at desc) filter(where e.id is not null),'[]'::jsonb),
    'active_strikes',count(*) filter(where e.enforcement_type='strike'),
    'capabilities',jsonb_build_object(
      'can_post',not bool_or(e.enforcement_type in (
        'posting_restriction','temporary_suspension','permanent_suspension')),
      'can_comment',not bool_or(e.enforcement_type in (
        'commenting_restriction','temporary_suspension','permanent_suspension')),
      'can_message',not bool_or(e.enforcement_type in (
        'messaging_restriction','temporary_suspension','permanent_suspension')),
      'can_edit_owner_content',not bool_or(e.enforcement_type in (
        'owner_edit_restriction','temporary_suspension','permanent_suspension')),
      'account_access',not bool_or(e.enforcement_type in (
        'temporary_suspension','permanent_suspension'))
    )
  ) into v_result
  from public.safety_account_enforcements e
  where e.user_id=auth.uid() and e.status='active'
    and e.starts_at<=now() and (e.ends_at is null or e.ends_at>now());

  return coalesce(v_result,jsonb_build_object(
    'active','[]'::jsonb,'active_strikes',0,
    'capabilities',jsonb_build_object(
      'can_post',true,'can_comment',true,'can_message',true,
      'can_edit_owner_content',true,'account_access',true
    )
  ));
end;
$$;

ALTER FUNCTION "public"."safety_my_account_status_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_my_actions_v1"("p_limit" integer DEFAULT 100) RETURNS TABLE("case_id" "uuid", "content_item_id" "uuid", "content_type" "text", "entity_type" "text", "entity_id" "uuid", "spot_id" "uuid", "text_content" "text", "image_urls" "text"[], "lifecycle_status" "text", "final_action" "text", "final_category" "text", "final_severity" integer, "explanation_public" "text", "explanation_code" "text", "decided_at" timestamp with time zone, "appeal_id" "uuid", "appeal_status" "text", "appeal_outcome" "text", "appeal_reason" "text", "appeal_statement" "text", "appeal_submitted_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;

  return query
  select
    c.id,
    i.id,
    i.content_type,
    i.entity_type,
    i.entity_id,
    i.spot_id,
    i.text_content,
    i.image_urls,
    i.lifecycle_status,
    c.final_action,
    c.final_category,
    c.final_severity,
    c.explanation_public,
    c.explanation_code,
    c.decided_at,
    a.id,
    a.status,
    a.outcome,
    a.appeal_reason,
    a.statement,
    a.submitted_at
  from public.safety_cases c
  join public.safety_content_items i
    on i.id = c.content_item_id
  left join lateral (
    select appeal.*
    from public.safety_appeals appeal
    where appeal.case_id = c.id
      and appeal.appellant_user_id = auth.uid()
    order by appeal.submitted_at desc
    limit 1
  ) a on true
  where i.actor_user_id = auth.uid()
    and c.case_status = 'decided'
    and (
      c.final_action in (
        'limit',
        'temporary_hide',
        'remove'
      )
      or a.id is not null
    )
  order by greatest(
    coalesce(a.reviewed_at, '-infinity'::timestamptz),
    coalesce(a.submitted_at, '-infinity'::timestamptz),
    coalesce(c.decided_at, '-infinity'::timestamptz)
  ) desc
  limit greatest(
    1,
    least(coalesce(p_limit, 100), 500)
  );
end;
$$;

ALTER FUNCTION "public"."safety_my_actions_v1"("p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_my_notices_v1"("p_limit" integer DEFAULT 100) RETURNS TABLE("notice_id" "uuid", "notice_type" "text", "title" "text", "body" "text", "action_label" "text", "action_path" "text", "case_id" "uuid", "appeal_id" "uuid", "metadata" "jsonb", "read_at" timestamp with time zone, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  return query
  select n.id,n.notice_type,n.title,n.body,n.action_label,n.action_path,
         n.case_id,n.appeal_id,n.metadata,n.read_at,n.created_at
  from public.safety_user_notices n
  where n.user_id=auth.uid()
  order by n.created_at desc
  limit greatest(1,least(coalesce(p_limit,100),500));
end;
$$;

ALTER FUNCTION "public"."safety_my_notices_v1"("p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_my_reports_v1"("p_limit" integer DEFAULT 100) RETURNS TABLE("report_id" "uuid", "report_reason" "text", "report_status" "text", "report_details" "text", "source_surface" "text", "created_at" timestamp with time zone, "reviewed_at" timestamp with time zone, "resolution_note" "text", "case_id" "uuid", "content_item_id" "uuid", "content_type" "text", "entity_type" "text", "entity_id" "uuid", "spot_id" "uuid", "text_content" "text", "image_urls" "text"[], "lifecycle_status" "text", "case_status" "text", "final_action" "text", "explanation_public" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;

  return query
  select
    r.id,
    r.report_reason,
    r.report_status,
    r.report_details,
    r.source_surface,
    r.created_at,
    r.reviewed_at,
    r.resolution_note,
    r.case_id,
    i.id,
    i.content_type,
    i.entity_type,
    i.entity_id,
    i.spot_id,
    i.text_content,
    i.image_urls,
    i.lifecycle_status,
    c.case_status,
    c.final_action,
    c.explanation_public
  from public.safety_user_reports r
  join public.safety_content_items i
    on i.id = r.content_item_id
  left join public.safety_cases c
    on c.id = r.case_id
  where r.reporter_user_id = auth.uid()
  order by r.created_at desc
  limit greatest(
    1,
    least(coalesce(p_limit, 100), 500)
  );
end;
$$;

ALTER FUNCTION "public"."safety_my_reports_v1"("p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_normalize_review_text_v1"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  select trim(
    regexp_replace(
      regexp_replace(
        lower(coalesce(p_text, '')),
        '[[:punct:]]+',
        ' ',
        'g'
      ),
      '\s+',
      ' ',
      'g'
    )
  );
$$;

ALTER FUNCTION "public"."safety_normalize_review_text_v1"("p_text" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_owner_change_text_v1"("p_change_area" "text", "p_new_data" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare
  v_parts text[] := '{}'::text[];
begin
  if p_change_area in ('profile', 'mobile_profile') then
    v_parts := array[
      nullif(trim(coalesce(p_new_data ->> 'name', '')), ''),
      nullif(trim(coalesce(p_new_data ->> 'owner_description', '')), ''),
      nullif(trim(coalesce(
        array_to_string(
          array(select jsonb_array_elements_text(coalesce(p_new_data -> 'owner_keywords', '[]'::jsonb))),
          ', '
        ),
        ''
      )), '')
    ];
  elsif p_change_area = 'intelligence' then
    v_parts := array[
      nullif(trim(coalesce(
        array_to_string(array(select jsonb_array_elements_text(coalesce(p_new_data -> 'best_for', '[]'::jsonb))), ', '),
        ''
      )), ''),
      nullif(trim(coalesce(
        array_to_string(array(select jsonb_array_elements_text(coalesce(p_new_data -> 'occasion_tags', '[]'::jsonb))), ', '),
        ''
      )), ''),
      nullif(trim(coalesce(
        array_to_string(array(select jsonb_array_elements_text(coalesce(p_new_data -> 'atmosphere_tags', '[]'::jsonb))), ', '),
        ''
      )), ''),
      nullif(trim(coalesce(
        array_to_string(array(select jsonb_array_elements_text(coalesce(p_new_data -> 'avoid_if_tags', '[]'::jsonb))), ', '),
        ''
      )), ''),
      nullif(trim(coalesce(
        array_to_string(array(select jsonb_array_elements_text(coalesce(p_new_data -> 'signature_items', '[]'::jsonb))), ', '),
        ''
      )), ''),
      nullif(trim(coalesce(p_new_data ->> 'special_notes', '')), '')
    ];
  end if;

  return nullif(
    trim(
      array_to_string(
        array(select x from unnest(v_parts) x where x is not null),
        E'\n'
      )
    ),
    ''
  );
end;
$$;

ALTER FUNCTION "public"."safety_owner_change_text_v1"("p_change_area" "text", "p_new_data" "jsonb") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_raise_review_integrity_signal_v1"("p_review_id" "uuid", "p_signal_type" "text", "p_risk_level" "text", "p_integrity_score" numeric DEFAULT NULL::numeric, "p_categories" "jsonb" DEFAULT '{}'::"jsonb", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("case_id" "uuid", "signal_id" "uuid", "case_status" "text", "priority" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_content_item_id uuid;
  v_case_id uuid;
  v_signal_id uuid;
  v_policy_version_id uuid;
  v_priority integer;
  v_existing_signal_id uuid;
begin

  -- ----------------------------------------------------------
  -- Eingaben validieren
  -- ----------------------------------------------------------

  if p_review_id is null then
    raise exception 'review_id_required';
  end if;

  if nullif(trim(coalesce(p_signal_type, '')), '') is null then
    raise exception 'signal_type_required';
  end if;

  if p_signal_type not like 'review_integrity_%' then
    raise exception 'invalid_review_integrity_signal_type';
  end if;

  if p_risk_level not in ('suspicious', 'high_risk') then
    raise exception 'invalid_review_integrity_risk_level';
  end if;


  -- ----------------------------------------------------------
  -- Review muss existieren
  -- ----------------------------------------------------------

  if not exists (
    select 1
    from public.reviews r
    where r.id = p_review_id
  ) then
    raise exception 'review_not_found';
  end if;


  -- ----------------------------------------------------------
  -- Bestehenden Registry-Eintrag verwenden
  -- ----------------------------------------------------------

  select ci.id
  into v_content_item_id
  from public.safety_content_items ci
  where ci.content_type = 'review'
    and ci.entity_type = 'review'
    and ci.entity_id = p_review_id
  limit 1;

  if v_content_item_id is null then
    raise exception 'review_not_registered_in_safety_registry';
  end if;


  -- ----------------------------------------------------------
  -- Priority nach Risk-Level
  -- ----------------------------------------------------------

  v_priority :=
    case p_risk_level
      when 'high_risk' then 80
      else 60
    end;


  -- ----------------------------------------------------------
  -- Bestehenden offenen Case verwenden
  --
  -- Wichtig:
  -- Kein zweiter paralleler Moderations-Case für denselben
  -- Content, wenn bereits einer offen ist.
  -- ----------------------------------------------------------

  select c.id
  into v_case_id
  from public.safety_cases c
  where c.content_item_id = v_content_item_id
    and c.case_status in (
      'queued',
      'evaluating',
      'needs_review'
    )
  order by c.created_at desc
  limit 1;


  -- ----------------------------------------------------------
  -- Falls kein offener Case existiert:
  -- neuen Integrity Case erzeugen
  -- ----------------------------------------------------------

  if v_case_id is null then

    select pv.id
    into v_policy_version_id
    from public.safety_policy_versions pv
    where pv.policy_key = 'backyrd-global'
      and pv.status in ('shadow', 'active')
    order by
      pv.activated_at desc nulls last,
      pv.created_at desc
    limit 1;

    if v_policy_version_id is null then
      raise exception 'active_or_shadow_safety_policy_missing';
    end if;

    insert into public.safety_cases (
      content_item_id,
      policy_version_id,
      case_status,
      priority,
      final_action,
      decision_source,
      explanation_code,
      explanation_internal
    )
    values (
      v_content_item_id,
      v_policy_version_id,
      'needs_review',
      v_priority,
      null,
      'automated_shadow',
      'REVIEW_INTEGRITY_SIGNAL',
      'Review authenticity or manipulation signal requires human review.'
    )
    returning id
    into v_case_id;

  else

    -- --------------------------------------------------------
    -- Bestehenden offenen Case hochstufen.
    --
    -- Keine automatische Entscheidung.
    -- Keine Enforcement-Maßnahme.
    -- --------------------------------------------------------

    update public.safety_cases c
    set
      case_status = 'needs_review',
      priority = greatest(c.priority, v_priority),
      updated_at = now()
    where c.id = v_case_id;

  end if;


  -- ----------------------------------------------------------
  -- Dasselbe Signal für denselben Review/Case nicht mehrfach
  -- erzeugen.
  -- ----------------------------------------------------------

  select s.id
  into v_existing_signal_id
  from public.safety_signals s
  where s.case_id = v_case_id
    and s.signal_type = p_signal_type
    and s.provider = 'backyrd_integrity'
    and s.raw_response->>'review_id' = p_review_id::text
  order by s.created_at desc
  limit 1;


  if v_existing_signal_id is not null then

    v_signal_id := v_existing_signal_id;

  else

    insert into public.safety_signals (
      case_id,
      signal_type,
      provider,
      model,
      model_version,
      categories,
      scores,
      flagged,
      raw_response,
      latency_ms,
      error_code
    )
    values (
      v_case_id,
      p_signal_type,
      'backyrd_integrity',
      'deterministic_rules',
      'review-integrity-v1',

      coalesce(p_categories, '{}'::jsonb)
        || jsonb_build_object(
          'risk_level',
          p_risk_level
        ),

      jsonb_build_object(
        'integrity_score',
        p_integrity_score
      ),

      true,

      coalesce(p_metadata, '{}'::jsonb)
        || jsonb_build_object(
          'review_id',
          p_review_id,
          'risk_level',
          p_risk_level,
          'integrity_version',
          'v1'
        ),

      null,
      null
    )
    returning id
    into v_signal_id;

  end if;


  -- ----------------------------------------------------------
  -- Ergebnis
  -- ----------------------------------------------------------

  return query
  select
    c.id,
    v_signal_id,
    c.case_status,
    c.priority
  from public.safety_cases c
  where c.id = v_case_id;

end;
$$;

ALTER FUNCTION "public"."safety_raise_review_integrity_signal_v1"("p_review_id" "uuid", "p_signal_type" "text", "p_risk_level" "text", "p_integrity_score" numeric, "p_categories" "jsonb", "p_metadata" "jsonb") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_recalculate_reporter_after_resolution_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if old.report_status is distinct from new.report_status
     and new.report_status in (
       'resolved_actioned',
       'resolved_no_violation'
     ) then
    perform public.safety_recalculate_reporter_reputation_v1(
      new.reporter_user_id
    );
  end if;

  return new;
end;
$$;

ALTER FUNCTION "public"."safety_recalculate_reporter_after_resolution_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_recalculate_reporter_reputation_v1"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_total integer;
  v_actioned integer;
  v_no_violation integer;
  v_duplicate integer;
  v_rate_hits integer;
  v_trust numeric(5,4);
  v_restricted_until timestamptz;
begin
  select
    count(*)::integer,
    count(*) filter (
      where report.report_status = 'resolved_actioned'
    )::integer,
    count(*) filter (
      where report.report_status = 'resolved_no_violation'
    )::integer
  into
    v_total,
    v_actioned,
    v_no_violation
  from public.safety_user_reports report
  where report.reporter_user_id = p_user_id
    and report.created_at >= now() - interval '90 days';

  select
    count(*) filter (
      where abuse.event_type = 'duplicate_report_blocked'
    )::integer,
    count(*) filter (
      where abuse.event_type in (
        'burst_limit_blocked',
        'daily_limit_blocked'
      )
    )::integer
  into
    v_duplicate,
    v_rate_hits
  from public.safety_report_abuse_events abuse
  where abuse.reporter_user_id = p_user_id
    and abuse.created_at >= now() - interval '90 days';

  v_trust := greatest(
    0.0500,
    least(
      1.0000,
      1.0000
      + least(v_actioned, 20) * 0.0200
      - least(v_no_violation, 20) * 0.0350
      - least(v_duplicate, 20) * 0.0250
      - least(v_rate_hits, 20) * 0.0400
    )
  );

  if v_total >= 8
     and v_no_violation::numeric / greatest(v_total, 1) >= 0.75
     and v_actioned <= 1 then
    v_restricted_until := now() + interval '72 hours';

    insert into public.safety_report_abuse_events(
      reporter_user_id,
      event_type,
      limit_window,
      current_count,
      threshold,
      metadata
    )
    values(
      p_user_id,
      'low_trust_restricted',
      '90_days',
      v_no_violation,
      8,
      jsonb_build_object(
        'total_reports', v_total,
        'actioned_reports', v_actioned,
        'trust_score', v_trust
      )
    );
  end if;

  insert into public.safety_reporter_reputation(
    user_id,
    trust_score,
    total_reports,
    actioned_reports,
    no_violation_reports,
    duplicate_attempts,
    rate_limit_hits,
    report_restricted_until,
    last_recalculated_at,
    updated_at
  )
  values(
    p_user_id,
    v_trust,
    v_total,
    v_actioned,
    v_no_violation,
    v_duplicate,
    v_rate_hits,
    v_restricted_until,
    now(),
    now()
  )
  on conflict(user_id)
  do update set
    trust_score = excluded.trust_score,
    total_reports = excluded.total_reports,
    actioned_reports = excluded.actioned_reports,
    no_violation_reports = excluded.no_violation_reports,
    duplicate_attempts = excluded.duplicate_attempts,
    rate_limit_hits = excluded.rate_limit_hits,
    report_restricted_until = coalesce(
      excluded.report_restricted_until,
      public.safety_reporter_reputation.report_restricted_until
    ),
    last_recalculated_at = now(),
    updated_at = now();

  return jsonb_build_object(
    'user_id', p_user_id,
    'trust_score', v_trust,
    'total_reports', v_total,
    'actioned_reports', v_actioned,
    'no_violation_reports', v_no_violation,
    'restricted_until', v_restricted_until
  );
end;
$$;

ALTER FUNCTION "public"."safety_recalculate_reporter_reputation_v1"("p_user_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_refresh_social_post_registry_media_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_post_id uuid := coalesce(new.post_id, old.post_id);
  v_post record;
  v_images text[];
begin
  select
    p.id,
    p.user_id,
    p.spot_id,
    p.caption,
    p.status
  into v_post
  from public.social_posts p
  where p.id = v_post_id;

  if v_post.id is null then
    return coalesce(new, old);
  end if;

  select coalesce(
    array_agg(m.storage_path order by m.sort_order)
      filter (
        where nullif(trim(m.storage_path), '') is not null
      ),
    '{}'::text[]
  )
  into v_images
  from public.social_post_media m
  where m.post_id = v_post_id;

  perform public.safety_upsert_registry_item_v2(
    'moment',
    'social_post',
    v_post.id,
    v_post.user_id,
    v_post.spot_id,
    v_post.caption,
    v_images,
    'de-CH',
    jsonb_build_object(
      'registry_version', 'v2',
      'source_table', 'social_post_media',
      'source_operation', tg_op,
      'synced_at', now()
    ),
    case v_post.status
      when 'hidden' then 'hidden'
      when 'deleted' then 'removed'
      when 'draft' then 'limited'
      else 'live'
    end
  );

  return coalesce(new, old);
end;
$$;

ALTER FUNCTION "public"."safety_refresh_social_post_registry_media_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_register_content_snapshot_v1"("p_entity_type" "text", "p_entity_id" "uuid", "p_content_type" "text", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_spot_id" "uuid" DEFAULT NULL::"uuid", "p_text_content" "text" DEFAULT NULL::"text", "p_image_urls" "text"[] DEFAULT '{}'::"text"[], "p_source_surface" "text" DEFAULT NULL::"text", "p_source_context" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor_user_id uuid;
  v_content_item_id uuid;
  v_case_id uuid;
  v_policy_version_id uuid;
  v_url text;
  v_has_images boolean;
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;

  v_actor_user_id := coalesce(
    p_actor_user_id,
    auth.uid()
  );

  if v_actor_user_id <> auth.uid()
     and not public.safety_is_admin_v1() then
    raise exception 'actor_mismatch';
  end if;

  v_has_images :=
    cardinality(
      coalesce(p_image_urls, '{}'::text[])
    ) > 0;

  select item.id
  into v_content_item_id
  from public.safety_content_items item
  where item.entity_type = p_entity_type
    and item.entity_id = p_entity_id
  order by item.created_at asc
  limit 1;

  if v_content_item_id is null then
    insert into public.safety_content_items(
      content_type,
      entity_type,
      entity_id,
      actor_user_id,
      spot_id,
      text_content,
      image_urls,
      lifecycle_status
    )
    values(
      p_content_type,
      p_entity_type,
      p_entity_id,
      v_actor_user_id,
      p_spot_id,
      nullif(
        trim(coalesce(p_text_content, '')),
        ''
      ),
      coalesce(
        p_image_urls,
        '{}'::text[]
      ),
      'live'
    )
    returning id
    into v_content_item_id;
  else
    update public.safety_content_items
    set
      content_type = p_content_type,
      actor_user_id = v_actor_user_id,
      spot_id = p_spot_id,
      text_content = nullif(
        trim(coalesce(p_text_content, '')),
        ''
      ),
      image_urls = coalesce(
        p_image_urls,
        '{}'::text[]
      )
    where id = v_content_item_id;
  end if;

  delete from public.safety_media_items
  where content_item_id = v_content_item_id
    and not (
      media_url = any(
        coalesce(
          p_image_urls,
          '{}'::text[]
        )
      )
    );

  foreach v_url in array coalesce(
    p_image_urls,
    '{}'::text[]
  )
  loop
    if nullif(trim(v_url), '') is not null then
      insert into public.safety_media_items(
        content_item_id,
        entity_type,
        entity_id,
        actor_user_id,
        spot_id,
        media_url,
        media_role,
        lifecycle_status,
        source_surface,
        source_context
      )
      values(
        v_content_item_id,
        p_entity_type,
        p_entity_id,
        v_actor_user_id,
        p_spot_id,
        v_url,
        case
          when p_entity_type = 'profile'
            then 'profile_image'
          else 'content_image'
        end,
        'live',
        p_source_surface,
        coalesce(
          p_source_context,
          '{}'::jsonb
        )
      )
      on conflict(content_item_id, media_url)
      do update set
        actor_user_id = excluded.actor_user_id,
        spot_id = excluded.spot_id,
        lifecycle_status = 'live',
        source_surface = excluded.source_surface,
        source_context = excluded.source_context,
        updated_at = now();
    end if;
  end loop;

  -- Every new or changed image snapshot gets an automated case.
  -- Existing open/evaluating case is reused.
  if v_has_images then
    select safety_case.id
    into v_case_id
    from public.safety_cases safety_case
    where safety_case.content_item_id =
      v_content_item_id
      and safety_case.case_status in (
        'queued',
        'evaluating',
        'needs_review'
      )
      and safety_case.decision_source in (
        'automated_shadow',
        'automated_policy',
        'image_upload'
      )
    order by safety_case.created_at desc
    limit 1;

    if v_case_id is null then
      select policy_version.id
      into v_policy_version_id
      from public.safety_policy_versions policy_version
      where policy_version.policy_key =
        'backyrd-global'
        and policy_version.status in (
          'shadow',
          'active'
        )
      order by
        policy_version.activated_at desc nulls last,
        policy_version.created_at desc
      limit 1;

      insert into public.safety_cases(
        content_item_id,
        policy_version_id,
        case_status,
        priority,
        final_action,
        decision_source,
        explanation_code,
        explanation_internal
      )
      values(
        v_content_item_id,
        v_policy_version_id,
        'queued',
        40,
        'allow_log',
        'image_upload',
        'IMAGE_ANALYSIS_QUEUED',
        concat(
          'Automatic image analysis queued. source=',
          coalesce(p_source_surface, 'unknown'),
          '; image_count=',
          cardinality(
            coalesce(
              p_image_urls,
              '{}'::text[]
            )
          )
        )
      )
      returning id
      into v_case_id;
    else
      update public.safety_cases
      set
        case_status = 'queued',
        final_action = 'allow_log',
        explanation_code =
          'IMAGE_ANALYSIS_REQUEUED',
        explanation_internal = concat(
          'Automatic image analysis requeued. source=',
          coalesce(p_source_surface, 'unknown'),
          '; image_count=',
          cardinality(
            coalesce(
              p_image_urls,
              '{}'::text[]
            )
          )
        ),
        updated_at = now()
      where id = v_case_id;
    end if;
  end if;

  return jsonb_build_object(
    'ok', true,
    'content_item_id',
      v_content_item_id,
    'case_id',
      v_case_id,
    'analysis_required',
      v_has_images,
    'media_count',
      cardinality(
        coalesce(
          p_image_urls,
          '{}'::text[]
        )
      )
  );
end;
$$;

ALTER FUNCTION "public"."safety_register_content_snapshot_v1"("p_entity_type" "text", "p_entity_id" "uuid", "p_content_type" "text", "p_actor_user_id" "uuid", "p_spot_id" "uuid", "p_text_content" "text", "p_image_urls" "text"[], "p_source_surface" "text", "p_source_context" "jsonb") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_reporter_status_v1"() RETURNS TABLE("trust_score" numeric, "total_reports" integer, "actioned_reports" integer, "no_violation_reports" integer, "duplicate_attempts" integer, "rate_limit_hits" integer, "report_restricted_until" timestamp with time zone, "can_report" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;

  perform public.safety_recalculate_reporter_reputation_v1(
    auth.uid()
  );

  return query
  select
    reputation.trust_score,
    reputation.total_reports,
    reputation.actioned_reports,
    reputation.no_violation_reports,
    reputation.duplicate_attempts,
    reputation.rate_limit_hits,
    reputation.report_restricted_until,
    coalesce(
      reputation.report_restricted_until <= now(),
      true
    )
  from public.safety_reporter_reputation reputation
  where reputation.user_id = auth.uid();
end;
$$;

ALTER FUNCTION "public"."safety_reporter_status_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_restore_last_allowed_owner_state_v1"("p_owner_change_event_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_event public.spot_owner_change_events%rowtype;
  v_snapshot jsonb;
  v_snapshot_event_id uuid;
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;

  if public.safety_is_admin_v1() is not true then
    raise exception 'admin_required';
  end if;

  select *
  into v_event
  from public.spot_owner_change_events
  where id = p_owner_change_event_id
  for update;

  if v_event.id is null then
    raise exception 'change_event_not_found';
  end if;

  /*
   * A restore source must:
   * - be earlier than the rejected revision
   * - have a final human/automated allow
   * - be classified as no violation
   * - not carry known violation reason codes
   * - pass the current local Policy V2 safety check
   */
  select
    previous_event.id,
    previous_event.new_data
  into
    v_snapshot_event_id,
    v_snapshot
  from public.spot_owner_change_events previous_event
  join public.safety_content_items item
    on item.entity_type = 'spot_owner_change'
   and item.entity_id = previous_event.id
  join public.safety_cases safety_case
    on safety_case.content_item_id = item.id
  where previous_event.spot_id = v_event.spot_id
    and previous_event.change_area = v_event.change_area
    and previous_event.created_at < v_event.created_at
    and safety_case.case_status = 'decided'
    and safety_case.final_action = 'allow'
    and coalesce(safety_case.final_category, 'none') = 'none'
    and coalesce(safety_case.final_severity, 0) = 0
    and coalesce(
      safety_case.explanation_code,
      'NO_POLICY_VIOLATION'
    ) = 'NO_POLICY_VIOLATION'
    and public.safety_text_has_local_policy_violation_v1(
      item.text_content
    ) is false
    and not exists (
      select 1
      from public.safety_decision_events decision_event
      where decision_event.case_id = safety_case.id
        and decision_event.reason_codes && array[
          'DISCRIMINATORY_EXCLUSION',
          'AMBIGUOUS_GROUP_TARGET',
          'EXCLUSION_LANGUAGE',
          'PROTECTED_CHARACTERISTIC',
          'DENIAL_OF_ACCESS_OR_SERVICE'
        ]::text[]
    )
  order by previous_event.created_at desc
  limit 1;

  if v_snapshot is null then
    if public.safety_text_has_local_policy_violation_v1(
      concat_ws(
        E'\n',
        v_event.old_data ->> 'name',
        v_event.old_data ->> 'owner_description'
      )
    ) is false then
      v_snapshot := coalesce(v_event.old_data, '{}'::jsonb);
      v_snapshot_event_id := null;
    else
      raise exception 'no_safe_restore_snapshot_found';
    end if;
  end if;

  if v_event.change_area in ('profile', 'mobile_profile') then
    update public.spots
    set
      name = case
        when v_snapshot ? 'name'
          then coalesce(nullif(v_snapshot ->> 'name', ''), name)
        else name
      end,
      address = case
        when v_snapshot ? 'address'
          then nullif(v_snapshot ->> 'address', '')
        else address
      end,
      city = case
        when v_snapshot ? 'city'
          then nullif(v_snapshot ->> 'city', '')
        else city
      end,
      country = case
        when v_snapshot ? 'country'
          then nullif(v_snapshot ->> 'country', '')
        else country
      end,
      category_id = case
        when v_snapshot ? 'category_id'
          and nullif(v_snapshot ->> 'category_id', '') is not null
          then (v_snapshot ->> 'category_id')::uuid
        else category_id
      end,
      phone = case
        when v_snapshot ? 'phone'
          then nullif(v_snapshot ->> 'phone', '')
        else phone
      end,
      website = case
        when v_snapshot ? 'website'
          then nullif(v_snapshot ->> 'website', '')
        else website
      end,
      email = case
        when v_snapshot ? 'email'
          then nullif(v_snapshot ->> 'email', '')
        else email
      end,
      price_level = case
        when v_snapshot ? 'price_level'
          and nullif(v_snapshot ->> 'price_level', '') is not null
          then (v_snapshot ->> 'price_level')::integer
        else price_level
      end,
      updated_at = now()
    where id = v_event.spot_id;

    update public.spot_descriptions
    set
      owner_description = case
        when v_snapshot ? 'owner_description'
          then nullif(v_snapshot ->> 'owner_description', '')
        else owner_description
      end,
      owner_keywords = case
        when v_snapshot ? 'owner_keywords'
          then coalesce(
            array(
              select jsonb_array_elements_text(
                coalesce(
                  v_snapshot -> 'owner_keywords',
                  '[]'::jsonb
                )
              )
            ),
            '{}'::text[]
          )
        else owner_keywords
      end,
      owner_updated_at = now(),
      content_status = 'published',
      updated_at = now()
    where spot_id = v_event.spot_id;

  elsif v_event.change_area = 'intelligence' then
    update public.spot_intelligence_v1
    set
      best_for = coalesce(
        array(
          select jsonb_array_elements_text(
            coalesce(v_snapshot -> 'best_for', '[]'::jsonb)
          )
        ),
        '{}'::text[]
      ),
      occasion_tags = coalesce(
        array(
          select jsonb_array_elements_text(
            coalesce(v_snapshot -> 'occasion_tags', '[]'::jsonb)
          )
        ),
        '{}'::text[]
      ),
      atmosphere_tags = coalesce(
        array(
          select jsonb_array_elements_text(
            coalesce(v_snapshot -> 'atmosphere_tags', '[]'::jsonb)
          )
        ),
        '{}'::text[]
      ),
      avoid_if_tags = coalesce(
        array(
          select jsonb_array_elements_text(
            coalesce(v_snapshot -> 'avoid_if_tags', '[]'::jsonb)
          )
        ),
        '{}'::text[]
      ),
      good_for_time = coalesce(
        array(
          select jsonb_array_elements_text(
            coalesce(v_snapshot -> 'good_for_time', '[]'::jsonb)
          )
        ),
        '{}'::text[]
      ),
      noise_level = nullif(v_snapshot ->> 'noise_level', ''),
      crowd_type = coalesce(
        array(
          select jsonb_array_elements_text(
            coalesce(v_snapshot -> 'crowd_type', '[]'::jsonb)
          )
        ),
        '{}'::text[]
      ),
      dress_code = nullif(v_snapshot ->> 'dress_code', ''),
      reservation_recommended = case
        when v_snapshot ? 'reservation_recommended'
          then (v_snapshot ->> 'reservation_recommended')::boolean
        else null
      end,
      average_duration_minutes = case
        when nullif(
          v_snapshot ->> 'average_duration_minutes',
          ''
        ) is not null
          then (
            v_snapshot ->> 'average_duration_minutes'
          )::integer
        else null
      end,
      signature_items = coalesce(
        array(
          select jsonb_array_elements_text(
            coalesce(v_snapshot -> 'signature_items', '[]'::jsonb)
          )
        ),
        '{}'::text[]
      ),
      special_notes = nullif(v_snapshot ->> 'special_notes', ''),
      updated_by = auth.uid(),
      updated_at = now()
    where spot_id = v_event.spot_id;

  else
    raise exception 'unsupported_change_area:%', v_event.change_area;
  end if;

  update public.spot_owner_change_events
  set
    moderation_status = 'reverted',
    moderation_note = coalesce(
      moderation_note,
      'Restored last safe state by Safety & Integrity Policy V2.'
    ),
    reviewed_by = auth.uid(),
    reviewed_at = now(),
    reverted_at = now()
  where id = v_event.id;

  return jsonb_build_object(
    'ok', true,
    'event_id', v_event.id,
    'spot_id', v_event.spot_id,
    'change_area', v_event.change_area,
    'restored_snapshot_event_id', v_snapshot_event_id
  );
end;
$$;

ALTER FUNCTION "public"."safety_restore_last_allowed_owner_state_v1"("p_owner_change_event_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_reverse_violation_on_appeal_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid;
  v_points integer;
begin
  if new.status <> 'decided'
     or new.outcome <> 'overturned' then
    return new;
  end if;

  if old.status = 'decided'
     and old.outcome = 'overturned' then
    return new;
  end if;

  select
    event.user_id,
    coalesce(sum(event.points), 0)::integer
  into
    v_user_id,
    v_points
  from public.safety_user_enforcement_events event
  where event.case_id = new.case_id
    and event.event_type = 'violation_confirmed'
  group by event.user_id
  limit 1;

  if v_user_id is null or v_points <= 0 then
    return new;
  end if;

  if not exists (
    select 1
    from public.safety_user_enforcement_events event
    where event.case_id = new.case_id
      and event.event_type = 'violation_reversed'
  ) then
    insert into public.safety_user_enforcement_events(
      user_id,
      case_id,
      event_type,
      points,
      action,
      reason,
      metadata
    )
    values(
      v_user_id,
      new.case_id,
      'violation_reversed',
      -v_points,
      'appeal_overturned',
      'Violation points reversed after successful appeal',
      jsonb_build_object(
        'appeal_id', new.id,
        'reversed_points', v_points
      )
    );
  end if;

  -- Revoke active warning/suspension that originated from this case
  -- when the user's rolling score no longer meets its threshold.
  update public.safety_account_measures measure
  set
    status = 'revoked',
    revoked_at = now(),
    updated_at = now(),
    internal_note = concat_ws(
      E'\n',
      measure.internal_note,
      'Automatically revoked after successful appeal.'
    )
  where measure.user_id = v_user_id
    and measure.status = 'active'
    and measure.source_case_id = new.case_id;

  return new;
end;
$$;

ALTER FUNCTION "public"."safety_reverse_violation_on_appeal_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_review_burst_after_insert_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
begin

  -- ----------------------------------------------------------
  -- A. Burst / Copy-Paste
  -- ----------------------------------------------------------

  begin

    perform *
    from public.safety_evaluate_review_burst_v1(new.id);

  exception
    when others then

      raise warning
        'review burst evaluation failed for review %: %',
        new.id,
        sqlerrm;

  end;


  -- ----------------------------------------------------------
  -- B. New Account Brigading
  -- ----------------------------------------------------------

  begin

    perform *
    from public.safety_evaluate_review_new_account_brigade_v1(
      new.id,
      7,
      48
    );

  exception
    when others then

      raise warning
        'new account brigade evaluation failed for review %: %',
        new.id,
        sqlerrm;

  end;


  -- ----------------------------------------------------------
  -- C. Repeated Coordinated Group
  -- ----------------------------------------------------------

  begin

    perform *
    from public.safety_evaluate_review_repeated_group_v1(
      new.id
    );

  exception
    when others then

      raise warning
        'repeated review group evaluation failed for review %: %',
        new.id,
        sqlerrm;

  end;


  return new;

end;
$$;

ALTER FUNCTION "public"."safety_review_burst_after_insert_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_review_integrity_after_insert_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog', 'extensions'
    AS $$
begin

  begin

    perform *
    from public.safety_evaluate_review_integrity_v1(new.id);

  exception
    when others then

      -- Shadow-first / fail-open:
      -- Review bleibt bestehen.
      raise warning
        'Review integrity evaluation failed for review %: %',
        new.id,
        sqlerrm;

  end;

  return new;

end;
$$;

ALTER FUNCTION "public"."safety_review_integrity_after_insert_v1"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_stable_entity_uuid_v1"("p_entity_type" "text", "p_source_id" "text") RETURNS "uuid"
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO 'pg_catalog'
    AS $$
  select (
    substr(md5(p_entity_type || ':' || p_source_id), 1, 8)
    || '-'
    || substr(md5(p_entity_type || ':' || p_source_id), 9, 4)
    || '-'
    || substr(md5(p_entity_type || ':' || p_source_id), 13, 4)
    || '-'
    || substr(md5(p_entity_type || ':' || p_source_id), 17, 4)
    || '-'
    || substr(md5(p_entity_type || ':' || p_source_id), 21, 12)
  )::uuid;
$$;

ALTER FUNCTION "public"."safety_stable_entity_uuid_v1"("p_entity_type" "text", "p_source_id" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_submit_appeal_v1"("p_case_id" "uuid", "p_appeal_reason" "text", "p_statement" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_case public.safety_cases%rowtype;
  v_content public.safety_content_items%rowtype;
  v_appeal_id uuid;
  v_policy_version text;
  v_existing_appeal_id uuid;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  if char_length(trim(coalesce(p_statement, ''))) < 10 then
    raise exception 'appeal_statement_too_short';
  end if;

  select *
  into v_case
  from public.safety_cases
  where id = p_case_id;

  if v_case.id is null then
    raise exception 'case_not_found';
  end if;

  if v_case.case_status <> 'decided' then
    raise exception 'case_not_decided';
  end if;

  if coalesce(v_case.final_action, 'allow') not in (
    'limit',
    'temporary_hide',
    'remove',
    'block_submit'
  ) then
    raise exception 'case_not_appealable';
  end if;

  select *
  into v_content
  from public.safety_content_items
  where id = v_case.content_item_id;

  if v_content.id is null then
    raise exception 'content_item_not_found';
  end if;

  if v_content.actor_user_id is distinct from v_user_id then
    raise exception 'appeal_not_allowed_for_user';
  end if;

  select id
  into v_existing_appeal_id
  from public.safety_appeals
  where case_id = p_case_id
    and appellant_user_id = v_user_id
    and status in ('submitted', 'in_review')
  order by submitted_at desc
  limit 1;

  if v_existing_appeal_id is not null then
    return jsonb_build_object(
      'ok', true,
      'duplicate', true,
      'appeal_id', v_existing_appeal_id,
      'case_id', p_case_id
    );
  end if;

  select version
  into v_policy_version
  from public.safety_policy_versions
  where id = v_case.policy_version_id;

  insert into public.safety_appeals(
    case_id,
    appellant_user_id,
    statement,
    status,
    outcome,
    appeal_reason,
    original_action,
    original_category,
    original_severity,
    original_policy_version,
    submitted_at,
    updated_at
  )
  values(
    p_case_id,
    v_user_id,
    trim(p_statement),
    'submitted',
    null,
    p_appeal_reason,
    v_case.final_action,
    v_case.final_category,
    v_case.final_severity,
    v_policy_version,
    now(),
    now()
  )
  returning id into v_appeal_id;

  insert into public.safety_decision_events(
    case_id,
    action,
    category,
    severity,
    confidence,
    source,
    policy_snapshot,
    reason_codes,
    metadata
  )
  values(
    p_case_id,
    v_case.final_action,
    v_case.final_category,
    v_case.final_severity,
    v_case.final_confidence,
    'appeal',
    '{}'::jsonb,
    array[
      'APPEAL_SUBMITTED',
      concat(
        'APPEAL_REASON_',
        upper(p_appeal_reason)
      )
    ]::text[],
    jsonb_build_object(
      'appeal_id', v_appeal_id,
      'appellant_user_id', v_user_id
    )
  );

  return jsonb_build_object(
    'ok', true,
    'duplicate', false,
    'appeal_id', v_appeal_id,
    'case_id', p_case_id,
    'status', 'submitted'
  );
end;
$$;

ALTER FUNCTION "public"."safety_submit_appeal_v1"("p_case_id" "uuid", "p_appeal_reason" "text", "p_statement" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_submit_content_v1"("p_content_type" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_spot_id" "uuid" DEFAULT NULL::"uuid", "p_text_content" "text" DEFAULT NULL::"text", "p_image_urls" "text"[] DEFAULT '{}'::"text"[], "p_locale" "text" DEFAULT NULL::"text", "p_context" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_item_id uuid;
  v_case_id uuid;
  v_policy public.safety_policy_versions%rowtype;
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;

  select * into v_policy from public.safety_get_current_policy_v1('backyrd-global');

  insert into public.safety_content_items(
    content_type, entity_type, entity_id, spot_id, actor_user_id,
    locale, text_content, image_urls, context
  ) values(
    p_content_type, p_entity_type, p_entity_id, p_spot_id, auth.uid(),
    p_locale, nullif(p_text_content,''), coalesce(p_image_urls,'{}'::text[]), coalesce(p_context,'{}'::jsonb)
  ) returning id into v_item_id;

  insert into public.safety_cases(content_item_id, policy_version_id, case_status, priority)
  values(v_item_id, v_policy.id, 'queued', 50)
  returning id into v_case_id;

  return jsonb_build_object('ok',true,'content_item_id',v_item_id,'case_id',v_case_id,'policy_version',v_policy.version);
end;
$$;

ALTER FUNCTION "public"."safety_submit_content_v1"("p_content_type" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_spot_id" "uuid", "p_text_content" "text", "p_image_urls" "text"[], "p_locale" "text", "p_context" "jsonb") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_submit_report_v1"("p_content_item_id" "uuid", "p_report_reason" "text", "p_report_details" "text" DEFAULT NULL::"text", "p_source_surface" "text" DEFAULT NULL::"text", "p_reporter_locale" "text" DEFAULT NULL::"text", "p_source_context" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_content public.safety_content_items%rowtype;
  v_case_id uuid;
  v_report_id uuid;
  v_existing_report_id uuid;
  v_policy_version_id uuid;
begin
  if v_user_id is null then
    raise exception 'not_authenticated';
  end if;

  select *
  into v_content
  from public.safety_content_items
  where id = p_content_item_id;

  if v_content.id is null then
    raise exception 'content_item_not_found';
  end if;

  select id
  into v_existing_report_id
  from public.safety_user_reports
  where content_item_id = p_content_item_id
    and reporter_user_id = v_user_id
    and report_status in (
      'submitted',
      'attached_to_case',
      'under_review'
    )
  order by created_at desc
  limit 1;

  if v_existing_report_id is not null then
    return jsonb_build_object(
      'ok', true,
      'duplicate', true,
      'report_id', v_existing_report_id
    );
  end if;

  select c.id
  into v_case_id
  from public.safety_cases c
  where c.content_item_id = p_content_item_id
    and c.case_status in (
      'queued',
      'evaluating',
      'needs_review'
    )
  order by c.created_at desc
  limit 1;

  if v_case_id is null then
    select id
    into v_policy_version_id
    from public.safety_policy_versions
    where policy_key = 'backyrd-global'
      and status in ('shadow', 'active')
    order by
      activated_at desc nulls last,
      created_at desc
    limit 1;

    insert into public.safety_cases(
      content_item_id,
      policy_version_id,
      case_status,
      priority,
      final_action,
      decision_source,
      explanation_code,
      explanation_internal
    )
    values(
      p_content_item_id,
      v_policy_version_id,
      'needs_review',
      50,
      'allow_log',
      'user_report',
      'USER_REPORT_RECEIVED',
      concat(
        'User report received. reason=',
        p_report_reason
      )
    )
    returning id into v_case_id;
  else
    update public.safety_cases
    set
      priority = least(
        100,
        coalesce(priority, 0) + 10
      ),
      updated_at = now()
    where id = v_case_id;
  end if;

  insert into public.safety_user_reports(
    content_item_id,
    case_id,
    reporter_user_id,
    report_reason,
    report_details,
    report_status,
    reporter_locale,
    source_surface,
    source_context
  )
  values(
    p_content_item_id,
    v_case_id,
    v_user_id,
    p_report_reason,
    nullif(trim(coalesce(p_report_details, '')), ''),
    'attached_to_case',
    nullif(trim(coalesce(p_reporter_locale, '')), ''),
    nullif(trim(coalesce(p_source_surface, '')), ''),
    coalesce(p_source_context, '{}'::jsonb)
  )
  returning id into v_report_id;

  insert into public.safety_decision_events(
    case_id,
    action,
    category,
    severity,
    confidence,
    source,
    policy_snapshot,
    reason_codes,
    metadata
  )
  values(
    v_case_id,
    'allow_log',
    null,
    null,
    null,
    'user_report',
    '{}'::jsonb,
    array[
      'USER_REPORT_RECEIVED',
      concat(
        'REPORT_REASON_',
        upper(p_report_reason)
      )
    ]::text[],
    jsonb_build_object(
      'report_id', v_report_id,
      'reporter_user_id', v_user_id,
      'source_surface', p_source_surface
    )
  );

  return jsonb_build_object(
    'ok', true,
    'duplicate', false,
    'report_id', v_report_id,
    'case_id', v_case_id
  );
end;
$$;

ALTER FUNCTION "public"."safety_submit_report_v1"("p_content_item_id" "uuid", "p_report_reason" "text", "p_report_details" "text", "p_source_surface" "text", "p_reporter_locale" "text", "p_source_context" "jsonb") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_sync_content_actor_v2"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_actor_user_id uuid;
begin
  if new.entity_id is null then
    return new;
  end if;

  if new.entity_type = 'review' then
    select user_id
    into v_actor_user_id
    from public.reviews
    where id = new.entity_id;

  elsif new.entity_type = 'social_post' then
    select user_id
    into v_actor_user_id
    from public.social_posts
    where id = new.entity_id;

  elsif new.entity_type = 'social_comment' then
    select user_id
    into v_actor_user_id
    from public.social_comments
    where id = new.entity_id;

  elsif new.entity_type = 'profile' then
    v_actor_user_id := new.entity_id;
  end if;

  if v_actor_user_id is not null then
    new.actor_user_id := v_actor_user_id;
  end if;

  return new;
end;
$$;

ALTER FUNCTION "public"."safety_sync_content_actor_v2"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_sync_media_lifecycle_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  update public.safety_media_items
  set
    lifecycle_status = new.lifecycle_status,
    updated_at = now()
  where content_item_id = new.id;

  return new;
end;
$$;

