CREATE OR REPLACE FUNCTION "public"."safety_sync_review_actor_v1"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_review_author uuid;
begin
  if new.entity_type = 'review'
     and new.entity_id is not null then

    select r.user_id
    into v_review_author
    from public.reviews r
    where r.id = new.entity_id;

    if v_review_author is not null then
      new.actor_user_id := v_review_author;
    end if;
  end if;

  return new;
end;
