CREATE OR REPLACE FUNCTION "public"."safety_sync_source_to_registry_v2"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_images text[] := '{}'::text[];
  v_text text;
  v_actor uuid;
  v_spot uuid;
  v_content_type text;
  v_entity_type text;
  v_entity_id uuid;
  v_lifecycle text := 'live';
begin
  if tg_op = 'DELETE' then
    v_entity_id := case
      when tg_table_name = 'spot_photos'
        then public.safety_stable_entity_uuid_v1(
          'spot_photo',
          old.id::text
        )
      else old.id::uuid
    end;

    update public.safety_content_items
    set lifecycle_status = 'removed'
    where entity_type = case tg_table_name
      when 'social_posts' then 'social_post'
      when 'social_comments' then 'social_comment'
      when 'reviews' then 'review'
      when 'review_comments' then 'review_comment'
      when 'profiles' then 'profile'
      when 'spot_photos' then 'spot_photo'
      else tg_table_name
    end
      and entity_id = v_entity_id;

    return old;
  end if;

  if tg_table_name = 'social_posts' then
    v_content_type := 'moment';
    v_entity_type := 'social_post';
    v_entity_id := new.id;
    v_actor := new.user_id;
    v_spot := new.spot_id;
    v_text := new.caption;

    select coalesce(
      array_agg(m.storage_path order by m.sort_order)
        filter (
          where nullif(trim(m.storage_path), '') is not null
        ),
      '{}'::text[]
    )
    into v_images
    from public.social_post_media m
    where m.post_id = new.id;

    v_lifecycle := case new.status
      when 'hidden' then 'hidden'
      when 'deleted' then 'removed'
      when 'draft' then 'limited'
      else 'live'
    end;

  elsif tg_table_name = 'social_comments' then
    v_content_type := 'comment';
    v_entity_type := 'social_comment';
    v_entity_id := new.id;
    v_actor := new.user_id;
    v_text := new.body;
    v_lifecycle := case new.status
      when 'hidden' then 'hidden'
      when 'deleted' then 'removed'
      else 'live'
    end;

  elsif tg_table_name = 'reviews' then
    v_content_type := 'review';
    v_entity_type := 'review';
    v_entity_id := new.id;
    v_actor := new.user_id;
    v_spot := new.spot_id;
    v_text := new.text;

    if nullif(trim(coalesce(new.photo_path, '')), '') is not null then
      v_images := array[new.photo_path];
    end if;

    if exists (
      select 1
      from information_schema.columns
      where table_schema = 'public'
        and table_name = 'reviews'
        and column_name = 'moderation_status'
    ) then
      v_lifecycle := case
        when to_jsonb(new)->>'moderation_status' = 'hidden'
          then 'hidden'
        when to_jsonb(new)->>'moderation_status' = 'flagged'
          then 'limited'
        else 'live'
      end;
    end if;

  elsif tg_table_name = 'review_comments' then
    v_content_type := 'comment';
    v_entity_type := 'review_comment';
    v_entity_id := new.id;
    v_actor := new.user_id;
    v_text := new.text;

    select r.spot_id
    into v_spot
    from public.reviews r
    where r.id = new.review_id;

  elsif tg_table_name = 'profiles' then
    v_content_type := 'profile';
    v_entity_type := 'profile';
    v_entity_id := new.id;
    v_actor := new.id;

    v_text := concat_ws(
      E'\n',
      nullif(trim(coalesce(new.display_name, '')), ''),
      nullif(trim(coalesce(new.username, '')), ''),
      nullif(trim(coalesce(new.bio, '')), ''),
      nullif(trim(coalesce(new.interests, '')), ''),
      nullif(trim(coalesce(new.personality, '')), '')
    );

    v_images := array_remove(
      array[
        nullif(trim(coalesce(new.avatar_url, '')), ''),
        nullif(trim(coalesce(new.header_photo_url, '')), '')
      ],
      null
    );

  elsif tg_table_name = 'spot_photos' then
    v_content_type := 'spot';
    v_entity_type := 'spot_photo';
    v_entity_id := public.safety_stable_entity_uuid_v1(
      'spot_photo',
      new.id::text
    );
    v_actor := new.uploaded_by;
    v_spot := new.spot_id;

    if nullif(trim(coalesce(new.url, '')), '') is not null then
      v_images := array[new.url];
    end if;

  else
    return new;
  end if;

  perform public.safety_upsert_registry_item_v2(
    v_content_type,
    v_entity_type,
    v_entity_id,
    v_actor,
    v_spot,
    v_text,
    v_images,
    'de-CH',
    jsonb_build_object(
      'registry_version', 'v2',
      'source_table', tg_table_name,
      'source_operation', tg_op,
      'synced_at', now()
    ),
    v_lifecycle
  );

  return new;
end;
$$;

ALTER FUNCTION "public"."safety_sync_source_to_registry_v2"() OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_text_content_hash_v1"("p_content_item_id" "uuid", "p_text_content" "text", "p_locale" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO 'pg_catalog'
    AS $$
select md5(p_content_item_id::text||':'||coalesce(p_locale,'')||':'||coalesce(p_text_content,''));
$$;

ALTER FUNCTION "public"."safety_text_content_hash_v1"("p_content_item_id" "uuid", "p_text_content" "text", "p_locale" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_text_has_local_policy_violation_v1"("p_text" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
declare
  v_text text := lower(trim(coalesce(p_text, '')));
  v_legitimate_access_rule boolean;
  v_protected_characteristic boolean;
  v_exclusion_language boolean;
  v_ambiguous_group_target boolean;
begin
  if v_text = '' then
    return false;
  end if;

  v_legitimate_access_rule :=
    v_text ~ '\meinlass[[:space:]]+ab[[:space:]]+[0-9]{1,2}\M'
    or v_text ~ '\mab[[:space:]]+[0-9]{1,2}[[:space:]]+jahren\M'
    or v_text ~ '\mgeschlossene[[:space:]]+gesellschaft\M'
    or v_text ~ '\mzutritt[[:space:]]+nur[[:space:]]+mit[[:space:]]+einladung\M'
    or v_text ~ '\mnur[[:space:]]+mit[[:space:]]+reservation\M'
    or v_text ~ '\mreservierung[[:space:]]+erforderlich\M'
    or v_text ~ '\mdresscode\M'
    or v_text ~ '\mkeine[[:space:]]+haustiere\M'
    or v_text ~ '\mkapazität[[:space:]]+erreicht\M';

  v_protected_characteristic :=
    v_text ~ '\mherkunft\M'
    or v_text ~ '\mnationalität\M'
    or v_text ~ '\methnie\M'
    or v_text ~ '\mreligion\M'
    or v_text ~ '\mgeschlecht\M'
    or v_text ~ '\msexuelle[nr]?[[:space:]]+orientierung\M'
    or v_text ~ '\mgeschlechtsidentität\M'
    or v_text ~ '\mbehinderung\M'
    or v_text ~ '\mrollstuhlfahrer(in|innen)?\M'
    or v_text ~ '\mkrankheit\M'
    or v_text ~ '\mausländer(in|innen)?\M'
    or v_text ~ '\mmuslime?\M'
    or v_text ~ '\mjuden?\M'
    or v_text ~ '\mchristen?\M'
    or v_text ~ '\mschwarze[nr]?\M'
    or v_text ~ '\mweisse[nr]?\M'
    or v_text ~ '\masiaten?\M';

  v_exclusion_language :=
    v_text ~ '\mnicht[[:space:]]+willkommen\M'
    or v_text ~ '\munerwünscht\M'
    or v_text ~ '\mkein(e|en|er|es)?[[:space:]]+zutritt\M'
    or v_text ~ '\merhalten[[:space:]]+keinen[[:space:]]+zutritt\M'
    or v_text ~ '\mdürfen[[:space:]]+nicht[[:space:]]+(rein|hinein|eintreten)\M'
    or v_text ~ '\mwir[[:space:]]+bedienen[[:space:]]+(keine|keinen|nicht)\M'
    or v_text ~ '\mwerden[[:space:]]+nicht[[:space:]]+bedient\M'
    or v_text ~ '\mkein(e|en|er|es)?[[:space:]]+service\M';

  v_ambiguous_group_target :=
    v_text ~ '\mbestimmte(n|r|s)?[[:space:]]+gruppen?\M'
    or v_text ~ '\mgewisse(n|r|s)?[[:space:]]+gruppen?\M'
    or v_text ~ '\mbestimmte(n|r|s)?[[:space:]]+personengruppen?\M'
    or v_text ~ '\msolche[[:space:]]+leute\M';

  if v_legitimate_access_rule then
    return false;
  end if;

  return
    (v_protected_characteristic and v_exclusion_language)
    or
    (v_ambiguous_group_target and v_exclusion_language);
end;
$$;

ALTER FUNCTION "public"."safety_text_has_local_policy_violation_v1"("p_text" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_upsert_registry_item_v2"("p_content_type" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_spot_id" "uuid" DEFAULT NULL::"uuid", "p_text_content" "text" DEFAULT NULL::"text", "p_image_urls" "text"[] DEFAULT '{}'::"text"[], "p_locale" "text" DEFAULT 'de-CH'::"text", "p_context" "jsonb" DEFAULT '{}'::"jsonb", "p_lifecycle_status" "text" DEFAULT 'live'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_id uuid;
  v_status text;
begin
  if p_entity_id is null then
    raise exception 'entity_id_required';
  end if;

  v_status := case
    when p_lifecycle_status in (
      'live',
      'limited',
      'hidden',
      'removed'
    ) then p_lifecycle_status
    else 'live'
  end;

  insert into public.safety_content_items(
    content_type,
    entity_type,
    entity_id,
    actor_user_id,
    spot_id,
    text_content,
    image_urls,
    locale,
    context,
    lifecycle_status
  )
  values(
    p_content_type,
    p_entity_type,
    p_entity_id,
    p_actor_user_id,
    p_spot_id,
    nullif(trim(coalesce(p_text_content, '')), ''),
    coalesce(p_image_urls, '{}'::text[]),
    coalesce(
      nullif(trim(coalesce(p_locale, '')), ''),
      'de-CH'
    ),
    coalesce(p_context, '{}'::jsonb),
    v_status
  )
  on conflict on constraint
  safety_content_items_unique_entity_v2
  do update set
    actor_user_id = coalesce(
      excluded.actor_user_id,
      public.safety_content_items.actor_user_id
    ),
    spot_id = coalesce(
      excluded.spot_id,
      public.safety_content_items.spot_id
    ),
    text_content = excluded.text_content,
    image_urls = excluded.image_urls,
    locale = excluded.locale,
    context =
      coalesce(public.safety_content_items.context, '{}'::jsonb)
      || coalesce(excluded.context, '{}'::jsonb),
    lifecycle_status = case
      -- Never silently restore a human/automatic removal merely because
      -- the source row was edited.
      when public.safety_content_items.lifecycle_status in (
        'hidden',
        'removed'
      )
        then public.safety_content_items.lifecycle_status
      else excluded.lifecycle_status
    end
  returning id into v_id;

  return v_id;
end;
$$;

ALTER FUNCTION "public"."safety_upsert_registry_item_v2"("p_content_type" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_actor_user_id" "uuid", "p_spot_id" "uuid", "p_text_content" "text", "p_image_urls" "text"[], "p_locale" "text", "p_context" "jsonb", "p_lifecycle_status" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_user_enforcement_summary_v1"("p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS TABLE("user_id" "uuid", "active_points" integer, "confirmed_violations" integer, "warning_count" integer, "active_measure_type" "text", "active_measure_ends_at" timestamp with time zone, "can_write" boolean, "requires_account_review" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_requested_user uuid;
begin
  v_requested_user := coalesce(p_user_id, auth.uid());

  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;

  if v_requested_user <> auth.uid()
     and not public.safety_is_admin_v1() then
    raise exception 'forbidden';
  end if;

  perform public.safety_expire_account_measures_v1(
    v_requested_user
  );

  return query
  with event_totals as (
    select
      coalesce(sum(event.points), 0)::integer
        as points,
      count(*) filter (
        where event.event_type = 'violation_confirmed'
          and event.points > 0
      )::integer as violations,
      count(*) filter (
        where event.event_type = 'warning_issued'
      )::integer as warnings
    from public.safety_user_enforcement_events event
    where event.user_id = v_requested_user
      and event.created_at >= now() - interval '90 days'
  ),
  active_measure as (
    select
      measure.measure_type,
      measure.ends_at
    from public.safety_account_measures measure
    where measure.user_id = v_requested_user
      and measure.status = 'active'
      and (
        measure.ends_at is null
        or measure.ends_at > now()
      )
    order by
      case measure.measure_type
        when 'account_restricted' then 4
        when 'account_review' then 3
        when 'write_suspension' then 2
        when 'warning' then 1
        else 0
      end desc,
      measure.created_at desc
    limit 1
  )
  select
    v_requested_user,
    event_totals.points,
    event_totals.violations,
    event_totals.warnings,
    active_measure.measure_type,
    active_measure.ends_at,
    coalesce(
      active_measure.measure_type not in (
        'write_suspension',
        'account_restricted'
      ),
      true
    ),
    coalesce(
      active_measure.measure_type in (
        'account_review',
        'account_restricted'
      ),
      false
    )
  from event_totals
  left join active_measure on true;
end;
$$;

ALTER FUNCTION "public"."safety_user_enforcement_summary_v1"("p_user_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_visible_comment_counts_v1"("p_post_ids" "uuid"[]) RETURNS TABLE("post_id" "uuid", "visible_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    requested.post_id,
    count(comment_row.id)::bigint as visible_count
  from unnest(
    coalesce(p_post_ids, '{}'::uuid[])
  ) as requested(post_id)
  left join public.social_comments comment_row
    on comment_row.post_id = requested.post_id
   and not exists (
     select 1
     from public.safety_content_items safety_item
     where safety_item.entity_type = 'social_comment'
       and safety_item.entity_id = comment_row.id
       and safety_item.lifecycle_status in (
         'hidden',
         'removed'
       )
   )
  group by requested.post_id;
$$;

ALTER FUNCTION "public"."safety_visible_comment_counts_v1"("p_post_ids" "uuid"[]) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_visible_entity_ids_v1"("p_entity_type" "text", "p_entity_ids" "uuid"[]) RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce(
    array_agg(candidate_id),
    '{}'::uuid[]
  )
  from unnest(
    coalesce(p_entity_ids, '{}'::uuid[])
  ) as candidate_id
  where not exists (
    select 1
    from public.safety_content_items i
    where i.entity_type = p_entity_type
      and i.entity_id = candidate_id
      and i.lifecycle_status in (
        'hidden',
        'removed'
      )
  );
$$;

ALTER FUNCTION "public"."safety_visible_entity_ids_v1"("p_entity_type" "text", "p_entity_ids" "uuid"[]) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."safety_visible_social_post_ids_v1"("p_post_ids" "uuid"[]) RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce(
    array_agg(requested.post_id),
    '{}'::uuid[]
  )
  from unnest(
    coalesce(p_post_ids, '{}'::uuid[])
  ) as requested(post_id)
  join public.social_posts post_row
    on post_row.id = requested.post_id
  where not exists (
    select 1
    from public.safety_content_items item
    where item.entity_type = 'social_post'
      and item.entity_id = post_row.id
      and item.lifecycle_status in (
        'hidden',
        'removed'
      )
  )
  and (
    post_row.review_id is null
    or not exists (
      select 1
      from public.safety_content_items review_item
      where review_item.entity_type = 'review'
        and review_item.entity_id = post_row.review_id
        and review_item.lifecycle_status in (
          'hidden',
          'removed'
        )
    )
  );
$$;

ALTER FUNCTION "public"."safety_visible_social_post_ids_v1"("p_post_ids" "uuid"[]) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."save_favorite_spot_seeds_v1"("p_city" "text", "p_spot_ids" "uuid"[] DEFAULT '{}'::"uuid"[], "p_raw_names" "text"[] DEFAULT '{}'::"text"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid;
  v_city text;
  v_spot_ids uuid[];
  v_raw text[];
begin
  v_uid := auth.uid();
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  v_city := trim(coalesce(p_city,''));
  if v_city = '' then
    raise exception 'city_required';
  end if;

  -- ✅ hard cast / defensive coalesce (kills "unknown")
  v_spot_ids := coalesce(p_spot_ids, '{}'::uuid[])::uuid[];
  v_raw := coalesce(p_raw_names, '{}'::text[])::text[];

  insert into public.user_favorite_spot_seeds(user_id, city, spot_id, raw_spot_name, source, status)
  select v_uid, v_city, sid, null, 'onboarding', 'exact_mood'
  from unnest(v_spot_ids) sid
  where sid is not null
  on conflict do nothing;

  insert into public.user_favorite_spot_seeds(user_id, city, spot_id, raw_spot_name, source, status)
  select v_uid, v_city, null, nullif(trim(rn),''), 'onboarding', 'exact_mood'
  from unnest(v_raw) rn
  where nullif(trim(rn),'') is not null;
end;
$$;

ALTER FUNCTION "public"."save_favorite_spot_seeds_v1"("p_city" "text", "p_spot_ids" "uuid"[], "p_raw_names" "text"[]) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."search_mobile_taxonomy_spots_v1"("p_query" "text", "p_locale" "text" DEFAULT 'de'::"text", "p_limit" integer DEFAULT 100) RETURNS TABLE("spot_id" "uuid", "matched_labels" "text"[], "match_score" numeric)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with input as (
    select lower(trim(coalesce(p_query, ''))) as query
  ),
  matching_nodes as (
    select
      n.id as taxonomy_node_id,
      coalesce(tr.label, de.label, n.slug) as matched_label,
      greatest(
        case
          when lower(coalesce(tr.label, de.label, n.slug)) = i.query then 1.00
          when lower(coalesce(tr.label, de.label, n.slug)) like i.query || '%' then 0.92
          when lower(coalesce(tr.label, de.label, n.slug)) like '%' || i.query || '%' then 0.82
          else 0
        end,
        case
          when lower(n.slug) = i.query then 0.95
          when lower(n.slug) like '%' || i.query || '%' then 0.75
          else 0
        end,
        coalesce((
          select max(
            case
              when lower(s.synonym) = i.query then 0.96 * s.weight
              when lower(s.synonym) like i.query || '%' then 0.88 * s.weight
              when lower(s.synonym) like '%' || i.query || '%' then 0.78 * s.weight
              else 0
            end
          )
          from public.taxonomy_synonyms s
          where s.taxonomy_node_id = n.id
            and s.locale in (coalesce(nullif(trim(p_locale), ''), 'de'), 'de')
        ), 0)
      ) * n.ml_weight as node_score
    from public.taxonomy_nodes n
    cross join input i
    left join public.taxonomy_node_translations tr
      on tr.taxonomy_node_id = n.id
     and tr.locale = coalesce(nullif(trim(p_locale), ''), 'de')
    left join public.taxonomy_node_translations de
      on de.taxonomy_node_id = n.id
     and de.locale = 'de'
    where n.is_active = true
      and char_length(i.query) >= 4
      and (
        lower(coalesce(tr.label, de.label, n.slug)) like '%' || i.query || '%'
        or lower(n.slug) like '%' || i.query || '%'
        or exists (
          select 1
          from public.taxonomy_synonyms s
          where s.taxonomy_node_id = n.id
            and s.locale in (coalesce(nullif(trim(p_locale), ''), 'de'), 'de')
            and lower(s.synonym) like '%' || i.query || '%'
        )
      )
  )
  select
    st.spot_id,
    array_agg(distinct mn.matched_label order by mn.matched_label),
    max(mn.node_score * greatest(st.confidence, 0.25))::numeric
  from matching_nodes mn
  join public.spot_taxonomies st on st.taxonomy_node_id = mn.taxonomy_node_id
  join public.spots sp on sp.id = st.spot_id
  where sp.status = 'approved'
  group by st.spot_id
  order by max(mn.node_score * greatest(st.confidence, 0.25)) desc, st.spot_id
  limit greatest(1, least(coalesce(p_limit, 100), 200));
$$;

ALTER FUNCTION "public"."search_mobile_taxonomy_spots_v1"("p_query" "text", "p_locale" "text", "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."search_social_users_v1"("p_query" "text", "p_limit" integer DEFAULT 30) RETURNS TABLE("user_id" "uuid", "display_name" "text", "username" "text", "avatar_url" "text", "city" "text", "bio" "text", "is_local" boolean, "viewer_follows_user" boolean, "follower_count" integer, "following_count" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_me uuid := auth.uid();
  v_query text := lower(btrim(coalesce(p_query, '')));
  v_limit integer := greatest(1, least(coalesce(p_limit, 30), 50));
begin
  if v_me is null then
    raise exception 'not_authenticated'
      using errcode = '28000';
  end if;

  if length(v_query) < 2 then
    return;
  end if;

  return query
  select
    p.id,
    coalesce(
      nullif(btrim(p.display_name), ''),
      nullif(btrim(p.first_name), ''),
      nullif(btrim(p.username), ''),
      'Backyrd User'
    ),
    nullif(btrim(p.username), ''),
    nullif(btrim(p.avatar_url), ''),
    nullif(btrim(p.city), ''),
    nullif(btrim(p.bio), ''),
    coalesce(p.is_local, false),
    exists (
      select 1
      from public.follows f
      where f.follower = v_me
        and f.following = p.id
    ),
    (
      select count(*)::integer
      from public.follows f
      where f.following = p.id
    ),
    (
      select count(*)::integer
      from public.follows f
      where f.follower = p.id
    )
  from public.profiles p
  where p.id <> v_me
    and p.is_private = false
    and not public.users_are_blocked_v1(v_me, p.id)
    and (
      lower(coalesce(p.username, '')) like '%' || v_query || '%'
      or lower(coalesce(p.display_name, '')) like '%' || v_query || '%'
      or lower(coalesce(p.first_name, '')) like '%' || v_query || '%'
      or lower(coalesce(p.last_name, '')) like '%' || v_query || '%'
    )
  order by
    case
      when lower(coalesce(p.username, '')) = v_query then 0
      when lower(coalesce(p.username, '')) like v_query || '%' then 1
      when lower(coalesce(p.display_name, '')) like v_query || '%' then 2
      else 3
    end,
    lower(coalesce(p.display_name, p.username, p.first_name, ''))
  limit v_limit;
end;
$$;

ALTER FUNCTION "public"."search_social_users_v1"("p_query" "text", "p_limit" integer) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."set_my_consent_v1"("p_purpose_key" "text", "p_granted" boolean, "p_document_id" "uuid" DEFAULT NULL::"uuid", "p_source" "text" DEFAULT 'mobile'::"text", "p_app_version" "text" DEFAULT NULL::"text", "p_locale" "text" DEFAULT 'de-CH'::"text") RETURNS TABLE("purpose_key" "text", "status" "text", "granted_at" timestamp with time zone, "withdrawn_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_purpose public.consent_purposes%rowtype;
  v_now timestamptz := now();
  v_previous_status text;
  v_event_type text;
begin
  if v_user_id is null then
    raise exception 'not_authenticated'
      using errcode = '28000';
  end if;

  if p_source not in ('mobile', 'web') then
    raise exception 'invalid_source'
      using errcode = '22023';
  end if;

  select cp.*
  into v_purpose
  from public.consent_purposes cp
  where cp.key = p_purpose_key
    and cp.is_active = true;

  if not found then
    raise exception 'unknown_consent_purpose'
      using errcode = '22023';
  end if;

  if v_purpose.requires_consent = false then
    raise exception 'purpose_does_not_use_consent'
      using errcode = '22023';
  end if;

  if p_granted and p_document_id is not null then
    if not exists (
      select 1
      from public.legal_documents d
      join public.consent_purpose_documents cpd
        on cpd.legal_document_id = d.id
       and cpd.purpose_key = p_purpose_key
      where d.id = p_document_id
        and d.status = 'published'
        and d.retired_at is null
        and d.effective_at <= v_now
    ) then
      raise exception 'invalid_or_inactive_consent_document'
        using errcode = '22023';
    end if;
  end if;

  select uc.status
  into v_previous_status
  from public.user_consents uc
  where uc.user_id = v_user_id
    and uc.purpose_key = p_purpose_key;

  if p_granted then
    v_event_type := case
      when v_previous_status = 'withdrawn' then 'consent_renewed'
      else 'consent_granted'
    end;

    insert into public.user_consents (
      user_id,
      purpose_key,
      status,
      document_id,
      granted_at,
      withdrawn_at,
      source,
      app_version,
      locale
    )
    values (
      v_user_id,
      p_purpose_key,
      'granted',
      p_document_id,
      v_now,
      null,
      p_source,
      p_app_version,
      p_locale
    )
    on conflict on constraint user_consents_pkey
    do update set
      status = excluded.status,
      document_id = excluded.document_id,
      granted_at = excluded.granted_at,
      withdrawn_at = excluded.withdrawn_at,
      source = excluded.source,
      app_version = excluded.app_version,
      locale = excluded.locale;
  else
    v_event_type := 'consent_withdrawn';

    insert into public.user_consents (
      user_id,
      purpose_key,
      status,
      document_id,
      granted_at,
      withdrawn_at,
      source,
      app_version,
      locale
    )
    values (
      v_user_id,
      p_purpose_key,
      'withdrawn',
      p_document_id,
      null,
      v_now,
      p_source,
      p_app_version,
      p_locale
    )
    on conflict on constraint user_consents_pkey
    do update set
      status = excluded.status,
      document_id = coalesce(
        excluded.document_id,
        public.user_consents.document_id
      ),
      withdrawn_at = excluded.withdrawn_at,
      source = excluded.source,
      app_version = excluded.app_version,
      locale = excluded.locale;
  end if;

  insert into public.consent_events (
    user_id,
    purpose_key,
    document_id,
    event_type,
    source,
    app_version,
    locale
  )
  values (
    v_user_id,
    p_purpose_key,
    p_document_id,
    v_event_type,
    p_source,
    p_app_version,
    p_locale
  );

  return query
  select
    uc.purpose_key,
    uc.status,
    uc.granted_at,
    uc.withdrawn_at
  from public.user_consents uc
  where uc.user_id = v_user_id
    and uc.purpose_key = p_purpose_key;
end;
$$;

ALTER FUNCTION "public"."set_my_consent_v1"("p_purpose_key" "text", "p_granted" boolean, "p_document_id" "uuid", "p_source" "text", "p_app_version" "text", "p_locale" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."set_my_profile_privacy_v1"("p_is_private" boolean) RETURNS TABLE("user_id" "uuid", "is_private" boolean, "removed_follower_count" integer, "removed_following_count" integer, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_me uuid := auth.uid();
  v_removed_followers integer := 0;
  v_removed_following integer := 0;
begin
  if v_me is null then
    raise exception 'not_authenticated'
      using errcode = '28000';
  end if;

  update public.profiles p
  set
    is_private = coalesce(p_is_private, false),
    updated_at = now()
  where p.id = v_me;

  if not found then
    raise exception 'profile_not_found';
  end if;

  if coalesce(p_is_private, false) then
    delete from public.follows f
    where f.following = v_me;
    get diagnostics v_removed_followers = row_count;

    delete from public.follows f
    where f.follower = v_me;
    get diagnostics v_removed_following = row_count;
  end if;

  user_id := v_me;
  is_private := coalesce(p_is_private, false);
  removed_follower_count := v_removed_followers;
  removed_following_count := v_removed_following;
  message :=
    case
      when coalesce(p_is_private, false)
        then 'profile_set_private'
      else 'profile_set_public'
    end;
  return next;
end;
$$;

ALTER FUNCTION "public"."set_my_profile_privacy_v1"("p_is_private" boolean) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."set_owner_spot_taxonomies_moderated_v1"("p_spot_id" "uuid", "p_taxonomy_node_ids" "uuid"[], "p_change_source" "text" DEFAULT 'unknown'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_old jsonb;
  v_new jsonb;
  v_result jsonb;
  v_event_id uuid;
begin
  perform public.backyrd_owner_assert_spot_v1(p_spot_id);

  select coalesce(jsonb_agg(st.taxonomy_node_id order by st.taxonomy_node_id), '[]'::jsonb)
  into v_old
  from public.spot_taxonomies st
  where st.spot_id = p_spot_id and st.source = 'owner';

  v_result := public.set_owner_spot_taxonomies_v1(p_spot_id, p_taxonomy_node_ids);

  select coalesce(jsonb_agg(st.taxonomy_node_id order by st.taxonomy_node_id), '[]'::jsonb)
  into v_new
  from public.spot_taxonomies st
  where st.spot_id = p_spot_id and st.source = 'owner';

  insert into public.spot_owner_change_events(
    spot_id, changed_by, change_area, change_source,
    old_data, new_data, moderation_status
  )
  values (
    p_spot_id, auth.uid(), 'taxonomy',
    coalesce(nullif(trim(p_change_source), ''), 'unknown'),
    jsonb_build_object('taxonomy_node_ids', coalesce(v_old, '[]'::jsonb)),
    jsonb_build_object('taxonomy_node_ids', coalesce(v_new, '[]'::jsonb)),
    'pending'
  )
  returning id into v_event_id;

  return jsonb_build_object(
    'ok', true, 'event_id', v_event_id,
    'moderation_status', 'pending', 'result', v_result
  );
end;
$$;

ALTER FUNCTION "public"."set_owner_spot_taxonomies_moderated_v1"("p_spot_id" "uuid", "p_taxonomy_node_ids" "uuid"[], "p_change_source" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."set_owner_spot_taxonomies_v1"("p_spot_id" "uuid", "p_taxonomy_node_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_ids uuid[] := coalesce(p_taxonomy_node_ids, '{}'::uuid[]);
  v_distinct_count integer;
  v_valid_count integer;
  v_subcategory_count integer;
begin
  if auth.uid() is null then
    raise exception 'Authentication required.';
  end if;

  if not public.can_edit_spot_v1(p_spot_id) then
    raise exception 'You are not allowed to edit this spot.';
  end if;

  select count(distinct x)
    into v_distinct_count
  from unnest(v_ids) as x;

  select count(*)
    into v_valid_count
  from public.taxonomy_nodes tn
  where tn.id = any(v_ids)
    and tn.is_active = true
    and tn.is_owner_selectable = true
    and (
      not exists (
        select 1
        from public.taxonomy_node_categories tnc
        where tnc.taxonomy_node_id = tn.id
      )
      or exists (
        select 1
        from public.taxonomy_node_categories tnc
        join public.spots s
          on s.id = p_spot_id
         and s.category_id = tnc.category_id
        where tnc.taxonomy_node_id = tn.id
      )
    );

  if v_valid_count <> v_distinct_count then
    raise exception
      'One or more taxonomy nodes are invalid, inactive, not owner-selectable, or incompatible with the spot category.';
  end if;

  select count(*)
    into v_subcategory_count
  from public.taxonomy_nodes tn
  where tn.id = any(v_ids)
    and tn.node_type = 'subcategory';

  if v_subcategory_count > 5 then
    raise exception 'A spot may have at most 5 owner-selected subcategories.';
  end if;

  delete from public.spot_taxonomies
  where spot_id = p_spot_id
    and source = 'owner';

  insert into public.spot_taxonomies (
    spot_id,
    taxonomy_node_id,
    source,
    confidence,
    is_verified,
    created_by,
    verified_by,
    verified_at
  )
  select
    p_spot_id,
    x,
    'owner',
    1.000,
    true,
    auth.uid(),
    auth.uid(),
    now()
  from (
    select distinct unnest(v_ids) as x
  ) q;

  return jsonb_build_object(
    'ok', true,
    'spot_id', p_spot_id,
    'selected_count', v_distinct_count,
    'subcategory_count', v_subcategory_count
  );
end;
$$;

ALTER FUNCTION "public"."set_owner_spot_taxonomies_v1"("p_spot_id" "uuid", "p_taxonomy_node_ids" "uuid"[]) OWNER TO "postgres";

