    auth.uid() is not null
    and p_target_user_id is not null
    and exists (
      select 1
      from public.profiles p
      where p.id = p_target_user_id
        and (
          p.id = auth.uid()
          or (
            p.is_private = false
            and not public.users_are_blocked_v1(
              auth.uid(),
              p.id
            )
          )
        )
    );
