CREATE OR REPLACE FUNCTION "public"."spot_is_open_now_safe_v1"("p_spot_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  has_open_now_col boolean;
  has_opening_hours_col boolean;
  v_open_now boolean;
  v_opening_hours jsonb;
begin
  select exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'spots'
      and column_name = 'open_now'
  ) into has_open_now_col;

  if has_open_now_col then
    execute 'select open_now from public.spots where id = $1' into v_open_now using p_spot_id;
    return v_open_now;
  end if;

  select exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'spots'
      and column_name = 'opening_hours'
  ) into has_opening_hours_col;

  if has_opening_hours_col then
    execute 'select opening_hours from public.spots where id = $1' into v_opening_hours using p_spot_id;
    if v_opening_hours ? 'open_now' then
      return (v_opening_hours->>'open_now')::boolean;
    end if;
  end if;

  return null;
end;
$_$;

ALTER FUNCTION "public"."spot_is_open_now_safe_v1"("p_spot_id" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."spots_with_review_count"() RETURNS TABLE("id" "uuid", "name" "text", "city" "text", "review_count" bigint)
    LANGUAGE "sql" STABLE
    AS $$
  select
    s.id,
    s.name,
    s.city,
    count(r.id) as review_count
  from spots s
  left join reviews r on r.spot_id = s.id
  group by s.id, s.name, s.city
  order by review_count desc;
$$;

