CREATE OR REPLACE FUNCTION "public"."unfollow_spot_v1"("p_spot_id" "uuid") RETURNS TABLE("spot_id" "uuid", "is_following" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  if p_spot_id is null then
    raise exception 'spot_id_required';
  end if;

  delete from public.spot_follows sf
  where sf.user_id = v_user_id
    and sf.spot_id = p_spot_id;

  spot_id := p_spot_id;
  is_following := false;
  message := 'spot_unfollowed';
  return next;
end;
$$;

