CREATE OR REPLACE FUNCTION "public"."unfollow_user_v1"("p_user_id" "uuid") RETURNS TABLE("following_id" "uuid", "is_following" boolean, "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  if p_user_id is null then
    raise exception 'user_id_required';
  end if;

  delete from public.follows f
  where f.follower = v_user_id
    and f.following = p_user_id;

  insert into public.social_feed_events (
    user_id,
    event_type,
    context
  )
  values (
    v_user_id,
    'unfollow_user',
    jsonb_build_object('following_id', p_user_id)
  );

  following_id := p_user_id;
  is_following := false;
  message := 'user_unfollowed';
  return next;
end;
$$;

