CREATE OR REPLACE FUNCTION "public"."unlock_achievement"("p_user_id" "uuid", "p_code" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  ach_id uuid;
begin
  -- Achievement anhand Code finden
  select id into ach_id from public.achievements where code = p_code;
  if ach_id is null then
    raise notice 'Achievement % nicht gefunden', p_code;
    return;
  end if;

  -- Wenn User es schon hat → nichts tun
  if exists (
    select 1 from public.user_achievements
    where user_id = p_user_id and achievement_id = ach_id
  ) then
    return;
  end if;

  -- Sonst hinzufügen
  insert into public.user_achievements (user_id, achievement_id)
  values (p_user_id, ach_id);
end;
$$;

