CREATE OR REPLACE FUNCTION "public"."update_owner_spot_intelligence_moderated_v1"("p_spot_id" "uuid", "p_best_for" "text"[] DEFAULT '{}'::"text"[], "p_occasion_tags" "text"[] DEFAULT '{}'::"text"[], "p_atmosphere_tags" "text"[] DEFAULT '{}'::"text"[], "p_avoid_if_tags" "text"[] DEFAULT '{}'::"text"[], "p_good_for_time" "text"[] DEFAULT '{}'::"text"[], "p_noise_level" "text" DEFAULT NULL::"text", "p_crowd_type" "text"[] DEFAULT '{}'::"text"[], "p_dress_code" "text" DEFAULT NULL::"text", "p_reservation_recommended" boolean DEFAULT NULL::boolean, "p_average_duration_minutes" integer DEFAULT NULL::integer, "p_signature_items" "text"[] DEFAULT '{}'::"text"[], "p_special_notes" "text" DEFAULT NULL::"text", "p_change_source" "text" DEFAULT 'unknown'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_old jsonb;
  v_new jsonb;
  v_detail jsonb;
  v_flags text[];
  v_status text;
  v_event_id uuid;
begin
  perform public.backyrd_owner_assert_spot_v1(p_spot_id);

  select to_jsonb(si) - 'spot_id'
  into v_old
  from public.spot_intelligence_v1 si
  where si.spot_id = p_spot_id;

  v_detail := public.update_owner_spot_intelligence_v1(
    p_spot_id, p_best_for, p_occasion_tags, p_atmosphere_tags,
    p_avoid_if_tags, p_good_for_time, p_noise_level, p_crowd_type,
    p_dress_code, p_reservation_recommended, p_average_duration_minutes,
    p_signature_items, p_special_notes
  );

  select to_jsonb(si) - 'spot_id'
  into v_new
  from public.spot_intelligence_v1 si
  where si.spot_id = p_spot_id;

  v_flags := public.backyrd_owner_text_risk_flags_v1(array[
    array_to_string(coalesce(p_best_for, '{}'::text[]), ' '),
    array_to_string(coalesce(p_occasion_tags, '{}'::text[]), ' '),
    array_to_string(coalesce(p_atmosphere_tags, '{}'::text[]), ' '),
    array_to_string(coalesce(p_avoid_if_tags, '{}'::text[]), ' '),
    array_to_string(coalesce(p_good_for_time, '{}'::text[]), ' '),
    p_noise_level,
    array_to_string(coalesce(p_crowd_type, '{}'::text[]), ' '),
    p_dress_code,
    array_to_string(coalesce(p_signature_items, '{}'::text[]), ' '),
    p_special_notes
  ]);
  v_status := case when cardinality(v_flags) > 0 then 'flagged' else 'pending' end;

  insert into public.spot_owner_change_events(
    spot_id, changed_by, change_area, change_source,
    old_data, new_data, moderation_status, risk_flags
  )
  values (
    p_spot_id, auth.uid(), 'intelligence',
    coalesce(nullif(trim(p_change_source), ''), 'unknown'),
    coalesce(v_old, '{}'::jsonb), coalesce(v_new, '{}'::jsonb),
    v_status, v_flags
  )
  returning id into v_event_id;

  return jsonb_build_object(
    'ok', true,
    'event_id', v_event_id,
    'moderation_status', v_status,
    'risk_flags', v_flags,
    'detail', v_detail
  );
end;
$$;

ALTER FUNCTION "public"."update_owner_spot_intelligence_moderated_v1"("p_spot_id" "uuid", "p_best_for" "text"[], "p_occasion_tags" "text"[], "p_atmosphere_tags" "text"[], "p_avoid_if_tags" "text"[], "p_good_for_time" "text"[], "p_noise_level" "text", "p_crowd_type" "text"[], "p_dress_code" "text", "p_reservation_recommended" boolean, "p_average_duration_minutes" integer, "p_signature_items" "text"[], "p_special_notes" "text", "p_change_source" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."update_owner_spot_intelligence_v1"("p_spot_id" "uuid", "p_best_for" "text"[] DEFAULT '{}'::"text"[], "p_occasion_tags" "text"[] DEFAULT '{}'::"text"[], "p_atmosphere_tags" "text"[] DEFAULT '{}'::"text"[], "p_avoid_if_tags" "text"[] DEFAULT '{}'::"text"[], "p_good_for_time" "text"[] DEFAULT '{}'::"text"[], "p_noise_level" "text" DEFAULT NULL::"text", "p_crowd_type" "text"[] DEFAULT '{}'::"text"[], "p_dress_code" "text" DEFAULT NULL::"text", "p_reservation_recommended" boolean DEFAULT NULL::boolean, "p_average_duration_minutes" integer DEFAULT NULL::integer, "p_signature_items" "text"[] DEFAULT '{}'::"text"[], "p_special_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.backyrd_owner_assert_spot_v1(p_spot_id);

  insert into public.spot_intelligence_v1 (
    spot_id,
    best_for,
    occasion_tags,
    atmosphere_tags,
    avoid_if_tags,
    good_for_time,
    noise_level,
    crowd_type,
    dress_code,
    reservation_recommended,
    average_duration_minutes,
    signature_items,
    special_notes,
    source,
    is_verified,
    updated_by,
    updated_at
  )
  values (
    p_spot_id,
    coalesce(p_best_for, '{}'::text[]),
    coalesce(p_occasion_tags, '{}'::text[]),
    coalesce(p_atmosphere_tags, '{}'::text[]),
    coalesce(p_avoid_if_tags, '{}'::text[]),
    coalesce(p_good_for_time, '{}'::text[]),
    nullif(trim(coalesce(p_noise_level, '')), ''),
    coalesce(p_crowd_type, '{}'::text[]),
    nullif(trim(coalesce(p_dress_code, '')), ''),
    p_reservation_recommended,
    case
      when p_average_duration_minutes is null then null
      else greatest(1, least(p_average_duration_minutes, 1440))
    end,
    coalesce(p_signature_items, '{}'::text[]),
    nullif(trim(coalesce(p_special_notes, '')), ''),
    'owner',
    false,
    auth.uid(),
    now()
  )
  on conflict (spot_id)
  do update set
    best_for = excluded.best_for,
    occasion_tags = excluded.occasion_tags,
    atmosphere_tags = excluded.atmosphere_tags,
    avoid_if_tags = excluded.avoid_if_tags,
    good_for_time = excluded.good_for_time,
    noise_level = excluded.noise_level,
    crowd_type = excluded.crowd_type,
    dress_code = excluded.dress_code,
    reservation_recommended = excluded.reservation_recommended,
    average_duration_minutes = excluded.average_duration_minutes,
    signature_items = excluded.signature_items,
    special_notes = excluded.special_notes,
    source = 'owner',
    is_verified = false,
    updated_by = auth.uid(),
    updated_at = now();

  return public.get_owner_spot_detail_v1(p_spot_id);
end;
$$;

ALTER FUNCTION "public"."update_owner_spot_intelligence_v1"("p_spot_id" "uuid", "p_best_for" "text"[], "p_occasion_tags" "text"[], "p_atmosphere_tags" "text"[], "p_avoid_if_tags" "text"[], "p_good_for_time" "text"[], "p_noise_level" "text", "p_crowd_type" "text"[], "p_dress_code" "text", "p_reservation_recommended" boolean, "p_average_duration_minutes" integer, "p_signature_items" "text"[], "p_special_notes" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."update_owner_spot_mobile_moderated_v1"("p_spot_id" "uuid", "p_category_id" "uuid" DEFAULT NULL::"uuid", "p_price_level" integer DEFAULT NULL::integer, "p_email" "text" DEFAULT NULL::"text", "p_phone" "text" DEFAULT NULL::"text", "p_website" "text" DEFAULT NULL::"text", "p_owner_description" "text" DEFAULT NULL::"text", "p_owner_keywords" "text"[] DEFAULT '{}'::"text"[], "p_change_source" "text" DEFAULT 'mobile'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_spot public.spots%rowtype;
  v_validation jsonb;
  v_old jsonb;
  v_new jsonb;
  v_flags text[];
  v_status text;
  v_event_id uuid;
begin
  perform public.backyrd_owner_assert_spot_v1(p_spot_id);

  select * into v_spot from public.spots where id = p_spot_id;
  if v_spot.id is null then raise exception 'Spot not found'; end if;

  if p_category_id is not null and not exists (
    select 1 from public.categories where id = p_category_id
  ) then
    raise exception 'owner_validation:category_invalid';
  end if;

  v_validation := public.validate_owner_spot_contact_v1(
    p_email, p_phone, p_website, v_spot.country
  );

  if coalesce((v_validation ->> 'ok')::boolean, false) is not true then
    raise exception 'owner_validation:%', array_to_string(
      array(select jsonb_array_elements_text(v_validation -> 'errors')), ','
    );
  end if;

  select jsonb_build_object(
    'category_id', s.category_id, 'price_level', s.price_level,
    'email', s.email, 'phone', s.phone, 'website', s.website,
    'owner_description', sd.owner_description,
    'owner_keywords', coalesce(sd.owner_keywords, '{}'::text[])
  )
  into v_old
  from public.spots s
  left join public.spot_descriptions sd on sd.spot_id = s.id
  where s.id = p_spot_id;

  update public.spots
  set category_id = coalesce(p_category_id, category_id),
      price_level = case when p_price_level is null then price_level else greatest(1, least(p_price_level, 4)) end,
      email = v_validation #>> '{normalized,email}',
      phone = v_validation #>> '{normalized,phone}',
      website = v_validation #>> '{normalized,website}'
  where id = p_spot_id;

  insert into public.spot_descriptions(
    spot_id, owner_user_id, owner_description, owner_keywords,
    owner_updated_at, content_status, updated_at
  )
  values(
    p_spot_id, auth.uid(),
    nullif(trim(coalesce(p_owner_description, '')), ''),
    coalesce(p_owner_keywords, '{}'::text[]),
    now(), 'draft', now()
  )
  on conflict (spot_id) do update set
    owner_user_id = auth.uid(),
    owner_description = excluded.owner_description,
    owner_keywords = excluded.owner_keywords,
    owner_updated_at = now(),
    updated_at = now();

  select jsonb_build_object(
    'category_id', s.category_id, 'price_level', s.price_level,
    'email', s.email, 'phone', s.phone, 'website', s.website,
    'owner_description', sd.owner_description,
    'owner_keywords', coalesce(sd.owner_keywords, '{}'::text[])
  )
  into v_new
  from public.spots s
  left join public.spot_descriptions sd on sd.spot_id = s.id
  where s.id = p_spot_id;

  v_flags := public.backyrd_owner_text_risk_flags_v1(array[
    p_owner_description,
    array_to_string(coalesce(p_owner_keywords, '{}'::text[]), ' ')
  ]);
  v_status := case when cardinality(v_flags) > 0 then 'flagged' else 'pending' end;

  insert into public.spot_owner_change_events(
    spot_id, changed_by, change_area, change_source,
    old_data, new_data, moderation_status, risk_flags, validation_warnings
  )
  values(
    p_spot_id, auth.uid(), 'mobile_profile',
    coalesce(nullif(trim(p_change_source), ''), 'mobile'),
    v_old, v_new, v_status, v_flags,
    array(select jsonb_array_elements_text(v_validation -> 'warnings'))
  )
  returning id into v_event_id;

  return jsonb_build_object(
    'ok', true,
    'event_id', v_event_id,
    'moderation_status', v_status,
    'risk_flags', v_flags,
    'validation', v_validation,
    'detail', public.get_owner_spot_detail_v1(p_spot_id)
  );
end;
$$;

ALTER FUNCTION "public"."update_owner_spot_mobile_moderated_v1"("p_spot_id" "uuid", "p_category_id" "uuid", "p_price_level" integer, "p_email" "text", "p_phone" "text", "p_website" "text", "p_owner_description" "text", "p_owner_keywords" "text"[], "p_change_source" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."update_owner_spot_profile_moderated_v1"("p_spot_id" "uuid", "p_name" "text", "p_address" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_country" "text" DEFAULT NULL::"text", "p_phone" "text" DEFAULT NULL::"text", "p_website" "text" DEFAULT NULL::"text", "p_email" "text" DEFAULT NULL::"text", "p_price_level" integer DEFAULT NULL::integer, "p_owner_description" "text" DEFAULT NULL::"text", "p_owner_keywords" "text"[] DEFAULT '{}'::"text"[], "p_change_source" "text" DEFAULT 'unknown'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_validation jsonb;
  v_old jsonb;
  v_new jsonb;
  v_detail jsonb;
  v_flags text[];
  v_event_id uuid;
  v_status text;
begin
  perform public.backyrd_owner_assert_spot_v1(p_spot_id);

  if nullif(trim(coalesce(p_name, '')), '') is null then
    raise exception 'owner_validation:name_required';
  end if;

  v_validation := public.validate_owner_spot_contact_v1(
    p_email, p_phone, p_website, p_country
  );

  if coalesce((v_validation ->> 'ok')::boolean, false) is not true then
    raise exception 'owner_validation:%', array_to_string(
      array(select jsonb_array_elements_text(v_validation -> 'errors')), ','
    );
  end if;

  select jsonb_build_object(
    'name', s.name, 'address', s.address, 'city', s.city, 'country', s.country,
    'phone', s.phone, 'website', s.website, 'email', s.email,
    'price_level', s.price_level,
    'owner_description', sd.owner_description,
    'owner_keywords', coalesce(sd.owner_keywords, '{}'::text[])
  )
  into v_old
  from public.spots s
  left join public.spot_descriptions sd on sd.spot_id = s.id
  where s.id = p_spot_id;

  v_detail := public.update_owner_spot_profile_v1(
    p_spot_id,
    p_name,
    p_address,
    p_city,
    p_country,
    v_validation #>> '{normalized,phone}',
    v_validation #>> '{normalized,website}',
    v_validation #>> '{normalized,email}',
    p_price_level,
    p_owner_description,
    coalesce(p_owner_keywords, '{}'::text[])
  );

  select jsonb_build_object(
    'name', s.name, 'address', s.address, 'city', s.city, 'country', s.country,
    'phone', s.phone, 'website', s.website, 'email', s.email,
    'price_level', s.price_level,
    'owner_description', sd.owner_description,
    'owner_keywords', coalesce(sd.owner_keywords, '{}'::text[])
  )
  into v_new
  from public.spots s
  left join public.spot_descriptions sd on sd.spot_id = s.id
  where s.id = p_spot_id;

  v_flags := public.backyrd_owner_text_risk_flags_v1(array[
    p_name, p_address, p_city, p_country, p_owner_description,
    array_to_string(coalesce(p_owner_keywords, '{}'::text[]), ' ')
  ]);
  v_status := case when cardinality(v_flags) > 0 then 'flagged' else 'pending' end;

  insert into public.spot_owner_change_events(
    spot_id, changed_by, change_area, change_source,
    old_data, new_data, moderation_status, risk_flags, validation_warnings
  )
  values (
    p_spot_id, auth.uid(), 'profile', coalesce(nullif(trim(p_change_source), ''), 'unknown'),
    coalesce(v_old, '{}'::jsonb), coalesce(v_new, '{}'::jsonb),
    v_status, v_flags,
    array(select jsonb_array_elements_text(v_validation -> 'warnings'))
  )
  returning id into v_event_id;

  return jsonb_build_object(
    'ok', true,
    'event_id', v_event_id,
    'moderation_status', v_status,
    'risk_flags', v_flags,
    'validation', v_validation,
    'detail', v_detail
  );
end;
$$;

ALTER FUNCTION "public"."update_owner_spot_profile_moderated_v1"("p_spot_id" "uuid", "p_name" "text", "p_address" "text", "p_city" "text", "p_country" "text", "p_phone" "text", "p_website" "text", "p_email" "text", "p_price_level" integer, "p_owner_description" "text", "p_owner_keywords" "text"[], "p_change_source" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."update_owner_spot_profile_v1"("p_spot_id" "uuid", "p_name" "text", "p_address" "text" DEFAULT NULL::"text", "p_city" "text" DEFAULT NULL::"text", "p_country" "text" DEFAULT NULL::"text", "p_phone" "text" DEFAULT NULL::"text", "p_website" "text" DEFAULT NULL::"text", "p_email" "text" DEFAULT NULL::"text", "p_price_level" integer DEFAULT NULL::integer, "p_owner_description" "text" DEFAULT NULL::"text", "p_owner_keywords" "text"[] DEFAULT '{}'::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.backyrd_owner_assert_spot_v1(p_spot_id);

  if nullif(trim(coalesce(p_name, '')), '') is null then
    raise exception 'Name is required';
  end if;

  update public.spots
  set
    name = trim(p_name),
    address = nullif(trim(coalesce(p_address, '')), ''),
    city = nullif(trim(coalesce(p_city, '')), ''),
    country = nullif(trim(coalesce(p_country, '')), ''),
    phone = nullif(trim(coalesce(p_phone, '')), ''),
    website = nullif(trim(coalesce(p_website, '')), ''),
    email = nullif(trim(coalesce(p_email, '')), ''),
    price_level = case
      when p_price_level is null then null
      else greatest(1, least(p_price_level, 4))
    end
  where id = p_spot_id;

  insert into public.spot_descriptions (
    spot_id,
    owner_user_id,
    owner_description,
    owner_keywords,
    owner_updated_at,
    content_status,
    updated_at
  )
  values (
    p_spot_id,
    auth.uid(),
    nullif(trim(coalesce(p_owner_description, '')), ''),
    coalesce(p_owner_keywords, '{}'::text[]),
    now(),
    'draft',
    now()
  )
  on conflict (spot_id)
  do update set
    owner_user_id = auth.uid(),
    owner_description = excluded.owner_description,
    owner_keywords = excluded.owner_keywords,
    owner_updated_at = now(),
    content_status = case
      when public.spot_descriptions.content_status in ('draft', 'review', 'published', 'archived')
        then public.spot_descriptions.content_status
      else 'draft'
    end,
    updated_at = now();

  return public.get_owner_spot_detail_v1(p_spot_id);
end;
$$;

ALTER FUNCTION "public"."update_owner_spot_profile_v1"("p_spot_id" "uuid", "p_name" "text", "p_address" "text", "p_city" "text", "p_country" "text", "p_phone" "text", "p_website" "text", "p_email" "text", "p_price_level" integer, "p_owner_description" "text", "p_owner_keywords" "text"[]) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."upsert_cluster_and_map_token"("p_token_id" integer, "p_cluster_name" "text", "p_confidence" numeric DEFAULT 0.7, "p_source" "text" DEFAULT 'ai'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  cname text := trim(coalesce(p_cluster_name,''));
  cnorm text := lower(trim(regexp_replace(cname, '\s+', ' ', 'g')));
  cid bigint;
begin
  if cname = '' then
    return;
  end if;

  insert into public.mood_clusters(name, name_norm)
  values (cname, cnorm)
  on conflict (name_norm) do update set name = excluded.name
  returning id into cid;

  insert into public.mood_token_clusters(token_id, cluster_id, confidence, source)
  values (p_token_id, cid, coalesce(p_confidence,0.7), coalesce(p_source,'ai'))
  on conflict (token_id, cluster_id) do update
    set confidence = excluded.confidence,
        source = excluded.source;

  update public.mood_cluster_jobs
  set status='done', updated_at=now(), last_error=null
  where token_id = p_token_id;
end $$;

ALTER FUNCTION "public"."upsert_cluster_and_map_token"("p_token_id" integer, "p_cluster_name" "text", "p_confidence" numeric, "p_source" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."upsert_my_owned_spot_content_v1"("p_spot_id" "uuid", "p_owner_description" "text" DEFAULT NULL::"text", "p_owner_keywords" "text"[] DEFAULT '{}'::"text"[]) RETURNS TABLE("ok" boolean, "spot_id" "uuid", "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_is_owner boolean := false;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  if p_spot_id is null then
    raise exception 'spot_id_required';
  end if;

  select exists (
    select 1
    from public.spots s
    where s.id = p_spot_id
      and s.owner_id = v_uid
  )
  or exists (
    select 1
    from public.spot_descriptions sd
    where sd.spot_id = p_spot_id
      and sd.owner_user_id = v_uid
      and sd.is_verified = true
  )
  into v_is_owner;

  if not coalesce(v_is_owner, false) then
    raise exception 'verified_owner_required' using errcode = '42501';
  end if;

  insert into public.spot_descriptions (
    spot_id,
    owner_description,
    owner_keywords,
    owner_user_id,
    owner_updated_at,
    is_verified,
    created_at,
    updated_at
  )
  values (
    p_spot_id,
    nullif(trim(coalesce(p_owner_description, '')), ''),
    coalesce(p_owner_keywords, '{}'::text[]),
    v_uid,
    now(),
    true,
    now(),
    now()
  )
  on conflict (spot_id)
  do update set
    owner_description = excluded.owner_description,
    owner_keywords = excluded.owner_keywords,
    owner_user_id = excluded.owner_user_id,
    owner_updated_at = now(),
    is_verified = true,
    updated_at = now();

  ok := true;
  spot_id := p_spot_id;
  message := 'owned_spot_content_saved';
  return next;
end;
$$;

ALTER FUNCTION "public"."upsert_my_owned_spot_content_v1"("p_spot_id" "uuid", "p_owner_description" "text", "p_owner_keywords" "text"[]) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."upsert_owner_description_v1"("p_spot_id" "uuid", "p_description" "text", "p_keywords" "text"[] DEFAULT NULL::"text"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_owner uuid;
  v_verified boolean;
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;

  select owner_user_id, is_verified into v_owner, v_verified
  from public.spot_descriptions
  where spot_id = p_spot_id;

  if v_owner is null or v_verified is distinct from true or v_owner <> auth.uid() then
    raise exception 'not_owner_or_not_verified';
  end if;

  update public.spot_descriptions
  set owner_description = p_description,
      owner_keywords = p_keywords,
      owner_updated_at = now(),
      updated_at = now()
  where spot_id = p_spot_id;
end $$;

ALTER FUNCTION "public"."upsert_owner_description_v1"("p_spot_id" "uuid", "p_description" "text", "p_keywords" "text"[]) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."upsert_spot_admin_content_v1"("p_spot_id" "uuid", "p_description" "text" DEFAULT NULL::"text", "p_keywords" "text"[] DEFAULT '{}'::"text"[], "p_source" "text" DEFAULT 'admin'::"text", "p_enriched_url" "text" DEFAULT NULL::"text") RETURNS TABLE("ok" boolean, "spot_id" "uuid", "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
  v_is_admin boolean := false;
  v_source text := coalesce(nullif(trim(p_source), ''), 'admin');
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  select coalesce(p.is_admin, false)
  into v_is_admin
  from public.profiles p
  where p.id = v_uid;

  if not coalesce(v_is_admin, false) then
    raise exception 'admin_required' using errcode = '42501';
  end if;

  if p_spot_id is null then
    raise exception 'spot_id_required';
  end if;

  if not exists (
    select 1
    from public.spots s
    where s.id = p_spot_id
  ) then
    raise exception 'spot_not_found';
  end if;

  insert into public.spot_descriptions (
    spot_id,
    admin_description,
    admin_keywords,
    admin_notes,
    admin_user_id,
    admin_updated_at,
    enriched_description,
    enriched_keywords,
    enriched_source,
    enriched_url,
    enriched_updated_at,
    content_status,
    created_at,
    updated_at
  )
  values (
    p_spot_id,

    case
      when v_source = 'admin'
      then nullif(trim(coalesce(p_description, '')), '')
      else null
    end,

    case
      when v_source = 'admin'
      then coalesce(p_keywords, '{}'::text[])
      else '{}'::text[]
    end,

    null,

    case
      when v_source = 'admin'
      then v_uid
      else null
    end,

    case
      when v_source = 'admin'
      then now()
      else null
    end,

    case
      when v_source <> 'admin'
      then nullif(trim(coalesce(p_description, '')), '')
      else null
    end,

    case
      when v_source <> 'admin'
      then coalesce(p_keywords, '{}'::text[])
      else null
    end,

    case
      when v_source <> 'admin'
      then v_source
      else null
    end,

    case
      when v_source <> 'admin'
      then p_enriched_url
      else null
    end,

    case
      when v_source <> 'admin'
      then now()
      else null
    end,

    'published',
    now(),
    now()
  )
  on conflict on constraint spot_descriptions_pkey
  do update set
    admin_description = case
      when v_source = 'admin'
      then nullif(trim(coalesce(p_description, '')), '')
      else public.spot_descriptions.admin_description
    end,

    admin_keywords = case
      when v_source = 'admin'
      then coalesce(p_keywords, '{}'::text[])
      else public.spot_descriptions.admin_keywords
    end,

    admin_user_id = case
      when v_source = 'admin'
      then v_uid
      else public.spot_descriptions.admin_user_id
    end,

    admin_updated_at = case
      when v_source = 'admin'
      then now()
      else public.spot_descriptions.admin_updated_at
    end,

    enriched_description = case
      when v_source <> 'admin'
      then nullif(trim(coalesce(p_description, '')), '')
      else public.spot_descriptions.enriched_description
    end,

    enriched_keywords = case
      when v_source <> 'admin'
      then coalesce(p_keywords, '{}'::text[])
      else public.spot_descriptions.enriched_keywords
    end,

    enriched_source = case
      when v_source <> 'admin'
      then v_source
      else public.spot_descriptions.enriched_source
    end,

    enriched_url = case
      when v_source <> 'admin'
      then p_enriched_url
      else public.spot_descriptions.enriched_url
    end,

    enriched_updated_at = case
      when v_source <> 'admin'
      then now()
      else public.spot_descriptions.enriched_updated_at
    end,

    content_status = 'published',
    updated_at = now();

  begin
    perform public.backyrd_refresh_spot_ml_document_v13(p_spot_id);
    perform public.backyrd_enqueue_spot_embedding_v13(
      p_spot_id,
      'spot_admin_content_update'
    );
  exception
    when undefined_function then
      null;
    when others then
      null;
  end;

  return query
  select
    true as ok,
    p_spot_id as spot_id,
    'spot_admin_content_saved'::text as message;
end;
$$;

ALTER FUNCTION "public"."upsert_spot_admin_content_v1"("p_spot_id" "uuid", "p_description" "text", "p_keywords" "text"[], "p_source" "text", "p_enriched_url" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."upsert_spot_intelligence_v1"("p_spot_id" "uuid", "p_best_for" "text"[] DEFAULT '{}'::"text"[], "p_occasion_tags" "text"[] DEFAULT '{}'::"text"[], "p_atmosphere_tags" "text"[] DEFAULT '{}'::"text"[], "p_avoid_if_tags" "text"[] DEFAULT '{}'::"text"[], "p_good_for_time" "text"[] DEFAULT '{}'::"text"[], "p_noise_level" "text" DEFAULT NULL::"text", "p_crowd_type" "text"[] DEFAULT '{}'::"text"[], "p_dress_code" "text" DEFAULT NULL::"text", "p_reservation_recommended" boolean DEFAULT NULL::boolean, "p_average_duration_minutes" integer DEFAULT NULL::integer, "p_signature_items" "text"[] DEFAULT '{}'::"text"[], "p_special_notes" "text" DEFAULT NULL::"text", "p_admin_notes" "text" DEFAULT NULL::"text", "p_source" "text" DEFAULT 'admin'::"text", "p_is_verified" boolean DEFAULT false) RETURNS TABLE("ok" boolean, "spot_id" "uuid", "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_is_admin boolean := false;
  v_source text := coalesce(nullif(trim(p_source), ''), 'admin');
  v_noise_level text := nullif(lower(trim(coalesce(p_noise_level, ''))), '');
  v_dress_code text := nullif(lower(trim(coalesce(p_dress_code, ''))), '');
begin
  if v_user_id is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  if p_spot_id is null then
    raise exception 'spot_id_required';
  end if;

  if not exists (
    select 1
    from public.spots s
    where s.id = p_spot_id
  ) then
    raise exception 'spot_not_found';
  end if;

  select coalesce(p.is_admin, false)
  into v_is_admin
  from public.profiles p
  where p.id = v_user_id;

  if not public.can_edit_spot_v1(p_spot_id) then
    raise exception 'not_allowed_to_edit_spot' using errcode = '42501';
  end if;

  if v_noise_level = 'medium' then
    v_noise_level := 'moderate';
  end if;

  if v_noise_level is not null
     and v_noise_level not in ('quiet', 'moderate', 'lively', 'loud') then
    raise exception 'invalid_noise_level';
  end if;

  if v_dress_code in ('smart casual', 'smart-casual') then
    v_dress_code := 'smart_casual';
  end if;

  if v_dress_code is not null
     and v_dress_code not in ('casual', 'smart_casual', 'dressy', 'formal') then
    raise exception 'invalid_dress_code';
  end if;

  if not v_is_admin then
    v_source := 'owner';
    p_admin_notes := null;
    p_is_verified := false;
  end if;

  insert into public.spot_intelligence_v1 (
    spot_id,
    best_for,
    occasion_tags,
    atmosphere_tags,
    avoid_if_tags,
    good_for_time,
    noise_level,
    crowd_type,
    dress_code,
    reservation_recommended,
    average_duration_minutes,
    signature_items,
    special_notes,
    admin_notes,
    source,
    is_verified,
    updated_by,
    created_at,
    updated_at
  )
  values (
    p_spot_id,
    coalesce(p_best_for, '{}'::text[]),
    coalesce(p_occasion_tags, '{}'::text[]),
    coalesce(p_atmosphere_tags, '{}'::text[]),
    coalesce(p_avoid_if_tags, '{}'::text[]),
    coalesce(p_good_for_time, '{}'::text[]),
    v_noise_level,
    coalesce(p_crowd_type, '{}'::text[]),
    v_dress_code,
    p_reservation_recommended,
    p_average_duration_minutes,
    coalesce(p_signature_items, '{}'::text[]),
    nullif(trim(coalesce(p_special_notes, '')), ''),
    nullif(trim(coalesce(p_admin_notes, '')), ''),
    v_source,
    coalesce(p_is_verified, false),
    v_user_id,
    now(),
    now()
  )
  on conflict on constraint spot_intelligence_v1_pkey
  do update set
    best_for = excluded.best_for,
    occasion_tags = excluded.occasion_tags,
    atmosphere_tags = excluded.atmosphere_tags,
    avoid_if_tags = excluded.avoid_if_tags,
    good_for_time = excluded.good_for_time,
    noise_level = excluded.noise_level,
    crowd_type = excluded.crowd_type,
    dress_code = excluded.dress_code,
    reservation_recommended = excluded.reservation_recommended,
    average_duration_minutes = excluded.average_duration_minutes,
    signature_items = excluded.signature_items,
    special_notes = excluded.special_notes,
    admin_notes = excluded.admin_notes,
    source = excluded.source,
    is_verified = excluded.is_verified,
    updated_by = excluded.updated_by,
    updated_at = now();

  begin
    perform public.backyrd_refresh_spot_ml_document_v13(p_spot_id);
    perform public.backyrd_enqueue_spot_embedding_v13(
      p_spot_id,
      'spot_intelligence_v1_update'
    );
  exception
    when undefined_function then
      null;
    when others then
      raise warning 'spot intelligence embedding enqueue failed for spot %: %', p_spot_id, sqlerrm;
  end;

  return query
  select
    true as ok,
    p_spot_id as spot_id,
    'spot_intelligence_upserted'::text as message;
end;
$$;

ALTER FUNCTION "public"."upsert_spot_intelligence_v1"("p_spot_id" "uuid", "p_best_for" "text"[], "p_occasion_tags" "text"[], "p_atmosphere_tags" "text"[], "p_avoid_if_tags" "text"[], "p_good_for_time" "text"[], "p_noise_level" "text", "p_crowd_type" "text"[], "p_dress_code" "text", "p_reservation_recommended" boolean, "p_average_duration_minutes" integer, "p_signature_items" "text"[], "p_special_notes" "text", "p_admin_notes" "text", "p_source" "text", "p_is_verified" boolean) OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."upsert_spot_owner_fields_v1"("p_spot_id" "uuid", "p_category_id" "uuid" DEFAULT NULL::"uuid", "p_price_level" integer DEFAULT NULL::integer, "p_email" "text" DEFAULT NULL::"text", "p_phone" "text" DEFAULT NULL::"text", "p_website" "text" DEFAULT NULL::"text", "p_header_photo_path" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_owner uuid;
  v_verified boolean;
begin
  if auth.uid() is null then
    raise exception 'not_authenticated';
  end if;

  select owner_user_id, is_verified into v_owner, v_verified
  from public.spot_descriptions
  where spot_id = p_spot_id;

  if v_owner is null or v_verified is distinct from true or v_owner <> auth.uid() then
    raise exception 'not_owner_or_not_verified';
  end if;

  update public.spots
  set
    category_id = coalesce(p_category_id, category_id),
    price_level = coalesce(p_price_level, price_level),
    email = p_email,
    phone = p_phone,
    website = p_website,
    header_photo_path = coalesce(p_header_photo_path, header_photo_path)
  where id = p_spot_id;
end $$;

ALTER FUNCTION "public"."upsert_spot_owner_fields_v1"("p_spot_id" "uuid", "p_category_id" "uuid", "p_price_level" integer, "p_email" "text", "p_phone" "text", "p_website" "text", "p_header_photo_path" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."user_has_active_consent_v1"("p_user_id" "uuid", "p_purpose_key" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  select
    case
      when p_user_id is null then false
      when not exists (
        select 1
        from public.consent_purposes cp
        where cp.key = p_purpose_key
          and cp.is_active = true
      ) then false
      when exists (
        select 1
        from public.consent_purposes cp
        where cp.key = p_purpose_key
          and cp.is_active = true
          and cp.requires_consent = false
      ) then true
      else exists (
        select 1
        from public.user_consents uc
        where uc.user_id = p_user_id
          and uc.purpose_key = p_purpose_key
          and uc.status = 'granted'
      )
    end;
$$;

ALTER FUNCTION "public"."user_has_active_consent_v1"("p_user_id" "uuid", "p_purpose_key" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."users_are_blocked_v1"("p_user_a" "uuid", "p_user_b" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
  select
    p_user_a is not null
    and p_user_b is not null
    and exists (
      select 1
      from public.user_blocks b
      where
        (b.blocker_id = p_user_a and b.blocked_id = p_user_b)
        or
        (b.blocker_id = p_user_b and b.blocked_id = p_user_a)
    );
$$;

ALTER FUNCTION "public"."users_are_blocked_v1"("p_user_a" "uuid", "p_user_b" "uuid") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."validate_owner_spot_contact_v1"("p_email" "text" DEFAULT NULL::"text", "p_phone" "text" DEFAULT NULL::"text", "p_website" "text" DEFAULT NULL::"text", "p_country" "text" DEFAULT 'Schweiz'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    AS $_$
declare
  v_email text := public.backyrd_normalize_owner_email_v1(p_email);
  v_phone text := public.backyrd_normalize_owner_phone_v1(p_phone, p_country);
  v_website text := public.backyrd_normalize_owner_website_v1(p_website);
  v_errors text[] := '{}'::text[];
  v_warnings text[] := '{}'::text[];
  v_phone_digits text;
begin
  if v_email is not null and v_email !~* '^[^[:space:]@]+@[^[:space:]@]+\.[a-z]{2,63}$' then
    v_errors := array_append(v_errors, 'email_invalid');
  end if;

  if v_website is not null and v_website !~* '^https?://([a-z0-9-]+\.)+[a-z]{2,63}([/:?#].*)?$' then
    v_errors := array_append(v_errors, 'website_invalid');
  end if;

  if v_phone is not null then
    v_phone_digits := regexp_replace(v_phone, '[^0-9]', '', 'g');

    if v_phone !~ '^\+[1-9][0-9]{7,14}$' then
      v_errors := array_append(v_errors, 'phone_invalid');
    elsif left(v_phone, 3) = '+41' and length(v_phone_digits) <> 11 then
      v_errors := array_append(v_errors, 'phone_ch_length_invalid');
    elsif left(v_phone, 3) <> '+41'
      and lower(coalesce(p_country, '')) in ('schweiz','switzerland','ch','suisse','svizzera') then
      v_warnings := array_append(v_warnings, 'phone_country_mismatch');
    end if;
  end if;

  return jsonb_build_object(
    'ok', cardinality(v_errors) = 0,
    'errors', v_errors,
    'warnings', v_warnings,
    'normalized', jsonb_build_object(
      'email', v_email,
      'phone', v_phone,
      'website', v_website
    )
  );
end;
$_$;

ALTER FUNCTION "public"."validate_owner_spot_contact_v1"("p_email" "text", "p_phone" "text", "p_website" "text", "p_country" "text") OWNER TO "postgres";

CREATE OR REPLACE FUNCTION "public"."verify_spot_claim_email_code_v1"("p_spot_id" "uuid", "p_business_email" "text", "p_code" "text") RETURNS TABLE("ok" boolean, "claim_id" bigint, "spot_id" "uuid", "status" "text", "message" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $_$
declare
  v_user_id uuid := auth.uid();
  v_email text := lower(trim(coalesce(p_business_email, '')));
  v_code text := trim(coalesce(p_code, ''));
  v_code_hash text;
  v_verification public.spot_claim_email_verifications_v1%rowtype;
  v_claim_id bigint;
  v_claim_status text;
begin
  if v_user_id is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;

  if p_spot_id is null then
    raise exception 'spot_id_required';
  end if;

  if v_email = '' then
    raise exception 'business_email_required';
  end if;

  if v_code !~ '^[0-9]{6}$' then
    raise exception 'invalid_code_format';
  end if;

  select v.*
  into v_verification
  from public.spot_claim_email_verifications_v1 v
  where v.spot_id = p_spot_id
    and v.user_id = v_user_id
    and lower(v.email) = v_email
    and v.status = 'pending'
  order by v.created_at desc
  limit 1;

  if v_verification.id is null then
    raise exception 'verification_not_found';
  end if;

  if v_verification.expires_at < now() then
    update public.spot_claim_email_verifications_v1 v
    set status = 'expired',
        updated_at = now()
    where v.id = v_verification.id;

    raise exception 'verification_expired';
  end if;

  if v_verification.attempts >= 5 then
    update public.spot_claim_email_verifications_v1 v
    set status = 'failed',
        updated_at = now()
    where v.id = v_verification.id;

    raise exception 'too_many_attempts';
  end if;

  v_code_hash := encode(
    extensions.digest(convert_to(v_code, 'UTF8'), 'sha256'),
    'hex'
  );

  update public.spot_claim_email_verifications_v1 v
  set attempts = v.attempts + 1,
      updated_at = now()
  where v.id = v_verification.id;

  if v_code_hash <> v_verification.code_hash then
    update public.spot_claim_email_verifications_v1 v
    set status = case
          when v.attempts >= 5 then 'failed'
          else v.status
        end,
        updated_at = now()
    where v.id = v_verification.id;

    raise exception 'invalid_code';
  end if;

  update public.spot_claim_email_verifications_v1 v
  set status = 'verified',
      verified_at = now(),
      updated_at = now()
  where v.id = v_verification.id;

  insert into public.spot_claims (
    spot_id,
    user_id,
    status,
    proof,
    note,
    claimant_name,
    claimant_role,
    business_email,
    business_domain,
    email_verified_at,
    domain_match_score,
    domain_match_reason,
    submitted_at,
    created_at,
    updated_at
  )
  values (
    p_spot_id,
    v_user_id,
    'pending',
    'business_email_code_verified',
    v_verification.note,
    v_verification.claimant_name,
    v_verification.claimant_role,
    v_verification.email,
    v_verification.email_domain,
    now(),
    v_verification.domain_match_score,
    v_verification.domain_match_reason,
    now(),
    now(),
    now()
  )
  on conflict on constraint spot_claims_spot_id_user_id_key
  do update set
    status = case
      when public.spot_claims.status = 'approved' then 'approved'
      else 'pending'
    end,
    proof = 'business_email_code_verified',
    note = excluded.note,
    claimant_name = excluded.claimant_name,
    claimant_role = excluded.claimant_role,
    business_email = excluded.business_email,
    business_domain = excluded.business_domain,
    email_verified_at = excluded.email_verified_at,
    domain_match_score = excluded.domain_match_score,
    domain_match_reason = excluded.domain_match_reason,
    submitted_at = now(),
    rejection_reason = null,
    updated_at = now()
  returning public.spot_claims.id, public.spot_claims.status
  into v_claim_id, v_claim_status;

  return query
  select
    true as ok,
    v_claim_id as claim_id,
    p_spot_id as spot_id,
    v_claim_status as status,
    'claim_submitted_for_admin_review'::text as message;
end;
$_$;

ALTER FUNCTION "public"."verify_spot_claim_email_code_v1"("p_spot_id" "uuid", "p_business_email" "text", "p_code" "text") OWNER TO "postgres";

