    CONSTRAINT "legal_documents_publish_fields" CHECK ((("status" <> 'published'::"text") OR (("published_at" IS NOT NULL) AND ("effective_at" IS NOT NULL)))),
    CONSTRAINT "legal_documents_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'retired'::"text"])))
);

