CREATE OR REPLACE VIEW "public"."mood_match" AS
 SELECT "t"."id" AS "canonical_id",
    "t"."token" AS "canonical_token",
    "t"."token" AS "synonym_token"
   FROM "public"."mood_tokens" "t"
UNION ALL
 SELECT "t"."id" AS "canonical_id",
    "t"."token" AS "canonical_token",
    "s"."synonym" AS "synonym_token"
   FROM ("public"."mood_tokens" "t"
     JOIN "public"."synonyms" "s" ON (("s"."token_id" = "t"."id")));

