CREATE OR REPLACE VIEW "public"."review_stats" AS
 SELECT "r"."id" AS "review_id",
    COALESCE("lc"."cnt", (0)::bigint) AS "likes_count",
    COALESCE("cc"."cnt", (0)::bigint) AS "comments_count"
   FROM (("public"."reviews" "r"
     LEFT JOIN LATERAL ( SELECT "count"(*) AS "cnt"
           FROM "public"."review_likes" "rl"
          WHERE ("rl"."review_id" = "r"."id")) "lc" ON (true))
     LEFT JOIN LATERAL ( SELECT "count"(*) AS "cnt"
           FROM "public"."review_comments" "rc"
          WHERE ("rc"."review_id" = "r"."id")) "cc" ON (true));

ALTER VIEW "public"."review_stats" OWNER TO "postgres";

