CREATE OR REPLACE VIEW "public"."spot_effective_content_v1" AS
 SELECT "spot_id",
        CASE
            WHEN (("is_verified" = true) AND (NULLIF(TRIM(BOTH FROM COALESCE("owner_description", ''::"text")), ''::"text") IS NOT NULL)) THEN 'owner'::"text"
            WHEN (NULLIF(TRIM(BOTH FROM COALESCE("admin_description", ''::"text")), ''::"text") IS NOT NULL) THEN 'admin'::"text"
            WHEN (NULLIF(TRIM(BOTH FROM COALESCE("enriched_description", ''::"text")), ''::"text") IS NOT NULL) THEN COALESCE("enriched_source", 'crawl'::"text")
            ELSE NULL::"text"
        END AS "description_source",
        CASE
            WHEN (("is_verified" = true) AND (NULLIF(TRIM(BOTH FROM COALESCE("owner_description", ''::"text")), ''::"text") IS NOT NULL)) THEN "owner_description"
            WHEN (NULLIF(TRIM(BOTH FROM COALESCE("admin_description", ''::"text")), ''::"text") IS NOT NULL) THEN "admin_description"
            WHEN (NULLIF(TRIM(BOTH FROM COALESCE("enriched_description", ''::"text")), ''::"text") IS NOT NULL) THEN "enriched_description"
            ELSE NULL::"text"
        END AS "effective_description",
        CASE
            WHEN (("is_verified" = true) AND (COALESCE("array_length"("owner_keywords", 1), 0) > 0)) THEN "owner_keywords"
            WHEN (COALESCE("array_length"("admin_keywords", 1), 0) > 0) THEN "admin_keywords"
            WHEN (COALESCE("array_length"("enriched_keywords", 1), 0) > 0) THEN "enriched_keywords"
            ELSE '{}'::"text"[]
        END AS "effective_keywords"
   FROM "public"."spot_descriptions" "sd";

ALTER VIEW "public"."spot_effective_content_v1" OWNER TO "postgres";

