CREATE OR REPLACE VIEW "public"."spot_moods_agg_reviews_v1" AS
 WITH "mood_rows" AS (
         SELECT "r"."id" AS "review_id",
            "r"."spot_id",
            "r"."mood_a_id" AS "mood_id"
           FROM "public"."reviews" "r"
          WHERE ("r"."mood_a_id" IS NOT NULL)
        UNION ALL
         SELECT "r"."id" AS "review_id",
            "r"."spot_id",
            "r"."mood_b_id" AS "mood_id"
           FROM "public"."reviews" "r"
          WHERE ("r"."mood_b_id" IS NOT NULL)
        ), "dedup" AS (
         SELECT DISTINCT "mood_rows"."review_id",
            "mood_rows"."spot_id",
            "mood_rows"."mood_id"
           FROM "mood_rows"
        )
 SELECT "spot_id",
    "mood_id",
    ("count"(*))::integer AS "mood_count"
   FROM "dedup"
  GROUP BY "spot_id", "mood_id";

ALTER VIEW "public"."spot_moods_agg_reviews_v1" OWNER TO "postgres";

