    "evidence" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "uuid",
    "verified_by" "uuid",
    "verified_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "spot_taxonomies_confidence_check" CHECK ((("confidence" >= (0)::numeric) AND ("confidence" <= (1)::numeric))),
    CONSTRAINT "spot_taxonomies_source_check" CHECK (("source" = ANY (ARRAY['owner'::"text", 'admin'::"text", 'ai'::"text", 'import'::"text", 'community'::"text"])))
);

ALTER TABLE "public"."spot_taxonomies" OWNER TO "postgres";

