    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "taxonomy_node_translations_label_not_blank" CHECK (("length"("btrim"("label")) > 0)),
    CONSTRAINT "taxonomy_node_translations_locale_check" CHECK (("locale" = ANY (ARRAY['de'::"text", 'en'::"text", 'fr'::"text", 'it'::"text"])))
);

ALTER TABLE "public"."taxonomy_node_translations" OWNER TO "postgres";

CREATE TABLE IF NOT EXISTS "public"."taxonomy_nodes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "slug" "text" NOT NULL,
    "node_type" "text" NOT NULL,
    "parent_id" "uuid",
    "icon" "text",
    "color" "text",
    "description" "text",
    "sort_order" integer DEFAULT 0 NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "is_owner_selectable" boolean DEFAULT true NOT NULL,
    "is_system" boolean DEFAULT false NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "ml_weight" numeric(4,3) DEFAULT 1.000 NOT NULL,
    CONSTRAINT "taxonomy_nodes_ml_weight_check" CHECK ((("ml_weight" >= (0)::numeric) AND ("ml_weight" <= 3.000))),
    CONSTRAINT "taxonomy_nodes_no_self_parent_check" CHECK ((("parent_id" IS NULL) OR ("parent_id" <> "id"))),
    CONSTRAINT "taxonomy_nodes_slug_format_check" CHECK (("slug" ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'::"text")),
    CONSTRAINT "taxonomy_nodes_type_check" CHECK (("node_type" = ANY (ARRAY['subcategory'::"text", 'feature'::"text", 'service'::"text", 'offering'::"text"])))
);

ALTER TABLE "public"."taxonomy_nodes" OWNER TO "postgres";

COMMENT ON COLUMN "public"."taxonomy_nodes"."ml_weight" IS 'Relative ML importance. 1.0 = normal; 0 = excluded from weighted taxonomy text.';

CREATE OR REPLACE VIEW "public"."spot_taxonomy_effective_v1" WITH ("security_invoker"='true') AS
 SELECT DISTINCT ON ("st"."spot_id", "st"."taxonomy_node_id") "st"."spot_id",
    "st"."taxonomy_node_id",
    "tn"."slug",
    "tn"."node_type",
    COALESCE("de"."label", "en"."label", "tn"."slug") AS "label",
    "st"."source",
    "st"."confidence",
    "st"."is_verified",
    "st"."updated_at"
   FROM ((("public"."spot_taxonomies" "st"
     JOIN "public"."taxonomy_nodes" "tn" ON (("tn"."id" = "st"."taxonomy_node_id")))
     LEFT JOIN "public"."taxonomy_node_translations" "de" ON ((("de"."taxonomy_node_id" = "tn"."id") AND ("de"."locale" = 'de'::"text"))))
     LEFT JOIN "public"."taxonomy_node_translations" "en" ON ((("en"."taxonomy_node_id" = "tn"."id") AND ("en"."locale" = 'en'::"text"))))
  WHERE ("tn"."is_active" = true)
  ORDER BY "st"."spot_id", "st"."taxonomy_node_id",
        CASE "st"."source"
            WHEN 'admin'::"text" THEN 1
            WHEN 'owner'::"text" THEN 2
            WHEN 'community'::"text" THEN 3
            WHEN 'ai'::"text" THEN 4
            WHEN 'import'::"text" THEN 5
            ELSE 9
        END, "st"."is_verified" DESC, "st"."confidence" DESC, "st"."updated_at" DESC;

ALTER VIEW "public"."spot_taxonomy_effective_v1" OWNER TO "postgres";

