CREATE OR REPLACE VIEW "public"."taxonomy_catalog_v1" WITH ("security_invoker"='true') AS
 SELECT "tn"."id",
    "tn"."slug",
    "tn"."node_type",
    "tn"."parent_id",
    "tn"."icon",
    "tn"."color",
    "tn"."sort_order",
    "tn"."is_active",
    "tn"."is_owner_selectable",
    COALESCE("de"."label", "en"."label", "tn"."slug") AS "label_de",
    COALESCE("en"."label", "de"."label", "tn"."slug") AS "label_en",
    "array_remove"("array_agg"(DISTINCT "tnc"."category_id"), NULL::"uuid") AS "category_ids"
   FROM ((("public"."taxonomy_nodes" "tn"
     LEFT JOIN "public"."taxonomy_node_translations" "de" ON ((("de"."taxonomy_node_id" = "tn"."id") AND ("de"."locale" = 'de'::"text"))))
     LEFT JOIN "public"."taxonomy_node_translations" "en" ON ((("en"."taxonomy_node_id" = "tn"."id") AND ("en"."locale" = 'en'::"text"))))
     LEFT JOIN "public"."taxonomy_node_categories" "tnc" ON (("tnc"."taxonomy_node_id" = "tn"."id")))
  GROUP BY "tn"."id", "tn"."slug", "tn"."node_type", "tn"."parent_id", "tn"."icon", "tn"."color", "tn"."sort_order", "tn"."is_active", "tn"."is_owner_selectable", "de"."label", "en"."label";

