-- Runtime contract gaps found during reconciliation.

-- BASELINE_REVIEW_REQUIRED: reservations is actively used by Mobile but absent from
-- production. The last canonical legacy definition is restored for fresh environments.
-- 20260411100108_reservations.sql
-- Reservation Requests als erste Commerce-/Owner-Basis

create table if not exists public.reservations (
  id uuid primary key default gen_random_uuid(),

  spot_id uuid not null references public.spots(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,

  date timestamptz not null,
  persons integer not null default 2,
  status text not null default 'pending',

  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  constraint reservations_persons_check check (persons >= 1 and persons <= 50),
  constraint reservations_status_check check (
    status in ('pending', 'confirmed', 'declined', 'cancelled')
  )
);

create index if not exists idx_reservations_spot_id on public.reservations(spot_id);
create index if not exists idx_reservations_user_id on public.reservations(user_id);
create index if not exists idx_reservations_date on public.reservations(date);

drop trigger if exists trg_reservations_set_updated_at on public.reservations;
create trigger trg_reservations_set_updated_at
before update on public.reservations
for each row
execute function public.set_updated_at();

alter table public.reservations enable row level security;
drop policy if exists reservations_select_own on public.reservations;
create policy reservations_select_own on public.reservations
for select to authenticated using (user_id = auth.uid());
drop policy if exists reservations_insert_own on public.reservations;
create policy reservations_insert_own on public.reservations
for insert to authenticated with check (user_id = auth.uid());
drop policy if exists reservations_update_own on public.reservations;
create policy reservations_update_own on public.reservations
for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

-- BASELINE_REVIEW_REQUIRED: Active Safety registry triggers require a current
-- backyrd-global policy even in an empty environment. Bootstrap the last committed
-- shadow-only policy so fresh signups and writes fail safe without activating automated
-- enforcement. Compare this configuration with production before reconciliation.
insert into public.safety_policy_versions (policy_key, version, status, policy, activated_at)
values (
  'backyrd-global',
  '2026-07-29.1',
  'shadow',
  $policy$
  {
    "policy_id":"backyrd-global",
    "version":"2026-07-29.1",
    "status":"shadow",
    "locales":["de-CH","de-DE","en","fr-CH","it-CH"],
    "principles":["context_sensitive","severity_and_confidence","human_review","appeals","auditability","shadow_first"],
    "content_types":{
      "owner_spot_profile":{"tolerance":"low","review_threshold":0.55,"temporary_hide_threshold":0.92},
      "review":{"tolerance":"medium","review_threshold":0.65,"temporary_hide_threshold":0.95},
      "moment":{"tolerance":"medium","review_threshold":0.65,"temporary_hide_threshold":0.95},
      "profile_text":{"tolerance":"low","review_threshold":0.60,"temporary_hide_threshold":0.93}
    }
  }
  $policy$::jsonb,
  now()
)
on conflict (policy_key, version) do nothing;

-- BASELINE_REVIEW_REQUIRED: Mobile reads spot_likes while the canonical domain table
-- is favorites. A read-only, security-invoker compatibility view avoids duplicating state.
create or replace view public.spot_likes with (security_invoker = true) as
select user_id, spot_id, created_at from public.favorites;
revoke all on public.spot_likes from public, anon, authenticated;
grant select on public.spot_likes to authenticated;

-- BASELINE_REVIEW_REQUIRED: active Mobile code references spot_visits and user_dislikes,
-- but neither production nor legacy migrations define an authoritative schema. They are
-- intentionally not invented here; migrate those reads to user_events/decision_actions
-- or approve explicit domain tables before local-chain acceptance.

-- BASELINE_REVIEW_REQUIRED: Active create-review-with-photos RPC reference is missing from production.
-- 20260411100110_rpc_core.sql
-- Erste zentrale Domain-RPCs:
-- - get_spot_detail_v1
-- - get_home_sections_v1
-- - match_mood_v1

create or replace function public.match_mood_v1(input text)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  clean text;
  matched_id bigint;
begin
  clean := lower(trim(input));

  if clean is null or clean = '' then
    return null;
  end if;

  select id
  into matched_id
  from public.mood_tokens
  where lower(token::text) = clean
  limit 1;

  if matched_id is not null then
    return matched_id;
  end if;

  insert into public.mood_tokens (token, locale, valid)
  values (clean, 'de-CH', true)
  returning id into matched_id;

  return matched_id;
end;
$$;

