-- PostgreSQL grants EXECUTE to PUBLIC by default. Remove that implicit surface after
-- replaying explicit production grants; direct anon/authenticated grants remain explicit.
revoke execute on all functions in schema public from public;

-- Remove database-maintenance and DDL-adjacent privileges inherited from historical
-- Supabase defaults. Data API CRUD remains governed by explicit grants plus RLS.
revoke truncate, references, trigger, maintain on all tables in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;
grant usage, select on all sequences in schema public to anon, authenticated;

grant select, insert, update on public.reservations to authenticated;
grant all on public.reservations to service_role;
revoke all on function public.match_mood_v1(text) from public, anon, authenticated;
grant execute on function public.match_mood_v1(text) to service_role;

-- Disabled/orphan achievement triggers and insecure HTTP triggers are intentionally
-- absent. Secret-free replacements and review notes live in supabase/canonical/.

set check_function_bodies = true;
